window.ENAMED_LOCAL_QUESTION_BANK=window.ENAMED_LOCAL_QUESTION_BANK||{};window.ENAMED_LOCAL_QUESTION_BANK["med:med-clinica-medica-med-clm-03"]={"block":"med:med-clinica-medica-med-clm-03","label":"MED · MED CLM 03","count":426,"questions":[{"id":"med-clinica-medica-med-clm-03-345454","number":"345454","sourceNumber":"345454","collectionBlock":"med:med-clinica-medica-med-clm-03","collectionLabel":"MED · MED CLM 03","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 03","subtopic":"","stem":"Paciente de 52 anos, portador de Hipertensão Arterial Sistêmica (HAS) há 5 anos, veio\nà consulta de rotina. Faz uso regular de\ncaptopril (25 mg, de 8/8 horas). A pressão arterial\nverificada no consultório era de 170 x 110 mmHg. Nos controles realizados em casa, foram\nobservados sempre níveis elevados, semelhantes ao da consulta atual. Qual a conduta mais\nadequada?","options":{"A":"Associar um antagonista do receptor de angiotensina II ao esquema em uso.","B":"Associar um diurético trazídico ao esquema em uso.","C":"Realizar investigação de HAS resistente.","D":"Indicar realização de Monitorização Ambulatorial de Pressão Arterial (MAPA)."},"answer":"B","source":"Clinica médica/MED CLM 03/MED CLM 03.txt","sourceLabel":"MED · MED CLM 03","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-03-345473","number":"345473","sourceNumber":"345473","collectionBlock":"med:med-clinica-medica-med-clm-03","collectionLabel":"MED · MED CLM 03","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 03","subtopic":"","stem":"Sobre alterações de perfil lipídico e relação com hábitos alimentares marque a\nalternativa INCORRETA:","options":{"A":"O alvo de tratamento das dislipidemias visa um LDL-colesterol abaixo de 70, independentemente\nda idade e de outros fatores de risco\ncardiovasculares.","B":"O hipotireoidismo pode ser uma causa secundária de dislipidemia.","C":"Muitas medicações incluindo diuréticos tiazídicos e hormônios podem influenciar os níveis\nsanguíneos de colesterol e triglicerídeos.","D":"Adoção de medidas saudáveis de estilo de vida como atividade física regular e diminuição do\netilismo auxiliam no tratamento das dislipidemias."},"answer":"A","source":"Clinica médica/MED CLM 03/MED CLM 03.txt","sourceLabel":"MED · MED CLM 03","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-03-343842","number":"343842","sourceNumber":"343842","collectionBlock":"med:med-clinica-medica-med-clm-03","collectionLabel":"MED · MED CLM 03","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 03","subtopic":"","stem":"Senhora de 62 anos, 60 kg de peso corporal, hipertensa em uso de losartana 50 mg/dia\n\n+ hidroclorotiazida 25 mg/dia, chega a unidade de Pronto Socorro encaminhada por colega para\navaliação de emergência devido exame laboratorial de rotina (Sódio sérico de 122 mEq/L; VR: 135 -\n145 mEq/l), sem outras queixas. Qual a sua conduta para o caso?","options":{"A":"SF 3% - 30 ml/hora EV nas primeiras 3 horas e solicitar novo Sódio sérico.","B":"SF 3% - 60 ml/hora EV nas primeiras 3 horas e solicitar novo Sódio sérico.","C":"Suspender hidroclorotiazida, orientar restrição de líquidos, furosemida via oral e repetir sódio\nsérico ambulatorialmente.","D":"Hidratar com SF 0,9% e reavaliar sódio sérico ambulatorialmente."},"answer":"C","source":"Clinica médica/MED CLM 03/MED CLM 03.txt","sourceLabel":"MED · MED CLM 03","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-03-343851","number":"343851","sourceNumber":"343851","collectionBlock":"med:med-clinica-medica-med-clm-03","collectionLabel":"MED · MED CLM 03","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 03","subtopic":"","stem":"Qual dos pacientes abaixo apresenta uma emergência hipertensiva?","options":{"A":"Senhora de 65 anos, obesa, hipertensa e diabética há 20 anos, vai visitar a mãe na UTI e fica\nmuito emocionada, apresenta tontura e é levada ao PS, onde se constata PA=210x120 mmHg; o\nrestante do exame físico com exceção da obesidade é normal.","B":"Jovem de 12 anos refere que há 15 dias teve impetigo, ontem acordou com as pálpebras\nedemaciadas e hoje não conseguiu praticar educação física por dispnéia. Ao exame físico\nobservaram-se PA=160x100 mmHg, pulmões livres, fundo de olho normal.","C":"Senhor de 72 anos, revascularizado do miocárdio há dois anos, refere dor retroestemal há 3\nhoras. Seu exame físico revela PA=210x130\nmmHg e o pulso: diminuídos em membros superiores\ne não palpáveis em membros inferiores.","D":"Senhora de 48 anos, portadora de estenose aórtica devido ao cardite reumática, refere tontura\nrotatória e vômitos desde hoje cedo, PA=180x105 mmHg."},"answer":"C","source":"Clinica médica/MED CLM 03/MED CLM 03.txt","sourceLabel":"MED · MED CLM 03","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-03-283286","number":"283286","sourceNumber":"283286","collectionBlock":"med:med-clinica-medica-med-clm-03","collectionLabel":"MED · MED CLM 03","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 03","subtopic":"","stem":"Mulher de 60 anos de idade, hipertensa, diabética e dislipidêmica em acompanhamento\nambulatorial em uso de metformina 850 mg\n2x ao dia, sinvastatina 20 mg/dia, AAS 100 mg/dia,\nlosartana 50 mg/dia, hidroclorotiazida 25 mg/dia e anlodipino 5 mg/dia. Refere que tem apresentado\nedema em membros inferiores e crise recorrente de gota. Quais medicamentos seriam\nresponsáveis respectivamente pelo edema e pela gota?","options":{"A":"Sinvastatina e losartana.","B":"Losartana e metformina.","C":"Anlodipino e hidroclorotiazida.","D":"Anlodipino e losartana."},"answer":"C","source":"Clinica médica/MED CLM 03/MED CLM 03.txt","sourceLabel":"MED · MED CLM 03","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-03-281121","number":"281121","sourceNumber":"281121","collectionBlock":"med:med-clinica-medica-med-clm-03","collectionLabel":"MED · MED CLM 03","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 03","subtopic":"","stem":"Pelas recomendações atuais o teste de perfil lipídicos de adultos deve se iniciar após\nos:","options":{"A":"20 anos e se repetir a cada 5 anos.","B":"18 anos e se repetir a cada 2 anos.","C":"25 anos e se repetir a cada 2 anos.","D":"30 anos e se repetir a cada ano.","E":"40 anos e se repetir a cada ano."},"answer":"A","source":"Clinica médica/MED CLM 03/MED CLM 03.txt","sourceLabel":"MED · MED CLM 03","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-03-281127","number":"281127","sourceNumber":"281127","collectionBlock":"med:med-clinica-medica-med-clm-03","collectionLabel":"MED · MED CLM 03","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 03","subtopic":"","stem":"Em relação às dislipidemias, é correto afirmar que:","options":{"A":"A farmacoterapia para otimização de HDL colesterol e triglicerídios tem menos impacto do que a\ndirecionada para LDL colesterol.","B":"Hipotireoidismo, síndrome nefrótica e doença hepática grave são causas identificáveis de\naumento do LDL colesterol.","C":"O paciente com hipercolesterolemia isolada beneficia-se de dieta com restrição de carboidratos\nsimples.","D":"O principal objetivo do tratamento das dislipidemias é a redução do LDL colesterol.","E":"O rastreamento de dislipidemia deve ser feito em pacientes adultos aos 35 anos."},"answer":"D","source":"Clinica médica/MED CLM 03/MED CLM 03.txt","sourceLabel":"MED · MED CLM 03","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-03-251858","number":"251858","sourceNumber":"251858","collectionBlock":"med:med-clinica-medica-med-clm-03","collectionLabel":"MED · MED CLM 03","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 03","subtopic":"","stem":"Assinale o efeito colateral mais comumente encontrado com o uso de inibidores da\nECA:","options":{"A":"Hipotensão arterial.","B":"Hiperpotassemia.","C":"Tosse.","D":"Disfunção renal."},"answer":"C","source":"Clinica médica/MED CLM 03/MED CLM 03.txt","sourceLabel":"MED · MED CLM 03","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-03-247147","number":"247147","sourceNumber":"247147","collectionBlock":"med:med-clinica-medica-med-clm-03","collectionLabel":"MED · MED CLM 03","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 03","subtopic":"","stem":"O principal mecanismo que leva à perda de função renal na hipertensão arterial é:","options":{"A":"Hiperfiltração glomerular.","B":"Hipertensão glomerular.","C":"Isquemia.","D":"Fibrose intersticial.","E":"Esclerose glomerular."},"answer":"C","source":"Clinica médica/MED CLM 03/MED CLM 03.txt","sourceLabel":"MED · MED CLM 03","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-03-251911","number":"251911","sourceNumber":"251911","collectionBlock":"med:med-clinica-medica-med-clm-03","collectionLabel":"MED · MED CLM 03","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 03","subtopic":"","stem":"Sobre o tratamento das dislipidemias, assinale a alternativa INCORRETA:","options":{"A":"A decisão para o início da terapia medicamentosa das dislipidemias depende do risco\ncardiovascular do paciente e do tipo de dislipidemia presente.","B":"Os medicamentos hipolipemiantes costumam ser divididos nos que agem predominantemente\nnas taxas séricas de colesterol e naqueles que\nagem predominantemente nas taxas de TG.","C":"Os fibratos são indicados no tratamento da hipertrigliceridemia endógena quando houver falha\ndas medidas não farmacológicas. Quando os\ntriglicerídeos forem muito elevados (> 300 mg/dL) são\nrecomendados, inicialmente, junto das medidas não farmacológicas.","D":"Na hipercolesterolemia isolada, os medicamentos recomendados são as estatinas, que podem\nser administradas em associação à ezetimiba, à\ncolestiramina e, eventualmente, aos fibratos ou ao\nácido nicotínico."},"answer":"C","source":"Clinica médica/MED CLM 03/MED CLM 03.txt","sourceLabel":"MED · MED CLM 03","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-03-247236","number":"247236","sourceNumber":"247236","collectionBlock":"med:med-clinica-medica-med-clm-03","collectionLabel":"MED · MED CLM 03","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 03","subtopic":"","stem":"Sobre dislipidemias, assinale a alternativa correta.","options":{"A":"Devem fazer parte da dieta as frutas, incluindo o abacate, hortaliças, óleos vegetais, sementes e\ncastanhas e os cereais refinados.","B":"O farelo de aveia é uma importante fonte de fibra insolúvel e, portanto auxilia o tratamento\ndietético da hipercolesterolemia.","C":"A dieta deve ser hipossódica e conter ate 20% de lipídios.","D":"O paciente deve ingerir diariamente 80g de fibras entre solúveis e insolúveis, para efeito\nterapêutico.","E":"O tratamento dietético na hipercolesterolemia prevê em torno de 60% de carboidratos, 15% de\nproteínas e 25% de lipídios, dos quais a gordura saturada não deverá ultrapassar 7%."},"answer":"C","source":"Clinica médica/MED CLM 03/MED CLM 03.txt","sourceLabel":"MED · MED CLM 03","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-03-217656","number":"217656","sourceNumber":"217656","collectionBlock":"med:med-clinica-medica-med-clm-03","collectionLabel":"MED · MED CLM 03","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 03","subtopic":"","stem":"Com relação aos hipotensores, assinale a alternativa CORRETA:","options":{"A":"Há contraindicação relativa ao uso de alfabloqueadores em hipertensos com hipertrofia\nprostática benigna.","B":"Os inibidores diretos da renina causam redução da produção de angiotensina II e há fortes\nevidências de seus benefícios sobre a morbimortalidade.","C":"Os bloqueadores dos receptores AT1 da angiotensina II proporcionam redução da\nmorbimortalidade cardiovascular, mas não da renal.","D":"Os bloqueadores dos canais de cálcio não di-hidropiridínicos podem deprimir a função sistólica\ncardíaca, principalmente em pacientes que já apresentam tal disfunção antes do início do seu uso,\ndevendo ser evitados nessa condição."},"answer":"D","source":"Clinica médica/MED CLM 03/MED CLM 03.txt","sourceLabel":"MED · MED CLM 03","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-03-182602","number":"182602","sourceNumber":"182602","collectionBlock":"med:med-clinica-medica-med-clm-03","collectionLabel":"MED · MED CLM 03","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 03","subtopic":"","stem":"Segundo a VII Diretriz Brasileira de Hipertensão Arterial - HAS (2016), a classificação\nda HAS em medição casual ou no consultório em\num paciente acima de 18 anos de idade com\nníveis tensionais de 140 X 95 mmHg, estaria classificado como:","options":{"A":"Pré hipertensão.","B":"HAS estágio 1.","C":"HAS estágio 2.","D":"HAS estágio 3."},"answer":"B","source":"Clinica médica/MED CLM 03/MED CLM 03.txt","sourceLabel":"MED · MED CLM 03","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-03-183178","number":"183178","sourceNumber":"183178","collectionBlock":"med:med-clinica-medica-med-clm-03","collectionLabel":"MED · MED CLM 03","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 03","subtopic":"","stem":"Homem de 55 anos de idade com história de infarto do miocárdio há 3 meses, com\ndieta de estágio II, exercitando-se\nregularmente em programa de reabilitação cardíaca. Não fuma e\na pressão arterial é de 120/80 mmHg sob terapia com betabloqueador e AAS. Apresenta colesterol\ntotal=240 mg/dl, HDL col.= 55 mg/dl, LDL col,=165 mg/dl e triglicérides= 100 mg/dl. Sua conduta no\ntratamento desse paciente é:","options":{"A":"Iniciar sinvastatina, 20 mg/dia.","B":"Iniciar niacina, 2.000 mg/dia.","C":"Recomendar dieta de estágio III.","D":"Encaminhar a um especialista em lipídeos.","E":"Avaliar membros da família para descartar hipercolesterolemia familiar."},"answer":"A","source":"Clinica médica/MED CLM 03/MED CLM 03.txt","sourceLabel":"MED · MED CLM 03","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 03","MED"],"answerSource":"inferred","commentDeferred":true},{"id":"med-clinica-medica-med-clm-03-159089","number":"159089","sourceNumber":"159089","collectionBlock":"med:med-clinica-medica-med-clm-03","collectionLabel":"MED · MED CLM 03","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 03","subtopic":"","stem":"O manejo do paciente hipertenso é de grande importância na prática clínica diária, por\nisso os conhecimentos sobre os fármacos\nutilizados para o tratamento da hipertensão arterial\nsistêmica e seus riscos são pré-requisitos básicos para o seu emprego adequado e responsável\npelo médico que irá atuar nas unidades básicas de saúde. Tendo em vista o exposto acima,\nrelacione as colunas, associando os efeitos adversos aos respectivos fármacos. (1)\nHidroclorotiazida; (2) Propranolol; (3) Anlodipino; (4) Captopril. ( ) Tosse e hipercalemia; ( )\nBroncoespasmo, insuficiência circulatória periférica, bradiarritmias e mascaramento de hipoglicemia\nem diabéticos; ( ) Hipocalemia e hiperuricemia; ( ) Cefaleia, edema periférico e palpitação. A ordem\nnumérica CORRETA, na coluna inferior, de cima para baixo é:","options":{"A":"2 - 3 - 4 - 1.","B":"2 - 4 - 1 - 3.","C":"4 - 2 - 1 - 3.","D":"4 - 1 - 3 - 2."},"answer":"C","source":"Clinica médica/MED CLM 03/MED CLM 03.txt","sourceLabel":"MED · MED CLM 03","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-03-159119","number":"159119","sourceNumber":"159119","collectionBlock":"med:med-clinica-medica-med-clm-03","collectionLabel":"MED · MED CLM 03","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 03","subtopic":"","stem":"Com relação aos diuréticos usados na insuficiência cardiaca, pode-se afirmar que a:","options":{"A":"Clortalidona reduz o sódio e potássio urinários.","B":"Furosemida pode causar alcalose hipoclorêmica.","C":"Amilorida reduz a concentração sérica de magnésio.","D":"Hidroclorotiazida não interfere no nível sérico de glicose."},"answer":"B","source":"Clinica médica/MED CLM 03/MED CLM 03.txt","sourceLabel":"MED · MED CLM 03","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-03-159122","number":"159122","sourceNumber":"159122","collectionBlock":"med:med-clinica-medica-med-clm-03","collectionLabel":"MED · MED CLM 03","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 03","subtopic":"","stem":"Sobre as urgências hipertensivas e complicações na hipertensão arterial, pode-se\nafirmar que: I - A causa da morte mais\nfrequente em hipertensos não tratados é o infarto agudo do\nmiocárdio. II - O metoprolol é o agente anti-hipertensivo parenteral mais indicado na maioria das\nemergências hipertensivas. III - No evento isquêmico agudo cerebral, não se deve administrar\n\nanti-hipertensivos, a não ser em condições específicas ou níveis de pressão extremamente\nelevados (PAS > 220mmHg ou PAD > 120 mmHg).","options":{"A":"Apenas a I está correta.","B":"Apenas a II está correta.","C":"Apenas a III está correta.","D":"I e III estão corretas."},"answer":"C","source":"Clinica médica/MED CLM 03/MED CLM 03.txt","sourceLabel":"MED · MED CLM 03","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-03-159125","number":"159125","sourceNumber":"159125","collectionBlock":"med:med-clinica-medica-med-clm-03","collectionLabel":"MED · MED CLM 03","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 03","subtopic":"","stem":"Na terapêutica das emergências hipertensivas, pode se afirmar que:","options":{"A":"O captopril sublingual é a opção terapêutica para o tratamento ambulatorial.","B":"O nitroprussiato de sódio deve ser utilizado em pacientes com suspeita de isquemia miocárdica\npara a rápida redução do consumo de oxigênio.","C":"A furosemida está indicada no tratamento da eclâmpsia para controle de volemia.","D":"O betabloqueador venoso está indicado na suspeita de dissecção aórtica em conjunto com o\nnitroprussiato de sódio."},"answer":"D","source":"Clinica médica/MED CLM 03/MED CLM 03.txt","sourceLabel":"MED · MED CLM 03","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-03-108801","number":"108801","sourceNumber":"108801","collectionBlock":"med:med-clinica-medica-med-clm-03","collectionLabel":"MED · MED CLM 03","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 03","subtopic":"","stem":"Para um médico de família é fundamental ter conhecimento sobre abordagem da\nhipertensão arterial sistêmica em seus pacientes. Sobre este assunto é CORRETO afirmar que:","options":{"A":"A medicação de primeira escolha é o atenolol 25 mg/dia.","B":"Pacientes com nível pressórico controlado necessitam realizar consultas anuais.","C":"O uso de ácido acetilsalicílico associado é recomendado como terapia auxiliar nos pacientes\nhipertensos.","D":"Mudança do estilo de vida como tratamento inicial pode ser recomendado para alguns pacientes."},"answer":"D","source":"Clinica médica/MED CLM 03/MED CLM 03.txt","sourceLabel":"MED · MED CLM 03","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-03-84507","number":"84507","sourceNumber":"84507","collectionBlock":"med:med-clinica-medica-med-clm-03","collectionLabel":"MED · MED CLM 03","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 03","subtopic":"","stem":"Assinale a opção correta, em se tratando de exames de rotina MÍNIMA para pacientes\nportadores de hipertensão arterial.","options":{"A":"Hemograma, sódio, potássio, ureia, urocultura;","B":"Glicemia, Na, K, ECG de esforço;","C":"Hemograma, EPF, urina I, Ureia;","D":"Urina parcial, creatinina, Potássio, glicemia, colesterol e frações, ECG de repouso;","E":"Glicemia, fosfatase alcalina, K, Na."},"answer":"D","source":"Clinica médica/MED CLM 03/MED CLM 03.txt","sourceLabel":"MED · MED CLM 03","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-03-84493","number":"84493","sourceNumber":"84493","collectionBlock":"med:med-clinica-medica-med-clm-03","collectionLabel":"MED · MED CLM 03","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 03","subtopic":"","stem":"Indivíduo do sexo masculino, 29 anos, estressado no trabalho e sedentário, com avó\nhipertensa, apresenta-se com IMC de 26,3 kg/m2 e PA de 138/84 mmHg (média de duas medidas).\nQual a melhor orientação do caso?","options":{"A":"A PA é normal e não necessita nenhuma orientação específica.","B":"A PA é normal e está recomendado o acompanhamento nutricional com vistas à redução do sal.","C":"A PA é normal alta e a ênfase deve ser perda de peso, iniciar atividade física e redução do sal.","D":"A PA é normal alta e deve ser prescrito fármaco anti-hipertensivo devido à história familiar\npositiva para hipertensão.","E":"A PA é alta e deve ser iniciado fármacos logo de início."},"answer":"C","source":"Clinica médica/MED CLM 03/MED CLM 03.txt","sourceLabel":"MED · MED CLM 03","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-03-84524","number":"84524","sourceNumber":"84524","collectionBlock":"med:med-clinica-medica-med-clm-03","collectionLabel":"MED · MED CLM 03","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 03","subtopic":"","stem":"Homem branco, 52 anos, Colesterol total - 255 mg/dl, HDL- 55 mg/dl, Pressão arterial\nsistólica de 130 mmHg sem uso de\nmedicamentos, não é diabético, não fuma, Risco de doença\ncoronariana ou AVC em 10 anos de 7,2%. Baseado nas diretrizes para tratamento de Dislipidemia\ndo Colégio Americano de Cardiologia e Associação Americana do Coração de 2013, responda qual\na melhor conduta para o caso:","options":{"A":"Ciprofibrato 100 mg/dia.","B":"Atorvastatina 20 mg/dia.","C":"Orientações higienodietéticas.","D":"Rosuvastatina 5 mg/dia.","E":"Genfibrozila."},"answer":"C","source":"Clinica médica/MED CLM 03/MED CLM 03.txt","sourceLabel":"MED · MED CLM 03","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-03-66967","number":"66967","sourceNumber":"66967","collectionBlock":"med:med-clinica-medica-med-clm-03","collectionLabel":"MED · MED CLM 03","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 03","subtopic":"","stem":"Para pacientes hipertensos em estágio 2 (pressão arterial sistólica \"maior ou igual a\"\n160 mmHg e pressão arterial diastólica \"maior\nou igual a\" 100 mmHg), pode-se considerar o uso de\nassociações de fármacos anti-hipertensivos como terapia inicial. Ao usar diuréticos tiazídicos\nassociados a betabloqueador, os riscos mais importantes são:","options":{"A":"Hipocalemia e tosse.","B":"Hipovolemia e tosse.","C":"Hipocalemia e broncoespasmo.","D":"Hipercalemia e hiperuricemia."},"answer":"C","source":"Clinica médica/MED CLM 03/MED CLM 03.txt","sourceLabel":"MED · MED CLM 03","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-03-37073","number":"37073","sourceNumber":"37073","collectionBlock":"med:med-clinica-medica-med-clm-03","collectionLabel":"MED · MED CLM 03","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 03","subtopic":"","stem":"Qual dos pacientes abaixo apresenta uma emergência hipertensiva?","options":{"A":"Senhora de 65 anos, obesa, hipertensa e diabética há 20 anos, vai visitar a mãe na UTI e fica\nmuito emocionada, apresenta tontura e é levada ao\nOS, onde se constata PA = 210 X 120 mmHg; o\nrestante do exame físico com exceção da obesidade é normal.","B":"Jovem de 12 anos refere que há 15 dias teve impetigo; ontem acordou com as pálpebras\nedemaciadas e hoje não conseguiu praticar educação física por dispneia. Ao exame físico\nobservaram-se PA = 160 X 100 mmHg, pulmões livres, fundo de olho normal.","C":"Senhor de 72 anos, revascularizado do miocárdio há dois anos, refere dor retroestemal há 3\nhoras. Seu exame físico revela PA = 210 X 130 mmHg e os pulsos: diminuídos em membros\nsuperiores e não palpáveis em membros inferiores.","D":"Moça lúpica de 22 anos, há uma semana fez todos os exames para avaliação de atividade da\ndoença que foram normais; hoje refere\ncefaleia e PA = 180 X 105 mmHg.","E":"Senhora de 48 anos, portadora de estenose aórtica devido a cardite reumática, refere tontura\nrotatória e vômitos desde hoje cedo, PA = 180 x 105 mmHg."},"answer":"C","source":"Clinica médica/MED CLM 03/MED CLM 03.txt","sourceLabel":"MED · MED CLM 03","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-03-37087","number":"37087","sourceNumber":"37087","collectionBlock":"med:med-clinica-medica-med-clm-03","collectionLabel":"MED · MED CLM 03","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 03","subtopic":"","stem":"Paciente com Hipertensão Arterial Sistêmica acelerada apresenta ao exame de fundo\nde olho:","options":{"A":"Exudatos e papiledema","B":"Hemorragia retiniana e papiledema","C":"Dano Vascular sem papiledema","D":"Cruzamentos artério-venoso e papiledema","E":"Espasmo arteriolar e papiledema"},"answer":"D","source":"Clinica médica/MED CLM 03/MED CLM 03.txt","sourceLabel":"MED · MED CLM 03","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-03-37129","number":"37129","sourceNumber":"37129","collectionBlock":"med:med-clinica-medica-med-clm-03","collectionLabel":"MED · MED CLM 03","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 03","subtopic":"","stem":"Sobre Síndrome Metabólica (SM) na infância, é correto afirmar que:","options":{"A":"Os critérios diagnósticos são diferentes dos critérios diagnósticos dos adultos.","B":"Os pontos de cortes para os componentes são idênticos aos dos adultos.","C":"Os pontos de corte devem ser obtidos da distribuição para cada variável de acordo com o sexo e\na idade correspondendo aos percentis 5 e 95.","D":"A PA maior ou igual a 130 x 80 mmHg é considerada hipertensão na infância.","E":"Diferentemente dos adultos, não está relacionado com a obesidade."},"answer":"C","source":"Clinica médica/MED CLM 03/MED CLM 03.txt","sourceLabel":"MED · MED CLM 03","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-03-29400","number":"29400","sourceNumber":"29400","collectionBlock":"med:med-clinica-medica-med-clm-03","collectionLabel":"MED · MED CLM 03","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 03","subtopic":"","stem":"A síndrome Metabólica é uma alteração que aumenta o risco cardiovascular. Seu\ntratamento tem sido apontado como importante medida de prevenção Cardiovascular. Que\nalteração abaixo não faz parte do quadro da Síndrome Metabólica?","options":{"A":"Aumento na quantidade de plaquetas.","B":"Aumento de ácido úrico.","C":"Aumento de triglicerídeos.","D":"Diminuição de colesterol HDL.","E":"Intolerância à glicose."},"answer":"A","source":"Clinica médica/MED CLM 03/MED CLM 03.txt","sourceLabel":"MED · MED CLM 03","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-03-29340","number":"29340","sourceNumber":"29340","collectionBlock":"med:med-clinica-medica-med-clm-03","collectionLabel":"MED · MED CLM 03","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 03","subtopic":"","stem":"Todas as situações clínicas abaixo são indícios de hipertensão arterial secudária,\nexceto:","options":{"A":"Sintomas de apneia durante o sono.","B":"Exame de urina anormal (proteinúria ou hematúria)","C":"Hipopotassemia espontânea","D":"Presença de sopro abdominal","E":"presença de síndrome metabólica associada"},"answer":"E","source":"Clinica médica/MED CLM 03/MED CLM 03.txt","sourceLabel":"MED · MED CLM 03","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-03-372081","number":"372081","sourceNumber":"372081","collectionBlock":"med:med-clinica-medica-med-clm-03","collectionLabel":"MED · MED CLM 03","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 03","subtopic":"","stem":"Na Síndrome da Quilomicronemia Familiar - SQF, os quilomícrons, os quilomícrons\nremanescentes e as lipoproteínas ricas em triglicérides não podem ser metabolizados e se\nacumulam no plasma.","options":{"A":"Dessa forma, o acúmulo de triglicérides pode prejudicar o fluxo sanguíneo pancreático e inativar\nprocessos inflamatórios, resultando em pancreatite aguda.","B":"Dessa forma, o acúmulo de triglicérides pode ajudar o fluxo sanguíneo pancreático e ativar\nprocessos inflamatórios, resultando em pancreatite aguda.","C":"Dessa forma, o acúmulo de triglicérides pode prejudicar o fluxo sanguíneo pancreático e ativar\nprocessos inflamatórios, resultando em pancreatite aguda.","D":"Dessa forma, o acúmulo de glicose pode prejudicar o fluxo sanguíneo pancreático e ativar\nprocessos inflamatórios, resultando em pancreatite aguda."},"answer":"C","source":"Clinica médica/MED CLM 03/MED CLM 03.txt","sourceLabel":"MED · MED CLM 03","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-03-343163","number":"343163","sourceNumber":"343163","collectionBlock":"med:med-clinica-medica-med-clm-03","collectionLabel":"MED · MED CLM 03","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 03","subtopic":"","stem":"A oclusão de artéria retiniana:","options":{"A":"Não é um marcador de lesão de pequenos vasos e tem sido associada a maior risco de evento\ncerebral.","B":"É um marcador de lesão de pequenos vasos e tem sido associada a maior risco de evento\ncerebral.","C":"É um marcador de lesão de pequenos vasos e tem sido associada a menor risco de evento\ncerebral.","D":"É um marcador de lesão de pequenos vasos e não tem sido associada a maior risco de evento\ncerebral."},"answer":"B","source":"Clinica médica/MED CLM 03/MED CLM 03.txt","sourceLabel":"MED · MED CLM 03","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-03-313427","number":"313427","sourceNumber":"313427","collectionBlock":"med:med-clinica-medica-med-clm-03","collectionLabel":"MED · MED CLM 03","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 03","subtopic":"","stem":"Os IECA e outros bloqueadores do Sistema Renina-Angiotensina-Aldosterona (SRAA),\nestão de acordo com o seguinte item\ncorreto:","options":{"A":"Podem provocar hipopotassemia em pacientes com insuficiência renal, sobretudo nos diabéticos\ne, o uso é contraindicado na gravidez, pelo\nrisco de complicações fetais. Por isso, seu emprego\ndeve ser cauteloso e frequentemente monitorado em adolescentes e mulheres em idade fértil.","B":"Podem provocar hiperpotassemia em pacientes com insuficiência renal, sobretudo nos\ndiabéticos e, o uso é indicado na gravidez\nfrequentemente monitorado em mulheres em idade fértil.","C":"Podem provocar hiperpotassemia em pacientes com insuficiência renal, exceto nos diabéticos e,\no uso é contraindicado na gravidez, pelo risco de complicações fetais. Por isso, seu emprego deve\nser cauteloso e frequentemente monitorado em adolescentes e mulheres em idade fértil.","D":"Podem provocar hiperpotassemia em pacientes com insuficiência renal, sobretudo nos\ndiabéticos e, o uso é contraindicado na\ngravidez, pelo risco de complicações fetais. Por isso, seu\nemprego deve ser cauteloso e frequentemente monitorado em adolescentes e mulheres em idade\nfértil."},"answer":"D","source":"Clinica médica/MED CLM 03/MED CLM 03.txt","sourceLabel":"MED · MED CLM 03","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-03-314192","number":"314192","sourceNumber":"314192","collectionBlock":"med:med-clinica-medica-med-clm-03","collectionLabel":"MED · MED CLM 03","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 03","subtopic":"","stem":"Devido à alta prevalência de Hipercolesterolemia Familiar (HF) na população geral e o\nseu grande impacto nas taxas de doença\ncardiovascular e mortalidade, está correto afirmar que:","options":{"A":"Toda anamnese deve incluir a pesquisa de histórico familiar de hipercolesterolemia, de uso de\nmedicamentos hipolipemiantes e de doença aterosclerótica prematura, incluindo a idade de\nacometimento.","B":"Toda anamnese deve incluir a pesquisa de histórico familiar de hipercolesterolemia, de uso de\nmedicamentos hipolipemiantes e de doença aterosclerótica prematura, excluindo a idade de\nacometimento.","C":"Toda anamnese deve incluir a pesquisa de histórico familiar de hipercolesterolemia, nunca de\nuso de medicamentos hipolipemiantes e de\ndoença aterosclerótica prematura, incluindo a idade de\nacometimento.","D":"Toda anamnese deve incluir a pesquisa de histórico familiar de hipercolesterolemia, de uso de\nmedicamentos hipolipemiantes e não de doença aterosclerótica prematura, incluindo a idade de\nacometimento."},"answer":"A","source":"Clinica médica/MED CLM 03/MED CLM 03.txt","sourceLabel":"MED · MED CLM 03","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-03-314193","number":"314193","sourceNumber":"314193","collectionBlock":"med:med-clinica-medica-med-clm-03","collectionLabel":"MED · MED CLM 03","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 03","subtopic":"","stem":"Os xantomas tuberosos amarelo-alaranjados e os xantelasmas de pálpebras não são\nespecíficos de Hipercolesterolemia Familiar (HF), sendo correto que:","options":{"A":"Não devem ser valorizados quando encontrados em pacientes com idade em torno de 20 a 25\nanos.","B":"Devem ser valorizados quando encontrados em pacientes com idade em torno de 5 a 10 anos.","C":"Devem ser desconsiderados quando encontrados em pacientes com idade em torno de 20 a 25\nanos.","D":"Devem ser valorizados quando encontrados em pacientes com idade em torno de 20 a 25 anos."},"answer":"D","source":"Clinica médica/MED CLM 03/MED CLM 03.txt","sourceLabel":"MED · MED CLM 03","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-03-313429","number":"313429","sourceNumber":"313429","collectionBlock":"med:med-clinica-medica-med-clm-03","collectionLabel":"MED · MED CLM 03","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 03","subtopic":"","stem":"Bloqueadores dos Receptores AT1 da Angiotensina II (BRA), estão de acordo com o\nseguinte item correto:","options":{"A":"Antagonizam a ação da Angiotensina II pelo bloqueio inespecífico dos Receptores AT1,\nresponsáveis pelas ações próprias da Angiotensina I (vasoconstrição, estímulo da proliferação\ncelular e da liberação de aldosterona).","B":"Antagonizam a ação da Angiotensina II pelo bloqueio específico dos Receptores AT1,\nresponsáveis pelas ações próprias da\nAngiotensina II (vasoconstrição, estímulo da proliferação\ncelular e da liberação de aldosterona).","C":"Aumentam a ação da Angiotensina II pelo bloqueio específico dos Receptores AT1,\nresponsáveis pelas ações próprias da Angiotensina\nII (vasoconstrição, estímulo da proliferação\ncelular e da liberação de aldosterona).","D":"Antagonizam a ação da Angiotensina II, mas não pelo bloqueio específico dos Receptores AT1,\nresponsáveis pelas ações próprias da Angiotensina II (vasoconstrição, estímulo da proliferação\ncelular e da liberação de aldosterona)."},"answer":"B","source":"Clinica médica/MED CLM 03/MED CLM 03.txt","sourceLabel":"MED · MED CLM 03","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-03-313431","number":"313431","sourceNumber":"313431","collectionBlock":"med:med-clinica-medica-med-clm-03","collectionLabel":"MED · MED CLM 03","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 03","subtopic":"","stem":"Assinale a alternativa correta de acordo com os Efeitos Adversos dos Bloqueadores de\nCanal de Cálcio:","options":{"A":"O edema maleolar costuma ser o efeito colateral mais registrado e resulta da própria ação\nvasodilatadora (mais arterial que venosa), promovendo a transudação capilar.","B":"O edema maleolar costuma ser o efeito colateral mais raro e resulta da própria ação\nvasodilatadora (mais arterial que venosa), promovendo a transudação capilar.","C":"O edema maleolar costuma ser o efeito colateral mais registrado e resulta da própria ação\nvasoconstrictora (mais arterial que venosa), promovendo a transudação capilar.","D":"O edema maleolar costuma ser o efeito colateral mais registrado e resulta da própria ação\nvasodilatadora (mais arterial que venosa), inibindo a transudação capilar."},"answer":"A","source":"Clinica médica/MED CLM 03/MED CLM 03.txt","sourceLabel":"MED · MED CLM 03","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-03-314196","number":"314196","sourceNumber":"314196","collectionBlock":"med:med-clinica-medica-med-clm-03","collectionLabel":"MED · MED CLM 03","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 03","subtopic":"","stem":"A determinação do perfil lipídico está sujeita a uma série de variações relacionadas:","options":{"A":"Tanto ao método e aos procedimentos utilizados, mas não aos fatores peculiares do indivíduo,\ncomo estilo de vida, uso de medicações e\ndoenças associada.","B":"Tanto ao método e aos procedimentos utilizados como aos fatores peculiares do indivíduo, como\nestilo de vida, uso de medicações e nunca de doenças associada.","C":"Tanto ao método e aos procedimentos utilizados como aos fatores peculiares do indivíduo,\nexcluindo o estilo de vida.","D":"Tanto ao método e aos procedimentos utilizados como aos fatores peculiares do indivíduo, como\nestilo de vida, uso de medicações e doenças associada."},"answer":"D","source":"Clinica médica/MED CLM 03/MED CLM 03.txt","sourceLabel":"MED · MED CLM 03","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-03-307033","number":"307033","sourceNumber":"307033","collectionBlock":"med:med-clinica-medica-med-clm-03","collectionLabel":"MED · MED CLM 03","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 03","subtopic":"","stem":"Mulher, 27 anos de idade, comparece à Unidade Básica de Saúde, UBS, para consulta\nde rotina, sem queixas. Nega comorbidades\nconhecidas, tabagismo ou etilismo. Pratica\ncaminhadas 3 vezes na semana, de uma hora. De antecedentes familiares, diz que o pai faleceu de\ninfarto aos 49 anos. Ao exame físico, observam-se xantomas em tendão calcâneo bilateralmente,\nsem outras alterações. IMC: 24 kg/m². Realizados exames laboratoriais, com colesterol total de\n385mg/dL, HDL: 86mg/dL, LDL: 262mg/dL e triglicérides: 92mg/dL. Diante do quadro, Em relação\nao diagnóstico, pode-se afirmar que","options":{"A":"o mais provável é tratar-se de dislipidemia secundária.","B":"os xantomas em tendão calcâneo são sinais patognomônicos de dislipidemia primária.","C":"apesar da dislipidemia, a paciente apresenta baixo risco cardiovascular devido ao HDL elevado.","D":"a paciente possui critérios suficientes para o diagnóstico de hipercolesterolemia familiar."},"answer":"D","source":"Clinica médica/MED CLM 03/MED CLM 03.txt","sourceLabel":"MED · MED CLM 03","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-03-307034","number":"307034","sourceNumber":"307034","collectionBlock":"med:med-clinica-medica-med-clm-03","collectionLabel":"MED · MED CLM 03","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 03","subtopic":"","stem":"Mulher, 27 anos de idade, comparece à Unidade Básica de Saúde, UBS, para consulta\nde rotina, sem queixas. Nega comorbidades\nconhecidas, tabagismo ou etilismo. Pratica\ncaminhadas 3 vezes na semana, de uma hora. De antecedentes familiares, diz que o pai faleceu de\ninfarto aos 49 anos. Ao exame físico, observam-se xantomas em tendão calcâneo bilateralmente,\nsem outras alterações. IMC: 24 kg/m². Realizados exames laboratoriais, com colesterol total de\n385mg/dL, HDL: 86mg/dL, LDL: 262mg/dL e triglicérides: 92mg/dL. Diante do quadro, Em relação à\nconduta terapêutica farmacológica, deve-se iniciar o tratamento, preferencialmente, com","options":{"A":"sinvastatina, em dose máxima.","B":"rosuvastatina ou atorvastatina.","C":"pitavastatina ou pravastatina.","D":"sinvastatina associada à ezetimibe."},"answer":"B","source":"Clinica médica/MED CLM 03/MED CLM 03.txt","sourceLabel":"MED · MED CLM 03","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-03-307035","number":"307035","sourceNumber":"307035","collectionBlock":"med:med-clinica-medica-med-clm-03","collectionLabel":"MED · MED CLM 03","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 03","subtopic":"","stem":"Mulher, 27 anos de idade, comparece à Unidade Básica de Saúde, UBS, para consulta\nde rotina, sem queixas. Nega comorbidades\nconhecidas, tabagismo ou etilismo. Pratica\ncaminhadas 3 vezes na semana, de uma hora. De antecedentes familiares, diz que o pai faleceu de\ninfarto aos 49 anos. Ao exame físico, observam-se xantomas em tendão calcâneo bilateralmente,\nsem outras alterações. IMC: 24 kg/m². Realizados exames laboratoriais, com colesterol total de\n385mg/dL, HDL: 86mg/dL, LDL: 262mg/dL e triglicérides: 92mg/dL. Diante do quadro, Em relação à\nconduta não farmacológica, pode se afirmar que","options":{"A":"o cateterismo cardíaco deve ser realizado devido ao alto risco cardiovascular.","B":"a avaliação cardiovascular complementar é dispensável por se tratar de paciente jovem.","C":"o xantoma tendinoso, geralmente, é doloroso, devendo ser realizada excisão cirúrgica.","D":"os familiares de primeiro grau, da paciente, devem ser rastreados com perfil lipídico."},"answer":"D","source":"Clinica médica/MED CLM 03/MED CLM 03.txt","sourceLabel":"MED · MED CLM 03","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-03-313434","number":"313434","sourceNumber":"313434","collectionBlock":"med:med-clinica-medica-med-clm-03","collectionLabel":"MED · MED CLM 03","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 03","subtopic":"","stem":"A cefaleia latejante e as tonturas são comuns Bloqueadores de Canal de Cálcio BCC,\nsendo correta a alternativa:","options":{"A":"O rubor facial é mais raro com os BCC di-hidropiridínicos de ação rápida. A hipercromia do terço\ndistal das pernas (dermatite ocre) e a hipertrofia gengival são efeitos adversos ocasionais.","B":"O rubor facial é mais comum com os BCC di-hidropiridínicos de ação lenta. A hipercromia do\nterço distal das pernas (dermatite ocre) e a hipertrofia gengival são efeitos adversos ocasionais.","C":"O rubor facial é mais comum com os BCC di-hidropiridínicos de ação rápida. A hipercromia do\nterço distal das pernas (dermatite ocre) e a hipertrofia gengival são efeitos adversos ocasionais.","D":"O rubor facial é mais comum com os BCC não di-hidropiridínicos de ação rápida. A hipercromia\ndo terço distal das pernas (dermatite ocre) e\na hipertrofia gengival são efeitos adversos ocasionais."},"answer":"C","source":"Clinica médica/MED CLM 03/MED CLM 03.txt","sourceLabel":"MED · MED CLM 03","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-03-314209","number":"314209","sourceNumber":"314209","collectionBlock":"med:med-clinica-medica-med-clm-03","collectionLabel":"MED · MED CLM 03","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 03","subtopic":"","stem":"Sabemos que a emergência hipertensiva caracteriza-se por descompensação rápida de\nfunções vitais causada por grande elevação da PA em presença de lesão evidente e recente de\nórgão-alvo. Assinale a alternativa que apresenta a droga de escolha nessa situação.","options":{"A":"Hidralazina.","B":"Nitroprussiato de sódio.","C":"Nifedipino.","D":"Enalapril."},"answer":"B","source":"Clinica médica/MED CLM 03/MED CLM 03.txt","sourceLabel":"MED · MED CLM 03","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-03-278073","number":"278073","sourceNumber":"278073","collectionBlock":"med:med-clinica-medica-med-clm-03","collectionLabel":"MED · MED CLM 03","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 03","subtopic":"","stem":"Em relação as situações que podem levar ao falso diagnóstico de Hipertensão Arterial\nResistente (HAR), acarretando a realização de exames e o uso de medicação de modo\ndesnecessário. Indique a alternativa correta.","options":{"A":"É possível referir-se à hipertensão do avental branco como uma causa de hipertensão arterial\npseudorresistente.","B":"É impossível referir-se à hipertensão do avental branco como uma causa de hipertensão arterial\npseudorresistente.","C":"É possível referir-se à hipertensão do avental branco como uma causa de hipertensão arterial\nresistente.","D":"É possível referir-se à hipertensão do avental branco como uma causa de hipotensão arterial\npseudorresistente."},"answer":"A","source":"Clinica médica/MED CLM 03/MED CLM 03.txt","sourceLabel":"MED · MED CLM 03","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-03-280393","number":"280393","sourceNumber":"280393","collectionBlock":"med:med-clinica-medica-med-clm-03","collectionLabel":"MED · MED CLM 03","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 03","subtopic":"","stem":"Uma vez afastada a pseudorresistência, confirma-se a existência da HAR e inicia-se\numa investigação diagnóstica com exames\nespecíficos, conforme a orientação das Diretrizes de\nHipertensão em relação ao comprometimento de lesões em órgãos-alvo e hipertensão secundária.\nSendo correto que:","options":{"A":"A ocorrência de comorbidades associadas não deve ser detectada com exames especializados\nde acordo com a suspeita clínica.","B":"A ocorrência de comorbidades associadas nunca deve ser detectada com exames de acordo\ncom a suspeita clínica.","C":"A ocorrência de comorbidades associadas deve ser detectada com exames especializados de\nacordo com a suspeita clínica.","D":"A ocorrência de comorbidades associadas deve ser detectada com exames especializados,\nmesmo sem qualquer suspeita clínica."},"answer":"C","source":"Clinica médica/MED CLM 03/MED CLM 03.txt","sourceLabel":"MED · MED CLM 03","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-03-275968","number":"275968","sourceNumber":"275968","collectionBlock":"med:med-clinica-medica-med-clm-03","collectionLabel":"MED · MED CLM 03","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 03","subtopic":"","stem":"De acordo com as Diretrizes Brasileira de Hipertensão 2020, pode-se afirmar que:","options":{"A":"A hipertensão se caracteriza por níveis pressóricos iguais ou maiores que 130/90 mmHg.","B":"Uma das principais causas secundárias de hipertensão é a estenose da artéria renal.","C":"Indivíduos com níveis pressóricos de 120-129 mmHg e/ou diastólica de 80-89mmHg são\nconsiderados pré-hipertensos.","D":"No tratamento a prioridade é medicar o paciente ficando a orientação quanto as modificações do\nestilo de vida como auxiliar secundário ao tratamento medicamentoso.","E":"Nenhuma das alternativas anteriores."},"answer":"B","source":"Clinica médica/MED CLM 03/MED CLM 03.txt","sourceLabel":"MED · MED CLM 03","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-03-278075","number":"278075","sourceNumber":"278075","collectionBlock":"med:med-clinica-medica-med-clm-03","collectionLabel":"MED · MED CLM 03","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 03","subtopic":"","stem":"A Hipertensão Arterial Resistente (HAR) é definida quando a pressão arterial (PA)\napresenta as seguintes características:","options":{"A":"Permanece abaixo das metas recomendadas com o uso de três anti-hipertensivos de diferentes\nclasses.","B":"Permanece acima das metas recomendadas com o uso de três anti-hipertensivos de diferentes\nclasses.","C":"Permanece acima das metas recomendadas com o uso de dois anti-hipertensivos de diferentes\nclasses.","D":"Permanece acima das metas recomendadas com o uso de três anti-hipertensivos de classes\niguais."},"answer":"B","source":"Clinica médica/MED CLM 03/MED CLM 03.txt","sourceLabel":"MED · MED CLM 03","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-03-278610","number":"278610","sourceNumber":"278610","collectionBlock":"med:med-clinica-medica-med-clm-03","collectionLabel":"MED · MED CLM 03","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 03","subtopic":"","stem":"Durante a abordagem da Emergências Hipertensivas (EH), o profissional deverá\nrealizar a diferenciação entre emergência e\nurgência, fazendo o diagnóstico correto das diversas\nsituações de EH, a fim de selecionar a terapia mais adequada para cada Lesão de Órgão Alvo\nLOA.","options":{"A":"Isso é muito importante, pois o diagnóstico e o tratamento corretos podem evitar agravamento do\nquadro clínico decorrente da situação crítica.","B":"Isso é muito importante, pois o diagnóstico e o tratamento corretos não evitam agravamento do\nquadro clínico decorrente da situação crítica.","C":"Isso não é importante, pois o diagnóstico e o tratamento incorretos podem evitar agravamento\ndo quadro clínico decorrente da situação crítica.","D":"Isso é muito importante, pois o diagnóstico e o tratamento incorretos podem evitar agravamento\ndo quadro clínico decorrente da situação\ncrítica."},"answer":"A","source":"Clinica médica/MED CLM 03/MED CLM 03.txt","sourceLabel":"MED · MED CLM 03","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-03-278611","number":"278611","sourceNumber":"278611","collectionBlock":"med:med-clinica-medica-med-clm-03","collectionLabel":"MED · MED CLM 03","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 03","subtopic":"","stem":"A proteína C reativa elevada foi preditoras independente de doença coronariana e\ncerebrovascular, podemos indicar como correto que:","options":{"A":"Sendo um marcador menos importante para hipertensos resistentes mais jovens, obesos, com\nMAPA não controlado e padrão não dipper\n(descenso noturno ausente ou atenuado).","B":"Sendo um marcador mais importante para hipertensos resistentes mais idosos, obesos, com\nMAPA não controlado e padrão não dipper\n(descenso noturno ausente ou atenuado).","C":"Sendo um marcador mais importante para hipertensos resistentes mais jovens, obesos, com\nMAPA controlado e padrão dipper (descenso noturno\nausente ou atenuado).","D":"Sendo um marcador mais importante para hipertensos resistentes mais jovens, obesos, com\nMAPA não controlado e padrão não dipper\n(descenso noturno ausente ou atenuado)."},"answer":"D","source":"Clinica médica/MED CLM 03/MED CLM 03.txt","sourceLabel":"MED · MED CLM 03","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-03-278613","number":"278613","sourceNumber":"278613","collectionBlock":"med:med-clinica-medica-med-clm-03","collectionLabel":"MED · MED CLM 03","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 03","subtopic":"","stem":"Atualmente, várias opções terapêuticas medicamentosas estão disponíveis para o\ntratamento das Emergências Hipertensivas (EH). O fármaco anti-hipertensivo ideal para uso\nparenteral deve apresentar as seguintes características listadas abaixo, indique a errada.","options":{"A":"capacidade de reverter alterações fisiopatológicas envolvidas.","B":"rápido início de ação.","C":"curva dose-resposta imprevisível.","D":"mínimo ajuste de dosagem."},"answer":"C","source":"Clinica médica/MED CLM 03/MED CLM 03.txt","sourceLabel":"MED · MED CLM 03","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-03-278086","number":"278086","sourceNumber":"278086","collectionBlock":"med:med-clinica-medica-med-clm-03","collectionLabel":"MED · MED CLM 03","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 03","subtopic":"","stem":"Assim, hipertensão arterial resistente não controlada (HAR-NC) é definida como uma\nPA que permanece acima do nível desejado\n(140/90 mmHg), sendo correto o item:","options":{"A":"Apesar do uso não concomitante de quatro ou mais agentes anti-hipertensivos de diferentes\nclasses e um quarto fármaco, que geralmente é\num antagonista do receptor mineralocorticoide ou\num bloqueador simpático central.","B":"Apesar do uso concomitante de quatro ou mais agentes anti-hipertensivos de iguais classes e\num quarto fármaco, que geralmente é um antagonista do receptor mineralocorticoide ou um\nbloqueador simpático central.","C":"Apesar do uso concomitante de quatro ou mais agentes anti-hipertensivos de diferentes classes\ne um quarto fármaco, que geralmente é um\nantagonista do receptor mineralocorticoide ou um\nbloqueador simpático central.","D":"Apesar do uso concomitante de quatro ou mais agentes anti-hipertensivos de diferentes classes\ne um quarto fármaco, que não pode ser um\nantagonista do receptor mineralocorticoide ou um\nbloqueador simpático central."},"answer":"C","source":"Clinica médica/MED CLM 03/MED CLM 03.txt","sourceLabel":"MED · MED CLM 03","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-03-279080","number":"279080","sourceNumber":"279080","collectionBlock":"med:med-clinica-medica-med-clm-03","collectionLabel":"MED · MED CLM 03","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 03","subtopic":"","stem":"Para o diagnóstico de Síndrome Metabólica segundo o AdultTreatment Panel III\n(ATP-III), são consideradas as seguintes referências, exceto","options":{"A":"cintura abdominal maior que 88 cm.","B":"triglicerídeos acima de 150 mg/dl.","C":"HDL colesterol acima de 50 mg/dl.","D":"glicose acima de 100 mg/dl."},"answer":"C","source":"Clinica médica/MED CLM 03/MED CLM 03.txt","sourceLabel":"MED · MED CLM 03","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-03-249381","number":"249381","sourceNumber":"249381","collectionBlock":"med:med-clinica-medica-med-clm-03","collectionLabel":"MED · MED CLM 03","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 03","subtopic":"","stem":"Considerando as aplicações da monitorização residencial da pressão arterial, não\npodemos apenas indicar como inadequado que:","options":{"A":"As variações dia a dia da PA podem ser avaliadas.","B":"Variações permitem estabelecer separadamente as medidas do período matinal e do\nentardecer/anoitecer.","C":"A PA matinal não pode estar associada a dano em órgão-alvo como AVE.","D":"A associação de dano em órgão-alvo com a PA durante o entardecer/anoitecer da MRPA pode\nser equivalente à PA durante o sono da MAPA."},"answer":"C","source":"Clinica médica/MED CLM 03/MED CLM 03.txt","sourceLabel":"MED · MED CLM 03","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-03-249285","number":"249285","sourceNumber":"249285","collectionBlock":"med:med-clinica-medica-med-clm-03","collectionLabel":"MED · MED CLM 03","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 03","subtopic":"","stem":"No diabetes, a hipotensão ortostática (HO) ocorre, frequentemente, consiste em\nredução da PA sistólica, de pelo menos 20\nmmHg, ou da PA diastólica, de pelo menos 10 mmHg,\nem 1 a 3 minutos após se assumir posição ortostática. Sendo correto que:","options":{"A":"Consequência de denervação parassimpática vasomotora eferente, reduzindo a vasoconstrição\ndo leito vascular esplâncnico e periférico.","B":"Consequência de denervação simpática vasomotora aferente, reduzindo a vasoconstrição do\nleito vascular esplâncnico e periférico.","C":"Consequência de denervação simpática vasomotora eferente, reduzindo a vasoconstrição do\nleito vascular esplâncnico e periférico.","D":"Consequência de denervação simpática vasomotora eferente, aumentando a vasoconstrição do\nleito vascular esplâncnico e periférico."},"answer":"C","source":"Clinica médica/MED CLM 03/MED CLM 03.txt","sourceLabel":"MED · MED CLM 03","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-03-249327","number":"249327","sourceNumber":"249327","collectionBlock":"med:med-clinica-medica-med-clm-03","collectionLabel":"MED · MED CLM 03","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 03","subtopic":"","stem":"Além das dosagens bioquímicas, a eletroforese de lipoproteínas ainda é utilizada por\nalguns médicos na prática clínica. O item com erro é:","options":{"A":"Atualmente, esse exame só é necessário em casos muito isolados, como na constatação da\nausência de lipoproteínas.","B":"Na maioria dos casos, a eletroforese de lipoproteínas não auxilia na tomada de decisões\nclínicas.","C":"O perfil lipídico deve ser determinado em indivíduos com dieta habitual, estado metabólico e\npeso estáveis por pelo menos 2 meses antes da\nrealização do exame.","D":"Devem-se evitar a ingestão de álcool e a prática de atividade física vigorosa nas 72 e 24 horas\nque antecedem a coleta de sangue."},"answer":"C","source":"Clinica médica/MED CLM 03/MED CLM 03.txt","sourceLabel":"MED · MED CLM 03","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-03-249263","number":"249263","sourceNumber":"249263","collectionBlock":"med:med-clinica-medica-med-clm-03","collectionLabel":"MED · MED CLM 03","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 03","subtopic":"","stem":"A diretriz brasileira para prevenção de doença cardiovascular no diabetes recomenda\nque se utilizem metas de tratamento para o\ncolesterol, apenas um dos itens abaixo está errado,\ndemonstre o item com erro:","options":{"A":"Pode servir de referência tanto o LDL-c como o não HDL-c.","B":"O não HDL-c é recomendado quando os níveis de TG estiverem acima de 300 mg/dL.","C":"A recomendação desta diretriz corresponde tanto a pacientes que nunca passaram por\ntratamento como a pacientes já em uso de estatina.","D":"O objetivo do uso de metas é, principalmente, garantir a adesão ao tratamento, visto que existe\npouca variabilidade de resposta a uma mesma dose de estatina."},"answer":"D","source":"Clinica médica/MED CLM 03/MED CLM 03.txt","sourceLabel":"MED · MED CLM 03","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-03-215470","number":"215470","sourceNumber":"215470","collectionBlock":"med:med-clinica-medica-med-clm-03","collectionLabel":"MED · MED CLM 03","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 03","subtopic":"","stem":"Elevação matinal precoce da PA ? calculada pela diferença entre a PAS matinal (média\ndas pressões nas primeiras duas horas após o\ndespertar) e a menor PAS durante o sono (média da\npressão mais baixa e das pressões imediatamente antes e após a mais baixa) ? tem sido associada\na desfechos cardiovasculares. É CORRETO, apenas, que:","options":{"A":"A dificuldade da padronização do cálculo desse parâmetro e a sua baixa reprodutibilidade\nindicam que deve ser usado na prática clínica.","B":"A dificuldade da padronização do cálculo desse parâmetro e a sua baixa reprodutibilidade\nindicam que ele não deve ser usado na prática\nclínica.","C":"A facilidade da padronização do cálculo desse parâmetro e a sua baixa reprodutibilidade indicam\nque ele não deve ser usado na prática clínica.","D":"A dificuldade da padronização do cálculo desse parâmetro e a sua alta reprodutibilidade indicam\nque ele não deve ser usado na prática clínica."},"answer":"B","source":"Clinica médica/MED CLM 03/MED CLM 03.txt","sourceLabel":"MED · MED CLM 03","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-03-215485","number":"215485","sourceNumber":"215485","collectionBlock":"med:med-clinica-medica-med-clm-03","collectionLabel":"MED · MED CLM 03","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 03","subtopic":"","stem":"A variabilidade extraída a partir das diferenças de cada medida é denominada\nvariabilidade de curto período (short term variability). Aponte, apenas. a CORRETA.","options":{"A":"Está identificada uma associação positiva entre mortalidade e variabilidade sistólica diurna de\ncurto período. Diante de tais resultados, a redução da variabilidade da PA não têm implicações\nterapêuticas independentemente da redução das médias de PA.","B":"Está identificada uma associação positiva entre mortalidade e variabilidade sistólica diurna de\ncurto período. Diante de tais resultados, a redução da variabilidade da PA poderia ter implicações\nterapêuticas independentemente da redução das médias de PA.","C":"Está identificada uma associação positiva entre mortalidade e variabilidade sistólica diurna de\ncurto período. Diante de tais resultados, a redução da variabilidade da PA poderia ter implicações\nterapêuticas dependentemente da redução das médias de PA.","D":"Está identificada uma associação negativa entre mortalidade e variabilidade sistólica diurna de\ncurto período. Diante de tais resultados, a redução da variabilidade da PA poderia ter implicações\nterapêuticas independentemente da redução das médias de PA."},"answer":"B","source":"Clinica médica/MED CLM 03/MED CLM 03.txt","sourceLabel":"MED · MED CLM 03","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-03-215510","number":"215510","sourceNumber":"215510","collectionBlock":"med:med-clinica-medica-med-clm-03","collectionLabel":"MED · MED CLM 03","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 03","subtopic":"","stem":"As cargas de pressões da MAPA expressam a percentagem de medidas acima dos\nvalores de normalidade para as 24 horas, vigília e sono.","options":{"A":"Avaliação prospectiva em estudo populacional indica que esse parâmetro possa modificar a\nestratificação de risco fornecida pelas médias de PA.","B":"Avaliação prospectiva em estudo populacional não indica que esse parâmetro não possa\nmodificar a estratificação de risco não fornecida pelas médias de PA.","C":"Avaliação prospectiva em estudo populacional não indica que esse parâmetro possa modificar a\nestratificação de risco fornecida pelas baixas e não médias de PA.","D":"Avaliação prospectiva em estudo populacional não indica que esse parâmetro possa modificar a\nestratificação de risco fornecida pelas médias de PA."},"answer":"D","source":"Clinica médica/MED CLM 03/MED CLM 03.txt","sourceLabel":"MED · MED CLM 03","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-03-201752","number":"201752","sourceNumber":"201752","collectionBlock":"med:med-clinica-medica-med-clm-03","collectionLabel":"MED · MED CLM 03","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 03","subtopic":"","stem":"Conforme a V Diretriz Brasileira de Dislipidemia, qual deve ser a meta de LDL colesterol\nao ser alcançada para uma mulher de 60 anos,\nhipertensa e que foi submetida à angioplastia\ncoronariana percutânea?","options":{"A":"< 160 mg/dl.","B":"< 130 mg/dl.","C":"< 100 mg/dl.","D":"< 70 mg/dl.","E":"< 50 mg/dl."},"answer":"E","source":"Clinica médica/MED CLM 03/MED CLM 03.txt","sourceLabel":"MED · MED CLM 03","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-03-212201","number":"212201","sourceNumber":"212201","collectionBlock":"med:med-clinica-medica-med-clm-03","collectionLabel":"MED · MED CLM 03","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 03","subtopic":"","stem":"As dislipidemias de causas secundárias são decorrentes do estilo de vida inadequado,\nde certas condições mórbidas, ou de\nmedicamentos. Entre essas causas secundárias encontra-se\no tabagismo, que tipicamente determina a","options":{"A":"redução do HDL-c.","B":"elevação do colesterol total.","C":"elevação dos triglicerídes e do HDL-c.","D":"redução do HDL-c e elevação dos triglicérides.","E":"elevação dos triglicérides e colesterol total associado a redução do HDL-c."},"answer":"A","source":"Clinica médica/MED CLM 03/MED CLM 03.txt","sourceLabel":"MED · MED CLM 03","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-03-215478","number":"215478","sourceNumber":"215478","collectionBlock":"med:med-clinica-medica-med-clm-03","collectionLabel":"MED · MED CLM 03","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 03","subtopic":"","stem":"Assinale a alternativa INCORRETA sobre o efeito analgésico da medicação alfa-2\nagonista.","options":{"A":"Por via sistêmica, potencializa o efeito analgésico do opioide pela regulação do aumento da\nsubstância P (neuromodulador) no SNC.","B":"Estimula receptores alfa-2 agonistas com redução do estímulo simpático.","C":"Melhor efeito analgésico via epidural, pois atinge maiores concentrações.","D":"Por via oral, potencializa o efeito analgésico do opioide."},"answer":"D","source":"Clinica médica/MED CLM 03/MED CLM 03.txt","sourceLabel":"MED · MED CLM 03","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-03-183579","number":"183579","sourceNumber":"183579","collectionBlock":"med:med-clinica-medica-med-clm-03","collectionLabel":"MED · MED CLM 03","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 03","subtopic":"","stem":"Os linfócitos T, embora menos numerosos que os macrófagos no interior do ateroma,\nsão de grande importância na aterogênese.\nSendo assim, assinale a alternativa INCORRETA:","options":{"A":"Mediante interação com os macrófagos, por exemplo, as células T podem se diferenciar e\nproduzir citocinas que modulam o processo inflamatório local.","B":"As moléculas de adesão são responsáveis pela atração de monócitos e linfócitos para a\nintimidade da parede arterial.","C":"As citocinas amplificam a inflamação de enzimas proteolíticas, incapazes de degradar colágeno\ne outros componentes teciduais locais.","D":"Induzidos por proteínas quimiotáticas, os monócitos migram para o espaço subendotelial, onde\nse diferenciam em macrófagos, que por sua vez\ncaptam as LDL-ox, sem controle da quantidade\nrecebida."},"answer":"C","source":"Clinica médica/MED CLM 03/MED CLM 03.txt","sourceLabel":"MED · MED CLM 03","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-03-183624","number":"183624","sourceNumber":"183624","collectionBlock":"med:med-clinica-medica-med-clm-03","collectionLabel":"MED · MED CLM 03","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 03","subtopic":"","stem":"Existe considerável variação intraindividual nos lipídios plasmáticos. Estando\nINADEQUADO que:","options":{"A":"Decorre de fatores ambientais como atividade física, mas não variação sazonal.","B":"Tem sido descrita variação de 5% a 10% para o CT e superior a 20% para os TGs,\nparticularmente nos indivíduos que apresentam hipertrigliceridemia.","C":"Esta variação é de certa forma devida à variação analítica.","D":"Decorre de fatores ambientais como dieta."},"answer":"A","source":"Clinica médica/MED CLM 03/MED CLM 03.txt","sourceLabel":"MED · MED CLM 03","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-03-183645","number":"183645","sourceNumber":"183645","collectionBlock":"med:med-clinica-medica-med-clm-03","collectionLabel":"MED · MED CLM 03","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 03","subtopic":"","stem":"A maioria dos pacientes vai necessitar do uso de mais de um medicamento para que\nsejam atingidas as metas de controle de Hipertensão. Sendo INADEQUADO que:","options":{"A":"Pacientes com HA estágio 1 e com risco CV alto ou muito alto ou com DCV associada e aqueles\ncom estágio 2 ou 3 com ou sem outros FRCV associados, devem ser considerados para o uso de\ncombinação de fármacos.","B":"A utilização de associações de dois medicamentos em baixas dosagens em hipertensos estágio\n1, mesmo com baixo ou moderado risco CV, embora\nnão preferencial, também poderá ser\nconsiderada em casos individuais.","C":"Associação de DIU tiazídicos com poupadores de potássio. O uso de DIU de alça deve ser\nreservado para aqueles com RFG abaixo de 10 ml/min ou com edema grave.","D":"Para a escolha dos medicamentos em associação, deve ser evitado o uso de anti-hipertensivos\ncom mesmo mecanismo."},"answer":"C","source":"Clinica médica/MED CLM 03/MED CLM 03.txt","sourceLabel":"MED · MED CLM 03","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-03-183592","number":"183592","sourceNumber":"183592","collectionBlock":"med:med-clinica-medica-med-clm-03","collectionLabel":"MED · MED CLM 03","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 03","subtopic":"","stem":"Dentro das classes de anti-hipertensivos, atualmente consideradas preferenciais para o\ncontrole da PA em monoterapia inicial, são verdadeiras as indicações, EXCETO:","options":{"A":"Deve ser observado que os DIU são os fármacos que apresentam menos evidências de\nefetividade com relação aos desfechos CV, com\nclaros benefícios para todos os tipos de eventos.","B":"Há situações em que a indicação de um ou outro grupo ganha destaque, de acordo com a\ncomorbidade presente.","C":"O BB poderá ser considerado como fármaco inicial em situações específicas, como a\nassociação de enxaqueca.","D":"O BB poderá ser considerado como fármaco inicial em situações específicas, como a IC e a\ncoronariopatia."},"answer":"A","source":"Clinica médica/MED CLM 03/MED CLM 03.txt","sourceLabel":"MED · MED CLM 03","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-03-182750","number":"182750","sourceNumber":"182750","collectionBlock":"med:med-clinica-medica-med-clm-03","collectionLabel":"MED · MED CLM 03","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 03","subtopic":"","stem":"Uma das premissas mais importantes é de que a decisão sobre o uso de estatinas em\npacientes com diabetes deve basear-se na estratificação do risco cardiovascular. Somente\npodemos CONCORDAR que, estudos recentes mostram que nem todos os pacientes com diabetes\nsão","options":{"A":"de alto risco, e quase 30% deles apresentam risco semelhante ao de pessoas sem diabetes.\n\nPortanto, o conceito de diabetes como equivalência de risco é questionável e tende a levar ao\nsupertratamento.","B":"de alto risco, e quase 60% deles apresentam risco semelhante ao de pessoas sem diabetes.\n\nPortanto, o conceito de diabetes como equivalência de risco é questionável e tende a levar ao\nsupertratamento.","C":"de médio risco, e quase 30% deles apresentam risco semelhante ao de pessoas sem diabetes.\n\nPortanto, o conceito de diabetes como equivalência de risco é questionável e tende a levar ao\nsupertratamento.","D":"de alto risco, e quase 30% deles apresentam risco semelhante ao de pessoas sem diabetes.\n\nPortanto, o conceito de diabetes como equivalência de risco não é questionável e tende a levar ao\nsupertratamento."},"answer":"A","source":"Clinica médica/MED CLM 03/MED CLM 03.txt","sourceLabel":"MED · MED CLM 03","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-03-181338","number":"181338","sourceNumber":"181338","collectionBlock":"med:med-clinica-medica-med-clm-03","collectionLabel":"MED · MED CLM 03","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 03","subtopic":"","stem":"Paciente do sexo masculino, 50 anos, obeso, diabético tipo 2, com HDL baixo e função\nrenal normal, vem mantendo pressão arterial de 145 x 95 mmHg. Diante do quadro, qual a conduta\nterapêutica e meta pressórica a ser atingida?","options":{"A":"Mudança do estilo de vida associada ao tratamento medicamentoso, com meta pressórica < 140\nx 90 mmHg.","B":"Mudança do estilo de vida associada ao tratamento medicamentoso, com meta pressórica < 140\nx 80 mmHg.","C":"Mudança do estilo de vida associada ao tratamento medicamentoso, com meta pressórica < 130\nx 80 mmHg.","D":"Mudança do estilo de vida por 3 meses; na falta de controle pressórico nesse período, iniciar\ntratamento farmacológico. Meta pressórica < 130 x 80 mmHg.","E":"Mudança do estilo de vida por 6 meses; na falta de controle pressórico nesse período, iniciar\ntratamento farmacológico. Meta pressórica < 130 x 80 mmHg."},"answer":"C","source":"Clinica médica/MED CLM 03/MED CLM 03.txt","sourceLabel":"MED · MED CLM 03","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-03-183108","number":"183108","sourceNumber":"183108","collectionBlock":"med:med-clinica-medica-med-clm-03","collectionLabel":"MED · MED CLM 03","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 03","subtopic":"","stem":"A Organização Mundial da Saúde passou a recomendar redução de açúcares e de\ncarboidratos, a partir de 2015, o consumo máximo de 5% em Kcal do valor energético da dieta na\nforma de açúcares de adição, nos quais se incluem a sacarose e o xarope de milho. Sobre isso,\nassinale o item INADEQUADO:","options":{"A":"Tanto a sacarose quanto os xaropes são constituídos por aproximadamente partes iguais de\nfrutose e glicose, os quais são metabolizados de forma diferente.","B":"Enquanto existe um mecanismo celular de feedback de regulação da glicose mediado pela\nfosfofrutoquinase, para a produção de piruvato e, consequentemente, de acetil-CoA e ácidos\ngraxos, o mesmo mecanismo não ocorre para metabolização da frutose, que é metabolizada pela\nfrutoquinase.","C":"Desta forma, a frutose gera ácidos graxos mais rapidamente do que a glicose, aumentando tanto\no depósito de gordura hepática, como o aumento\nda produção de VLDL.","D":"Estudos mostram que o consumo superior a 50 g de frutose ao dia abaixa o TG pós-prandial."},"answer":"D","source":"Clinica médica/MED CLM 03/MED CLM 03.txt","sourceLabel":"MED · MED CLM 03","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-03-181423","number":"181423","sourceNumber":"181423","collectionBlock":"med:med-clinica-medica-med-clm-03","collectionLabel":"MED · MED CLM 03","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 03","subtopic":"","stem":"A hipertensão arterial, na infância, é fator previsor de hipertensão arterial no adulto e\nsua aferição nas consultas pediátricas deve ser\nrealizada:","options":{"A":"em toda criança a partir do primeiro ano de idade.","B":"com manguito que deixe descoberta a fossa cubital.","C":"em todas as avaliações médicas de rotina, desde o período escolar.","D":"em crianças portadoras de condições especiais que representem risco elevado para\nhipertensão.","E":"em toda criança a partir de três anos de idade e também nas menores de três anos, se forem\nprematuras, com complicações neonatais, genitourinárias e outras doenças associadas com\nhipertensão arterial."},"answer":"E","source":"Clinica médica/MED CLM 03/MED CLM 03.txt","sourceLabel":"MED · MED CLM 03","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-03-182806","number":"182806","sourceNumber":"182806","collectionBlock":"med:med-clinica-medica-med-clm-03","collectionLabel":"MED · MED CLM 03","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 03","subtopic":"","stem":"A análise dos níveis de TG sem jejum prévio fornece informações importantes sobre\nlipoproteínas remanescentes associadas com risco aumentado de doença coronária, estando\nINCORRETO apenas que:","options":{"A":"Níveis elevados de TG se associam frequentemente a elevados níveis de HDL-c.","B":"A avaliação de Triglicérides TG é determinada por técnica enzimática.","C":"A grande variabilidade biológica dos TG é a principal fonte de oscilações nos seus resultados.","D":"A técnica enzimática é método preciso e de baixo custo."},"answer":"A","source":"Clinica médica/MED CLM 03/MED CLM 03.txt","sourceLabel":"MED · MED CLM 03","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-03-183120","number":"183120","sourceNumber":"183120","collectionBlock":"med:med-clinica-medica-med-clm-03","collectionLabel":"MED · MED CLM 03","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 03","subtopic":"","stem":"Atualmente, as recentes diretrizes e guias internacionais apontam para os benefícios de\npadrões alimentares saudáveis, como demonstrado nos estudos que testaram a eficiência da Dieta\ndo Mediterrâneo, nos quais a matriz alimentar assume papel de destaque. Somente NÃO podemos\nconsiderar adequada uma das alternativas abaixo, assinale-a.","options":{"A":"Ocorre relevância de se manterem quantidades moderadas de gordura na dieta, eliminar ácidos\ngraxos trans, controlar o consumo de saturados, priorizar poliinsaturados e monoinsaturados,\nreduzir açúcares e incluir carnes magras, frutas, grãos e hortaliças na dieta.","B":"O alcance das metas nutricionais no tratamento é variável e depende da adesão à dieta e às\ncorreções no estilo de vida, como perda de peso, e pode resultar na redução de 20% da\nconcentração plasmática de TG.","C":"Além do controle de calorias na dieta (déficit de 500 a 1.000 Kcal), enfatiza-se a relevância da\nqualidade dos nutrientes em aspectos relacionados ao desenvolvimento da obesidade, como\nsaciedade, resposta insulínica, lipogênese hepática, adipogênese, gasto energético e microbiota.","D":"O consumo de bebida alcoólica é recomendado para indivíduos com hipertrigliceridemia, por não\ninterferir. Paradoxo francês."},"answer":"A","source":"Clinica médica/MED CLM 03/MED CLM 03.txt","sourceLabel":"MED · MED CLM 03","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 03","MED"],"answerSource":"inferred","commentDeferred":true},{"id":"med-clinica-medica-med-clm-03-183113","number":"183113","sourceNumber":"183113","collectionBlock":"med:med-clinica-medica-med-clm-03","collectionLabel":"MED · MED CLM 03","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 03","subtopic":"","stem":"Um consumo excessivo de etanol potencializa a elevação da trigliceridemia, mas ocorre\nalguma divergência no impacto da ingestão de etanol nos Triacilgliceróis (TAG) em situações de\nconsumo moderado (até 30g/dia). Sobre isso, podemos considerar INADEQUADO que:","options":{"A":"O consumo de bebida alcoólica não é recomendado para indivíduos com hipertrigliceridemia.","B":"A inibição da lipase das lipoproteínas pelo excesso de etanol e o cosequente aumento na\nhidrólise de quilomícrons parecem justificar a lipemia induzida pelo etanol.","C":"O produto da metabolização do álcool é a Acetilcoenzima A (acetil-CoA), principal precursora da\nsíntese de ácidos graxos.","D":"A combinação de um consumo excessivo de etanol e ácidos graxos saturados potencializa a\nelevação da trigliceridemia."},"answer":"B","source":"Clinica médica/MED CLM 03/MED CLM 03.txt","sourceLabel":"MED · MED CLM 03","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-03-183123","number":"183123","sourceNumber":"183123","collectionBlock":"med:med-clinica-medica-med-clm-03","collectionLabel":"MED · MED CLM 03","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 03","subtopic":"","stem":"As diferentes fontes de ômega 3, por meio da diminuição da lipogênese hepática e da\nLPL, contribuem de forma significativa com a redução de triglicerídeos, somente sendo\nINADEQUADO o conceito de que:","options":{"A":"Os ácidos graxos saturados da dieta relacionam-se com a elevação da trigliceridemia, por\ndiminuírem a lipogênese hepática e a secreção de VLDL.","B":"É recomendada a inclusão de poli e monoinsturados. O ácido Alfalinolenico (ALA) produz\npequenas quantidades endógenas de EPA e DHA, e também\nexerce ação cardioprotetora.","C":"Para indivíduos com níveis de TG muito altos, se recomenda uma redução significativa em\ngordura saturada, o que diminui o risco de pancreatite.","D":"Dentre os ácidos graxos poliinsaturados, os da série ômega 3 são reconhecidos pela atividade\ncardioprotetora."},"answer":"A","source":"Clinica médica/MED CLM 03/MED CLM 03.txt","sourceLabel":"MED · MED CLM 03","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-03-183037","number":"183037","sourceNumber":"183037","collectionBlock":"med:med-clinica-medica-med-clm-03","collectionLabel":"MED · MED CLM 03","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 03","subtopic":"","stem":"A análise do ECG pode complementar a avaliação cardiológica e permitir a identificação\nde pacientes com alto risco cardíaco operatório.\nSendo INADEQUADO, apenas, o seguinte:","options":{"A":"O ECG proporciona a detecção de arritmias, distúrbios de condução, isquemia miocárdica ou\nInfarto Agudo do Miocárdio (IAM) prévio, sobrecargas ventriculares e alterações decorrentes de\ndistúrbios eletrolíticos ou de efeitos de medicamentos.","B":"A aplicação de rotina de um teste com especificidade limitada pode levar à ocorrência de\nresultados falso-positivos em pacientes\n\nassintomáticos, uma vez que as alterações eletrocardiográficas costumam ser causa de\npreocupação da equipe cirúrgica e anestésica\ne, muitas vezes, podem levar ao cancelamento\ndesnecessário da operação.","C":"As anormalidades encontradas no ECG tendem a aumentar com a idade e a existência de\ncomorbidades.","D":"Um traçado eletrocardiográfico basal não se mostra importante para a avaliação comparativa no\nperioperatório em pacientes com alto risco de ocorrência de eventos cardiovasculares."},"answer":"D","source":"Clinica médica/MED CLM 03/MED CLM 03.txt","sourceLabel":"MED · MED CLM 03","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-03-182741","number":"182741","sourceNumber":"182741","collectionBlock":"med:med-clinica-medica-med-clm-03","collectionLabel":"MED · MED CLM 03","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 03","subtopic":"","stem":"Aspectos importantes na medição da PA na população idosa decorrem de alterações\npróprias do envelhecimento, com grande interação nos achados e na interpretação clínica da\nsituação, sendo assim, assinale a alternativa CORRETA:","options":{"A":"A pseudo-hipertensão, que está associada ao processo aterosclerótico, pode ser detectada pela\nmanobra de Osler, ou seja, a artéria radial permanece ainda palpável após a insuflação do\nmanguito pelo menos 30 mmHg acima do desaparecimento do pulso radial. Maior ocorrência de\nEAB, hipotensão ortostática e pós-prandial e, finalmente, a presença de arritmias, como fibrilação\natrial, podem dificultar a medição da PA.","B":"A pseudo-hipertensão, não está associada ao processo aterosclerótico, pode ser detectada pela\nmanobra de Osler, ou seja, a artéria radial permanece ainda palpável após a insuflação do\nmanguito pelo menos 30 mmHg acima do desaparecimento do pulso radial. Maior ocorrência de\nEAB, hipotensão ortostática e pós-prandial e, finalmente, a presença de arritmias, como fibrilação\natrial, podem dificultar a medição da PA.","C":"A pseudo-hipertensão, que está associada ao processo aterosclerótico, pode ser detectada pela\nmanobra de Osler, ou seja, a artéria radial permanece impalpável após a insuflação do manguito\npelo menos 30 mmHg acima do desaparecimento do pulso radial. Maior ocorrência de EAB,\nhipotensão ortostática e pós-prandial e, finalmente, a presença de arritmias, como fibrilação\natrial,\npodem dificultar a medição da PA.","D":"A pseudo-hipertensão, que está associada ao processo aterosclerótico, pode ser detectada pela\nmanobra de Osler, ou seja, a artéria radial permanece ainda palpável após a insuflação do\nmanguito pelo menos 50 mmHg acima do desaparecimento do pulso radial. Maior ocorrência de\nEAB, hipotensão ortostática e pós-prandial e, finalmente, a presença de arritmias, como fibrilação\natrial, podem dificultar a medição da PA."},"answer":"A","source":"Clinica médica/MED CLM 03/MED CLM 03.txt","sourceLabel":"MED · MED CLM 03","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-03-183044","number":"183044","sourceNumber":"183044","collectionBlock":"med:med-clinica-medica-med-clm-03","collectionLabel":"MED · MED CLM 03","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 03","subtopic":"","stem":"A aterosclerose é uma doença inflamatória crônica de origem multifatorial, que ocorre\nem resposta à agressão endotelial, acometendo\nprincipalmente a camada íntima de artérias de\nmédio e grande calibre. Sendo INADEQUADO que:","options":{"A":"em geral, as lesões iniciais, denominadas estrias gordurosas, formam-se ainda na infância e\ncaracterizam-se por acúmulo de\n\ncolesterol em macrófagos.","B":"com o tempo, mecanismos protetores levam à redução do tecido matricial, que circunda o núcleo\nlipídico mas, na presença de\n\nsubtipos de linfócitos de fenótipo mais inflamatório, a formação do tecido matricial se reduz.","C":"com o tempo, mecanismos protetores levam ao aumento do tecido matricial, que circunda o\nnúcleo lipídico.","D":"com o tempo, mecanismos protetores levam ao aumento do tecido matricial, na presença de\nsubtipos de linfócitos de fenótipo\n\nmais inflamatório."},"answer":"B","source":"Clinica médica/MED CLM 03/MED CLM 03.txt","sourceLabel":"MED · MED CLM 03","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-03-182760","number":"182760","sourceNumber":"182760","collectionBlock":"med:med-clinica-medica-med-clm-03","collectionLabel":"MED · MED CLM 03","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 03","subtopic":"","stem":"Ocorre uma grande variação da PA nos idosos ao longo das 24 horas, o que torna a\nMAPA uma ferramenta muitas vezes útil, também a pseudo-hipertensão, que está associada ao\nprocesso aterosclerótico, pode ser detectada pela manobra de Osler. Dessa forma, indique a\nalternativa CORRETA:","options":{"A":"Aspectos especiais na medição da PA na população idosa decorrem de alterações próprias do\nenvelhecimento, como a menor frequência do hiato auscultatório, que consiste no desaparecimento\ndos sons durante a deflação do manguito, resultando em valores falsamente baixos para a PAS ou\nfalsamente altos para a PAD.","B":"Aspectos especiais na medição da PA na população idosa decorrem de alterações próprias do\nenvelhecimento, como a maior frequência do hiato auscultatório, que consiste no aparecimento\nprecoce dos sons durante a deflação do manguito, não resultando em valores falsamente baixos\npara a PAS ou falsamente altos para a PAD.","C":"Aspectos especiais na medição da PA na população idosa decorrem de alterações próprias do\nenvelhecimento, como a maior frequência do hiato auscultatório, que consiste no desaparecimento\ndos sons durante a deflação do manguito, resultando em valores falsamente baixos para a PAS ou\nfalsamente altos para a PAD.","D":"Aspectos especiais na medição da PA na população idosa decorrem de alterações próprias do\nenvelhecimento, como a maior frequência do hiato auscultatório, que consiste no aparecimento dos\nsons durante a deflação do manguito, resultando em valores falsamente baixos para a PAS ou\nfalsamente baixos para a PAD."},"answer":"C","source":"Clinica médica/MED CLM 03/MED CLM 03.txt","sourceLabel":"MED · MED CLM 03","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-03-183061","number":"183061","sourceNumber":"183061","collectionBlock":"med:med-clinica-medica-med-clm-03","collectionLabel":"MED · MED CLM 03","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 03","subtopic":"","stem":"A formação da placa aterosclerótica inicia-se com a agressão ao endotélio vascular por\ndiversos fatores de risco, como dislipidemia, hipertensão arterial ou tabagismo. Sendo\nADEQUADO, apenas, que o depósito de lipoproteínas","options":{"A":"na parede arterial, processo secundário no início da aterogênese, ocorre de maneira\nproporcional à concentração dessas lipoproteínas no plasma.","B":"na parede arterial, processo chave no início da aterogênese, ocorre de maneira desproporcional\nà concentração dessas lipoproteínas no plasma.","C":"na parede arterial, processo chave no início da aterogênese, ocorre de maneira proporcional à\nconcentração dessas lipoproteínas no plasma.","D":"na parede venosa, processo chave no início da aterogênese, ocorre de maneira proporcional à\nconcentração dessas lipoproteínas no plasma."},"answer":"C","source":"Clinica médica/MED CLM 03/MED CLM 03.txt","sourceLabel":"MED · MED CLM 03","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-03-182792","number":"182792","sourceNumber":"182792","collectionBlock":"med:med-clinica-medica-med-clm-03","collectionLabel":"MED · MED CLM 03","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 03","subtopic":"","stem":"A decisão terapêutica para tratamento da Pressão Arterial deve basear-se não apenas\nno nível da PA, mas considerar também a\npresença de Fatores de Risco, Lesões de Órgãos Alvos\ne Doença Cardiovascular concomitante. Em relação a isso, assinale a alternativa INCORRETA:","options":{"A":"Por outro lado, resultados de estudos clínicos controlados e randomizados com uso de fármacos\nanti-hipertensivos placebo-controlados em hipertensos demonstraram claramente redução\nsignificativa de mortalidade CV, AVE, infarto do miocárdio e IC. Cabe destacar que a maioria\ndesses estudos avaliou indivíduos com idade \"maior ou igual que\" 55 anos, de alto risco CV e\ntempo de seguimento de 3 a 6 anos, limitando, portanto, a extrapolação desses benefícios para o\ntratamento de longo prazo e em pacientes com outras características.","B":"Indivíduos com PA \"maior ou igual que\" 160/100 mmHg e/ou portadores de risco CV estimado\nalto, mesmo no estágio 1, devem iniciar de\nimediato o tratamento medicamentoso associado à\nterapia não medicamentosa.","C":"A abordagem terapêutica da PA elevada inclui medidas não medicamentosas e o uso de\nfármacos anti-hipertensivos, a fim de reduzir a PA,\nproteger órgãos-alvo, prevenir desfechos CV e\nrenais. Medidas não medicamentosas têm se mostrado ruins na redução da PA, pela perda de\nadesão a curto prazo.","D":"Estudos com fármacos anti-hipertensivos, a maioria realizada com esse perfil de pacientes\nhipertensos estágios 2 e 3 e/ou de alto risco,\ndemonstraram eficácia na redução da PA e proteção\nCV."},"answer":"C","source":"Clinica médica/MED CLM 03/MED CLM 03.txt","sourceLabel":"MED · MED CLM 03","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-03-183103","number":"183103","sourceNumber":"183103","collectionBlock":"med:med-clinica-medica-med-clm-03","collectionLabel":"MED · MED CLM 03","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 03","subtopic":"","stem":"Os macrófagos repletos de lípides são chamados de células espumosas e são o\nprincipal componente das estrias gordurosas, lesões macroscópicas iniciais da aterosclerose.\nSendo CORRETO, apenas, que","options":{"A":"uma vez desativados, os macrófagos são, em grande parte, responsáveis pela progressão da\nplaca aterosclerótica por meio da secreção de\ncitocinas, que amplificam a inflamação, e de enzimas\nproteolíticas, capazes de degradar colágeno e outros componentes teciduais locais.","B":"uma vez ativados, os macrófagos são, em grande parte, responsáveis pela progressão da placa\naterosclerótica por meio da secreção de citocinas, que amplificam a inflamação, e de enzimas\nproteolíticas, capazes de degradar colágeno e outros componentes teciduais locais.","C":"uma vez ativados, os macrófagos são raramente responsáveis pela progressão da placa\naterosclerótica por meio da secreção de citocinas, que amplificam a inflamação, e de enzimas\nproteolíticas, capazes de degradar colágeno e outros componentes teciduais locais.","D":"uma vez ativados, os macrófagos são, em grande parte, responsáveis pela regressão da placa\naterosclerótica por meio da secreção de citocinas, que amplificam a inflamação, e de enzimas\nproteolíticas, capazes de degradar colágeno e outros componentes teciduais locais."},"answer":"B","source":"Clinica médica/MED CLM 03/MED CLM 03.txt","sourceLabel":"MED · MED CLM 03","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-03-182802","number":"182802","sourceNumber":"182802","collectionBlock":"med:med-clinica-medica-med-clm-03","collectionLabel":"MED · MED CLM 03","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 03","subtopic":"","stem":"A abordagem de hipertensos estágio 1 de risco baixo e moderado, apresenta uma\nlacuna no rol de evidências em favor do impacto da terapia anti-hipertensiva sobre a redução de\ndesfechos em hipertensos estágio 1 de risco baixo e moderado. Em relação a isso, assinale a\nalternativa INCORRETA:","options":{"A":"Nos hipertensos estágio 1 e moderado ou baixo risco CV, a terapia não farmacológica deve ser\ntentada por um ano.","B":"Findo esse período no qual a falta de controle da PA condicionará o início de terapia\nfarmacológica. Faz-se imperativo, contudo,\nacompanhar esses indivíduos com avaliação periódica\nda adesão às medidas não farmacológicas.","C":"Constatada a falta de adesão às medidas não farmacológicas ou a piora dos valores\npressóricos, dever-se-á iniciar precocemente a terapia farmacológica.","D":"Vale destacar que a intervenção em hipertensos de baixo risco no estágio 1 pode prevenir a\nprogressão para um risco CV mais elevado."},"answer":"A","source":"Clinica médica/MED CLM 03/MED CLM 03.txt","sourceLabel":"MED · MED CLM 03","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-03-158800","number":"158800","sourceNumber":"158800","collectionBlock":"med:med-clinica-medica-med-clm-03","collectionLabel":"MED · MED CLM 03","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 03","subtopic":"","stem":"Frequentemente há necessidade de associação de fármacos para o controle da\npressão arterial. Qual a associação de fármacos\nque deve ser usada com cautela em pacientes\ndiabéticos, em razão da dificuldade do controle glicêmico?","options":{"A":"Betabloqueadores e diuréticos.","B":"Diuréticos e bloqueadores dos receptores de angiotensina.","C":"Inibidores da enzima conversora angiotensina e diuréticos.","D":"Bloqueadores dos canais de cálcio e bloqueadores dos receptores de angiotensina.","E":"Bloqueadores dos canais de cálcio e inibidores da enzima conversora de angiotensina."},"answer":"A","source":"Clinica médica/MED CLM 03/MED CLM 03.txt","sourceLabel":"MED · MED CLM 03","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-03-158795","number":"158795","sourceNumber":"158795","collectionBlock":"med:med-clinica-medica-med-clm-03","collectionLabel":"MED · MED CLM 03","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 03","subtopic":"","stem":"Paciente, 45 anos, obesa, comparece ao ambulatório e relata ser hipertensa e\ndislipidêmica. Traz resultados de exames\nlaboratoriais: glicemia 120 mg/dl; triglicerídeos 180 mg/dl\ne LDL 160 mg/dl, e na consulta PA = 170 x 100 mmHg. Foi orientada a iniciar de imediato terapia\nnão medicamentosa. Conforme a 7ª Diretriz Brasileira de Hipertensão Arterial, qual o estágio da\nhipertensão quando deve ser iniciada a terapia medicamentosa, qual a meta e a melhor conduta\nterapêutica a ser implementada?","options":{"A":"Estágio 2, terapia medicamentosa deve ser iniciada após 3 meses da mudança no estilo de vida;\n\n< 130 x 80 mmHg; terapia combinada (duas classes diferentes).","B":"Estágio 2, terapia medicamentosa deve ser iniciada de imediato; < 140 x 90 mmHg; terapia\ncombinada (duas classes diferentes).","C":"Estágio 2, terapia medicamentosa deve ser iniciada de imediato; < 130 x 80 mmHg; terapia\ncombinada (duas classes diferentes).","D":"Estágio 2, terapia medicamentosa deve ser iniciada de imediato; < 130 x 80 mmHg;\nmonoterapia.","E":"Estágio 3, terapia medicamentosa deve ser iniciada de imediato; < 130 x 80 mmHg; terapia\ncombinada (duas classes diferentes)."},"answer":"C","source":"Clinica médica/MED CLM 03/MED CLM 03.txt","sourceLabel":"MED · MED CLM 03","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-03-161356","number":"161356","sourceNumber":"161356","collectionBlock":"med:med-clinica-medica-med-clm-03","collectionLabel":"MED · MED CLM 03","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 03","subtopic":"","stem":"Paciente feminina de 56 anos de idade, hipertensa mal controlada, evoluiu com\nagitação seguida de insuficiência respiratória\nnesta manhã. Sua pressão sistólica foi de 230 mmHg.\nQuando assumiu o seu turno no plantão, foi passado o caso como Encefalopatia Hipertensiva, após\ndiagnóstico por Tomografia de Crânio. Dos achados a seguir, qual deles, na Tomografia, NÃO é\ncompatível com o diagnóstico?","options":{"A":"Edema Cerebral.","B":"Apagamento de Sulcos.","C":"Lâmina hiperdensa.","D":"Dificuldade de separação de substância cinza e branca."},"answer":"C","source":"Clinica médica/MED CLM 03/MED CLM 03.txt","sourceLabel":"MED · MED CLM 03","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-03-161302","number":"161302","sourceNumber":"161302","collectionBlock":"med:med-clinica-medica-med-clm-03","collectionLabel":"MED · MED CLM 03","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 03","subtopic":"","stem":"Quando da escolha do tratamento anti-hipertensivo, ocorre a necessidade de grande\nraciocínio clínico a fim de determinar a escolha ideal, considerando paciente, mecanismo de ação\ndas medicações, bem como seus efeitos colaterais. Acerca desse assunto, indique a opção\nconsiderada INCORRETA.","options":{"A":"A metildopa pode provocar reações autoimunes, como febre, anemia hemolítica, galactorreia e\ndisfunção hepática, que na maioria dos casos desaparecem com a cessação do uso.","B":"Os Betabloqueadores promovem diminuição inicial do débito cardíaco, e aumento da secreção\nde renina, havendo readaptação dos\nbarorreceptores e aumento das catecolaminas nas sinapses\nnervosas.","C":"Os bloqueadores dos canais de cálcio agem primordialmente proporcionando redução da RVP\ncomo consequência da diminuição da quantidade de\ncálcio no interior das células musculares lisas\ndas arteríolas, decorrente do bloqueio dos canais de cálcio na membrana dessas células.","D":"Bloqueadores dos receptores AT1 da angiotensina II, os BRA antagonizam a ação da\nangiotensina II por meio do bloqueio específico dos receptores AT1, responsáveis pelas ações\nvasoconstritoras, proliferativas e estimuladoras da liberação de androsterona, próprias da\nangiotensina II."},"answer":"B","source":"Clinica médica/MED CLM 03/MED CLM 03.txt","sourceLabel":"MED · MED CLM 03","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-03-161392","number":"161392","sourceNumber":"161392","collectionBlock":"med:med-clinica-medica-med-clm-03","collectionLabel":"MED · MED CLM 03","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 03","subtopic":"","stem":"Paciente com Insuficiência Renal Crônica não dialítica apresenta hoje intensa dispneia\ndemonstrando em sua ausculta pulmonar estertores e roncos difusos, sendo sua saturação de\n80%. Foi indicado entubação e iniciada ventilação mecânica com altas FiO2. Sua pressão é de 230\nx 120 mmHg. Iniciado Nitroprussiato de Sódio e solicitado avaliação da Nefrologia para possível\nHemodiálise, assinale a alternativa considerada ADEQUADA.","options":{"A":"Provavelmente não ocorrerá necessidade de hemodiálise após controle da hipertensão.","B":"Foi inadequada a indicação de ventilação mecânica.","C":"A opção por nitroprussiato foi inadequada.","D":"Maior risco de toxicidade por disfunção orgânica."},"answer":"D","source":"Clinica médica/MED CLM 03/MED CLM 03.txt","sourceLabel":"MED · MED CLM 03","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-03-161226","number":"161226","sourceNumber":"161226","collectionBlock":"med:med-clinica-medica-med-clm-03","collectionLabel":"MED · MED CLM 03","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 03","subtopic":"","stem":"?Medicação que promove a inibição direta da ação da renina com consequente\ndiminuição da formação de angiotensina II.\nOutras ações podem contribuir para a redução da PA e\na proteção tissular, tais como redução da atividade plasmática de renina, bloqueio de um receptor\ncelular próprio de renina/pró-renina e diminuição da síntese intracelular de angiotensina II. Foi\ndemonstrado sua eficácia anti-hipertensiva, bem como sua capacidade, em sonoterapia, de\nredução da PA de intensidade semelhante aos demais anti-hipertensivos.? Marque a alternativa a\nque corresponde essa afirmação.","options":{"A":"BRA.","B":"IECA.","C":"Alisquireno.","D":"Betabloqueador."},"answer":"C","source":"Clinica médica/MED CLM 03/MED CLM 03.txt","sourceLabel":"MED · MED CLM 03","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-03-161197","number":"161197","sourceNumber":"161197","collectionBlock":"med:med-clinica-medica-med-clm-03","collectionLabel":"MED · MED CLM 03","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 03","subtopic":"","stem":"Acerca da pesquisa diagnóstica de complicações em órgãos-alvo, relacionadas com a\nHipertensão Arterial, as informações obtidas e otimizadas pelo Ecocardiograma estão corretas, com\nEXCEÇÃO de uma. Aponte-a.","options":{"A":"Menos sensível do que o ECG no diagnóstico de HVE.","B":"Agrega valor na avaliação das formas geométricas de hipertrofia e tamanho do átrio esquerdo.","C":"Análise da função sistólica e diastólica.","D":"Indicado na presença de indícios de HVE ao ECG ou pacientes com suspeita clínica de IC."},"answer":"A","source":"Clinica médica/MED CLM 03/MED CLM 03.txt","sourceLabel":"MED · MED CLM 03","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-03-161203","number":"161203","sourceNumber":"161203","collectionBlock":"med:med-clinica-medica-med-clm-03","collectionLabel":"MED · MED CLM 03","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 03","subtopic":"","stem":"Em relação à decisão de tratamento da abordagem de hipertensos estágios 2 e 3 e/ou\nde alto risco, assinale a alternativa\nconsiderada CORRETA.","options":{"A":"Indivíduos com PA (maior ou igual) 180/100 mmHg e/ou portadores de risco CV estimado alto,\nmesmo no estágio 1, devem iniciar de imediato o tratamento medicamentoso associado à terapia\nnão medicamentosa.","B":"Estudos com fármacos anti-hipertensivos, a maioria realizada com esse perfil de pacientes,\ndemonstraram eficácia na redução\n\nda PA e proteção CV.","C":"Admite-se que a terapia não farmacológica isoladamente possa promover reduções da PA\nsuficientes para o alcance da meta pressórica recomendada, sendo efetivo controle da PA e de\noutros FRCV frequentemente presentes.","D":"Embora o benefício absoluto da terapia seja menor nos estágios 2 e 3, também aumenta o risco\nresidual devido à frequente presença e influência de outros FR e LOA já instalada, neutralizando\nparte desse benefício. Essa observação reforça a importância de se abordar o risco CV de forma\nglobal."},"answer":"B","source":"Clinica médica/MED CLM 03/MED CLM 03.txt","sourceLabel":"MED · MED CLM 03","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-03-161270","number":"161270","sourceNumber":"161270","collectionBlock":"med:med-clinica-medica-med-clm-03","collectionLabel":"MED · MED CLM 03","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 03","subtopic":"","stem":"Dentre as possíveis causas de hipertensão arterial secundária, ou seja, com etiologia\ndefinida e, acima de tudo, potencialmente\ncurável, o Feocromocitoma (FEO) são tumores de células\ncromafins do eixo simpático-adreno-medular produtores de catecolaminas. A respeito disso, aponte\na alternativa INCORRETA.","options":{"A":"De 10% a 15% são extradrenais (paragangliomas), 10% são bilaterais e 90% são malignos.","B":"Formas familiares apresentam traço autossômico dominante ou são parte de síndromes com\nmutações genéticas reconhecidas.","C":"Presença de HA persistente ou paroxística (50%), paroxismos de cefaleia, sudorese profusa e\npalpitações (tríade clássica) são indicativos da doença.","D":"O diagnóstico laboratorial é baseado em dosagens de catecolaminas e seus metabólitos no\nsangue e na urina."},"answer":"A","source":"Clinica médica/MED CLM 03/MED CLM 03.txt","sourceLabel":"MED · MED CLM 03","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-03-161414","number":"161414","sourceNumber":"161414","collectionBlock":"med:med-clinica-medica-med-clm-03","collectionLabel":"MED · MED CLM 03","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 03","subtopic":"","stem":"Dentre os objetivos de uma reabilitação cardiovascular e da prevenção secundária,\npodemos considerar como seus pilares da reabilitação cardiovascular os listados a seguir, com\nEXCEÇÃO de um. Indique-o.","options":{"A":"Mudanças no estilo de vida com ênfase na atividade física programada, adoção de hábitos\nalimentares saudáveis, remoção do tabagismo e do uso de drogas em geral.","B":"Uso de estratégias para modular o estresse.","C":"O programa de RCV deve ter como objetivo, não só melhorar o estado fisiológico, mas sem\npoder interferir também o psicológico do paciente cardíaco.","D":"O programa deve se basear em uma intervenção multidisciplinar (programa de exercício,\neducação, avaliação médica, avaliação nutricional etc.)."},"answer":"C","source":"Clinica médica/MED CLM 03/MED CLM 03.txt","sourceLabel":"MED · MED CLM 03","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-03-161359","number":"161359","sourceNumber":"161359","collectionBlock":"med:med-clinica-medica-med-clm-03","collectionLabel":"MED · MED CLM 03","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 03","subtopic":"","stem":"Dentro dos conceitos epidemiológicos básicos de Hipertensão Arterial, indique a\nalternativa que NÃO se encaixa perfeitamente nesse assunto.","options":{"A":"Hipertensão Arterial (HA) é condição clínica multifatorial caracterizada por elevação sustentada\ndos níveis pressóricos = 140 e/ou 90 mmHg.","B":"Frequentemente se associa a distúrbios metabólicos, alterações funcionais e/ou estruturais de\nórgãos-alvo.","C":"Agravada pela presença de outros Fatores de Risco (FR), como dislipidemia, obesidade\nabdominal, intolerância à glicose e Diabetes Melito (DM).","D":"Mantém associação dependente com eventos, como morte súbita, Acidente Vascular Encefálico\n(AVE), Infarto Agudo do Miocárdio (IAM),\nInsuficiência Cardíaca (IC), Doença Arterial Periférica\n(DAP) e Doença Renal Crônica (DRC), fatal e não fatal."},"answer":"D","source":"Clinica médica/MED CLM 03/MED CLM 03.txt","sourceLabel":"MED · MED CLM 03","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-03-161366","number":"161366","sourceNumber":"161366","collectionBlock":"med:med-clinica-medica-med-clm-03","collectionLabel":"MED · MED CLM 03","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 03","subtopic":"","stem":"Dentre os diversos fatores de risco para Hipertensão Arterial, na realidade brasileira,\nestudos que avaliaram o impacto de\npolimorfismos na população não conseguiram identificar um\npadrão mais prevalente. Indique este fator.","options":{"A":"Na ingestão de álcool.","B":"na idade.","C":"Na genética.","D":"No sexo."},"answer":"C","source":"Clinica médica/MED CLM 03/MED CLM 03.txt","sourceLabel":"MED · MED CLM 03","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-03-161380","number":"161380","sourceNumber":"161380","collectionBlock":"med:med-clinica-medica-med-clm-03","collectionLabel":"MED · MED CLM 03","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 03","subtopic":"","stem":"Você participa do grupo de conselho de saúde de sua cidade, e como médico foi\nsolicitado a opinar a respeito de estratégias para a implementação de medidas de prevenção e\ndesenvolvimento da Hipertensão Arterial. Em relação à sua opinião sobre essas estratégias,\nassinale a alternativa considerada INCORRETA.","options":{"A":"Englobam políticas públicas de saúde combinadas com ações das sociedades médicas e dos\nmeios de comunicação.","B":"O objetivo deve ser estimular o diagnóstico precoce, e somente o tratamento medicamentoso\ncontínuo.","C":"O controle da PA e de FR associados por meio da modificação do estilo de vida (MEV).","D":"Estimular uso regular de medicamentos."},"answer":"B","source":"Clinica médica/MED CLM 03/MED CLM 03.txt","sourceLabel":"MED · MED CLM 03","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-03-161383","number":"161383","sourceNumber":"161383","collectionBlock":"med:med-clinica-medica-med-clm-03","collectionLabel":"MED · MED CLM 03","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 03","subtopic":"","stem":"Sobre o sedentarismo no contexto brasileiro de hipertensos, estudos de nossa\npopulação revelaram prevalência geral de sedentarismo de 75,8%. Observou-se associação\nsignificativa entre HA e idade, sexo masculino, e diversos outros fatores, EXCETO por:","options":{"A":"sobrepeso.","B":"adiposidade central.","C":"sedentarismo nos momentos de folga e durante o trabalho.","D":"escolaridade inferior a 8 anos e renda per capita superior a 5 salários mínimos."},"answer":"D","source":"Clinica médica/MED CLM 03/MED CLM 03.txt","sourceLabel":"MED · MED CLM 03","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-03-161389","number":"161389","sourceNumber":"161389","collectionBlock":"med:med-clinica-medica-med-clm-03","collectionLabel":"MED · MED CLM 03","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 03","subtopic":"","stem":"Em referência aos procedimentos para se aferir à Pressão Arterial, marque a opção que\nNÃO se enquadra nesses procedimentos.","options":{"A":"Explicar o procedimento ao paciente e deixá-lo em repouso de 3 a 5 minutos em ambiente\ncalmo.","B":"Certificar-se de que o paciente não esteja com a bexiga cheia.","C":"Certificar-se de que o paciente não tenha praticado exercícios físicos há pelo menos 60 minutos.","D":"Certificar-se de que o paciente não tenha fumado nos 10 minutos anteriores"},"answer":"D","source":"Clinica médica/MED CLM 03/MED CLM 03.txt","sourceLabel":"MED · MED CLM 03","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-03-161393","number":"161393","sourceNumber":"161393","collectionBlock":"med:med-clinica-medica-med-clm-03","collectionLabel":"MED · MED CLM 03","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 03","subtopic":"","stem":"Para a adequada técnica de aferição da Pressão Arterial, assinale a alternativa\nCORRETA.","options":{"A":"Posicionamento, o paciente deve estar sentado, com pernas cruzadas.","B":"Posicionamento, o paciente deve estar com os pés apoiados no chão, dorso recostado na\ncadeira e relaxado.","C":"O braço deve estar na altura acima do coração, apoiado, com a palma da mão voltada para cima\ne as roupas não devem garrotear o membro.","D":"Medir a PA na posição de pé, após 5 minutos, nos diabéticos, idosos e em outras situações em\nque a hipotensão ortostática possa ser\nfrequente ou suspeitada."},"answer":"B","source":"Clinica médica/MED CLM 03/MED CLM 03.txt","sourceLabel":"MED · MED CLM 03","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-03-161323","number":"161323","sourceNumber":"161323","collectionBlock":"med:med-clinica-medica-med-clm-03","collectionLabel":"MED · MED CLM 03","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 03","subtopic":"","stem":"A Síndrome Metabólica tem como características, com EXCEÇÃO de uma. Aponte-a.","options":{"A":"Representa um conjunto de importantes fatores de risco para doença cérebro-vascular.","B":"A obesidade abdominal e a resistência insulínica são fatores importantes na gênese do\nproblema.","C":"A terapia com Metformina, mesmo que isoladamente, pode reverter quadro de anovulação em\nalgumas pacientes.","D":"Os anticoncepcionais combinados orais não são de grande utilidade prática em casos de\nAnovulação Crônica relacionada à Síndrome Metabólica."},"answer":"D","source":"Clinica médica/MED CLM 03/MED CLM 03.txt","sourceLabel":"MED · MED CLM 03","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-03-161287","number":"161287","sourceNumber":"161287","collectionBlock":"med:med-clinica-medica-med-clm-03","collectionLabel":"MED · MED CLM 03","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 03","subtopic":"","stem":"Em relação à pressão arterial, analise as afirmativas a seguir. I. O uso de monitorização\ninvasiva de pressão arterial é indicado\npara os pacientes com instabilidade hemodinâmica mais\nimportante, para os que se apresentem hipotensos e nos casos de hipertensão arterial grave, como\nnas emergências hipertensivas. II. A pressão arterial normal descarta a presença de baixo débito\ncardíaco e baixa oferta tecidual de oxigênio. III. Como regra prática, pode-se utilizar como um dos\nvalores para diagnóstico de hipotensão em crianças e recém-nascidos a pressão arterial sistólica\ninferior a 60 mmHg. Está CORRETO, APENAS, o contido em","options":{"A":"I e II.","B":"I e III.","C":"II e III.","D":"II."},"answer":"B","source":"Clinica médica/MED CLM 03/MED CLM 03.txt","sourceLabel":"MED · MED CLM 03","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-03-134314","number":"134314","sourceNumber":"134314","collectionBlock":"med:med-clinica-medica-med-clm-03","collectionLabel":"MED · MED CLM 03","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 03","subtopic":"","stem":"Jovem masculino, 32 anos de idade, deu entrada no hospital após grande mal-estar,\npor uso de cocaína. Seu quadro de intoxicação\nmostra taquicardia, sudorese fria e agitação. Sua\npressão está em 210 x 120 mmHg e sua frequência cardíaca em 185 bpm, referindo, nesse\nmomento, dor torácica. Para esse caso clínico, indique a alternativa que não é adequada:","options":{"A":"Benzodiazepínicos.","B":"Betabloqueadores.","C":"Antagonistas de canal de cálcio.","D":"Oxigênio."},"answer":"B","source":"Clinica médica/MED CLM 03/MED CLM 03.txt","sourceLabel":"MED · MED CLM 03","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-03-134277","number":"134277","sourceNumber":"134277","collectionBlock":"med:med-clinica-medica-med-clm-03","collectionLabel":"MED · MED CLM 03","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 03","subtopic":"","stem":"Quando lidamos com quadros de emergência hipertensiva, frequentemente devemos\nutilizar o Nitroprussiato de Sódio. Por se tratar de medicação potente, sua farmacologia deve ser\nbem entendida, sendo que","options":{"A":"Atua somente em artérias.","B":"Pode ser usado em todos os pacientes.","C":"Seu metabólico tóxico prejudica a respiração.","D":"Somente funciona em altas doses."},"answer":"C","source":"Clinica médica/MED CLM 03/MED CLM 03.txt","sourceLabel":"MED · MED CLM 03","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-03-134833","number":"134833","sourceNumber":"134833","collectionBlock":"med:med-clinica-medica-med-clm-03","collectionLabel":"MED · MED CLM 03","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 03","subtopic":"","stem":"Paciente hipertenso crônico, com elevação dos valores de ureia e creatinina fora\ndiabetes mal controlado, evolui com\nrebaixamento do nível de consciência e dificuldade\nrespiratória. Sua pressão arterial está extremamente elevada com PA 230 x 130 mmHg.\nSeus exames demonstram glicemia de 120, valores de ureia e creatinina ainda não indicam\nhemodiálise. Tomografia demonstra intenso edema cerebral. Qual das alternativas abaixo MELHOR\nexplica o caso?","options":{"A":"Provável distúrbio metabólico com acidose lática.","B":"Vasodilatação por pressão, hiperemia cerebral e encefalopatia.","C":"Hemorragia cerebral.","D":"Provável AVC isquêmico."},"answer":"B","source":"Clinica médica/MED CLM 03/MED CLM 03.txt","sourceLabel":"MED · MED CLM 03","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-03-109718","number":"109718","sourceNumber":"109718","collectionBlock":"med:med-clinica-medica-med-clm-03","collectionLabel":"MED · MED CLM 03","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 03","subtopic":"","stem":"Paciente do sexo masculino, 60 anos, apresenta medidas seriadas de pressão arterial\nem torno de 150 x 90 mmHg. Você orientará o\npaciente sobre medidas não farmacológicas de\ncontrole da pressão arterial. Assinale abaixo a medida que NÃO faz parte das orientações para\nesse paciente:","options":{"A":"Realizar atividade física regular.","B":"Estimular consumo de dieta rica em frutas, vegetais e potássio.","C":"Limitar ingestão de café.","D":"Limitar ingestão de bebidas alcoólicas."},"answer":"C","source":"Clinica médica/MED CLM 03/MED CLM 03.txt","sourceLabel":"MED · MED CLM 03","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-03-109766","number":"109766","sourceNumber":"109766","collectionBlock":"med:med-clinica-medica-med-clm-03","collectionLabel":"MED · MED CLM 03","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 03","subtopic":"","stem":"Paciente do sexo masculino, 76 anos, com Hipertensão Arterial Sistólica Isolada, sem\noutras comorbidades. Assinale a MELHOR opção terapêutica para esse paciente.","options":{"A":"Diurético tiazídico.","B":"Beta-bloqueador.","C":"Bloqueador do receptor da angiotensina.","D":"Nitrato."},"answer":"A","source":"Clinica médica/MED CLM 03/MED CLM 03.txt","sourceLabel":"MED · MED CLM 03","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-03-110608","number":"110608","sourceNumber":"110608","collectionBlock":"med:med-clinica-medica-med-clm-03","collectionLabel":"MED · MED CLM 03","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 03","subtopic":"","stem":"A Síndrome metabólica é descrita como:","options":{"A":"Obesidade abdominal (acima de 102 cm no homem e 88 cm na mulher),\nhipertrigliceridemia\n\n(acima de 150 mg/dl), baixos níveis de HDL-colesterol (menor que 40 mg/dl nos homens e\n50 mg/dl nas mulheres) e hipertensão arterial\n(PA maior ou igual a 130 x 85 mmHg).","B":"IMC acima de 35 nas mulheres e 38 nos homens. Associado a: hiperglicemia de jejum\n(acima de 126 mg/dl), hipertrigliceridemia (acima de\n\n150 mg/dl) e hipertensão arterial (PA maior ou igual\na 130 x 85 mmHg).","C":"Obesidade abdominal (acima de 102 cm no homem e 88 cm na mulher),\nhipertrigliceridemia\n\n(acima de 180 mg/dl), baixos níveis de HDL-colesterol (menor que 40 mg/dl nos homens e\n50 mg/dl nas mulheres), hiperglicemia de\njejum (acima de 118 mg/dl) e hipertensão arterial (PA\nmaior ou igual a 130 x 85 mmHg).","D":"Hipertensão arterial (PA maior que 130 x 85 mmHg), hipertrigliceridemia (acima de 180\nmg/dl), baixos níveis de HDL-colesterol (menor que 40 mg/dl nos homens e 50 mg/dl nas\nmulheres), hiperglicemia de jejum (acima de 118 mg/dl) e obesidade.","E":"Hiperglicemia de jejum (acima de 126 mg/dl),\n\nhipertrigliceridemia (acima de 150 mg/dl), hipertensão arterial (PA maior ou igual a 130 x 85\nmmHg) e obesidade."},"answer":"A","source":"Clinica médica/MED CLM 03/MED CLM 03.txt","sourceLabel":"MED · MED CLM 03","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-03-86639","number":"86639","sourceNumber":"86639","collectionBlock":"med:med-clinica-medica-med-clm-03","collectionLabel":"MED · MED CLM 03","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 03","subtopic":"","stem":"Paciente 52 anos, masculino, com relato de taquidispneia há três horas acompanhada\nde cefaleia importante holocraniana. Refere\nainda que observou dificuldade respiratória progressiva\na partir do início do quadro. É hipertenso há 10 anos e faz uso irregular de captopril 25 mg três\nvezes ao dia e hidroclorotiazida 25 mg/dia. Tabagista crônico há 30 anos e deixou há 5 anos. Nega\netilismo, dislipidemia e diabetes mellitus. O diagnóstico sindrômico para este paciente é:","options":{"A":"Emergência hipertensiva sem lesão órgão-alvo.","B":"Urgência hipertensiva sem lesão órgão-alvo.","C":"Emergência hipertensiva com provável lesão órgão-alvo.","D":"Urgência hipertensiva com provável lesão órgão-alvo.","E":"Apenas urgência hipertensiva."},"answer":"C","source":"Clinica médica/MED CLM 03/MED CLM 03.txt","sourceLabel":"MED · MED CLM 03","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-03-86803","number":"86803","sourceNumber":"86803","collectionBlock":"med:med-clinica-medica-med-clm-03","collectionLabel":"MED · MED CLM 03","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 03","subtopic":"","stem":"Os Inibidores da Enzima Conversora de Angiotensina (IECA), atualmente são drogas\neficazes em monoterapia nos pacientes com hipertensão arterial sistêmica. Assinale a alternativa\ncorreta sobre os efeitos adversos dessas drogas: I. Hipersensibilidade cutânea; II. Rubor facial;\nIII.\nBloqueio atrioventricular; IV. Alteração do paladar.","options":{"A":"Somente I é verdadeira.","B":"Somente I e II são verdadeiras.","C":"Somente III e IV são verdadeiras.","D":"Somente I e IV são verdadeiras.","E":"Somente II e III."},"answer":"D","source":"Clinica médica/MED CLM 03/MED CLM 03.txt","sourceLabel":"MED · MED CLM 03","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-03-86637","number":"86637","sourceNumber":"86637","collectionBlock":"med:med-clinica-medica-med-clm-03","collectionLabel":"MED · MED CLM 03","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 03","subtopic":"","stem":"Rita de Cássia tem 56 anos, parda, recém chegada na Comunidade Vila das Casas.\nCasada com Antônio, 53 anos e mãe de dois\nfilhos adolescentes. Trabalha como caixa de\nsupermercado na área nobre da cidade, levando cerca de 1 hora no transporte em cada uma das\nviagens. Faz consultas regulares para planejamento familiar, rastreamento de câncer de colo de\nútero e controle da HAS. Na última consulta seu nível pressórico foi de 150 x 100 mmHg. O qual ela\natribuiu a uma semana estressante no trabalho. Atualmente está fazendo uso de Anlodipino 5\nmg/dia e Hidroclorotiazida 25 mg/dia. Foi pedido que ela realizasse uma Monitorização Residencial\nda Pressão Arterial e evidenciou uma média pressórica de 148 x 98 mmHg. Afirma que não sente\nnenhum sintoma, não tem tempo para fazer atividade física e nem fazer sua comida à parte da\nfamília e prefere resolver seus problemas de saúde com remédios. Tabagista há 36 anos. Na\nescala de Framinghan obteve resultado de 22% de chances de desenvolver um evento\ncardiovascular em 10 anos. Frente ao caso e considerando o sinergismo entre as medicações, qual\nseria conduta mais adequada:","options":{"A":"Reforçar as medidas não medicamentosas.","B":"Reforçar as medidas não medicamentosas e aumentar a dose do Antagonista dos Canais\nCálcio.","C":"Reforçar as medidas não medicamentosas e aumentar a dose da diurético.","D":"Reforçar as medidas não medicamentosas e substituir o Antagonista dos Canais Cálcio por\nIECA.","E":"Reforçar as medidas não medicamentosas e trocar as medicações por IECA e Betabloqueador."},"answer":"D","source":"Clinica médica/MED CLM 03/MED CLM 03.txt","sourceLabel":"MED · MED CLM 03","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-03-158398","number":"158398","sourceNumber":"158398","collectionBlock":"med:med-clinica-medica-med-clm-03","collectionLabel":"MED · MED CLM 03","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 03","subtopic":"","stem":"Masculino de 68 anos, com antecedente pessoal de diabetes mellitus, hipertensão\narterial sistêmica e infarto do miocárdio prévio,\nem uso de AAS, enalapril 10 mg ao dia,\nhidroclorotiazida 25 mg ao dia e metformina 850 mg duas vezes ao dia. Esse quadro evoluiu com\ndispneia e ortopneia há três dias, piorando progressivamente. Ao exame físico, o paciente\napresentou: pressão arterial: 230 x 170 mmHg; frequência cardíaca: 120 bpm; frequência\nrespiratória: 36 irpm; saturação arterial de oxigênio: 94%. RX de tórax evidenciou infiltrado\npulmonar difuso, com predomínio na região peri-hilar, sugerindo quadro de congestão pulmonar.\nQual a conduta mais adequada para o caso?","options":{"A":"Noradrenalina EV + hidratação EV + culturas + antibioticoterapia.","B":"Morfina EV + midazolam EV + intubação orotraqueal.","C":"Nitroprussiato EV + furosemida EV + morfina EV + ventilação não invasiva (CPAP).","D":"Hidrocortisona EV + terbutalina SC + inalação com fenoterol e ipratrópio.","E":"Dobutamina EV + metoprolol EV + morfina EV + sildenafila VO."},"answer":"C","source":"Clinica médica/MED CLM 03/MED CLM 03.txt","sourceLabel":"MED · MED CLM 03","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-03-327230","number":"327230","sourceNumber":"327230","collectionBlock":"med:med-clinica-medica-med-clm-03","collectionLabel":"MED · MED CLM 03","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 03","subtopic":"","stem":"No diagnóstico de Hipertensão Arterial podemos encontrar Hipertensão mascarada que\né caracterizada por:","options":{"A":"Valores elevados no consultório, porém com PA normal pela MAPA ou medidas residenciais.","B":"Valores normais da PA no consultório, porém com PA elevada pela MAPA ou medidas\nresidenciais.","C":"Valores elevados da PA no consultório e pela MAPA.","D":"Valores normais da PA no consultório e pela MAPA."},"answer":"B","source":"Clinica médica/MED CLM 03/MED CLM 03.txt","sourceLabel":"MED · MED CLM 03","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-03-298204","number":"298204","sourceNumber":"298204","collectionBlock":"med:med-clinica-medica-med-clm-03","collectionLabel":"MED · MED CLM 03","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 03","subtopic":"","stem":"Em relação à Hipertensão Arterial em doentes renais. Assina a alternativa CORRETA:","options":{"A":"A Diretriz Brasileira de Hipertensão Arterial, 2020 recomenda em adultos com Hipertensão\nArterial e Doença Renal Crônica, diabéticos ou\nnão, meta de PA < 130/80 mmHg para os que\nestejam em tratamento conservador.","B":"A Diretriz Brasileira de Hipertensão Arterial, 2020 recomenda em adultos com Hipertensão\nArterial e Doença Renal Crônica, diabéticos\nou não, meta de PA < 120/75 mmHg.","C":"A Diretriz Brasileira de Hipertensão Arterial, 2020 recomenda em adultos com Hipertensão\nArterial e Doença Renal Crônica, diabéticos\nou não, meta de PA < 140/90 mmHg.","D":"A Diretriz Brasileira de Hipertensão Arterial, 2020 recomenda em adultos com Hipertensão\nArterial e Doença Renal Crônica, diabéticos\nou não, meta de PA < 120/80 mmHg."},"answer":"A","source":"Clinica médica/MED CLM 03/MED CLM 03.txt","sourceLabel":"MED · MED CLM 03","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-03-286766","number":"286766","sourceNumber":"286766","collectionBlock":"med:med-clinica-medica-med-clm-03","collectionLabel":"MED · MED CLM 03","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 03","subtopic":"","stem":"A hipertensão arterial secundária em uma criança de 3 anos tem como principal causa:","options":{"A":"Alterações vasculares","B":"Doenças cardiológicas","C":"Endocrinopatias","D":"Anormalidades renais"},"answer":"D","source":"Clinica médica/MED CLM 03/MED CLM 03.txt","sourceLabel":"MED · MED CLM 03","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-03-176074","number":"176074","sourceNumber":"176074","collectionBlock":"med:med-clinica-medica-med-clm-03","collectionLabel":"MED · MED CLM 03","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 03","subtopic":"","stem":"Davi tem 35 anos, é branco, solteiro, vive com os pais hipertensos e veio à consulta\npara fazer ?exames de rotina?. Nega doenças\nprévias e não apresenta queixas no momento. A\npressão arterial está em 154 x 96 mmHg. Podemos orientá-lo:","options":{"A":"A monitorar sua pressão arterial ao menos 2 vezes com um intervalo de 10 dias.","B":"Que está com hipertensão arterial estágio 3, sendo indicado modificações do seu estilo de vida.","C":"Que está com hipertensão arterial estágio 1 e necessita de tratamento medicamentoso no\ndiagnóstico.","D":"A monitorar sua pressão arterial ao menos 3 vezes pela manhã e 3 vezes à noite durante 7 dias."},"answer":"D","source":"Clinica médica/MED CLM 03/MED CLM 03.txt","sourceLabel":"MED · MED CLM 03","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-03-80930","number":"80930","sourceNumber":"80930","collectionBlock":"med:med-clinica-medica-med-clm-03","collectionLabel":"MED · MED CLM 03","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 03","subtopic":"","stem":"São fatores de risco para a ocorrência tanto de doença cardiovascular quanto de\nDiabetes Mellitus:","options":{"A":"Herança genética e consumo excessivo de sal.","B":"Ocupações estressantes e baixa escolaridade.","C":"Ocupações menos qualificadas e obesidade.","D":"Hipercolesterolemia e obesidade.","E":"Sedentarismo e obesidade."},"answer":"E","source":"Clinica médica/MED CLM 03/MED CLM 03.txt","sourceLabel":"MED · MED CLM 03","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-03-61535","number":"61535","sourceNumber":"61535","collectionBlock":"med:med-clinica-medica-med-clm-03","collectionLabel":"MED · MED CLM 03","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 03","subtopic":"","stem":"De acordo com as VI diretrizes de Hipertensão Arterial da SBC, as metas pressóricas\nnos pacientes em estágio 1 e 2 com risco\ncardiovascular baixo e médio são:","options":{"A":"PA < 140 x 90 mmHg.","B":"PA = 140 x 90 mmHg.","C":"PA = 130 x 80 mmHg.","D":"PA < 130 x 80 mmHg.","E":"PA = 120 x 80 mmHg."},"answer":"A","source":"Clinica médica/MED CLM 03/MED CLM 03.txt","sourceLabel":"MED · MED CLM 03","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-03-60844","number":"60844","sourceNumber":"60844","collectionBlock":"med:med-clinica-medica-med-clm-03","collectionLabel":"MED · MED CLM 03","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 03","subtopic":"","stem":"Jonas, de 62 anos, refere crises hipertensivas no último mês, tendo sido atendido no\nPronto-Socorro 4 vezes e sua pressão oscilou entre 140-156 x 80-88 mmHg. Sua mãe é hipertensa.\nHoje, sua pressão arterial é de 150 x 90 mmHg. Você, enquanto seu médico, pode lhe dizer:","options":{"A":"que Jonas apresenta hipertensão arterial sistemica estágio II.","B":"se formos iniciar terapia medicamentosa, devemos dar preferencia a um vasodilatador direto.","C":"orientar Jonas a fazer o tratamento não medicamentoso, dependendo do risco cardiovascular.","D":"que devemos avaliar seu risco de evento cardiovascular e, de acordo com ele, iniciar ou não,\ntratamento medicamentoso.","E":"dentre as medidas não medicamentosas estão o incentivo a prática de atividade física, consumo\nde álcool e redução do sal na dieta."},"answer":"D","source":"Clinica médica/MED CLM 03/MED CLM 03.txt","sourceLabel":"MED · MED CLM 03","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-03-34300","number":"34300","sourceNumber":"34300","collectionBlock":"med:med-clinica-medica-med-clm-03","collectionLabel":"MED · MED CLM 03","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 03","subtopic":"","stem":"José de 42 anos, veio a primeira consulta na Unidade Saúde da Família em que você\ntrabalha. Refere dores na nuca. Tem índice de Massa Corporal de 28, pressão Arterial de 180 X110\nmmHg. Refere outras aferições também com valores semelhantes, como consta em receituário\npreenchido pelo técnico de enfermagem de sua unidade. Os pais de José são acompanhados na\nunidade por você e a mãe tem hipertensão arterial. José é tabagista, vive com pais e trabalha como\nmotorista de táxi. Em relação ao quadro clínico apresentado por José, podemos afirmar, EXCETO:","options":{"A":"Que ele apresenta Hipertensão Arterial em estágio II.","B":"Você deve orientá-lo sobre medidas não famarcológicas bem como a iniciar terapia\nmedicamentosa para controle da pressão.","C":"José deve ser orientado a parar de fumar e iniciar abordagem breve cognitivo-comportamental\nantitabagismo.","D":"Os exames que devem ser solicitados nesta 1ª. consulta são exame de urina tipo I, potássio\nsérico, glicemia, creatinina sérica, lipidograma, hematócrito e eletroencefalograma.","E":"José deve ser encaminhado ao especialista caso sua hipertensão seja refratária ao tratamento\nou apresente importante lesão de órgão-alvo."},"answer":"D","source":"Clinica médica/MED CLM 03/MED CLM 03.txt","sourceLabel":"MED · MED CLM 03","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-03-26442","number":"26442","sourceNumber":"26442","collectionBlock":"med:med-clinica-medica-med-clm-03","collectionLabel":"MED · MED CLM 03","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 03","subtopic":"","stem":"Algumas situações interferem na avaliação da pressão arterial (PA). Assinale a\nalternativa INCORRETA:","options":{"A":"em pacientes com pseudo-hipertensão, os níveis pressóricos são falsamente elevados devido ao\nenrijecimento arterial","B":"o hiato auscultatório ocorre entre a fase I e II do Korotkoff e pode subestimar a PA sistólica ou\nsuperestimar a diastólica","C":"a hipertensão do avental branco ocorre quando temos medidas pressóricas elevadas no\nconsultório, porém normais à monitoração\nambulatorial da PA (MAPA) ou à monitoração residencial","D":"quando o manguito é muito pequeno para o braço do indivíduo, medidas falsamente elevadas\npodem ocorrer","E":"pseudo-hipertensão e hiato auscultatório são mais comuns em gestantes"},"answer":"E","source":"Clinica médica/MED CLM 03/MED CLM 03.txt","sourceLabel":"MED · MED CLM 03","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-03-10045","number":"10045","sourceNumber":"10045","collectionBlock":"med:med-clinica-medica-med-clm-03","collectionLabel":"MED · MED CLM 03","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 03","subtopic":"","stem":"Dona Elsa faz seu tratamento de hipertensão há muitos anos na unidade de saúde da\nfamília onde você trabalha. Hoje, você irá consultar o seu filho Marcelo que acaba de chegar à\ncidade. Marcelo tem 40 anos e descobriu há 3 meses ser hipertenso. Ao exame, está com níveis\npressóricos elevados, apesar do uso correto da medicação, e sobrepeso. Ele refere que sempre\nfica nervoso quando vai ao médico. Você o orienta a, EXCETO:","options":{"A":"Investigar a síndrome do avental branco e pede o MAPA (monitorização ambulatorial da pressão\narterial).","B":"Investiga Hipertensão secundária visto o início súbito da hipertensão antes dos 55 anos de idade\ne a história familiar.","C":"Solicita alguns exames complementares como creatinina sérica, potássio sérico, lipidograma,\nsedimentocospia urinária e eletrocardiograma.","D":"Recomenda dieta com restrição calórica e de sódio.","E":"Orienta a prática regular de exercício físico para controle pressórico e redução de peso."},"answer":"B","source":"Clinica médica/MED CLM 03/MED CLM 03.txt","sourceLabel":"MED · MED CLM 03","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-03-7514","number":"7514","sourceNumber":"7514","collectionBlock":"med:med-clinica-medica-med-clm-03","collectionLabel":"MED · MED CLM 03","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 03","subtopic":"","stem":"Alguns medicamentos anti-hipertensivos em mulheres não-grávidas são mais úteis em\ncondições específicas. Qual destas combinações está contraindicada?","options":{"A":"Inibidores da ECA em diabéticas.","B":"ß-bloqueadores com doenças coronariana coexistente.","C":"Bloqueadores dos canais de cálcio com insuficiência cardíaca esquerda.","D":"ß-bloqueadores com enxaqueca.","E":"Não há combinação que esteja contraindicada."},"answer":"C","source":"Clinica médica/MED CLM 03/MED CLM 03.txt","sourceLabel":"MED · MED CLM 03","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-03-284568","number":"284568","sourceNumber":"284568","collectionBlock":"med:med-clinica-medica-med-clm-03","collectionLabel":"MED · MED CLM 03","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 03","subtopic":"","stem":"Mulher, 60 anos de idade, é acompanhada na Unidade de Saúde da Família (USF) por\ndiabetes mellitus tipo 2 e hipertensão arterial sistêmica. Na primeira visita à USF, há cerca de 6\nmeses, a PA estava em 182 x 100 mmHg. Atualmente, assintomática. Nega outras comorbidades.\nEm uso regular de metformina 850 mg duas vezes ao dia, losartana 50 mg de 12/12h e anlodipina\n10 mg ao dia, há cerca de 6 meses. Ao exame físico, apresenta-se em bom estado geral, com FC:\n70 bpm, PA: 166 x 96 mmHg em ambos os membros superiores e glicemia capilar de 110 mg/dl.\n\nPulsos palpáveis e simétricos. Exame segmentar sem alterações. Traz monitorização residencial da\npressão arterial, com PAS entre 140 e 172 mmHg e PAD entre 90 e 96 mmHg. Indique a\nclassificação para a pressão dessa paciente na primeira visita à Unidade de Saúde da Família.","options":{"A":"Pressão arterial elevada.","B":"Hipertensão arterial sistêmica estágio 1.","C":"Hipertensão arterial sistêmica estágio 2.","D":"Hipertensão arterial sistêmica estágio 3."},"answer":"D","source":"Clinica médica/MED CLM 03/MED CLM 03.txt","sourceLabel":"MED · MED CLM 03","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-03-284569","number":"284569","sourceNumber":"284569","collectionBlock":"med:med-clinica-medica-med-clm-03","collectionLabel":"MED · MED CLM 03","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 03","subtopic":"","stem":"Mulher, 60 anos de idade, é acompanhada na Unidade de Saúde da Família (USF) por\ndiabetes mellitus tipo 2 e hipertensão arterial sistêmica. Na primeira visita à USF, há cerca de 6\nmeses, a PA estava em 182 x 100 mmHg. Atualmente, assintomática. Nega outras comorbidades.\nEm uso regular de metformina 850 mg duas vezes ao dia, losartana 50 mg de 12/12h e anlodipino\n10 mg ao dia, há cerca de 6 meses. Ao exame físico, apresenta-se em bom estado geral, com FC:\n70 bpm, PA: 166 x 96 mmHg em ambos os membros superiores e glicemia capilar de 110 mg/dl.\n\nPulsos palpáveis e simétricos. Exame segmentar sem alterações. Traz monitorização residencial da\npressão arterial, com PAS entre 140 e 172 mmHg e PAD entre 90 e 96 mmHg. Indique a conduta\nmais adequada para otimizar o esquema anti-hipertensivo dessa paciente.","options":{"A":"Introdução de hidroclorotiazida.","B":"Introdução de captopril.","C":"Troca da losartana por hidralazina.","D":"Aumento das doses de losartana e anlodipino."},"answer":"A","source":"Clinica médica/MED CLM 03/MED CLM 03.txt","sourceLabel":"MED · MED CLM 03","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-03-284570","number":"284570","sourceNumber":"284570","collectionBlock":"med:med-clinica-medica-med-clm-03","collectionLabel":"MED · MED CLM 03","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 03","subtopic":"","stem":"Mulher, 60 anos de idade, é acompanhada na Unidade de Saúde da Família (USF) por\ndiabetes mellitus tipo 2 e hipertensão arterial sistêmica. Na primeira visita à USF, há cerca de 6\nmeses, a PA estava em 182 x 100 mmHg. Atualmente, assintomática. Nega outras comorbidades.\nEm uso regular de metformina 850 mg duas vezes ao dia, losartana 50 mg de 12/12h e anlodipino\n10 mg ao dia, há cerca de 6 meses. Ao exame físico, apresenta-se em bom estado geral, com FC:\n70 bpm, PA: 166 x 96 mmHg em ambos os membros superiores e glicemia capilar de 110 mg/dl.\n\nPulsos palpáveis e simétricos. Exame segmentar sem alterações. Traz monitorização residencial da\npressão arterial, com PAS entre 140 e 172 mmHg e PAD entre 90 e 96 mmHg. Determine as metas\nde pressão arterial sistólica e diastólica para essa paciente, segundo a Sociedade Brasileira de\nCardiologia e a Sociedade Brasileira de Diabetes.","options":{"A":"PAS < 120 e PAS < 70 mmHg.","B":"PAS < 130 e PAD < 80 mmHg.","C":"PAS < 135 e PAD < 85 mmHg.","D":"PAS < 140 e PAD < 90 mmHg."},"answer":"B","source":"Clinica médica/MED CLM 03/MED CLM 03.txt","sourceLabel":"MED · MED CLM 03","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-03-27432","number":"27432","sourceNumber":"27432","collectionBlock":"med:med-clinica-medica-med-clm-03","collectionLabel":"MED · MED CLM 03","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 03","subtopic":"","stem":"A aferição da tensão arterial pode ser subestimada quando:","options":{"A":"for realizada após ingesta de bebidas à base de cola.","B":"forem realizadas duas auferições com menos de 2 minutos de intervalo.","C":"tiver o manguito de borracha com largura de 60% da circunferência do braço.","D":"for realizada imediatamente após atividade física.","E":"a insuflação do manguito estiver acima de 50 mmHg da sistólica palpatória."},"answer":"C","source":"Clinica médica/MED CLM 03/MED CLM 03.txt","sourceLabel":"MED · MED CLM 03","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-03-27482","number":"27482","sourceNumber":"27482","collectionBlock":"med:med-clinica-medica-med-clm-03","collectionLabel":"MED · MED CLM 03","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 03","subtopic":"","stem":"Paciente, 12 anos de idade, vem ao ambulatório pela primeira vez, com o propósito de\nrealizar exame de rotina, pois sua mãe está preocupada com a proximidade da menarca. Ao\nexame, foi notada TA: 130 X 100 mmHg, sem qualquer outra anormalidade. A melhor conduta a ser\nadotada, nesse caso, é:","options":{"A":"solicitar sumário de urina e provas de função renal.","B":"marcar retorno, pelo menos, mais 2 vezes na mesma semana para confirmar a pressão arterial.","C":"solicitar ultrassonografia renal e sumário de urina.","D":"suspender o sal da dieta e usar diurético.","E":"prescrever captopril em dose mínima e marcar retorno após uma semana."},"answer":"B","source":"Clinica médica/MED CLM 03/MED CLM 03.txt","sourceLabel":"MED · MED CLM 03","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-03-11132","number":"11132","sourceNumber":"11132","collectionBlock":"med:med-clinica-medica-med-clm-03","collectionLabel":"MED · MED CLM 03","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 03","subtopic":"","stem":"A aferição correta da tensão arterial, por técnica padronizada, vem sendo enfatizada\ncomo medida de qualidade de atenção médica. São\nrecomendações que fazem parte da\npadronização do Ministério da Saúde, exceto:","options":{"A":"uso de manguito com largura correspondente a 40% da circunferência do braço","B":"intervalo mínimo de 1 minuto entre as duas aferições","C":"registro habitual da tensão arterial diastólica no momento do desaparecimento dos sons\n(Korotkoff V)","D":"arredondamento de no máximo 5 mmHg no registro dos valores da tensão arterial","E":"tomada sistemática da tensão arterial sistólica palpatória antes da auscultatória"},"answer":"E","source":"Clinica médica/MED CLM 03/MED CLM 03.txt","sourceLabel":"MED · MED CLM 03","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-03-281849","number":"281849","sourceNumber":"281849","collectionBlock":"med:med-clinica-medica-med-clm-03","collectionLabel":"MED · MED CLM 03","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 03","subtopic":"","stem":"Na encefalopatia hipertensiva pode, posteriormente, surgir alterações adequadamente\ndescritas no item:","options":{"A":"Nunca do estado mental e sim campimétricas, fotopsia, visão turva, alucinações visuais, crises\nconvulsivas generalizadas, hiperreflexia e sinais de hipertensão intracraniana.","B":"Do estado mental e campimétricas, fotopsia, visão turva, alucinações visuais, crises convulsivas\ngeneralizadas, hiperreflexia e nunca sinais de hipertensão intracraniana.","C":"Do estado mental e não campimétricas, fotopsia ou visão turva.","D":"Do estado mental e campimétricas, fotopsia, visão turva, alucinações visuais, crises convulsivas\ngeneralizadas, hiperreflexia e sinais de hipertensão intracraniana."},"answer":"D","source":"Clinica médica/MED CLM 03/MED CLM 03.txt","sourceLabel":"MED · MED CLM 03","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-03-281854","number":"281854","sourceNumber":"281854","collectionBlock":"med:med-clinica-medica-med-clm-03","collectionLabel":"MED · MED CLM 03","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 03","subtopic":"","stem":"No momento em que aparecem as manifestações neurológicas da encefalopatia\nhipertensiva, geralmente, a PAD encontra-se acima de\n125 mmHg. Podemos indicar como correto:","options":{"A":"A resolução do quadro, quer do ponto de vista clínico, mas não do ponto de vista de imagem,\ndemora, em média, várias semanas após o controle da PA.","B":"A resolução do quadro, quer do ponto de vista clínico, quer do ponto de vista de imagem,\ndemora, em média, várias semanas após o controle da PA.","C":"A resolução do quadro, quer do ponto de vista clínico, quer do ponto de vista de imagem,\ndemora, em média, várias meses após o controle da PA.","D":"A resolução do quadro, quer do ponto de vista clínico, quer do ponto de vista de imagem,\ndemora, em média, várias semanas antes do controle da PA."},"answer":"B","source":"Clinica médica/MED CLM 03/MED CLM 03.txt","sourceLabel":"MED · MED CLM 03","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-03-281859","number":"281859","sourceNumber":"281859","collectionBlock":"med:med-clinica-medica-med-clm-03","collectionLabel":"MED · MED CLM 03","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 03","subtopic":"","stem":"A Ressonância Magnética é o exame diagnóstico de maior valor para o diagnóstico da\nencefalopatia hipertensiva. Sendo correto o item:","options":{"A":"Na sequência T2, evidenciam-se lesões hiperintensas na substância branca com\ncomprometimento preferencial das regiões parieto-occipitais.","B":"Na sequência T2, evidenciam-se lesões hipointensas na substância branca com\ncomprometimento preferencial das regiões parieto-occipitais.","C":"Na sequência T2, evidenciam-se lesões hiperintensas na substância branca sem o\ncomprometimento preferencial das regiões parieto-occipitais.","D":"Na sequência T2, não evidenciam-se lesões hiperintensas na substância branca com\ncomprometimento preferencial das regiões parieto-occipitais."},"answer":"A","source":"Clinica médica/MED CLM 03/MED CLM 03.txt","sourceLabel":"MED · MED CLM 03","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-03-283855","number":"283855","sourceNumber":"283855","collectionBlock":"med:med-clinica-medica-med-clm-03","collectionLabel":"MED · MED CLM 03","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 03","subtopic":"","stem":"Paciente do sexo feminino, 52 anos de idade, em investigação de alterações cardíacas.\nApós ecocardiograma, notou-se pressão arterial <\n140 x 90 mmHg em duas aferições em\nconsultório realizadas pelo médico, em ambos os braços, mas com Monitorização Ambulatorial da\nPressão Arterial (MAPA) com valores médios diurnos em torno de 146 x 92 mmHg. A alternativa\nque contém o diagnóstico CORRETO desse caso clínico é:","options":{"A":"Crise hipertensiva.","B":"Hipertensa controlada.","C":"Normotensa verdadeira.","D":"Hipertensão Arterial Sistêmica mascarada.","E":"Hipertensão Arterial Sistêmica do avental branco."},"answer":"D","source":"Clinica médica/MED CLM 03/MED CLM 03.txt","sourceLabel":"MED · MED CLM 03","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-03-215595","number":"215595","sourceNumber":"215595","collectionBlock":"med:med-clinica-medica-med-clm-03","collectionLabel":"MED · MED CLM 03","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 03","subtopic":"","stem":"A MAPA pode dar informações clínicas valiosas em pacientes idosos, como nos casos\nde suspeita de hipotensão arterial ortostática,\npós-prandial, medicamentosa e situacional. É\nCORRETO que, no idoso, o descenso da PA durante o sono:","options":{"A":"Não é relacionado com a redução da resistência vascular periférica, enquanto no jovem esse\nfenômeno é relacionado com a redução do débito cardíaco.","B":"É relacionado com ao aumento da resistência vascular periférica, enquanto no jovem esse\nfenômeno é relacionado com a redução do débito cardíaco.","C":"É relacionado com a redução da resistência vascular periférica, enquanto no jovem esse\nfenômeno não é relacionado com a redução do débito cardíaco.","D":"É relacionado com a redução da resistência vascular periférica, enquanto no jovem esse\nfenômeno é relacionado com a redução do débito cardíaco."},"answer":"D","source":"Clinica médica/MED CLM 03/MED CLM 03.txt","sourceLabel":"MED · MED CLM 03","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-03-215613","number":"215613","sourceNumber":"215613","collectionBlock":"med:med-clinica-medica-med-clm-03","collectionLabel":"MED · MED CLM 03","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 03","subtopic":"","stem":"A hipertensão matinal atraiu atenção por causa da estreita relação com risco\ncardiovascular como condições caracterizadas por\nvalores elevados de PA, podem causar eventos\nem idosos e, por meio da MAPA, é possível identificá-los e definir a melhor forma de tratamento.\n\nEstá CORRETO que, em idosos, verificou-se que:","options":{"A":"A elevação matinal precoce da PA acima de 75 mmHg estava vinculada à maior prevalência de\nacidente vascular encefálico isquêmico.","B":"A redução matinal precoce da PA acima de 55 mmHg estava vinculada à maior prevalência de\nacidente vascular encefálico isquêmico.","C":"A elevação matinal precoce da PA acima de 55 mmHg estava vinculada à menor prevalência de\nacidente vascular encefálico isquêmico.","D":"A elevação matinal precoce da PA acima de 55 mmHg estava vinculada à maior prevalência de\nacidente vascular encefálico isquêmico."},"answer":"D","source":"Clinica médica/MED CLM 03/MED CLM 03.txt","sourceLabel":"MED · MED CLM 03","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-03-215615","number":"215615","sourceNumber":"215615","collectionBlock":"med:med-clinica-medica-med-clm-03","collectionLabel":"MED · MED CLM 03","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 03","subtopic":"","stem":"A MAPA pode dar informações clínicas valiosas em pacientes idosos, como nos casos\nde suspeita de hipotensão arterial ortostática,\npós-prandial, medicamentosa e situacional, bem\ncomo na avaliação de disautonomia e síncopes. Indique a CORRETA.","options":{"A":"Nos idosos, algumas limitações devem ser salientadas. O enrijecimento arterial próprio da idade\ntende a superestimar a PA medida pelo método oscilométrico e, consequentemente, na presença\nde pseudo-hipertensão, a MAPA está sujeita a erros.","B":"A presença de hiato auscultatório, comum nos idosos, mas que sendo usado o método\noscilométrico não resultará em limitações.","C":"Não se aceitam para os idosos os mesmos valores de normalidade da MAPA adotados para os\nadultos não idosos.","D":"A redução do descenso da PA durante o sono, a pressão de pulso aumentada e a elevação\nmatinal precoce da PA, rara nos idosos, relacionam-se a aumento do risco cardiovascular."},"answer":"B","source":"Clinica médica/MED CLM 03/MED CLM 03.txt","sourceLabel":"MED · MED CLM 03","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-03-218190","number":"218190","sourceNumber":"218190","collectionBlock":"med:med-clinica-medica-med-clm-03","collectionLabel":"MED · MED CLM 03","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 03","subtopic":"","stem":"Sobre a atenção à Hipertensão Arterial Sistêmica (HAS) e às doenças crônicas não\ntransmissíveis, analise as assertivas e identifique com V as verdadeiras e com F as falsas. ( ) Os\npacientes com pré-hipertensão arterial e comorbidades devem ser tratados. O grupo de\nmedicamentos com mais evidências científicas e que deve ser o tratamento de escolha são os\nBetabloqueadores, cujo uso recomendado é, exclusivo inicialmente, até que o teste terapêutico\nmostre a necessidade de associação de mais algum medicamento, que pode ser qualquer um\ndentre os Tiazídicos. inibidores da ECA ou bloqueadores do canal de cálcio. ( ) Todos os adultos\ndevem ter sua PA aferida como medida de rastreamento e uma PAS ? 130 mmHg e/ou PAD ? 80\nmmHg caracteriza HAS. A decisão do início do tratamento farmacológico deve se basear no cálculo\ndo risco cardiovascular pelo escore global de Framingham tendo como alvo terapêutico uma PA <\n120/80 mmHg. É recomendado o início de terapia combinada (2 anti-hipertensivos), se HAS estágio\n2, e/ou se a PA medida estiver acima da meta em mais de 20/10 mmHg (sistólica/diastólica). Os\nfármacos de primeira linha são os Tiazídicos; inibidores da ECA ou bloqueadores do canal de cálcio\ne Betabloqueadores. ( ) O manejo da pessoa com HAS exige a estratificação de seu risco e\nvulnerabilidade, sendo o escore de Framingham ou o QRisk2, e, também, a Pirâmide de Risco para\nanalisar a capacidade de autocuidado, grau de confiança e o apoio que as pessoas têm para cuidar\nde si mesmas, etc, ferramentas importantíssimas para a tomada de decisão junto com o usuário.\n\nNão se recomenda o início do tratamento medicamentoso, antes de se tentar as intervenções não\nmedicamentosas para pessoas com PAS em até 159 ou 99 (grau I) se não elas não tiverem risco\ncardiovascular maior que 20%, ou diabetes mellitus, ou lesão de órgão alvo ou, ainda, doença\ncardiovascular estabelecida. A alternativa que contém a sequência CORRETA, de cima para baixo,\né:","options":{"A":"V, F, V.","B":"V, F, F.","C":"F, V, F.","D":"F, F, V.","E":"F, V, V."},"answer":"D","source":"Clinica médica/MED CLM 03/MED CLM 03.txt","sourceLabel":"MED · MED CLM 03","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-03-181155","number":"181155","sourceNumber":"181155","collectionBlock":"med:med-clinica-medica-med-clm-03","collectionLabel":"MED · MED CLM 03","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 03","subtopic":"","stem":"Dos itens abaixo, qual geralmente não está relacionado à Síndrome Metabólica?","options":{"A":"Baixos níveis de insulina.","B":"Síndrome dos Ovários Policísticos.","C":"Esteatose hepática não alcoólica.","D":"Dislipidemia."},"answer":"A","source":"Clinica médica/MED CLM 03/MED CLM 03.txt","sourceLabel":"MED · MED CLM 03","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-03-181169","number":"181169","sourceNumber":"181169","collectionBlock":"med:med-clinica-medica-med-clm-03","collectionLabel":"MED · MED CLM 03","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 03","subtopic":"","stem":"A Aterosclerose é uma doença inflamatória crônica de origem multifatorial que ocorre\nem resposta à agressão endotelial, acometendo\nprincipalmente a camada íntima de artérias de\nmédio e grande calibres. Sendo INCORRETO a seu respeito:","options":{"A":"A formação da placa aterosclerótica inicia-se com a agressão ao endotélio vascular devida a\ndiversos fatores de risco como dislipidemia, hipertensão arterial ou tabagismo.","B":"A disfunção endotelial diminui a permeabilidade da íntima às lipoproteínas plasmáticas,\nfavorecendo a retenção das mesmas no espaço subendotelial.","C":"Ocorre que as partículas de LDL sofrem oxidação, causando a exposição de diversos\nneoepitopos e tornando-as imunogênicas.","D":"O depósito de lipoproteínas na parede arterial, processo-chave no início da aterogênese, ocorre\nde maneira proporcional à concentração dessas\nlipoproteínas no plasma."},"answer":"D","source":"Clinica médica/MED CLM 03/MED CLM 03.txt","sourceLabel":"MED · MED CLM 03","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-03-181182","number":"181182","sourceNumber":"181182","collectionBlock":"med:med-clinica-medica-med-clm-03","collectionLabel":"MED · MED CLM 03","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 03","subtopic":"","stem":"Um grande número de pacientes procura serviços de Emergência devido à Hipertensão\nArterial. Considerando os conceitos de Urgência\nHipertensiva (UH), Emergência Hipertensiva (EH)\ne Crise Hipertensiva, qual item não se mostra adequado?","options":{"A":"A sobrevida de até 5 anos é significantemente maior em indivíduos com UH do que com EH.","B":"Ausência de descenso noturno associa-se a maior risco de Lesão Órgão Alvo e consequente\ndisfunção endotelial, situação envolvida na\nelevação aguda da PA.","C":"Pacientes com queixas de cefaleia, dor torácica atípica, dispneia, estresse psicológico agudo e\nsíndrome de pânico associados à PA elevada não caracterizam UH ou EH, mas, na realidade, uma\npseudocrise hipertensiva,","D":"O tratamento pseudocrise hipertensiva deve ser realizado com medicações endovenosas\npreferencialmente e conscientização da adesão ao tratamento."},"answer":"D","source":"Clinica médica/MED CLM 03/MED CLM 03.txt","sourceLabel":"MED · MED CLM 03","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-03-181202","number":"181202","sourceNumber":"181202","collectionBlock":"med:med-clinica-medica-med-clm-03","collectionLabel":"MED · MED CLM 03","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 03","subtopic":"","stem":"O quadro de Hipertensão Arterial Resistente (HAR) é definido de maneira adequado por\ndiversos fatores. Para o diagnóstico de HAR é necessária medida ambulatorial de PA e verificação\nsistemática de adesão, sendo INCORRETO apenas:","options":{"A":"PA de consultório não controlada apesar do uso de três ou mais anti-hipertensivos em doses\ninadequadas, incluindo-se preferencialmente um DIU, ou em uso de quatro ou mais medicamentos\ncom controle pressórico.","B":"Quando não inclui a verificação sistemática da terapêutica e da adesão, essa situação é melhor\ndefinida como HAR aparente (pseudorresistência).","C":"A identificação da HAR verdadeira é fundamental para estabelecer abordagens específicas.","D":"Estudos populacionais estimam prevalência em 12% da população hipertensa."},"answer":"A","source":"Clinica médica/MED CLM 03/MED CLM 03.txt","sourceLabel":"MED · MED CLM 03","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-03-162511","number":"162511","sourceNumber":"162511","collectionBlock":"med:med-clinica-medica-med-clm-03","collectionLabel":"MED · MED CLM 03","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 03","subtopic":"","stem":"Josefina, 56 anos, vem para consulta do HIPERDIA, na Unidade de Saúde da Família e\né atendida por um médico residente. Ela está\npreocupada e relata estar usando as medicações\n\"direitinho\" como foram prescritas, que faz uso das medicações neste dia da consulta e a\nalimentação está adequada. Está em uso de hidroclorotiazida 50mg/dia, enalapril 40 mg/dia e\nanlodipino 10mg/dia. Sua PA no momento está 168 x 90 mmHg e a média das medidas\nambulatoriais estão maiores que 150 x 90 mmHg. Em relação a este caso, é correto afirmar que","options":{"A":"é necessário aumentar a dose do enalapril para 80 mg/dia.","B":"é necessário aumentar a dose do anlodipino para 20 mg/dia.","C":"pode ser necessário encaminhar a paciente para o cardiologista.","D":"a PA de Josefina está elevada, pois a medicação de escolha, em monoterapia, seria um\nbetabloqueador.","E":"a PA de Josefina está elevada, pois não há indicação de uso de enalapril associado à\nhidroclorotiazida ou ao anlodipino."},"answer":"C","source":"Clinica médica/MED CLM 03/MED CLM 03.txt","sourceLabel":"MED · MED CLM 03","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-03-157628","number":"157628","sourceNumber":"157628","collectionBlock":"med:med-clinica-medica-med-clm-03","collectionLabel":"MED · MED CLM 03","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 03","subtopic":"","stem":"Dentro do diagnóstico de doença aterosclerótica coronariana subclínica, podemos\nconsiderar como VERDADEIRA a seguinte situação. Assinale-a.","options":{"A":"A identificação apenas de indivíduos sintomáticos, portadores de aterosclerose e, dessa forma,\nsob risco de eventos cardiovasculares\nagudos, como o infarto e morte, é fundamental para se\ninstituírem medidas de tratamento e prevenção secundária.","B":"Diversos algoritmos têm sido criados com base em análises de regressão de estudos\npopulacionais, por meio dos quais a\nidentificação do risco global é substancialmente piorada pela\ncriação de viés.","C":"A estimativa do risco de doença aterosclerótica não apresenta necessidade de ser avaliada pelo\nsomatório do risco causado individualmente ou pelo sinergismo dos reconhecidos fatores de risco\npara doença cardiovascular.","D":"Diante da complexidade dessas interações cardiovasculares, a atribuição intuitiva do risco\nfrequentemente resulta em subestimação ou superestimação dos casos de maior ou menor risco,\nrespectivamente. Para contornar essa dificuldade, diversos algoritmos têm sido criados com base\nem análises de regressão de estudos populacionais, por meio dos quais a identificação do risco\nglobal é substancialmente aprimorada."},"answer":"D","source":"Clinica médica/MED CLM 03/MED CLM 03.txt","sourceLabel":"MED · MED CLM 03","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-03-157630","number":"157630","sourceNumber":"157630","collectionBlock":"med:med-clinica-medica-med-clm-03","collectionLabel":"MED · MED CLM 03","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 03","subtopic":"","stem":"A avaliação inicial de um paciente com Hipertensão Arterial Sistêmica (HAS) inclui a\nconfirmação do diagnóstico, a suspeição e a identificação de causa secundária, além da avaliação\ndo risco CV, sendo DESNECESSÁRIO certificar-se de que o paciente não:","options":{"A":"Esteja com a bexiga cheia.","B":"Tenha praticado exercícios físicos há pelo menos 60 minutos.","C":"Tenha ingerido bebidas alcoólicas, café ou alimentos.","D":"Tenha fumado nos 60 minutos anteriores."},"answer":"D","source":"Clinica médica/MED CLM 03/MED CLM 03.txt","sourceLabel":"MED · MED CLM 03","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-03-157629","number":"157629","sourceNumber":"157629","collectionBlock":"med:med-clinica-medica-med-clm-03","collectionLabel":"MED · MED CLM 03","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 03","subtopic":"","stem":"Hipertensão Arterial (HA) é condição clínica multifatorial caracterizada por diversas\nalterações. Sobre isso, indique a alternativa CORRETA.","options":{"A":"Raramente se associa a distúrbios metabólicos, alterações funcionais e/ou estruturais de\nórgãos-alvo, sendo agravada pela presença de outros fatores de risco (FR), como dislipidemia,\nobesidade abdominal, intolerância à glicose e diabetes melito (DM).","B":"Hipertensão arterial (HA) é condição clínica multifatorial caracterizada por elevação eventual\ndos\nníveis pressóricos = 140 e/ou 90 mmHg.","C":"Mantém associação dependente com eventos como morte súbita, acidente vascular encefálico\n(AVE) e infarto agudo do miocárdio (IAM).","D":"Mantém associação independente com eventos como insuficiência cardíaca (IC), doença arterial\nperiférica (DAP) e doença renal crônica (DRC), fatal e não fatal."},"answer":"D","source":"Clinica médica/MED CLM 03/MED CLM 03.txt","sourceLabel":"MED · MED CLM 03","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-03-157633","number":"157633","sourceNumber":"157633","collectionBlock":"med:med-clinica-medica-med-clm-03","collectionLabel":"MED · MED CLM 03","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 03","subtopic":"","stem":"Quando analisamos o quadro brasileiro de Hipertensão Arterial e doença\ncardiovascular, podemos considerar como ADEQUADO o\nque consta em uma das opções.\nIndique-a.","options":{"A":"Hipertensão arterial atinge mais de 60% dos idosos.","B":"Junto com DM, suas complicações (cardíacas, renais e AVE) têm impacto pequeno na perda da\nprodutividade do trabalho e da renda familiar.","C":"Hipertensão arterial no Brasil atinge 15% (36 milhões) de indivíduos adultos.","D":"Em 2013 ocorreram 1.138.670 óbitos, 339.672 dos quais (9,8%) decorrentes de DCV, a principal\ncausa de morte no país."},"answer":"A","source":"Clinica médica/MED CLM 03/MED CLM 03.txt","sourceLabel":"MED · MED CLM 03","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-03-157577","number":"157577","sourceNumber":"157577","collectionBlock":"med:med-clinica-medica-med-clm-03","collectionLabel":"MED · MED CLM 03","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 03","subtopic":"","stem":"Dentro da necessidade de avaliação inicial de um paciente com Hipertensão Arterial\nSistêmica (HAS) inclui a confirmação do diagnóstico, com correta metodologia de aferição da PA,\nINADEQUADAMENTE descrita em uma das alternativas a seguir. Assinale-a:","options":{"A":"Posicionamento: o paciente deve estar sentado, com pernas descruzadas e pés apoiados no\nchão.","B":"O braço deve estar na altura do coração, apoiado, com a palma da mão voltada para baixo e as\nroupas não devem garrotear o membro.","C":"Medir a PA na posição de pé, após 3 minutos.","D":"Posicionamento: o paciente deve estar sentado, dorso recostado na cadeira e relaxado."},"answer":"B","source":"Clinica médica/MED CLM 03/MED CLM 03.txt","sourceLabel":"MED · MED CLM 03","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-03-157581","number":"157581","sourceNumber":"157581","collectionBlock":"med:med-clinica-medica-med-clm-03","collectionLabel":"MED · MED CLM 03","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 03","subtopic":"","stem":"Dentre as etapas para a realização da medição, NÃO pode ser considerada correta\numa delas. Indique-a.","options":{"A":"Determinar a circunferência do braço no ponto médio entre acrômio e olecrano.","B":"Selecionar o manguito de tamanho adequado ao braço.","C":"Colocar o manguito, sem deixar folgas, 5 cm acima da fossa cubital.","D":"Centralizar o meio da parte compressiva do manguito sobre a artéria braquial."},"answer":"C","source":"Clinica médica/MED CLM 03/MED CLM 03.txt","sourceLabel":"MED · MED CLM 03","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-03-157584","number":"157584","sourceNumber":"157584","collectionBlock":"med:med-clinica-medica-med-clm-03","collectionLabel":"MED · MED CLM 03","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 03","subtopic":"","stem":"Dentre as inter-relações entre Hipertensão Arterial e doença cardiovascular no Brasil,\naponte a alternativa em que a afirmação esteja INCORRETA.","options":{"A":"Em 2013 ocorreram 1.138.670 óbitos, 339.672 dos quais (29,8%) decorrentes de DCV, a\nprincipal causa de morte no País.","B":"As taxas de mortalidade decorrentes de DCV em geral têm apresentado redução ao longo dos\nanos, com exceção das doenças hipertensivas (DH), que aumentou entre 2002 e 2009 e mostrou\ntendência à redução desde 2010.","C":"As taxas de mortalidade têm apresentado redução das doenças hipertensivas (DH), no período\nque compreendeu entre 2002 e 2009.","D":"Dentro de nossa realidade houve redução da IC congestiva."},"answer":"C","source":"Clinica médica/MED CLM 03/MED CLM 03.txt","sourceLabel":"MED · MED CLM 03","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-03-157587","number":"157587","sourceNumber":"157587","collectionBlock":"med:med-clinica-medica-med-clm-03","collectionLabel":"MED · MED CLM 03","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 03","subtopic":"","stem":"Dentro dos conceitos de Medicina Preventiva existe um importante conceito de\n\nPré-hipertensão que NÃO está adequadamente relacionado a uma das alternativas apresentadas a\nseguir. Aponte-a.","options":{"A":"Pré-hipertensão (PH) é uma condição caracterizada por PA sistólica (PAS) entre 121 e 139 e/ou\nPA diastólica (PAD) entre 81 e 89 mmHg.","B":"Cerca de um décimo dos eventos cardiovasculares (CV) atribuíveis à elevação de PA ocorrem\nem indivíduos com PH.","C":"A PH associa-se a maior risco de desenvolvimento de Hipertensão.","D":"A implicação clínica dessas evidências epidemiológicas é que a PA de indivíduos\n\nPré-hipertensos deve ser monitorada mais de perto, pois uma significativa proporção deles irá\ndesenvolver HA e suas complicações."},"answer":"B","source":"Clinica médica/MED CLM 03/MED CLM 03.txt","sourceLabel":"MED · MED CLM 03","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-03-157589","number":"157589","sourceNumber":"157589","collectionBlock":"med:med-clinica-medica-med-clm-03","collectionLabel":"MED · MED CLM 03","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 03","subtopic":"","stem":"Em relação ao estudo de prevalência de Hipertensão Arterial no Brasil, aponte a\nalternativa que está em DESACORDO com as últimas diretrizes científicas.","options":{"A":"A prevalência de HA no Brasil varia de acordo com a população estudada e o método de\navaliação.","B":"No Norte, foram apresentadas as maiores taxas.","C":"Estudos transversais e de coorte incluídos mostraram tendência à diminuição da prevalência nas\núltimas três décadas.","D":"O Sudeste foi a região com maior prevalência de HA autorreferida."},"answer":"B","source":"Clinica médica/MED CLM 03/MED CLM 03.txt","sourceLabel":"MED · MED CLM 03","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-03-157594","number":"157594","sourceNumber":"157594","collectionBlock":"med:med-clinica-medica-med-clm-03","collectionLabel":"MED · MED CLM 03","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 03","subtopic":"","stem":"Dentre os fatores de risco para Hipertensão Arterial, diversos fatores relacionados a ela\npodem ser considerados como importantes. Desse modo, marque a opção INCORRETA.","options":{"A":"Não ocorre uma associação direta e linear entre envelhecimento e prevalência de Hipertensão.","B":"A prevalência de HA autorreferida foi estatisticamente diferente entre os sexos.","C":"Estudos realizados no Brasil, incluindo indivíduos idosos, mostraram 68% de prevalência de\nHipertensão.","D":"Estudos brasileiros que avaliaram o impacto de polimorfismos genéticos na população de\nquilombolas não conseguiram identificar um padrão mais prevalente."},"answer":"A","source":"Clinica médica/MED CLM 03/MED CLM 03.txt","sourceLabel":"MED · MED CLM 03","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-03-157596","number":"157596","sourceNumber":"157596","collectionBlock":"med:med-clinica-medica-med-clm-03","collectionLabel":"MED · MED CLM 03","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 03","subtopic":"","stem":"Acerca das estratégias para a implementação de medidas de prevenção da\nHipertensão Arterial, que englobam políticas públicas de saúde combinadas com ações das\nsociedades médicas e dos meios de comunicação, podemos considerar como NÃO efetivo o\nseguinte. Indique-o.","options":{"A":"O objetivo deve ser estimular o diagnóstico precoce, o tratamento contínuo, o controle da PA e\nde FR associados.","B":"Promover modificação do estilo de vida (MEV) e/ou uso regular de medicamentos.","C":"Consumo crônico e elevado de bebidas alcoólicas aumenta a PA de forma consistente.","D":"O impacto da dieta rica em sódio, estimada em pesquisas, indica que a maioria das pessoas\nentrevistadas reconhece conteúdo alto ou muito alto de sal nos alimentos."},"answer":"D","source":"Clinica médica/MED CLM 03/MED CLM 03.txt","sourceLabel":"MED · MED CLM 03","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-03-157599","number":"157599","sourceNumber":"157599","collectionBlock":"med:med-clinica-medica-med-clm-03","collectionLabel":"MED · MED CLM 03","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 03","subtopic":"","stem":"Para auxiliar o diagnóstico de hipertensão, pode ser proposta a medição da PA fora do\nconsultório. A PA fora do consultório pode ser obtida através da Medição Residencial da Pressão\nArterial (MRPA), ou da MAPA de 24 horas. As medições da PA fora do consultório devem ser\nestimuladas, podendo ser realizadas por equipamento semiautomático do próprio paciente ou dos\nserviços de saúde. As principais vantagens da medição da PA fora do consultório estão listadas a\nseguir, com a EXCEÇÃO de uma delas. Aponte-a:","options":{"A":"Maior número de medidas obtidas.","B":"Refletem as atividades usuais dos examinandos.","C":"Menor engajamento dos pacientes com o diagnóstico e o seguimento.","D":"Abolição ou sensível redução do efeito de avental branco."},"answer":"C","source":"Clinica médica/MED CLM 03/MED CLM 03.txt","sourceLabel":"MED · MED CLM 03","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-03-157602","number":"157602","sourceNumber":"157602","collectionBlock":"med:med-clinica-medica-med-clm-03","collectionLabel":"MED · MED CLM 03","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 03","subtopic":"","stem":"Paciente hipertenso, mal controlado por ser muito agitado e teimoso, procura seu\nconsultório pela terceira vez a fim de tentar obter o controle de sua hipertensão. Então durante a\nconsulta, diversas argumentações a esse respeito são feitas. Entre elas, uma está atualmente\nINCORRETA, e está contida em uma das opções seguintes. Indique-a.","options":{"A":"O AVE é a manifestação mais comum da lesão vascular causada pela HA.","B":"A escolha terapêutica deve ser baseada na eficácia do medicamento e na tolerabilidade ao\nmesmo.","C":"A associação de Hipertensão e Diabetes aumenta em quatro o risco Cardiovascular, e tem\naumentado a prevalência de HA.","D":"Cronicamente, a terapia anti-hipertensiva eficaz, mantendo PA menor que 130/80 mmHg, tem\ntido um papel decisivo na prevenção secundária de todos os tipos de AVE e AIT."},"answer":"C","source":"Clinica médica/MED CLM 03/MED CLM 03.txt","sourceLabel":"MED · MED CLM 03","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-03-157598","number":"157598","sourceNumber":"157598","collectionBlock":"med:med-clinica-medica-med-clm-03","collectionLabel":"MED · MED CLM 03","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 03","subtopic":"","stem":"O tratamento da Hipertensão tem, em última análise, a redução da morbimortalidade,\nsendo que os desfechos mostram benefícios do\ntratamento realizado com o uso de medicações,\nsendo, entretanto, de grande importância conhecer seus mecanismos de ação bem como efeitos\ncolaterais descritos. Sobre isso, aponte a alternativa INCORRETA.","options":{"A":"Os Betabloqueadores promovem diminuição inicial do débito cardíaco e da secreção de renina,\nhavendo readaptação dos barorreceptores e diminuição das catecolaminas nas sinapses nervosas.","B":"Bloqueadores dos receptores AT1 da angiotensina II, assim os BRA antagonizam a ação da\nangiotensina II por meio do bloqueio específico dos receptores AT1, responsáveis pelas ações\nvasoconstritoras, proliferativas e estimuladoras da liberação de aldosterona, próprias da\nangiotensina II.","C":"Alfa bloqueadores; os medicamentos dessa classe agem como antagonistas competitivos dos\na1-receptores pós-sinápticos, levando à redução da RVP com grande diminuição no débito\ncardíaco.","D":"Vasodilatadores diretos; os medicamentos que representam essa classe são hidralazina e\nminoxidil. Atuam, diretamente, relaxando a musculatura lisa arterial, levando à redução da RVP."},"answer":"C","source":"Clinica médica/MED CLM 03/MED CLM 03.txt","sourceLabel":"MED · MED CLM 03","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-03-157603","number":"157603","sourceNumber":"157603","collectionBlock":"med:med-clinica-medica-med-clm-03","collectionLabel":"MED · MED CLM 03","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 03","subtopic":"","stem":"Recentemente um antigo paciente, que você acompanha no ambulatório de clínica\nmédica, evolui mal e teve indicado o início de Hemodiálise devido à lesão causada pela\nhipertensão. Ele o procurou bastante arrependido de não ter se medicado adequadamente no\npassado, mas pediu novamente a sua orientação, apesar de já ter sido transferido de\nespecialidade. Em consideração aos anos de convívio, você o orientou ADEQUADAMENTE,\nconforme o contido em uma das alternativas a seguir. Assinale-o.","options":{"A":"A medição da PA desses pacientes deve ser feita preferencialmente fora das unidades de\ndiálise, nos intervalos interdialíticos.","B":"As decisões terapêuticas baseadas na medição de PA residencial associam-se a um pior\ncontrole pressórico interdialítico avaliado pela MAPA de 24h em comparação à medição de PA\npré-diálise.","C":"Quando utilizamos a mensuração dos níveis pressóricos pré-diálise, ocorre que a PA obtida\ndessa forma, além de apresentar grande variabilidade, está geralmente superestimada.","D":"Quando utilizamos a mensuração dos níveis pressóricos, ela é subestimada quando obtida após\na diálise."},"answer":"B","source":"Clinica médica/MED CLM 03/MED CLM 03.txt","sourceLabel":"MED · MED CLM 03","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-03-157610","number":"157610","sourceNumber":"157610","collectionBlock":"med:med-clinica-medica-med-clm-03","collectionLabel":"MED · MED CLM 03","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 03","subtopic":"","stem":"Paciente hipertenso e diabético (ambos mal controlados porque o paciente é rebelde ao\ntratamento) se recusa a se medicar diariamente, bem como não consegue mudar seu estilo de vida,\nque tem, como principais pontos, o tabagismo e a ingesta de grandes quantidades de sal nos\nchurrascos. Durante última consulta, foi constatado alteração da creatinina bem como um USG, que\ndemonstrava rins aparentemente com anatomia preservada. Acerca desse quadro, podemos\nconsiderar que:","options":{"A":"Na doença renal crônica, a redução pressórica não constitui a medida mais eficaz para a\nredução do risco CV.","B":"Após iniciada a doença renal crônica, o controle da HAS não promove mais a atenuação da\nprogressão do dano renal, independentemente do anti-hipertensivo utilizado.","C":"O achado de albuminúria elevada é determinante de evolução desfavorável da doença renal,\nmas não causa aumento do risco Cardiovascular.","D":"Pacientes idosos com doença renovascular, DAC e com risco de hipotensão postural\nfrequentemente requerem a individualização do tratamento anti-hipertensivo."},"answer":"D","source":"Clinica médica/MED CLM 03/MED CLM 03.txt","sourceLabel":"MED · MED CLM 03","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-03-157617","number":"157617","sourceNumber":"157617","collectionBlock":"med:med-clinica-medica-med-clm-03","collectionLabel":"MED · MED CLM 03","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 03","subtopic":"","stem":"Recentemente ocorreu um óbito em seu plantão com um paciente relativamente jovem,\n57 anos de idade, que apresentava intensa\ndor torácica e dorsal, fora pressão extremamente\nelevada. Assim, sua curiosidade levou a, novamente, a revisar os conceitos de hipertensão,\ndescobrindo que o seguinte conceito estava INCORRETO. Assinale-o.","options":{"A":"Crise hipertensiva, chamada de Emergência, é caracterizada por elevação aguda de PA\nassociada à Lesão Órgão Alvo, que pode\nincluir acometimento neurológico, renal, ocular, hepático\nou insuficiência miocárdica, manifesta como encefalopatia, convulsões, alterações visuais, achados\nanormais de eletrocardiograma ou ecocardiograma, insuficiência renal ou hepática.","B":"A Urgência é descrita como elevação da PA superior ao percentil 99 mais 5 mmHg (estágio 2),\nassociada a sintomas menos graves, em paciente sob risco de evolução para LOA progressiva,\nsem evidência de acometimento recente.","C":"Na Urgência sugere-se manejo com medicamentos, por via oral, com redução de PA em 12\nhoras, sob monitorização.","D":"A redução muito rápida de PA na Urgência é contraindicada, pois leva à hipotensão, falência de\nmecanismos autorreguladores e possibilidade de isquemia cerebral e visceral."},"answer":"C","source":"Clinica médica/MED CLM 03/MED CLM 03.txt","sourceLabel":"MED · MED CLM 03","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-03-157621","number":"157621","sourceNumber":"157621","collectionBlock":"med:med-clinica-medica-med-clm-03","collectionLabel":"MED · MED CLM 03","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 03","subtopic":"","stem":"Como seu avô é viúvo e participa ativamente de diversas atividades sociais da terceira\nidade, ele convidou você para ministrar uma palestra, em seu grupo de idosos, com orientações\nsobre a hipertensão, o que você prontamente atendeu. Sobre as suas orientações, aponte aquela\nque é considera a MAIS correta.","options":{"A":"A prevalência da Hipertensão aumenta progressivamente com o envelhecimento, sendo\nconsiderado o principal Fator Risco Cardiovascular não modificável na população geriátrica.","B":"São considerados idosos, sob o ponto de vista cronológico, indivíduos com 75 anos ou mais de\nidade, vivendo em países desenvolvidos, ou com 70 anos ou mais, em países em desenvolvimento.","C":"Dentro desse grupo etário, são chamados de muito idosos aqueles que já alcançaram a sétima\ndécada de vida.","D":"O envelhecimento vascular é o aspecto principal relacionado à elevação da PA nos idosos,\ncaracterizado por alterações na microarquitetura da parede dos vasos, com consequente\nenrijecimento arterial."},"answer":"D","source":"Clinica médica/MED CLM 03/MED CLM 03.txt","sourceLabel":"MED · MED CLM 03","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-03-157626","number":"157626","sourceNumber":"157626","collectionBlock":"med:med-clinica-medica-med-clm-03","collectionLabel":"MED · MED CLM 03","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 03","subtopic":"","stem":"Dentro da abordagem de hipertensão na situação especial que é a do idoso, NÃO\npodemos concordar que:","options":{"A":"Existem evidências robustas do benefício de reduzir a PA com o tratamento anti-hipertensivo em\nidosos com 80 anos ou mais. Essa vantagem está limitada a indivíduos com PAS = 160 mmHg, nos\nquais a PAS foi reduzida a valores < 150 mmHg.","B":"Em indivíduos idosos com menos de 80 anos, o tratamento anti-hipertensivo pode ser\nconsiderado para aqueles com PAS > 140 mmHg,\npara uma meta de PAS < 140 mmHg, desde que\nos indivíduos apresentem uma boa condição clínica e o tratamento seja bem tolerado.","C":"Os benefícios de diferentes regimes terapêuticos em pacientes com idade superior ou inferior a\n65 anos confirmam que existem evidências de\nque diferentes classes possuam efetividades\ndiferentes em pacientes mais jovens ou mais velhos.","D":"Um aspecto que merece destaque é a possibilidade de HA secundária no idoso, cujas causas\nmais frequentes são estenose de artérias renal,\nsíndrome da apneia e hipopneia obstrutiva do sono\n(SAHOS), alterações de função tireoidiana e uso de medicamentos que podem elevar a PA."},"answer":"C","source":"Clinica médica/MED CLM 03/MED CLM 03.txt","sourceLabel":"MED · MED CLM 03","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-03-157738","number":"157738","sourceNumber":"157738","collectionBlock":"med:med-clinica-medica-med-clm-03","collectionLabel":"MED · MED CLM 03","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 03","subtopic":"","stem":"Durante consulta ambulatorial de paciente cardiopata, os familiares do paciente\nquestionaram o médico assistente a respeito do\nconsumo de álcool dele. Sendo assim, assinale a\nalternativa que apresenta a orientação INCORRETA a respeito desse questionamento.","options":{"A":"Consumo crônico e elevado de bebidas alcoólicas aumenta a PA de forma consistente.","B":"Ocorre em mulheres efeito protetor com dose inferior a 40 g de álcool/dia.","C":"Ocorre em mulheres risco de HA com consumo de 30-40 g de álcool/dia.","D":"Em homens, o risco aumentado de HA tornou-se consistente a partir de 31 g de álcool/dia."},"answer":"B","source":"Clinica médica/MED CLM 03/MED CLM 03.txt","sourceLabel":"MED · MED CLM 03","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-03-157748","number":"157748","sourceNumber":"157748","collectionBlock":"med:med-clinica-medica-med-clm-03","collectionLabel":"MED · MED CLM 03","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 03","subtopic":"","stem":"Durante reunião da equipe de saúde, você é convidado a opinar a respeito de uma\ncampanha de aferição de pressão arterial,\nfora do ambiente médico. Assim, você fundamenta sua\nopinião, ADEQUADAMENTE, com o contido na seguinte opção. Assinale-a:","options":{"A":"Uma das vantagens de medição da PA fora do consultório seria o maior engajamento dos\npacientes com diagnóstico e seguimento.","B":"Uma das desvantagens seria a de ter relação com as atividades usuais dos examinandos.","C":"Maior chance de vezes de medida pela potencialização do efeito do avental branco.","D":"Aumenta a chance de erro diagnóstico por menor número de medidas pelo médico."},"answer":"A","source":"Clinica médica/MED CLM 03/MED CLM 03.txt","sourceLabel":"MED · MED CLM 03","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-03-157749","number":"157749","sourceNumber":"157749","collectionBlock":"med:med-clinica-medica-med-clm-03","collectionLabel":"MED · MED CLM 03","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 03","subtopic":"","stem":"Quando da avaliação de Idosos Hipertensos, podemos considerar como característicos\ndeles as seguintes alternativas, com EXCEÇÃO de\numa delas. Assinale-a.","options":{"A":"Ocorre uma maior frequência do hiato uscultatório, que consiste no desaparecimento dos sons\ndurante a deflação do manguito, resultando em valores falsamente baixos para a PAS ou\nfalsamente baixos para a PAD.","B":"A grande variação da PA nos idosos ao longo das 24 horas torna a MAPA uma ferramenta\nmuitas vezes útil.","C":"A pseudo-hipertensão, que está associada ao processo aterosclerótico.","D":"Presença de arritmias, como Fibrilação Atrial, pode dificultar a medição da PA."},"answer":"A","source":"Clinica médica/MED CLM 03/MED CLM 03.txt","sourceLabel":"MED · MED CLM 03","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-03-157753","number":"157753","sourceNumber":"157753","collectionBlock":"med:med-clinica-medica-med-clm-03","collectionLabel":"MED · MED CLM 03","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 03","subtopic":"","stem":"O sucesso do tratamento da Hipertensão Arterial com medidas nutricionais depende da\nadoção de um plano alimentar saudável e\nsustentável, sendo que a proposta de utilização de dietas\nradicais resulta em abandono do tratamento. Podemos adequadamente orientar durante a consulta\nestes tópicos, com a EXCEÇÃO de um deles. Aponte-o.","options":{"A":"Existem evidências de que a ingestão de laticínios, em especial os com baixo teor de gordura,\nreduz a PA, sendo que o leite contém vários\ncomponentes, como cálcio, potássio e peptídeos\nbioativos que podem diminuir a PA.","B":"O café, apesar de rico em cafeína, é uma substância com efeito pressor agudo, e possui\npolifenóis que podem favorecer a redução da PA.","C":"O consumo de café em doses habituais está associado à maior incidência de Hipertensão\nArterial.","D":"O aumento do consumo de sódio está relacionado ao aumento da PA."},"answer":"C","source":"Clinica médica/MED CLM 03/MED CLM 03.txt","sourceLabel":"MED · MED CLM 03","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-03-157754","number":"157754","sourceNumber":"157754","collectionBlock":"med:med-clinica-medica-med-clm-03","collectionLabel":"MED · MED CLM 03","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 03","subtopic":"","stem":"As ditas crises hipertensivas representam grande desafio para a prática clínica da\nmedicina de urgência, vez que se correlacionam diversos órgãos e sistemas que finalmente são\nlesados pela elevação descontrolada e lesiva da Pressão. Assinale a alternativa que NÃO está\ndentre essas lesões.","options":{"A":"Edema Cerebral.","B":"Sangramento Cerebral.","C":"Edema de Papila de Nervo Óptico.","D":"Cefaleia tipo Cluster."},"answer":"D","source":"Clinica médica/MED CLM 03/MED CLM 03.txt","sourceLabel":"MED · MED CLM 03","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-03-111819","number":"111819","sourceNumber":"111819","collectionBlock":"med:med-clinica-medica-med-clm-03","collectionLabel":"MED · MED CLM 03","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 03","subtopic":"","stem":"Paciente hipertenso mal controlado, suspendeu, durante as festas do final de ano, sua\nmedicação anti-hipertensiva, que era Atenolol, Enalapril e Hidroclorotiazida. Após discussão\nfamiliar, deu entrada no hospital com intenso mal-estar, desorientação e agitação, sendo, então,\nrealizada tomografia de crânio. Foi abordado por quadro de emergência hipertensiva, que foi\ncaracterizado na Tomografia de crânio. Qual dos itens abaixo NÃO é compatível com esse\ndiagnóstico?","options":{"A":"Hemorragia subaracnoide.","B":"Edema cerebral por vasodilatação.","C":"Hemorragia intraparenquimatosa.","D":"Hematoma subdural crônico."},"answer":"D","source":"Clinica médica/MED CLM 03/MED CLM 03.txt","sourceLabel":"MED · MED CLM 03","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-03-111870","number":"111870","sourceNumber":"111870","collectionBlock":"med:med-clinica-medica-med-clm-03","collectionLabel":"MED · MED CLM 03","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 03","subtopic":"","stem":"Paciente dá entrada no pronto-socorro queixando-se de intensa cefaleia e mal-estar de\ninício súbito nesta manhã, quando iniciou suas atividades. Em avaliação inicial, mostrava-se lúcida,\nmas com fácies de dor e algo agitada. Sua pressão demonstrava valores elevados de 200 x 100\nmmHg. Dessa forma, qual informação podemos considerar ADEQUADA?","options":{"A":"Trata-se de emergência hipertensiva.","B":"Trata-se de AVC Hemorrágico.","C":"Está indicado Nitroprussiato de Sódio.","D":"Inicialmente devemos medicar com analgésicos e ansiolíticos."},"answer":"D","source":"Clinica médica/MED CLM 03/MED CLM 03.txt","sourceLabel":"MED · MED CLM 03","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-03-111901","number":"111901","sourceNumber":"111901","collectionBlock":"med:med-clinica-medica-med-clm-03","collectionLabel":"MED · MED CLM 03","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 03","subtopic":"","stem":"Qual das medicações abaixo listadas apresenta a necessidade de cuidados quanto à\ninterferência de energia física, durante a sua infusão, e por isso de equipo com proteção?","options":{"A":"Furosemida.","B":"Emulsão Lipídeos.","C":"Nitroprussiato de Sódio.","D":"Glicose hipertônica."},"answer":"C","source":"Clinica médica/MED CLM 03/MED CLM 03.txt","sourceLabel":"MED · MED CLM 03","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-03-350864","number":"350864","sourceNumber":"350864","collectionBlock":"med:med-clinica-medica-med-clm-03","collectionLabel":"MED · MED CLM 03","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 03","subtopic":"","stem":"Paciente de 42 anos, atleta, com história recente de hipertensão de difícil controle, sem\noutras comorbidades. Faz uso de dois anti-hipertensivos (anlodipina e atenolol). O paciente\napresentou episódio de astenia e paresia de membros inferiores tendo sido internado para\ninvestigação. Exame laboratorial evidenciou hipocalemia (1,9mmol/L), dosagem de catecolaminas\nurinárias normais. Qual achado de exame complementar é mais compatível com o diagnóstico?","options":{"A":"Nódulo adrenal à tomografia com contraste.","B":"Aneurisma de artéria renal à angiotomografia.","C":"Hematúria e proteinúria no sumário de urina.","D":"Nefropatia atrófica no ultrassom de vias urinárias."},"answer":"A","source":"Clinica médica/MED CLM 03/MED CLM 03.txt","sourceLabel":"MED · MED CLM 03","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-03-350854","number":"350854","sourceNumber":"350854","collectionBlock":"med:med-clinica-medica-med-clm-03","collectionLabel":"MED · MED CLM 03","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 03","subtopic":"","stem":"Homem de 58 anos teve um infarto agudo do miocárdio (IAM) há 3 meses, quando foi\ndiagnosticado como hipertenso. Está em uso de losartana 50 mg/dia, sinvastatina 10 mg/dia e AAS\n100 mg/dia, com boa tolerância. É sedentário e refere ingestão diária de frituras. Informa pai\nfalecido aos 54 anos por IAM e mãe diabética. Ao exame físico: acantose nigricans cervical,\npressão arterial 124/80 mmHg, IMC 33 kg/m², circunferência abdominal 108 cm, ausculta\ncardiopulmonar fisiológica, sem edemas. Os exames laboratoriais evidenciaram TSH 3,0 uUI/mL\n(VR: 0,5-5,0 uUI/mL), TGO 38 U/L (VR até 40 U/L), TGP 40 U/L (VR até 41 U/L), glicemia de jejum\n98 mg/dL (VR: 70 a 99 mg/dL), colesterol total 224 mg/dL (VR menor que 190 mg/dL), HDL 36\nmg/dL (VR maior que 40 mg/dL), LDL 148 mg/dL (VR menor que 50 mg/dL), triglicerídeos 180\nmg/dL (VR menor que 150 mg/dL). Assinale a abordagem terapêutica mais adequada para\ndislipidemia desse paciente:","options":{"A":"Aumentar sinvastatina para 20 mg/dia e estabelecer dieta hipolipídica.","B":"Associar ezetimiba 10 mg/dia e iniciar ciprofibrato 100 mg/dia.","C":"Trocar sinvastatina por rosuvastatina 20 mg/dia.","D":"Trocar sinvastatina por atorvastatina 20 mg/dia."},"answer":"C","source":"Clinica médica/MED CLM 03/MED CLM 03.txt","sourceLabel":"MED · MED CLM 03","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-03-350877","number":"350877","sourceNumber":"350877","collectionBlock":"med:med-clinica-medica-med-clm-03","collectionLabel":"MED · MED CLM 03","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 03","subtopic":"","stem":"Paciente de 45 anos procura atendimento sem queixas objetivas. Relata perda de peso\nintencional - 15Kg ao longo dos últimos 12 meses - após mudança de estilo de vida (dieta e\natividade física), motivada por diagnóstico de pré-diabetes. Persiste com o hábito de exercícios\nregulares (150min de atividade aeróbica semanal) além de dieta adequada. O exame físico está\nnormal, exceto pela pressão arterial de 140x100mmHg e discreto edema de membros inferiores\nassociado a aparente insuficiência venosa. Optou-se por uma rotina de aferições pressóricas\nambulatoriais diárias (realizadas em um ambiente próximo ao seu domicílio), além de realização de\nexames complementares. Os resultados foram: hemograma, perfil lipídico e função renal normais.\nHemoglobina glicada=5,5%, relação albumina/creatinina urinárias=450mg/g (VR < 30mg/g). A\nmédia das medidas pressóricas confirmou o valor aferido na consulta inicial. Ao ser informado da\nnecessidade de tratamento, relata ser contrário ao uso de mais de uma droga, inicialmente. Com\nbase nesses dados, qual dos itens abaixo representa a melhor escolha anti-hipertensiva?","options":{"A":"Bloqueador de canal de cálcio.","B":"Diurético tiazídico.","C":"Inibidor de ECA.","D":"Betabloqueador."},"answer":"C","source":"Clinica médica/MED CLM 03/MED CLM 03.txt","sourceLabel":"MED · MED CLM 03","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-03-292865","number":"292865","sourceNumber":"292865","collectionBlock":"med:med-clinica-medica-med-clm-03","collectionLabel":"MED · MED CLM 03","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 03","subtopic":"","stem":"Durante o exame físico de Edberto, você aferiu PA = 162 x 114mmHg, IMC = 38kg/m² ,\ncircunferência abdominal = 110 cm e glicemia capilar em jejum = 158 mg/dl. A ausculta cardíaca\nevidenciou frequência cardíaca de repouso de 120 bpm, ictus deslocado para o 6º espaço\nintercostal e com caráter propulsivo. Edberto ficou surpreso com o valor de sua pressão arterial,\nreferindo que, apesar de não lembrar quando fora a última vez que teve a pressão arterial aferida,\nnunca havia chegado a esse nível pressórico. Ele, então, pergunta qual significado clínico desse\nvalor. Assinale a alternativa com a conduta CORRETA.","options":{"A":"Orientar que essa aferição isolada não implica diagnóstico de HAS, mas, em próximo\natendimento, caso nível pressórico esteja maior que\n140x90, será dado o diagnóstico de HAS.","B":"Orientar que essa aferição isolada não implica diagnóstico de HAS. Solicitar diário pressórico\n(MRPA) para diagnóstico de HAS em próximo atendimento.","C":"Diagnosticar e comunicar evento de Emergência hipertensiva e encaminhar a serviço de\nUrgência e Emergência para controle parenteral.","D":"Informar que mesmo com somente essa aferição isolada, considerando dados clínicos, o\npaciente tem diagnóstico de HAS em medição única."},"answer":"D","source":"Clinica médica/MED CLM 03/MED CLM 03.txt","sourceLabel":"MED · MED CLM 03","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-03-199784","number":"199784","sourceNumber":"199784","collectionBlock":"med:med-clinica-medica-med-clm-03","collectionLabel":"MED · MED CLM 03","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 03","subtopic":"","stem":"Um senhor de 74 anos, sem história de doenças prévias ou uso de medicações,\nfumante de cerca de 5 cigarros por dia,\napresentou em consulta prévia registro de 2 aferições de\nPA com média de 136 x 86 mmHg. Trouxe ECG que apresenta padrão strain e evidencia derivação\naVL com onda R de 13 mm e derivação V3 com onda S de 20 mm associado a componente\nnegativo de onda P em derivação V1, de 2 mm. Ao realizar fundoscopia direta, observa-se o\nachado da foto abaixo. O médico insufla o cuff até 160 mmHg, deixando de perceber pulso radial\nentre 130 e 140 mmHg e não consegue palpar artéria radial em 160 mmHg. Após isso, faz 2\nmedidas de PA espaçadas com média de 136 x 82 mmHg. IMC = 29 kg/m². Restante do exame\nfísico sem achados relevantes. LEGENDA: PA: Pressão Arterial; ECG: Eletrocardiograma; IMC:\nÍndice de Massa Corpórea. O médico deve concluir tratar-se de qual condição?","options":{"A":"Pré-hipertensão.","B":"Pseudo-hipertensão.","C":"Hipertensão mascarada.","D":"Hiato auscultatório aumentado."},"answer":"A","source":"Clinica médica/MED CLM 03/MED CLM 03.txt","sourceLabel":"MED · MED CLM 03","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-03-126947","number":"126947","sourceNumber":"126947","collectionBlock":"med:med-clinica-medica-med-clm-03","collectionLabel":"MED · MED CLM 03","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 03","subtopic":"","stem":"Paciente de 48 anos, motorista de ônibus, procurou unidade básica de saúde com\nqueixas de fadiga, hipersonolência diurna\nrelatando que a esposa se queixa do seu ronco à\nnoite que não a deixa dormir. Ao exame físico: índice de massa corpórea de 32 kg/m2,\ncircunferência do pescoço de 41cm, PA:145x95mmHg, Pulso:80 ppm, f:16 irpm. Auscultas\ncardíaca e pulmonar dentro da normalidade. Traz hemograma, glicemia e exames da função\nda tireoide dentro da normalidade. Qual exame deve ser solicitado para confirmação do provável\ndiagnóstico?","options":{"A":"Monitorização cardiorrespiratória de noite inteira.","B":"Endoscopia nasal com manobra de Müller.","C":"Polissonografia de noite inteira.","D":"Polissonografia diurna (nap study)."},"answer":"C","source":"Clinica médica/MED CLM 03/MED CLM 03.txt","sourceLabel":"MED · MED CLM 03","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-03-126993","number":"126993","sourceNumber":"126993","collectionBlock":"med:med-clinica-medica-med-clm-03","collectionLabel":"MED · MED CLM 03","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 03","subtopic":"","stem":"Dona Júlia, 50 anos, descobre em uma atividade preventiva realizada em seu Posto\nque sua pressão está alterada. Após três\nconsultas com sua médica de família (MFC), com\nintervalo de 1 semana entre elas, Dona Júlia é informada que a média de seus valores de PA foi de\n150 x 86 mmHg. A MFC solicita alguns exames para a paciente, que retorna em consulta\nsubsequente com os seguintes resultados: glicemia de jejum = 88mg/dL; K+= 4 mEq/L; creatinina=\n0,6 mg/dL; colesterol total = 180 mg/dL; HDL = 60 mg/dL; triglicerídeos = 145 mg/dL; sumário de\nurina, eletrocardiograma e fundo de olho sem alterações. A paciente nega tabagismo, etilismo,\nhistória prévia ou familiar de doença cardiovascular, tem IMC = 19,6 kg/m², peso = 55 Kg e pratica\nnatação 4 vezes por semana. Relata à médica ter uma certa resistência a tomar medicamentos.\n\nQual a conduta em relação à decisão de terapia medicamentosa para esse caso?","options":{"A":"Iniciar terapia medicamentosa com um fármaco, uma vez que a paciente apresenta hipertensão\nestágio 1.","B":"Iniciar terapia medicamentosa com um fármaco, uma vez que a paciente apresenta lesão em\nórgão-alvo.","C":"Adiar por três a seis meses a decisão por terapia medicamentosa, uma vez que a paciente\napresenta baixo risco cardiovascular.","D":"Adiar por três a seis meses a decisão por terapia medicamentosa, uma vez que a paciente\napresenta moderado risco cardiovascular."},"answer":"C","source":"Clinica médica/MED CLM 03/MED CLM 03.txt","sourceLabel":"MED · MED CLM 03","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-03-102132","number":"102132","sourceNumber":"102132","collectionBlock":"med:med-clinica-medica-med-clm-03","collectionLabel":"MED · MED CLM 03","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 03","subtopic":"","stem":"Paciente do sexo feminino, 56 anos, queixa-se de escurecimento da pele em região\ncervical posterior (veja foto) e axilas. A\nmesma é acompanhada por diabetes melitus tipo 2,\ndislipidemia e hipertensão arterial sistêmica. Faz uso regular de Metformina 1,7 g/dia, Sinvastatina\n20 mg/dia, AAS 100 mg/dia e Hidroclorotiazida 12,5 mg/dia. Nega tabagismo, etilismo ou uso de\ndrogas ilícitas. Exame físico evidencia peso de 85 kg, altura de 1,55 m, pressão arterial de 155 x\n90\nmmHg, discretas crepitações à movimentação passiva de ambos os joelhos e a alteração ilustrada\nna fotografia; demais aspectos inalterados. Exame ginecológico normal. Exames laboratoriais\nrecentes: Hemoglobina glicada (HbA1C) = 6,2%, glicemia de jejum = 106 mg/dl, Colesterol total =\n250 mg/dl, HDL = 30 mg/dl, Triglicerídeos = 300 mg/dl; demais exames séricos e sumário de urina\nnormais. Mamografia = Bi-rads 2, Endoscopia Digestiva Alta e Baixa = normais, Radiografia de\ntórax normal. (VER IMAGEM). Qual das seguintes condutas tem maior impacto no controle da lesão\ndermatológica da paciente?","options":{"A":"Alteração da dose de sinvastatina.","B":"Aumento da dose de hidroclorotiazida.","C":"Associação de sulfoniureia à metformina.","D":"Dieta e exercícios para controle do peso."},"answer":"D","source":"Clinica médica/MED CLM 03/MED CLM 03.txt","sourceLabel":"MED · MED CLM 03","images":["question_bank/media/medcurso/med-clinica-medica-med-clm-03/102132.png"],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-03-102173","number":"102173","sourceNumber":"102173","collectionBlock":"med:med-clinica-medica-med-clm-03","collectionLabel":"MED · MED CLM 03","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 03","subtopic":"","stem":"Paciente, feminina, 58 anos, diabética, comparece em consulta de seguimento com seu\nmédico de família e comunidade. Faz uso contínuo de hipoglicemiante oral de forma regular.\n\nTrouxe exames solicitados na última consulta: glicemia jejum 168 mg/dl, hemoglobina glicada\n8,2%, triglicérides 400 mg/dl, Colesterol total 230 mg/dl, HDL 20 mg/dl. Que conduta deve ser\ntomada na situação acima?","options":{"A":"Prescrever fibrato.","B":"Prescrever estatina.","C":"Prescrever fibrato e estatina.","D":"Prescrever fibrato, estatina e ácido acetilsalicílico."},"answer":"B","source":"Clinica médica/MED CLM 03/MED CLM 03.txt","sourceLabel":"MED · MED CLM 03","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-03-51246","number":"51246","sourceNumber":"51246","collectionBlock":"med:med-clinica-medica-med-clm-03","collectionLabel":"MED · MED CLM 03","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 03","subtopic":"","stem":"Qual a alternativa correta quanto à doença cardiovascular na hipertensão arterial\nsistêmica?","options":{"A":"Diuréticos são eficazes no tratamento da hipertensão arterial, mas não têm eficácia na redução\nda morbidade e da mortalidade cardiovasculares.","B":"A hipertensão sistólica isolada e a pressão de pulso são fatores de risco importantes para\ndoença cardiovascular em pacientes de meia-idade e idosos.","C":"Metas antropométricas a serem alcançadas são o IMC menor que 25 kg/m² e a circunferência\nabdominal \"menor que\" 108 cm para os homens e \"menor que\" 80 cm para as mulheres.","D":"Há superioridade do bloqueador do receptor de angiotensina II em relação ao inibidor da enzima\nconversora da angiotensina na redução de eventos coronarianos."},"answer":"D","source":"Clinica médica/MED CLM 03/MED CLM 03.txt","sourceLabel":"MED · MED CLM 03","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-03-51250","number":"51250","sourceNumber":"51250","collectionBlock":"med:med-clinica-medica-med-clm-03","collectionLabel":"MED · MED CLM 03","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 03","subtopic":"","stem":"Em um indivíduo adulto normal, sem comorbidades, com que idade e intervalo é\nrecomendado solicitar perfil lipídico para avaliação de risco cardiovascular?","options":{"A":"Desde os 20 anos e a cada 5 anos.","B":"Desde os 30 anos e a cada 5 anos.","C":"Desde os 30 anos e a cada 3 anos.","D":"Desde os 40 anos e a cada ano."},"answer":"A","source":"Clinica médica/MED CLM 03/MED CLM 03.txt","sourceLabel":"MED · MED CLM 03","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-03-51225","number":"51225","sourceNumber":"51225","collectionBlock":"med:med-clinica-medica-med-clm-03","collectionLabel":"MED · MED CLM 03","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 03","subtopic":"","stem":"Homem de 46 anos, pedreiro, foi diagnosticado como hipertenso há 2 meses. Seu pai e\ndois irmãos mais velhos são hipertensos. O paciente está em uso de enalapril (20 mg/dia). Ao\nexame, apresentou pressão 150 x 90 mmHg em ambos os braços e 160 x 100 mmHg em membros\ninferiores. Os exames complementares apresentaram: creatinina 0,9 mg/dl; potássio sérico 3,2\nmEq/L; sódio sérico 142 mEq/L; colesterol total 250 mg/dl; LDL 150 mg/dl; triglicerídeos 200 mg/dl;\nglicemia 110 mg/dl. O eletrocardiograma revelou sobrecarga de ventrículo esquerdo. A radiografia\nde tórax não evidenciou alteração. Qual achado sugere hipertensão arterial secundária?","options":{"A":"Potássio sérico baixo.","B":"Sódio sérico elevado.","C":"ECG com sobrecarga de ventrículo esquerdo.","D":"Pressão arterial mais alta nos membros inferiores."},"answer":"A","source":"Clinica médica/MED CLM 03/MED CLM 03.txt","sourceLabel":"MED · MED CLM 03","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-03-51236","number":"51236","sourceNumber":"51236","collectionBlock":"med:med-clinica-medica-med-clm-03","collectionLabel":"MED · MED CLM 03","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 03","subtopic":"","stem":"Homem de 38 anos, motorista, negro, procura seu médico de família para avaliação de\nrotina. Relata etilismo, tabagismo, sedentarismo e alimentação rica em gordura animal. Ao exame:\n98 Kg; 1,65 metros de altura; PA 165 x 95 mmHg (1° medida), PA: 160/95 mmHg (2° medida);\ncintura abdominal 98 cm. Ausculta cardíaca e pulmonar sem alterações. Exames complementares:\nColesterol total: 200 mg/dl; HDL: 50 mg/dl; triglicérides: 260 mg/dl; glicemia de jejum: 98 mg/dl;\ncreatinina: 0,8 mg/dl; sumário de urina sem alterações; ácido úrico 8,2 mg/dl. Raio X de tórax e\nECG de repouso sem alterações. Segundo a escala de Framingham, qual o risco cardiovascular\nestimado para esse paciente?","options":{"A":"Risco médio, ou entre 15 e 20% em 10 anos.","B":"Risco baixo, ou menos de 10% em 10 anos.","C":"Risco médio, entre 10 e 15% em 10 anos.","D":"Risco alto, ou mais de 20% em 10 anos."},"answer":"B","source":"Clinica médica/MED CLM 03/MED CLM 03.txt","sourceLabel":"MED · MED CLM 03","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-03-141578","number":"141578","sourceNumber":"141578","collectionBlock":"med:med-clinica-medica-med-clm-03","collectionLabel":"MED · MED CLM 03","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 03","subtopic":"","stem":"Dona Gasparina, 70 anos, fuma há 40 anos, vive com Sr. Manoel, 75 anos, tabagista\nhá 48 anos. Sedentarismo e alimentação rica\nem proteínas e gorduras. Dona Gasparina chega a\nconsulta de retorno apresentando as seguintes alterações no exame físico e exames laboratorial:\nPeso: 72 Kg PA: 165 x 95 mmHg. Resultado de exames: Glicemia de jejum: 140 mg/dl; Colesterol\ntotal: 270 mg/dl; Colesterol LDL: 180 mg/dl; Colesterol HDL: 30 mg/dl; Triglicerídeos: 300 mg/dl;\nCreatinina: 1,0 mg/dl; ECG: Normal. Marque a afirmativa CORRETA.","options":{"A":"A paciente tem 3 critérios para diagnóstico de síndrome metabólica.","B":"A paciente não tem critério para alto risco de doença cardiovascular.","C":"A paciente tem Clearence estimado de 59,5, sendo classificado como IRC estágio.","D":"Para tratamento da dislipidemia devemos propor alteração no estilo de vida: dieta hipolipídica e\natividade física regular."},"answer":"C","source":"Clinica médica/MED CLM 03/MED CLM 03.txt","sourceLabel":"MED · MED CLM 03","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-03-37599","number":"37599","sourceNumber":"37599","collectionBlock":"med:med-clinica-medica-med-clm-03","collectionLabel":"MED · MED CLM 03","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 03","subtopic":"","stem":"Em relação aos valores de pressão arterial no consultório, Monitorização Ambulatorial\nda Pressão Arterial de 24 horas (MAPA),\nAutomedida da Pressão Arterial (AMPA) e Monitorização\nResidencial da Pressão Arterial (MRPA) que caracterizam a normotensão ou hipertensão controla,\na hipertensão, a hipertensão do avental branco e a hipertensão mascarada, marque a opção\nincorreta:","options":{"A":"Normotensão ou hipertensão controla: consultório <140/90; MAPA vigília = 130/85; AMPA =\n130/85; MRPA = 130/85.","B":"Hipertensão do avental branco: consultório = 140/90; MAPA vigília < 130/85; AMPA < 130/85;\nMRPA < 130/85.","C":"Hipertensão: consultório = 140/90; MAPA vigília > 130/85; AMPA > 130/85; MRPA > 130/85.","D":"Hipertensão mascarada: consultório = 140/90; MAPA vigília < 130/85; AMPA < 130/85; MRPA <\n130/85."},"answer":"D","source":"Clinica médica/MED CLM 03/MED CLM 03.txt","sourceLabel":"MED · MED CLM 03","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 03","MED"],"answerSource":"inferred","commentDeferred":true},{"id":"med-clinica-medica-med-clm-03-37609","number":"37609","sourceNumber":"37609","collectionBlock":"med:med-clinica-medica-med-clm-03","collectionLabel":"MED · MED CLM 03","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 03","subtopic":"","stem":"Segundo a VI diretriz de Hipertensão Arterial, assinale a alternativa incorreta em\nrelação aos fatores de risco para a hipertensão arterial sistêmica (HAS).","options":{"A":"Em relação à cor, a HAS é duas vezes mais\nprevalente em indivíduos de cor não branca.","B":"A influência do nível socioeconômico na\nocorrência da HAS já está estabelecida, ela é\nmais frequente nos indivíduos de menor nível\nsocioeconômico.","C":"A contribuição de fatores genéticos para a\ngênese da HAS está bem estabelecida na\npopulação.","D":"Atividade física reduz a incidência de HAS,\nmesmo em indivíduos pré-hipertensos, bem\ncomo a mortalidade."},"answer":"B","source":"Clinica médica/MED CLM 03/MED CLM 03.txt","sourceLabel":"MED · MED CLM 03","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 03","MED"],"answerSource":"inferred","commentDeferred":true},{"id":"med-clinica-medica-med-clm-03-37026","number":"37026","sourceNumber":"37026","collectionBlock":"med:med-clinica-medica-med-clm-03","collectionLabel":"MED · MED CLM 03","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 03","subtopic":"","stem":"Homem de 50 anos, não fumante, hipertenso, cardiopata, queixa-se de hipersonolência\ndiurna, fadiga e ansiedade. Um estudo\npolissonográfico detectou episódios de cessação da\nrespiração com duração entre 14 a 25 segundos, cerca de 28 episódios/hora com dessaturação\n(SpO2<88%) não acompanhados de movimento toracoabdominal e vários microdespertares com\nbaixa eficiência do sono. O registro capnográfico revelou uma hipocapnia precedendo os episódios.\nQual das intervenções abaixo tem maior chance de sucesso terapêutico?","options":{"A":"Realização de uvulopalatofaringoplastia.","B":"Aplicação de dispositivo avançador de\nmandíbula.","C":"Otimização de terapia com vasodilatadores e betabloqueadores","D":"Administração de indutores do sono em baixas doses à noite"},"answer":"C","source":"Clinica médica/MED CLM 03/MED CLM 03.txt","sourceLabel":"MED · MED CLM 03","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-03-29446","number":"29446","sourceNumber":"29446","collectionBlock":"med:med-clinica-medica-med-clm-03","collectionLabel":"MED · MED CLM 03","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 03","subtopic":"","stem":"São procedimentos da avaliação inicial de rotina para o paciente hipertenso, EXCETO:","options":{"A":"análise de urina","B":"ureia plasmática","C":"potássio plasmático","D":"acido úrico plasmático"},"answer":"B","source":"Clinica médica/MED CLM 03/MED CLM 03.txt","sourceLabel":"MED · MED CLM 03","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-03-29448","number":"29448","sourceNumber":"29448","collectionBlock":"med:med-clinica-medica-med-clm-03","collectionLabel":"MED · MED CLM 03","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 03","subtopic":"","stem":"Joana, 40 anos, diabética e hipertensa em uso de captopril 25 mg de 8/8 horas e de\nglibenclamida 5 mg por dia. Apresenta estatura de 1,6 m e peso de 72,0 Kg. Trouxe exames\nlaboratoriais solicitados na última consulta - creatinina: 1,0; colesterol total: 200,0; HDL: 50,0;\ntriglicerídeos: 150,0; glicemia de jejum: 110,0 e hemoglobina glicosilada: 7,2. Calcule o clearance\nde creatinina e o LDL da paciente, respectivamente:","options":{"A":"100 e 120;","B":"85 e 100;","C":"100 e 100;","D":"85 e 120."},"answer":"D","source":"Clinica médica/MED CLM 03/MED CLM 03.txt","sourceLabel":"MED · MED CLM 03","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-03-29450","number":"29450","sourceNumber":"29450","collectionBlock":"med:med-clinica-medica-med-clm-03","collectionLabel":"MED · MED CLM 03","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 03","subtopic":"","stem":"São indícios de hipertensão arterial secundária, EXCETO:","options":{"A":"Início da hipertensão antes dos 30 anos ou após os 60 anos de idade.","B":"Assimetria de pulsos femorais.","C":"Exame de urina anormal (proteinúria ou hematúria).","D":"Sintomas de apneia durante o sono."},"answer":"A","source":"Clinica médica/MED CLM 03/MED CLM 03.txt","sourceLabel":"MED · MED CLM 03","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-03-29457","number":"29457","sourceNumber":"29457","collectionBlock":"med:med-clinica-medica-med-clm-03","collectionLabel":"MED · MED CLM 03","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 03","subtopic":"","stem":"Em relação aos critérios da OMS para caracterização da síndrome metabólica, marque\na alternativa ERRADA:","options":{"A":"IMC > ou igual a 30 kg/m² e/ou Relação Cintura-Quadril > 0,9 (Masculino) e > 0,85 (Feminino);","B":"Triglicerídeos > 150 mg/dl ou Colesterol total > ou igual 200 mg/dl;","C":"Diabetes mellitus tipo 2 ou intolerância à glicose no TOTG;","D":"PA > 140 X 90 mmHg."},"answer":"B","source":"Clinica médica/MED CLM 03/MED CLM 03.txt","sourceLabel":"MED · MED CLM 03","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-03-24343","number":"24343","sourceNumber":"24343","collectionBlock":"med:med-clinica-medica-med-clm-03","collectionLabel":"MED · MED CLM 03","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 03","subtopic":"","stem":"Em relação ao tratamento da hipertensão arterial sistêmica (HAS), é CORRETO\nafirmar:","options":{"A":"Os betabloqueadores têm indicação na HAS pós-infarto agudo do miocárdio.","B":"Os diureticos devem ser usados como tratamento inicial de homens sexualmente ativos.","C":"HAS secundária à estenose bilateral da arteria renal deve ser tratada com antagonistas da\nangiotensina II.","D":"Os antagonistas do cálcio são drogas preferenciais para jovens portadores de BAV do 2º grau."},"answer":"A","source":"Clinica médica/MED CLM 03/MED CLM 03.txt","sourceLabel":"MED · MED CLM 03","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-03-27701","number":"27701","sourceNumber":"27701","collectionBlock":"med:med-clinica-medica-med-clm-03","collectionLabel":"MED · MED CLM 03","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 03","subtopic":"","stem":"Paciente de 49 anos, sexo masculino, diabético há 5 anos e em uso de metformina.\nSem outras alterações relevantes. Após\nrepetidas medições, foi constatada hipertensão arterial\nsistêmica com PA = 150 x 85 mmHg. Exames de sangue e urina foram normais. Dos itens abaixo,\nselecione o que contém a medicação mais apropriada para este caso.","options":{"A":"Inibidor da ECA.","B":"Antagonista de canal de cálcio.","C":"Betabloqueador.","D":"Diurético.","E":"Antagonista do receptor da angiotensina."},"answer":"D","source":"Clinica médica/MED CLM 03/MED CLM 03.txt","sourceLabel":"MED · MED CLM 03","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-03-27750","number":"27750","sourceNumber":"27750","collectionBlock":"med:med-clinica-medica-med-clm-03","collectionLabel":"MED · MED CLM 03","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 03","subtopic":"","stem":"Um garoto de 9 anos é visto pelo médico para seu exame anual de manutenção da\nsaúde. Ele tem uma história de asma, que foi\ndiagnosticada na idade de 7 anos. Atualmente, ele\nestá passando por episódios de falta de ar e chiado a cada duas semanas. Estes episódios são\nrapidamente aliviados por salbutamol inalado. Seus pais negam qualquer uso prévio de\ncorticosteroides orais e nunca foi internado por insuficiência respiratória. O exame físico é\nnormal,\nexceto por uma pressão arterial de 145/95 mmHg. Duas medições seguintes, durante visitas\nseparadas confirmam este valor. A causa mais provável para esta pressão arterial elevada é:","options":{"A":"patologia cardiovascular.","B":"patologia do sistema nervoso central.","C":"o efeito de droga.","D":"patologia endócrina.","E":"patologia renal."},"answer":"E","source":"Clinica médica/MED CLM 03/MED CLM 03.txt","sourceLabel":"MED · MED CLM 03","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-03-25360","number":"25360","sourceNumber":"25360","collectionBlock":"med:med-clinica-medica-med-clm-03","collectionLabel":"MED · MED CLM 03","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 03","subtopic":"","stem":"Paciente de 55 anos é acompanhada por hipertensão arterial sistêmica (HAS) em uso\nde hidroclorotiazida há 5 anos. Nos últimos 6\nmeses, vem apresentado mau controle da pressão\narterial e decide-se associar captopril após avaliação que não detectou sinais de HAS secundária.\nApós 1 mês de uso da combinação, paciente evolui com angioedema facial. Assinale o item abaixo\nque descreve a conduta adequada nesta paciente:","options":{"A":"Deve-se suspender o captopril e reintroduzi-lo aos poucos após 4 a 6 semanas","B":"Deve-se substituir o captopril por outra droga da mesma classe","C":"Deve-se suspender permanentemente o uso de inibidores da ECA nesta paciente","D":"Deve-se manter o esquema e administrar anti-histamínicos até resolução completa","E":"Deve-se associar o captopril a outra droga que não a hidroclorotiazida"},"answer":"C","source":"Clinica médica/MED CLM 03/MED CLM 03.txt","sourceLabel":"MED · MED CLM 03","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-03-9010","number":"9010","sourceNumber":"9010","collectionBlock":"med:med-clinica-medica-med-clm-03","collectionLabel":"MED · MED CLM 03","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 03","subtopic":"","stem":"Mulher de 45 anos admitida com queixas de cefaleia intensa, sudorese, taquipneia,\npalpitações e vômitos. Ao exame,\napresentava PA: 220 x 110 mmHg, FC: 112 bpm , rubor facial e\nextrema ansiedade. Qual a MELHOR hipótese diagnóstica para o caso?","options":{"A":"Hiperaldosteronismo primário","B":"Feocromocitoma","C":"Síndrome de Cushing","D":"Hipotireoidismo"},"answer":"B","source":"Clinica médica/MED CLM 03/MED CLM 03.txt","sourceLabel":"MED · MED CLM 03","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-03-9125","number":"9125","sourceNumber":"9125","collectionBlock":"med:med-clinica-medica-med-clm-03","collectionLabel":"MED · MED CLM 03","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 03","subtopic":"","stem":"João, 18 anos, residente em Fortaleza, comparece à unidade de saúde após ?picada?\nde escorpião há cerca de 4 horas. Apresenta dor\nlocal. Considerando que ele tem\nmicroalbuminúria, não teve evento isquêmico coronariano e não tem insuficiência cardíaca ou renal,\nqual a classe de anti-hipertensivo de escolha?","options":{"A":"Inibidores da enzima conversora da angiotensina/antagonista do receptor da angiotensina.","B":"Beta-bloqueadores.","C":"Diuréticos de alça.","D":"Bloqueadores dos canais de cálcio."},"answer":"A","source":"Clinica médica/MED CLM 03/MED CLM 03.txt","sourceLabel":"MED · MED CLM 03","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-03-9071","number":"9071","sourceNumber":"9071","collectionBlock":"med:med-clinica-medica-med-clm-03","collectionLabel":"MED · MED CLM 03","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 03","subtopic":"","stem":"Seu José, 74 anos, tabagista, 60 Kg, com hipertensão arterial há 4 anos e claudicação\nintermitente há 11 meses. Usava sinvastatina para hipercolesterolemia, atenolol e hidroclorotiazida,\nporém a pressão arterial mantinha-se em 190/115 mmHg, com creatinina sérica de 1,5 mg/dL. Foi\nintroduzido captopril 75 mg/dia, sem ser conseguido o controle da pressão arterial. Portanto, foi\naumentada a dose de captopril para 150 mg/dia. Após 10 dias, retorna para reavaliação com PA =\n138/80 mmHg, FC = 96 bpm, com a presença de frêmito epigástrico, sem dor abdominal. Não\napresentava edema em membros inferiores, nem alteração da cor dos pés. Pulsos poplíteos\nnormais e pediosos diminuídos. Exames: ureia = 90,0 mg/dL; creatinina sérica = 3,6 mg/dL; K = 5,6\nmEq/L; EAS = densidade 1018, traços de proteínas, sem sangue, exame do sedimento normal. A\nprimeira conduta mais adequada para esse paciente é:","options":{"A":"deixar o paciente em observação com soro fisiológico intravenoso.","B":"manter a medicação em uso e orientar dieta hipossódica e abandono do tabagismo.","C":"suspender o captopril, solicitar novamente potássio e a creatinina sérica e encaminhar para\nnefrologista.","D":"reduzir a dose de captopril para 75 mg/dia e dosar o potássio e a creatinina sérica e encaminhar\npara nefrologista."},"answer":"C","source":"Clinica médica/MED CLM 03/MED CLM 03.txt","sourceLabel":"MED · MED CLM 03","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-03-365575","number":"365575","sourceNumber":"365575","collectionBlock":"med:med-clinica-medica-med-clm-03","collectionLabel":"MED · MED CLM 03","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 03","subtopic":"","stem":"Nos últimos anos, está aumentando o número de casos de hipertensão arterial\nsistêmica na faixa etária pediátrica. Isso se\ndeve ao aumento da prevalência de obesidade,\nsedentarismo e hábitos alimentares inadequados. Com relação à hipertensão arterial na infância,\nassinale a alternativa correta.","options":{"A":"Betabloqueadores são as drogas de primeira linha na maioria dos casos, com baixo risco de\nefeitos colaterais nessa faixa etária.","B":"A hipertensão relacionada à obesidade é classificada como secundária.","C":"Todas as crianças devem ter a pressão arterial verificada anualmente a partir dos 3 anos de\nidade.","D":"Hipertensão arterial primária acomete principalmente crianças menores de 5 anos de idade."},"answer":"C","source":"Clinica médica/MED CLM 03/MED CLM 03.txt","sourceLabel":"MED · MED CLM 03","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-03-349717","number":"349717","sourceNumber":"349717","collectionBlock":"med:med-clinica-medica-med-clm-03","collectionLabel":"MED · MED CLM 03","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 03","subtopic":"","stem":"Um senhor de 62 anos, portador de HAS e tabagista, comparece à UBS para trazer os\nresultados de seus exames de rotina. Ele faz uso de losartana 50 mg BID e anlodipino 5mg MID e\napresenta bom controle de pressão arterial. A seguir estão os resultados dos exames desse\npaciente: Hemoglobina: 14,3 mg/dl / Leucócitos: 7200/mm3 / Plaquetas: 230.000/mm3 / Potássio:\n5,6 mEq/L / Sódio: 143 mEq/L / Ácido Úrico: 4,3 mg/dl / Glicose: 93 mg/dl / HbA1c - 5,4% /\nCreatinina: 0,8 mg/dl. Sangue oculto nas fezes (imunohistoquímica): positivo / Colesterol total:\n122 /\nCol. HDL: 46 / Col. LDL: 68 / Relação albumina-creatinina: 3,2 mg/g. Diante desse quadro, qual é a\nconduta mais adequada?","options":{"A":"O paciente apresenta hipercalemia, sendo necessária a prescrição de diuréticos de alça para\ncontrole do potássio. Ele deve também ser referenciado para realização de colonoscopia para\nrastreio de câncer de cólon.","B":"O paciente apresenta hipercalemia, sendo necessária a prescrição de diuréticos de alça para\ncontrole do potássio. Ele deve também repetir o exame de sangue oculto nas fezes, uma vez que\nsão necessárias 3 amostras positivas.","C":"O paciente apresenta hipercalemia, sendo necessária a suspensão da losartana para controle\ndo potássio - devendo ser substituída por\natenolol, que também é um medicamento de primeira\nlinha para tratamento da HAS. Ele deve também ser referenciado para realização de colonoscopia\npara rastreio de câncer de cólon.","D":"O paciente apresenta hipercalemia, sendo necessária a suspensão da losartana para controle\ndo potássio - devendo ser substituída por\nindapamida, que também é um medicamento de primeira\nlinha para o tratamento da HAS. Ele deve também ser referenciado para realização de\ncolonoscopia para rastreio de câncer de cólon.","E":"O paciente apresenta hipercalemia, sendo necessária a suspensão da losartana para controle\ndo potássio - devendo ser substituída por\nindapamida, que também é um medicamento de primeira\nlinha para tratamento da HAS. Ele deve também repetir o exame de sangue oculto nas fezes, uma\nvez que são necessárias 3 amostras positivas."},"answer":"D","source":"Clinica médica/MED CLM 03/MED CLM 03.txt","sourceLabel":"MED · MED CLM 03","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-03-322207","number":"322207","sourceNumber":"322207","collectionBlock":"med:med-clinica-medica-med-clm-03","collectionLabel":"MED · MED CLM 03","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 03","subtopic":"","stem":"Dona Marli queixa-se de edema de membros inferiores após iniciar uso de\nmedicamento para controlar sua pressão\narterial e procura atendimento para realizar a troca do\nremédio, pois sente-se muito incomodada. O fármaco em questão deve ser","options":{"A":"hidroclorotiazida.","B":"losartana.","C":"enalapril.","D":"anlodipino.","E":"atenolol."},"answer":"D","source":"Clinica médica/MED CLM 03/MED CLM 03.txt","sourceLabel":"MED · MED CLM 03","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-03-337594","number":"337594","sourceNumber":"337594","collectionBlock":"med:med-clinica-medica-med-clm-03","collectionLabel":"MED · MED CLM 03","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 03","subtopic":"","stem":"Roberto, um homem de 58 anos, é portador de hipertensão arterial, diabetes mellitus e\nhipotireoidismo. Há cerca de dois meses, ele sofreu um AVE isquêmico, apresentando diminuição\nde força em dimidio esquerdo, necessitando de auxílio para marcha. Desde que ocorreu o AVEi,\nRoberto não recuperou completamente a função cognitiva, apresentando dificuldade em\ncompreender fala, acalculia e diminuição da memória de curto prazo. Considerando o caso descrito\ne seus conhecimentos, julgue o item a seguir. O tratamento adequado da hipertensão arterial com\nmedicamentos de primeira linha (IECA, BRA, bloqueadores de canal de cálcio diidropiridínicos ou\ndiuréticos tiazídicos) reduz o risco de eventos como um AVEi.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Clinica médica/MED CLM 03/MED CLM 03.txt","sourceLabel":"MED · MED CLM 03","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-03-298950","number":"298950","sourceNumber":"298950","collectionBlock":"med:med-clinica-medica-med-clm-03","collectionLabel":"MED · MED CLM 03","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 03","subtopic":"","stem":"Uma paciente de 65 anos de idade compareceu à consulta com queixa de polidipsia,\npolifagia, poliúria e perda ponderal de 5 kg nos\núltimos três meses. Queixa-se também de humor\ndeprimido, anedonia e avolia. Tabagista, possui diagnósticos de hipertensão arterial sistêmica\n(HAS), doença pulmonar obstrutiva crônica (DPOC) e depressão. Faz uso de amitriptilina 25 mg à\nnoite, enalapril 10 mg, 2 vezes ao dia, hidroclorotiazida 25 mg, 1 vez ao dia e salbutamol\ninalatório\nsob demanda. Ao exame físico, apresenta mancha hiperpigmentada em região de dobra cervical,\naveludada à palpação. Observou-se PA = 160 mmHg x 110 mmHg em ambos os membros\nsuperiores. Foi realizada medida de HGT, com resultado de 320 mg/dL. Com base nesse caso\nclínico e nos conhecimentos médicos correlatos, julgue o item a seguir. Pode-se associar um\nbetabloqueador, como o propranolol, ao tratamento anti-hipertensivo.","options":{"A":"CERTO","B":"ERRADO"},"answer":"B","source":"Clinica médica/MED CLM 03/MED CLM 03.txt","sourceLabel":"MED · MED CLM 03","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-03-298951","number":"298951","sourceNumber":"298951","collectionBlock":"med:med-clinica-medica-med-clm-03","collectionLabel":"MED · MED CLM 03","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 03","subtopic":"","stem":"Uma paciente de 65 anos de idade compareceu à consulta com queixa de polidipsia,\npolifagia, poliúria e perda ponderal de 5 kg nos\núltimos três meses. Queixa-se também de humor\ndeprimido, anedonia e avolia. Tabagista, possui diagnósticos de hipertensão arterial sistêmica\n(HAS), doença pulmonar obstrutiva crônica (DPOC) e depressão. Faz uso de amitriptilina 25 mg à\nnoite, enalapril 10 mg, 2 vezes ao dia, hidroclorotiazida 25 mg, 1 vez ao dia e salbutamol\ninalatório\nsob demanda. Ao exame físico, apresenta mancha hiperpigmentada em região de dobra cervical,\naveludada à palpação. Observou-se PA = 160 mmHg x 110 mmHg em ambos os membros\nsuperiores. Foi realizada medida de HGT, com resultado de 320 mg/dL. Com base nesse caso\nclínico e nos conhecimentos médicos correlatos, julgue o item a seguir. Uma boa opção, como\nterceiro fármaco anti-hipertensivo, seria um bloqueador dos receptores de angiotensina ? (BRA),\ncomo a losartana, visto que diminuiria o risco cardiovascular, além de auxiliar na nefroproteção.","options":{"A":"CERTO","B":"ERRADO"},"answer":"B","source":"Clinica médica/MED CLM 03/MED CLM 03.txt","sourceLabel":"MED · MED CLM 03","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-03-298952","number":"298952","sourceNumber":"298952","collectionBlock":"med:med-clinica-medica-med-clm-03","collectionLabel":"MED · MED CLM 03","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 03","subtopic":"","stem":"Uma paciente de 65 anos de idade compareceu à consulta com queixa de polidipsia,\npolifagia, poliúria e perda ponderal de 5 kg nos\núltimos três meses. Queixa-se também de humor\ndeprimido, anedonia e avolia. Tabagista, possui diagnósticos de hipertensão arterial sistêmica\n(HAS), doença pulmonar obstrutiva crônica (DPOC) e depressão. Faz uso de amitriptilina 25 mg à\nnoite, enalapril 10 mg, 2 vezes ao dia, hidroclorotiazida 25 mg, 1 vez ao dia e salbutamol\ninalatório\nsob demanda. Ao exame físico, apresenta mancha hiperpigmentada em região de dobra cervical,\naveludada à palpação. Observou-se PA = 160 mmHg x 110 mmHg em ambos os membros\nsuperiores. Foi realizada medida de HGT, com resultado de 320 mg/dL. Com base nesse caso\nclínico e nos conhecimentos médicos correlatos, julgue o item a seguir. Fatores socioeconômicos\npodem acarretar risco significativo para hipertensão arterial, como, por exemplo, baixa renda\nfamiliar e menor escolaridade.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Clinica médica/MED CLM 03/MED CLM 03.txt","sourceLabel":"MED · MED CLM 03","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-03-284284","number":"284284","sourceNumber":"284284","collectionBlock":"med:med-clinica-medica-med-clm-03","collectionLabel":"MED · MED CLM 03","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 03","subtopic":"","stem":"A hipertensão arterial atinge grande parte dos brasileiros e contribui para a\nmorbimortalidade cardiovascular. Em 2016, a Sociedade\nBrasileira de Cardiologia publicou a\nSétima Diretriz Brasileira de Hipertensão Arterial. De acordo com essa diretriz, julgue o item a\nseguir. A hipotensão ortostática é definida como uma redução > 20 mmHg da pressão arterial\nsistólica ou 10 mmHg da pressão arterial diastólica em pacientes que estejam, há três minutos, na\nposição ortostática.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Clinica médica/MED CLM 03/MED CLM 03.txt","sourceLabel":"MED · MED CLM 03","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-03-284285","number":"284285","sourceNumber":"284285","collectionBlock":"med:med-clinica-medica-med-clm-03","collectionLabel":"MED · MED CLM 03","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 03","subtopic":"","stem":"A hipertensão arterial atinge grande parte dos brasileiros e contribui para a\nmorbimortalidade cardiovascular. Em 2016, a Sociedade Brasileira de Cardiologia publicou a\nSétima Diretriz Brasileira de Hipertensão Arterial. De acordo com essa diretriz, julgue o item a\nseguir. Pacientes que apresentam pressão de 120 x 80 mmHG no consultório médico e de 150 x\n100 mmHg na monitorização ambulatorial de pressão arterial (MAPA) de 24 horas são definidos\ncomo portadores de hipertensão do avental branco.","options":{"A":"CERTO","B":"ERRADO"},"answer":"B","source":"Clinica médica/MED CLM 03/MED CLM 03.txt","sourceLabel":"MED · MED CLM 03","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-03-284286","number":"284286","sourceNumber":"284286","collectionBlock":"med:med-clinica-medica-med-clm-03","collectionLabel":"MED · MED CLM 03","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 03","subtopic":"","stem":"A hipertensão arterial atinge grande parte dos brasileiros e contribui para a\nmorbimortalidade cardiovascular. Em 2016, a Sociedade\nBrasileira de Cardiologia publicou a\nSétima Diretriz Brasileira de Hipertensão Arterial. De acordo com essa diretriz, julgue o item a\nseguir. A melhor combinação medicamentosa para pacientes com doença renal crônica em estágio\nIV é a de inibidores da ECA com bloqueadores do receptor de angiotensina.","options":{"A":"CERTO","B":"ERRADO"},"answer":"B","source":"Clinica médica/MED CLM 03/MED CLM 03.txt","sourceLabel":"MED · MED CLM 03","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-03-274364","number":"274364","sourceNumber":"274364","collectionBlock":"med:med-clinica-medica-med-clm-03","collectionLabel":"MED · MED CLM 03","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 03","subtopic":"","stem":"Paciente, masculino, 63 anos, obeso e sedentário, vai à consulta de avaliação de rotina\npelo programa saúde da família. Durante a anamnese, o paciente se queixa de edema de membros\ninferiores, poliúria e crises de dor em hálux e tornozelos, com diagnóstico de artrite gotosa. Nega\noutras doenças ou uso de medicação contínua. Ao exame físico, apresenta-se corado, hidratado,\ncom PA: 190/110, FC: 88, FR: 16, SO2: 98% em ar ambiente, com ausculta pulmonar sem\nalterações, hiperfonese de B2 em foco aórtico e edema de membros inferiores ++/4+. Referente a\nesse caso, qual é a conduta mais adequada?","options":{"A":"Orientar sobre cuidados e hábitos de vida, diagnosticar hipertensão arterial sistêmica e iniciar\ndiurético tiazídico.","B":"Diagnosticar síndrome metabólica e iniciar hipoglicemiante biguanida.","C":"Orientar sobre cuidados e hábitos de vida e solicitar monitorização ambulatorial da pressão\narterial sistêmica.","D":"Orientar sobre cuidados e hábitos de vida, diagnosticar hipertensão arterial sistêmica e iniciar\ninibidor de enzima conversora de angiotensina.","E":"Orientar sobre cuidados e hábitos de vida e orientar retorno em 3 meses para reavaliação."},"answer":"D","source":"Clinica médica/MED CLM 03/MED CLM 03.txt","sourceLabel":"MED · MED CLM 03","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-03-274370","number":"274370","sourceNumber":"274370","collectionBlock":"med:med-clinica-medica-med-clm-03","collectionLabel":"MED · MED CLM 03","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 03","subtopic":"","stem":"Paciente, 65 anos, masculino, previamente hipertenso, em uso regular da medicação, é\nadmitido no setor de urgência com quadro de aumento pressórico de forma rápida, associado à\ncefaleia holocraniana, vômitos e confusão mental. Nega demais sintomas associados, como febre.\nNa admissão, está com PA: 210/130 mmHg, FC: 60bpm, FR: 14 ipm, SO2: 96% em ar ambiente. A\nrespeito desse o quadro, é CORRETO afirmar que:","options":{"A":"Deve-se considerar o diagnóstico de crise hipertensiva, com encefalopatia hipertensiva, e a meta\né redução da PA média em 10 a 15% na primeira\nhora e até 25% no primeiro dia de tratamento.","B":"O diagnóstico é crise de migrânea, sendo o tratamento a analgesia forte e hidratação.","C":"O diagnóstico é hipertensão intracraniana e deve ser feita imediata punção de líquido\ncefalorraquidiano.","D":"Devem ser feitos controle com medicação anti-hipertensiva via oral e solicitação de exames para\nanálise de possível lesão de órgão-alvo.","E":"Um dos diagnósticos diferenciais do quadro neurológico é hipertensão maligna e, nesse caso,\ndeve ser feita ressonância para diferenciar etiologias."},"answer":"A","source":"Clinica médica/MED CLM 03/MED CLM 03.txt","sourceLabel":"MED · MED CLM 03","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-03-284343","number":"284343","sourceNumber":"284343","collectionBlock":"med:med-clinica-medica-med-clm-03","collectionLabel":"MED · MED CLM 03","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 03","subtopic":"","stem":"São complicações relacionadas à obesidade na gravidez, entre outras, o diabetes\ngestacional, a pré-eclâmpsia e a prevalência aumentada de natimortalidade.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Clinica médica/MED CLM 03/MED CLM 03.txt","sourceLabel":"MED · MED CLM 03","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 03","MED"],"answerSource":"inferred","commentDeferred":true},{"id":"med-clinica-medica-med-clm-03-284354","number":"284354","sourceNumber":"284354","collectionBlock":"med:med-clinica-medica-med-clm-03","collectionLabel":"MED · MED CLM 03","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 03","subtopic":"","stem":"Em relação à prevenção, à epidemiologia e à história natural das doenças, julgue o item\na seguir. O índice de massa corporal associado à circunferência abdominal fornece a avaliação\ncombinada para a estratificação do risco metabólico.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Clinica médica/MED CLM 03/MED CLM 03.txt","sourceLabel":"MED · MED CLM 03","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 03","MED"],"answerSource":"inferred","commentDeferred":true},{"id":"med-clinica-medica-med-clm-03-261305","number":"261305","sourceNumber":"261305","collectionBlock":"med:med-clinica-medica-med-clm-03","collectionLabel":"MED · MED CLM 03","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 03","subtopic":"","stem":"Determinado paciente de 58 anos de idade, tabagista, com histórico de IAM há cinco\nanos e DM2, em uso de metformina, comparece\nà consulta com os seguintes exames laboratoriais:\nglicemia = 136 mg/dl; colesterol HDL = 32 mg/dl; colesterol LDL = 192,3 mg/dl; e creatinina sérica =\n1,32 mg/dl. Apresenta medida de PA = 165 mmHg x 102 mmHg. FC = 80 bpm, SatO2 = 92% com\nníveis tensionais confirmados em duas consultas com mais de quatro semanas entre elas.\n\nConsiderando esse caso clínico e os conhecimentos médicos correlatos, julgue o item a seguir.\nTrata-se de um caso de HAS estágio 2.","options":{"A":"Certo.","B":"Errado."},"answer":"A","source":"Clinica médica/MED CLM 03/MED CLM 03.txt","sourceLabel":"MED · MED CLM 03","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-03-261306","number":"261306","sourceNumber":"261306","collectionBlock":"med:med-clinica-medica-med-clm-03","collectionLabel":"MED · MED CLM 03","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 03","subtopic":"","stem":"Determinado paciente de 58 anos de idade, tabagista, com histórico de IAM há cinco\nanos e DM2, em uso de metformina, comparece\nà consulta com os seguintes exames laboratoriais:\nglicemia = 136 mg/dl; colesterol HDL = 32 mg/dl; colesterol LDL = 192,3 mg/dl; e creatinina sérica =\n1,32 mg/dl. Apresenta medida de PA = 165 mmHg x 102 mmHg. FC = 80 bpm, SatO2 = 92% com\nníveis tensionais confirmados em duas consultas com mais de quatro semanas entre elas.\n\nConsiderando esse caso clínico e os conhecimentos médicos correlatos, julgue o item a seguir. O\ntratamento indicado é a realização de medidas não farmacológicas (mudanças no estilo de vida) e\nreavaliação em três meses.","options":{"A":"Certo.","B":"Errado."},"answer":"B","source":"Clinica médica/MED CLM 03/MED CLM 03.txt","sourceLabel":"MED · MED CLM 03","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-03-261308","number":"261308","sourceNumber":"261308","collectionBlock":"med:med-clinica-medica-med-clm-03","collectionLabel":"MED · MED CLM 03","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 03","subtopic":"","stem":"Determinado paciente de 58 anos de idade, tabagista, com histórico de IAM há cinco\nanos e DM2, em uso de metformina, comparece\nà consulta com os seguintes exames laboratoriais:\nglicemia = 136 mg/dL; colesterol HDL = 32 mg/dL; colesterol LDL = 192,3 mg/dL; e creatinina sérica\n\n= 1,32 mg/dL. Apresenta medida de PA = 165 mmHg x 102 mmHg. FC = 80 bpm, SatO2 = 92%\ncom níveis tensionais confirmados em duas\nconsultas com mais de quatro semanas entre elas.\nConsiderando esse caso clínico e os conhecimentos médicos correlatos, julgue o item a seguir.\nTendo em vista o histórico de IAM prévio e as demais comorbidades, além do controle pressórico,\ntambém é recomendado o controle dos fatores de risco, tais como controle glicêmico, cessar\ntabagismo, uso de AAS e estatinas.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Clinica médica/MED CLM 03/MED CLM 03.txt","sourceLabel":"MED · MED CLM 03","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-03-261309","number":"261309","sourceNumber":"261309","collectionBlock":"med:med-clinica-medica-med-clm-03","collectionLabel":"MED · MED CLM 03","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 03","subtopic":"","stem":"Determinado paciente de 58 anos de idade, tabagista, com histórico de IAM há cinco\nanos e DM2, em uso de metformina, comparece\nà consulta com os seguintes exames laboratoriais:\nglicemia = 136 mg/dL; colesterol HDL = 32 mg/dL; colesterol LDL = 192,3 mg/dL; e creatinina sérica\n\n= 1,32 mg/dL. Apresenta medida de PA = 165 mmHg x 102 mmHg. FC = 80 bpm, SatO2 = 92%\ncom níveis tensionais confirmados em duas\nconsultas com mais de quatro semanas entre elas.\nConsiderando esse caso clínico e os conhecimentos médicos correlatos, julgue o item a seguir.\nEntre as drogas de primeira linha para tratamento da hipertensão, encontram-se os diuréticos\ntiazídicos, IECA, betabloqueadores e antagonistas dos canais de cálcio.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Clinica médica/MED CLM 03/MED CLM 03.txt","sourceLabel":"MED · MED CLM 03","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 03","MED"],"answerSource":"inferred","commentDeferred":true},{"id":"med-clinica-medica-med-clm-03-239364","number":"239364","sourceNumber":"239364","collectionBlock":"med:med-clinica-medica-med-clm-03","collectionLabel":"MED · MED CLM 03","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 03","subtopic":"","stem":"Uma paciente de 58 anos de idade, hipertensa, com história de mau controle,\nobesidade grau 1, dislipidêmica, tabagista\n40 anos/maços, com histórico de participação sem\nsucesso em programa de abandono ao tabagismo, é atendida em consulta de acolhimento em\nUnidade de Saúde da Família, após dois anos da última consulta agendada. Alega que procura\natendimento em razão da dor de intensidade grau quatro em hemitórax anterior esquerdo há dois\ndias, contínua, sem irradiações, realizando \"sinal do apontamento\" para demonstrar local exato da\ndor, sem fator gatilho ou fator de piora notados. Além disso, relata que vem apresentando tosse\nnão produtiva frequente há um mês, sem febre, dispneia, emagrecimento ou demais\ncomemorativos. Não vem fazendo uso das respectivas medicações, alegando que se esquece de\nadministrá-las. Leva boletim de atendimento em consulta realizada há duas semanas em unidade\nde pronto atendimento em razão da dor lombar, mostrando receita de corticoide intramuscular\nfornecida na alta, medicação da qual admite fazer uso com certa frequência, afirmando que esta\nsempre lhe é prescrita quando consulta na UPA. Mostra também exames realizados, há dois\nmeses, solicitados em consulta médica em clínica popular, com os seguintes resultados: Hb = 13,2\ng/dl, Ht = 37,1%, leucócitos = 7,2 mil, plaquetas = 148 mil, Cr = 1,1 mg/dl, Ur = 42 mg/dl,\ncolesterol\ntotal = 270 mg/dl, HDL = 38 mg/dl, LDL =192 mg/dl, triglicerídeos = 198 mg/dl e glicemia de jejum =\n123 mg/dl. Com relação a esse caso clínico e tendo em vista os conhecimentos médicos correlatos,\njulgue o item a seguir. Há indicação formal de início do uso de estatina, independentemente de a\npaciente apresentar interesse recente por atividades físicas e desejo de adesão a medidas\nalimentares.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Clinica médica/MED CLM 03/MED CLM 03.txt","sourceLabel":"MED · MED CLM 03","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-03-179165","number":"179165","sourceNumber":"179165","collectionBlock":"med:med-clinica-medica-med-clm-03","collectionLabel":"MED · MED CLM 03","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 03","subtopic":"","stem":"Assinale a alternativa que apresenta os parâmetros considerados para se estabelecer o\ndiagnóstico de síndrome metabólica segundo a Organização Mundial da Saúde (OMS) e o\n\nNCEP-ATP III (National Cholesterol Education Program's Adult Treatment Panel III).","options":{"A":"Obesidade abdominal por meio de circunferência abdominal, glicemia de jejum, ácido úrico e\nLDL colesterol.","B":"Obesidade abdominal por meio de circunferência abdominal, glicemia pós-prandial, LDL\ncolesterol e triglicerídeos.","C":"Obesidade abdominal por meio de circunferência abdominal, triglicerídeos, HDL colesterol,\npressão arterial e glicemia de jejum.","D":"Esteatose hepática por meio de ultrassom, hemoglobina glicada, HDL colesterol e hipertensão\narterial.","E":"Esteatose hepática por meio de ultrassom, glicemia de jejum, ácido úrico e LDL colesterol."},"answer":"C","source":"Clinica médica/MED CLM 03/MED CLM 03.txt","sourceLabel":"MED · MED CLM 03","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-03-179174","number":"179174","sourceNumber":"179174","collectionBlock":"med:med-clinica-medica-med-clm-03","collectionLabel":"MED · MED CLM 03","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 03","subtopic":"","stem":"Com relação à abordagem terapêutica da hipertensão arterial em paciente com\nsíndrome metabólica, é correto afirmar que","options":{"A":"o controle da pressão arterial com apenas uma droga ocorra em cerca de 2/3 dos pacientes\nhipertensos.","B":"seu objetivo seja a redução da pressão arterial para valores abaixo de 140 mmHg/ 90 mmHg,\nconsiderando-se o elevado risco cardiovascular associado.","C":"a presença de nefropatia com proteinúria importante implique em redução da pressão arterial\npara valores abaixo de 130 mmHg/85 mmHg.","D":"a pressão arterial deva ser reduzida para valores abaixo de 140 mmHg/ 90 mmHg em\nassociação com diabetes tipo 2.","E":"a associação de drogas seja indicada desde o início do tratamento anti-hipertensivo quando a\npressão arterial for \"maior ou igual\"160 mmHg/ 100 mmHg."},"answer":"E","source":"Clinica médica/MED CLM 03/MED CLM 03.txt","sourceLabel":"MED · MED CLM 03","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-03-177635","number":"177635","sourceNumber":"177635","collectionBlock":"med:med-clinica-medica-med-clm-03","collectionLabel":"MED · MED CLM 03","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 03","subtopic":"","stem":"No contexto da Atenção Primária à Saúde, eventualmente, encontram-se prontuários\nque relatam todo o curso de vida de certo\npaciente, desde o período gestacional até a idade adulta,\nincluindo-se o período reprodutivo. Suponha que o M.S.F., atualmente com 28 anos de idade, foi\nacompanhada, no posto de saúde, durante toda a sua vida, desde a própria gestação da qual foi\nfruto. Ao longo de sua vida, várias estratégias de prevenção e programas de rastreamento foram\nefetuados e, eventualmente, continuarão sendo utilizados ao longo de seu envelhecimento. A\npaciente é sexualmente ativa, solteira, negra, com dois filhos (2 e 4 anos de idade), secretária,\nnão\ntabagista, não etilista, fisicamente ativa, com IMC = 22,5 e PA = 125 mmHg x 70 mmHg na última\nconsulta. A respeito dessas estratégias e desses programas e considerando as recomendações\ndos Cadernos de Atenção Básica do Ministério da Saúde, julgue o item a seguir. A dosagem do\ncolesterol total e frações estará indicada em 2 anos.","options":{"A":"CERTO","B":"ERRADO"},"answer":"B","source":"Clinica médica/MED CLM 03/MED CLM 03.txt","sourceLabel":"MED · MED CLM 03","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-03-177640","number":"177640","sourceNumber":"177640","collectionBlock":"med:med-clinica-medica-med-clm-03","collectionLabel":"MED · MED CLM 03","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 03","subtopic":"","stem":"No contexto da Atenção Primária à Saúde, eventualmente, encontram-se prontuários\nque relatam todo o curso de vida de certo\npaciente, desde o período gestacional até a idade adulta,\nincluindo-se o período reprodutivo. Suponha que o M.S.F., atualmente com 28 anos de idade, foi\nacompanhada, no posto de saúde, durante toda a sua vida, desde a própria gestação da qual foi\nfruto. Ao longo de sua vida, várias estratégias de prevenção e programas de rastreamento foram\nefetuados e, eventualmente, continuarão sendo utilizados ao longo de seu envelhecimento. A\npaciente é sexualmente ativa, solteira, negra, com dois filhos (2 e 4 anos de idade), secretária,\nnão\ntabagista, não etilista, fisicamente ativa, com IMC = 22,5 e PA = 125 mmHg x 70 mmHg na última\nconsulta. A respeito dessas estratégias e desses programas e considerando as recomendações\ndos Cadernos de Atenção Básica do Ministério da Saúde, julgue o item a seguir. A medida da\npressão arterial é indicada para a faixa etária da paciente, devendo-se realizar essa medida\nanualmente.","options":{"A":"CERTO","B":"ERRADO"},"answer":"B","source":"Clinica médica/MED CLM 03/MED CLM 03.txt","sourceLabel":"MED · MED CLM 03","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-03-152147","number":"152147","sourceNumber":"152147","collectionBlock":"med:med-clinica-medica-med-clm-03","collectionLabel":"MED · MED CLM 03","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 03","subtopic":"","stem":"Paciente, 40 anos de idade, foi ao pronto-socorro por anasarca, espuma na urina e\nhipertensão (160 x 100 mmHg). Apresenta exames de função renal sérica normais. Fez exame de\nurina que demonstrou proteína +++. Realizou proteinúria de 24 horas, que demonstrou 5 g de\nproteínas. Considerando essa situação, julgue o item a seguir. Casos dessa síndrome geralmente\ncursam com perda de função renal.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Clinica médica/MED CLM 03/MED CLM 03.txt","sourceLabel":"MED · MED CLM 03","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 03","MED"],"answerSource":"inferred","commentDeferred":true},{"id":"med-clinica-medica-med-clm-03-131810","number":"131810","sourceNumber":"131810","collectionBlock":"med:med-clinica-medica-med-clm-03","collectionLabel":"MED · MED CLM 03","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 03","subtopic":"","stem":"Segundo a Sociedade Brasileira de Cardiologia, com relação à Hipertensão Arterial\nSistêmica (HAS) e seus fatores de risco, assinale a alternativa CORRETA:","options":{"A":"Inexiste relação entre a pressão arterial e a idade do indivíduo.","B":"A prevalência global de HAS é mais elevada nas mulheres até os 50 anos de idade.","C":"Embora a população brasileira apresente uma dieta rica em sódio, carboidratos e gorduras, a\nelevação da pressão arterial não se relaciona com o consumo elevado de sódio.","D":"A ingesta de bebidas alcoólicas por um período de tempo prolongado pode aumentar os níveis\nde pressão arterial.","E":"A atividade física reduz a incidência de HAS apenas em indivíduos previamente hígidos, não\napresentando o mesmo efeito em indivíduos pré-hipertensos."},"answer":"D","source":"Clinica médica/MED CLM 03/MED CLM 03.txt","sourceLabel":"MED · MED CLM 03","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-03-108126","number":"108126","sourceNumber":"108126","collectionBlock":"med:med-clinica-medica-med-clm-03","collectionLabel":"MED · MED CLM 03","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 03","subtopic":"","stem":"A hipertensão arterial, que se associa a alterações metabólicas, hormonais e a\nfenômenos tróficos, é uma doença de causa\nmultifatorial que acomete cerca de 15% a 20% da\npopulação brasileira adulta. Acerca dessa patologia, julgue o item subsecutivo. O exame de fundo\nde olho permite identificar lesões no sistema vascular de pacientes portadores de hipertensão\narterial sistêmica.","options":{"A":"CERTO.","B":"ERRADO."},"answer":"A","source":"Clinica médica/MED CLM 03/MED CLM 03.txt","sourceLabel":"MED · MED CLM 03","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 03","MED"],"answerSource":"inferred","commentDeferred":true},{"id":"med-clinica-medica-med-clm-03-105537","number":"105537","sourceNumber":"105537","collectionBlock":"med:med-clinica-medica-med-clm-03","collectionLabel":"MED · MED CLM 03","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 03","subtopic":"","stem":"De acordo com o último relatório do <i>Joint National Committee</i>, o oitavo, (JNC\nVIII) publicado no início deste ano (2014), a\nrecomendação para adultos maiores de sessenta anos\nde idade é que se introduza terapêutica anti-hipertensiva para valores de pressão, em mmHg:","options":{"A":"> 120 x 80.","B":"> 135 x 85.","C":"> 139 x 85.","D":"\"Maior ou igual a\" 140 x 90.","E":"\"Maior ou igual a\" 150 x 90."},"answer":"E","source":"Clinica médica/MED CLM 03/MED CLM 03.txt","sourceLabel":"MED · MED CLM 03","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-03-88710","number":"88710","sourceNumber":"88710","collectionBlock":"med:med-clinica-medica-med-clm-03","collectionLabel":"MED · MED CLM 03","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 03","subtopic":"","stem":"Acerca de doenças crônicas, julgue o item subsequente. Pacientes com hipertensão\narterial maligna apresentam frequentemente\ninsuficiência renal progressiva e retinopatia com\nexsudatos.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Clinica médica/MED CLM 03/MED CLM 03.txt","sourceLabel":"MED · MED CLM 03","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 03","MED"],"answerSource":"inferred","commentDeferred":true},{"id":"med-clinica-medica-med-clm-03-88635","number":"88635","sourceNumber":"88635","collectionBlock":"med:med-clinica-medica-med-clm-03","collectionLabel":"MED · MED CLM 03","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 03","subtopic":"","stem":"Com relação aos pacientes com dislipidemias, julgue o item seguinte. A modificação\ndos hábitos de vida (alimentação saudável,\nprática regular de atividades físicas, manutenção do\níndice de massa corporal saudável) é parte essencial do acompanhamento desses pacientes e tem\nimpacto significativo na redução do risco de doença aterosclerótica cardiovascular dos indivíduos.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Clinica médica/MED CLM 03/MED CLM 03.txt","sourceLabel":"MED · MED CLM 03","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 03","MED"],"answerSource":"inferred","commentDeferred":true},{"id":"med-clinica-medica-med-clm-03-82121","number":"82121","sourceNumber":"82121","collectionBlock":"med:med-clinica-medica-med-clm-03","collectionLabel":"MED · MED CLM 03","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 03","subtopic":"","stem":"Acerca das doenças dos cuidados de saúde em pessoas idosas, julgue o item a seguir:\nDurante a medida da pressão arterial em idosos, pode ocorrer maior frequência de hiato\nauscultatório, subestimando a verdadeira pressão sistólica ou superestimando a pressão diastólica,\ne a pseudo-hipertensão, que pode ser detectada por meio da manobra de Osler.","options":{"A":"CERTO.","B":"ERRADO."},"answer":"A","source":"Clinica médica/MED CLM 03/MED CLM 03.txt","sourceLabel":"MED · MED CLM 03","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 03","MED"],"answerSource":"inferred","commentDeferred":true},{"id":"med-clinica-medica-med-clm-03-88646","number":"88646","sourceNumber":"88646","collectionBlock":"med:med-clinica-medica-med-clm-03","collectionLabel":"MED · MED CLM 03","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 03","subtopic":"","stem":"Acerca de doenças cardiovasculares e hipertensão, julgue o item a seguir. Para\npacientes hipertensos que apresentam pressão\narterial controlada, a prescrição de ácido\nacetilsalicílico em baixas doses diminuem a ocorrência de complicações cardiovasculares, desde\nque o uso deste medicamento não seja contraindicado ao paciente e gere mais benefícios que\neventuais riscos a sua saúde.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Clinica médica/MED CLM 03/MED CLM 03.txt","sourceLabel":"MED · MED CLM 03","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 03","MED"],"answerSource":"inferred","commentDeferred":true},{"id":"med-clinica-medica-med-clm-03-88665","number":"88665","sourceNumber":"88665","collectionBlock":"med:med-clinica-medica-med-clm-03","collectionLabel":"MED · MED CLM 03","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 03","subtopic":"","stem":"Acerca de doenças cardiovasculares e hipertensão, julgue o item a seguir. O\ntratamento das dislipidemias pode ser feito\nmediante o uso de diversos medicamentos, tais como\nestatinas, fibratos e determinados fármacos, como ezetimibe e genfibrozil, contudo o uso do ácido\nnicotínico é indesejado, uma vez que ele pode elevar a resistência à insulina e o nível de\ntriglicerídeos em pacientes diabéticos.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Clinica médica/MED CLM 03/MED CLM 03.txt","sourceLabel":"MED · MED CLM 03","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 03","MED"],"answerSource":"inferred","commentDeferred":true},{"id":"med-clinica-medica-med-clm-03-64298","number":"64298","sourceNumber":"64298","collectionBlock":"med:med-clinica-medica-med-clm-03","collectionLabel":"MED · MED CLM 03","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 03","subtopic":"","stem":"Em relação à Síndrome de Apneia-Hipopneia Obstrutiva do Sono (SAOS) em adultos,\njulgue o item subsecutivo: A polissonografia\né o exame complementar padrão-ouro para elucidar os\ncasos de SAOS, cujo diagnóstico é confirmado quando o paciente assintomático apresentar Índice\nde Apneia-Hiponeia (IAH) maior ou igual a quinze eventos por hora de sono (mais de 75% dessas\napneias-hipopneias apresentam padrão obstrutivo).","options":{"A":"Certo","B":"Errado"},"answer":"A","source":"Clinica médica/MED CLM 03/MED CLM 03.txt","sourceLabel":"MED · MED CLM 03","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 03","MED"],"answerSource":"inferred","commentDeferred":true},{"id":"med-clinica-medica-med-clm-03-37940","number":"37940","sourceNumber":"37940","collectionBlock":"med:med-clinica-medica-med-clm-03","collectionLabel":"MED · MED CLM 03","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 03","subtopic":"","stem":"Um rapaz com 18 anos de idade, em atendimento médico ambulatorial de um centro de\nsaúde, relatou inchaço no corpo, náuseas/vômitos matinais, anorexia, redução progressiva do\nvolume urinário e urina avermelhada, com início há uma semana. Relatou ter apresentado, havia\nduas semanas, infecção das vias aéreas (completamente resolvida) e negou outras doenças. No\nexame físico, ele se apresentava: normolíneo, em regular estado geral, com mucosas hipocoradas\n(+2/+4), frequência cardíaca de 105 bpm e pressão arterial de 150 mmHg x 110 mmHg (deitado,\nmedida no membro superior direito, usando-se bolsa inflável apropriada para a circunferência do\nbraço). Pulmões sem alterações. O exame cardiovascular revelou ictus cordis no quinto espaço\nintercostal e na linha hemiclavicular esquerda, com 2 cm de extensão, normoimpulsivo, ritmo\ncardíaco regular em 3 tempos (à custa de terceira bulha), sopro sistólico (+2/+6), suave, audível em\ntodos os\n\nfocos, presença de ruído compatível com atrito pericárdico, mais bem audível na borda esternal\nesquerda baixa. Abdome sem alterações. Edema\nem membros inferiores (+2/+4) até os joelhos,\nfrio, indolor, com sinal de Godet. Exames complementares evidenciaram: ureia = 130 mg/dl;\ncreatinina = 7 mg/dl; sódio plasmático = 140 mEq/L; potássio plasmático = 6,8 mEq/L; hematócrito\n\n= 28%; hemoglobina = 9,2 g/dl; leucograma normal; plaquetas = 250.000/mm³; EAS com ausência\nde glicose e de proteína; hemoglobina (++);\nhemácias = 25 por campo; leucócitos = 2 por campo;\ncilindros hemáticos (+++). Com base nas informações do quadro clínico acima, julgue o item. Nesse\nquadro clínico, durante a esfigmomanometria, como a relação entre as dimensões da bolsa inflável\ne a medida da circunferência do braço foi adequada, é correto inferir que o comprimento e a largura\ndessa bolsa inflável correspondiam a, respectivamente, 80% e 40% da medida da circunferência do\nmembro em questão.","options":{"A":"Certo.","B":"Errado."},"answer":"A","source":"Clinica médica/MED CLM 03/MED CLM 03.txt","sourceLabel":"MED · MED CLM 03","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 03","MED"],"answerSource":"inferred","commentDeferred":true},{"id":"med-clinica-medica-med-clm-03-27558","number":"27558","sourceNumber":"27558","collectionBlock":"med:med-clinica-medica-med-clm-03","collectionLabel":"MED · MED CLM 03","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 03","subtopic":"","stem":"Quanto ao tratamento para hipertensão arterial sistêmica (HAS), considere as seguintes\nafirmações, selecionando a correta.","options":{"A":"Os diuréticos tiazídicos são fármacos muito conhecidos e frequentemente utilizados no\ntratamento da HAS, devendo ser utilizados em\nbaixas doses, dado a sua capacidade de redução da\nmorbimortalidade em estudos de longo prazo.","B":"A seleção de um determinado fármaco para o tratamento da HAS deve considerar a sua\ntolerabilidade através de doses crescentes para que se possa tratar o distúrbio fisiopatológico\ncoexistente","C":"Metanálises dos estudos clínicos vêm demonstrando a importância de estabelecer metas de\npressão arterial mais baixa em pacientes idosos","D":"Os inibidores da ECA são agentes de escolha em pacientes com disfunção renal e estenose\nbilateral da artéria renal","E":"O estabelecimento de metas de pressão arterial mais baixa inclui grupos específicos de\npacientes como: diabéticos, jovens e portadores de lesão em órgão-alvo"},"answer":"A","source":"Clinica médica/MED CLM 03/MED CLM 03.txt","sourceLabel":"MED · MED CLM 03","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-03-7551","number":"7551","sourceNumber":"7551","collectionBlock":"med:med-clinica-medica-med-clm-03","collectionLabel":"MED · MED CLM 03","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 03","subtopic":"","stem":"Hipertensão arterial sistêmica é a principal causa de morte no mundo. Acerca dessa\nafecção, assinale a alternativa incorreta.","options":{"A":"É fator de risco para acidente vascular cerebral, infarto do miocárdio, insuficiência cardíaca\ncongestiva e dissecção da aorta.","B":"Em sociedades menos industrializadas, nas quais o consumo de calorias e de sal é baixo, a\npressão arterial dos indivíduos não aumenta com o avançar da idade.","C":"Os níveis de pressão sistólica e diastólica de 120-139 e 80-89 mmHg, respectivamente, são\nconsiderados pré-hipertensão.","D":"Os inibidores de enzima conversora da angiotensina (ECA) e os antagonistas dos receptores\nATI da angiotensina II, apresentam perfil\nfarmacológico adequado para diabéticos hipertensos,\nespecialmente na vigência de nefropatia diabética.","E":"As anormalidades tireoidianas (hiper e hipotireoidismo) são as principais causas de hipertensão\nsecundária."},"answer":"E","source":"Clinica médica/MED CLM 03/MED CLM 03.txt","sourceLabel":"MED · MED CLM 03","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-03-301251","number":"301251","sourceNumber":"301251","collectionBlock":"med:med-clinica-medica-med-clm-03","collectionLabel":"MED · MED CLM 03","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 03","subtopic":"","stem":"Em pacientes hipertensos com doença renal crônica, existem particularidades que\ndevem ser observadas ao se propor o\ntratamento adequado. Acerca do tratamento da hipertensão\narterial sistêmica para esses indivíduos e conforme as recomendações das Diretrizes Brasileiras de\nHipertensão Arterial - 2020, julgue o item a seguir. Os betabloqueadores estão indicados para\npacientes com insuficiência cardíaca associada à doença renal crônica.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Clinica médica/MED CLM 03/MED CLM 03.txt","sourceLabel":"MED · MED CLM 03","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 03","MED"],"answerSource":"inferred","commentDeferred":true},{"id":"med-clinica-medica-med-clm-03-301252","number":"301252","sourceNumber":"301252","collectionBlock":"med:med-clinica-medica-med-clm-03","collectionLabel":"MED · MED CLM 03","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 03","subtopic":"","stem":"Em pacientes hipertensos com doença renal crônica, existem particularidades que\ndevem ser observadas ao se propor o\ntratamento adequado. Acerca do tratamento da hipertensão\narterial sistêmica para esses indivíduos e conforme as recomendações das Diretrizes Brasileiras de\nHipertensão Arterial - 2020, julgue o item a seguir. Bloqueadores do canal de cálcio e bloqueadores\ndo receptor AT1 da angiotensina II devem ser a primeira opção em pacientes transplantados renais\npor prevenirem a perda do enxerto.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Clinica médica/MED CLM 03/MED CLM 03.txt","sourceLabel":"MED · MED CLM 03","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-03-301253","number":"301253","sourceNumber":"301253","collectionBlock":"med:med-clinica-medica-med-clm-03","collectionLabel":"MED · MED CLM 03","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 03","subtopic":"","stem":"Em pacientes hipertensos com doença renal crônica, existem particularidades que\ndevem ser observadas ao se propor o\ntratamento adequado. Acerca do tratamento da hipertensão\narterial sistêmica para esses indivíduos e conforme as recomendações das Diretrizes Brasileiras de\nHipertensão Arterial - 2020, julgue o item a seguir. A associação entre bloqueadores do receptor\nAT1 da angiotensina II e inibidores da enzima conversora de angiotensina é útil nos casos que\ncursam com albuminúria importante.","options":{"A":"CERTO","B":"ERRADO"},"answer":"B","source":"Clinica médica/MED CLM 03/MED CLM 03.txt","sourceLabel":"MED · MED CLM 03","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-03-301254","number":"301254","sourceNumber":"301254","collectionBlock":"med:med-clinica-medica-med-clm-03","collectionLabel":"MED · MED CLM 03","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 03","subtopic":"","stem":"Em pacientes hipertensos com doença renal crônica, existem particularidades que\ndevem ser observadas ao se propor o\ntratamento adequado. Acerca do tratamento da hipertensão\narterial sistêmica para esses indivíduos e conforme as recomendações das Diretrizes Brasileiras de\nHipertensão Arterial - 2020, julgue o item a seguir. A meta de tratamento de pacientes desse grupo\né a mesma para diabéticos e não diabéticos: pressão arterial <130 mmHg x 80 mmHg.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Clinica médica/MED CLM 03/MED CLM 03.txt","sourceLabel":"MED · MED CLM 03","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-03-301255","number":"301255","sourceNumber":"301255","collectionBlock":"med:med-clinica-medica-med-clm-03","collectionLabel":"MED · MED CLM 03","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 03","subtopic":"","stem":"Em pacientes hipertensos com doença renal crônica, existem particularidades que\ndevem ser observadas ao se propor o\ntratamento adequado. Acerca do tratamento da hipertensão\narterial sistêmica para esses indivíduos e conforme as recomendações das Diretrizes Brasileiras de\nHipertensão Arterial - 2020, julgue o item a seguir. Em pacientes hipertensos sob tratamento\ndialítico, as médias sistólicas obtidas por medidas domiciliares associam-se linearmente ao\naumento do risco cardiovascular.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Clinica médica/MED CLM 03/MED CLM 03.txt","sourceLabel":"MED · MED CLM 03","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-03-291471","number":"291471","sourceNumber":"291471","collectionBlock":"med:med-clinica-medica-med-clm-03","collectionLabel":"MED · MED CLM 03","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 03","subtopic":"","stem":"Uma mulher de 48 anos de idade é trazida por familiares à unidade de emergência de\nhospital de alta complexidade com quadro de confusão mental, cefaleia e amaurose bilateral.\n\nSegundo familiares, a paciente é portadora de hipertensão arterial sistêmica há 2 anos, vindo em\ninvestigação diagnóstica por ser classificada como hipertensão arterial resistente. Nas últimas 2\nsemanas, a paciente passou a não tomar seus fármacos anti-hipertensivos, em razão de acreditar\nque o tratamento não estava mais funcionando. Na véspera, a paciente começou a se queixar de\ncefaleia holocraniana, pouco responsiva a fármacos, além de turvação visual. No dia de hoje, a\npaciente tornou-se um pouco confusa e começou a se queixar de que não estava conseguindo\nenxergar nada, razão por que foi trazida, às pressas, à unidade de emergência. Ao exame físico, a\npaciente mostra-se confusa, sonolenta, atendendo com dificuldade a algumas solicitações verbais.\nSua Pressão Arterial (PA) encontra-se em 240 x 160 mmHg em ambos os membros superiores,\nenquanto a frequência cardíaca é de 96 bpm. Um sopro é auscultado no flanco direito de seu\nabdome. Iniciado tratamento anti-hipertensivo, intravenoso, a paciente é submetida a uma\ntomografia computadorizada de crânio em que foram detectadas áreas hipodensas em regiões\noccipitais. A paciente é, então, encaminhada para realização de uma ressonância magnética de\nencéfalo que, na imagem pesada em T2, revela a presença de hiperintensidade de sinal nos lobos,\noccipitais, sem limites muito bem definidos. Instituído o tratamento indicado, a paciente evolui com\nregressão completa dos déficits neurológicos previamente descritos. Acerca do tratamento da\npaciente em questão, pode-se afirmar que:","options":{"A":"O alvo terapêutico no caso seria a normalização da pressão arterial em, no máximo, 2 horas.","B":"Após compensação clínica, seria fundamental ressecar o tumor adrenal secretor presente à\ndireita.","C":"Nicardipina e labetalol por via intravenosa seriam excelentes escolhas farmacológicas para\nredução da PA da paciente.","D":"Em razão da presença de trombose da artéria basilar, deveria ser adicionada anticoagulação\nplena com heparina de baixo peso molecular."},"answer":"C","source":"Clinica médica/MED CLM 03/MED CLM 03.txt","sourceLabel":"MED · MED CLM 03","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-03-268899","number":"268899","sourceNumber":"268899","collectionBlock":"med:med-clinica-medica-med-clm-03","collectionLabel":"MED · MED CLM 03","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 03","subtopic":"","stem":"Um paciente de 57 anos de idade compareceu ao atendimento ambulatorial para ajuste\nde medicamento anti-hipertensivo; faz uso de\namlodipina 10 mg ao dia. Não apresentou queixas.\n\nAo exame, observam-se FC= 80 bpm, FR = 20 irpm, SatO2 = 97% e PA = 160 mmHg x100 mmHg.\nDe acordo com uma possível comorbidade\napresentada pelo paciente, assinale a alternativa que\ncorresponde a uma adequada indicação de anti-hipertensivo.","options":{"A":"Diabetes mellitus - Hidroclorotiazida.","B":"Gota - Losartana.","C":"Disfunção erétil - Clonidina.","D":"Insuficiência coronariana - Hidralazina.","E":"Asma - Propranolol."},"answer":"B","source":"Clinica médica/MED CLM 03/MED CLM 03.txt","sourceLabel":"MED · MED CLM 03","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-03-263362","number":"263362","sourceNumber":"263362","collectionBlock":"med:med-clinica-medica-med-clm-03","collectionLabel":"MED · MED CLM 03","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 03","subtopic":"","stem":"Uma mulher com 69 anos de idade, hipertensa, em uso de enalapril 40 mg/dia e de\nhidroclorotiazida 25 mg/dia, tem palpitações, tremores de membros superiores e dispneia que\ncomeçaram há cerca de 30 minutos, logo após ter sido assaltada. Está orientada, corada, sem\ndéficits motores focais, FC = 110 bpm, PA = 200 x 120 mmHg em membros superiores. Ausculta\ncardíaca: bulhas normofonéticas, ritmo regular em 2 tempos, sem sopros. Pulsos radiais e femorais\namplos, bilateralmente, FR = 24 irpm, sem esforço respiratório. Ausculta pulmonar normal.\n\nOximetria de pulso de 99 % (em ar ambiente). O eletrocardiograma mostra taquicardia sinusal e\nsinais de sobrecarga ventricular esquerda. A abordagem inicial adequada para essa paciente é\nadministrar","options":{"A":"nifedipina de liberação rápida por via oral ou sublingual, repetindo a medicação se PA\npermanecer acima de 180 x 100 mmHg após 60 minutos.","B":"ansiolítico por via oral, mantendo-a em observação em local tranquilo e reavaliando os níveis\npressóricos num intervalo de 30 a 60 minutos.","C":"nitroglicerina por via endovenosa contínua, ajustando a dose a cada 5 minutos até alcançar\nníveis pressóricos inferiores a 160 x 90 mmHg.","D":"metoprolol em bolus por via endovenosa, repetindo a medicação se PA permanecer acima de\n180 x 100 mmHg após 10 minutos."},"answer":"B","source":"Clinica médica/MED CLM 03/MED CLM 03.txt","sourceLabel":"MED · MED CLM 03","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-03-273342","number":"273342","sourceNumber":"273342","collectionBlock":"med:med-clinica-medica-med-clm-03","collectionLabel":"MED · MED CLM 03","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 03","subtopic":"","stem":"Paciente do sexo feminino, 67 anos, hipertensa, obesa, dislipidêmica, apresenta em\nconsultas sucessivas níveis pressóricos médios de 156x104 e IMC 30,5; está em uso de losartana\n100mg/dia e atenolol 50mg/dia. Perfil laboratorial: Cr 0,7, LDL 162, HDL 33, TGL 270, Glic 110.\n\nConsidere RCV: risco cardiovascular e LOA: lesão de órgão alvo. Nesse caso, o RCV é:","options":{"A":"intermediário; a avaliação de LOA não á mandatória; a meta pressórica é < 135x85; o tratamento\né inadequado e deverá ser reformulado","B":"muito alto; deverá ser avaliada a presença de LOA; a meta pressórica é < 130x80; ao tratamento\natual deverá ser associado inicialmente um\ndiurético tiazídico","C":"intermediário; deverá ser avaliada a presença de LOA; a meta pressórica é < 140x90; ao\ntratamento atual deve ser associado um bloqueadores de canais de cálcio","D":"alto; deverá ser avaliada a presença de LOA; a meta pressórica é < 130x80; o tratamento é\ninadequado e deverá ser reformulado"},"answer":"D","source":"Clinica médica/MED CLM 03/MED CLM 03.txt","sourceLabel":"MED · MED CLM 03","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-03-212131","number":"212131","sourceNumber":"212131","collectionBlock":"med:med-clinica-medica-med-clm-03","collectionLabel":"MED · MED CLM 03","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 03","subtopic":"","stem":"Com relação a doenças respiratórias, julgue o item a seguir. A Síndrome da Apneia\nObstrutiva do Sono (SAOS) aumenta, de forma significativa, o risco de doença coronariana;\ninsuficiência cardíaca (com ou sem redução da fração de ejeção); ocorrência de arritmias atriais e\nventriculares; aterosclerose; doença coronariana; acidente vascular encefálico e diabetes melito.","options":{"A":"CERTO.","B":"ERRADO."},"answer":"A","source":"Clinica médica/MED CLM 03/MED CLM 03.txt","sourceLabel":"MED · MED CLM 03","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-03-206133","number":"206133","sourceNumber":"206133","collectionBlock":"med:med-clinica-medica-med-clm-03","collectionLabel":"MED · MED CLM 03","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 03","subtopic":"","stem":"Alterações próprias do envelhecimento determinam aspectos diferenciais na PA dessa\npopulação, sendo INADEQUADO se considerar que,","options":{"A":"o envelhecimento vascular é o aspecto principal relacionado à elevação da PA nos idosos,\ncaracterizado por alterações na microarquitetura da parede dos vasos, com consequente\nenrijecimento arterial.","B":"grandes vasos, como a aorta, perdem sua distensibilidade e, apesar de os mecanismos precisos\nnão estarem claros, envolvem\n\nprimariamente mudanças estruturais na camada média dos vasos, como fratura por fadiga da\nelastina, depósito de colágeno e calcificação.","C":"alterações próprias do envelhecimento determinam aspectos diferenciais na PA dessa\npopulação, como maior frequência de hiato\nauscultatório, que consiste no desaparecimento dos\nsons durante a deflação do manguito, geralmente entre o final da fase I e o início da fase II dos\nsons de Korotkoff, resultando em valores falsamente baixos para a PAS ou falsamente altos para a\nPAD.","D":"apesar de os indivíduos nessa faixa etária serem menos conscientes de sua condição e estarem\nmais frequentemente sob tratamento do que os\nhipertensos de meia-idade, as taxas de controle da\nPA nos idosos são inferiores, em especial após os 60 anos."},"answer":"D","source":"Clinica médica/MED CLM 03/MED CLM 03.txt","sourceLabel":"MED · MED CLM 03","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-03-206142","number":"206142","sourceNumber":"206142","collectionBlock":"med:med-clinica-medica-med-clm-03","collectionLabel":"MED · MED CLM 03","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 03","subtopic":"","stem":"O diagnóstico e a avaliação do grau de envolvimento com LOA são fundamentais para\na escolha do tratamento, sendo INADEQUADO que","options":{"A":"a hipertensão renovascular (HARV) não pode ser secundária à estenose parcial, uni ou bilateral\nda artéria renal (EAR), desencadeada e mantida\npor isquemia do tecido renal.","B":"a hipertensão renovascular (HARV) tem prevalência de 5% dos pacientes hipertensos.","C":"a principal causa é a aterosclerose (90%), seguida por displasia fibromuscular, sendo a arterite\nde Takayasu a menos frequente.","D":"independentemente do fator causal, é importante determinante de morbimortalidade CV."},"answer":"A","source":"Clinica médica/MED CLM 03/MED CLM 03.txt","sourceLabel":"MED · MED CLM 03","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-03-206084","number":"206084","sourceNumber":"206084","collectionBlock":"med:med-clinica-medica-med-clm-03","collectionLabel":"MED · MED CLM 03","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 03","subtopic":"","stem":"Para detecção de adenoma unilateral produtor de Aldo APA ou hiperplasia, é indicada\nTC de adrenais com cortes finos ou RNM.\nSendo CORRETA a seguinte conduta:","options":{"A":"o cateterismo de veias adrenais é indicado quando, à TC, as adrenais são normais, têm\nanormalidades bilaterais (espessamento\n\nou micronódulos) ou lesão unilateral em pacientes > 60 anos.","B":"o teste de supressão com dexametasona é indicado para investigar HAP supressível por\nglicocorticoide em pacientes com hiperaldosteronismoprimário HAP e início de HA antes dos 40\nanos.","C":"o cateterismo de veias adrenais é contraindicado quando, à TC, as adrenais são normais, têm\nanormalidades bilaterais (espessamento ou micronódulos) ou lesão unilateral em pacientes > 40\nanos.","D":"o teste de supressão com dexametasona não é indicado para investigar HAP supressível por\nglicocorticoide em pacientes com hiperaldosteronismo primário HAP e início de HA antes dos 40\nanos."},"answer":"B","source":"Clinica médica/MED CLM 03/MED CLM 03.txt","sourceLabel":"MED · MED CLM 03","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-03-177246","number":"177246","sourceNumber":"177246","collectionBlock":"med:med-clinica-medica-med-clm-03","collectionLabel":"MED · MED CLM 03","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 03","subtopic":"","stem":"Um homem com 61 anos de idade procura atendimento médico em ambulatório de\ndislipidemia para ouvir uma segunda opinião a respeito do tratamento que ele realizava para\ncontrolar os níveis elevados do próprio colesterol LDL. Ele afirma que, ao longo da vida ,\napresentou valores sempre altos de LDL-C, com valor máximo de 214 mg/dL, há dois anos. No\núltimo exame , realizado no presente mês, os resultados foram: colesterol total (CT) de 242 mg/dL,\nLDL-C de 178 mg/dL e colesterol HDL de 45 mg/dL. O paciente é portador de hipertensão arterial\nsistêmica , com controle adequado e uso de duas classes de medicamentos (I-ECA e bloqueador\nde canal de cálcio). Nega diabetes ou tabagismo. Além disso, o paciente questiona qual seria o\nbenefício do tratamento proposto por outra equipe médica, depois que ele obteve informações em\nrede sociais. Com base no referido caso clínico e considerando o tratamento da elevação do\ncolesterol LDL, assinale a anativa correta.","options":{"A":"Neste caso, a redução do colesterol LDL, conseguida com medicamentos ou mudança do estilo\nde vida do paciente, equivale aos desfechos\ncardiovasculares maiores, por se tratar de pacientente\nestratificado na categoria de baixo risco cardiovascular.","B":"O achado de espessamento da íntima-média de carótida, em 1,5 mm, indicaria o uso de\nestatinas potentes, como a rosuvastatina na\nprevenção de desfechos cardiovasculares maiores.","C":"Se o paciente já fizer uso da estatina, não há benefício em reduções de LDL para valores\ninfiores a 70 mg/DL , indepedentemente do risco cardiovascular.","D":"O valor do colestreol LDL não interfere na estratificação de risco e, portanto, não interfere na\nescolha da estatina.","E":"A meta de colestrol HDL não deve ser usada como critério de prevenção de desfechos."},"answer":"C","source":"Clinica médica/MED CLM 03/MED CLM 03.txt","sourceLabel":"MED · MED CLM 03","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-03-175141","number":"175141","sourceNumber":"175141","collectionBlock":"med:med-clinica-medica-med-clm-03","collectionLabel":"MED · MED CLM 03","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 03","subtopic":"","stem":"Dentro da abordagem de Jovens com Hipertensão Sistólica Isolada (HSI), podemos\nconsiderar como INCORRETO:","options":{"A":"A HSI é rara em jovens saudáveis do sexo masculino com menos de 30 anos e pode estar\nassociada à pressão central normal.","B":"A HSI em jovens saudáveis do sexo masculino com menos de 30 anos é associada à pressão\ncentral normal, o tratamento não teria benefícios significativos.","C":"A HSI em jovens saudáveis do sexo masculino, com pressão central normal, é recomendada a\nadoção de medidas não medicamentosas, com\nmonitorização de LOA.","D":"O tratamento da HSI deve ter início imediato de terapia farmacológica caso seu risco CV seja\nalto."},"answer":"A","source":"Clinica médica/MED CLM 03/MED CLM 03.txt","sourceLabel":"MED · MED CLM 03","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-03-175170","number":"175170","sourceNumber":"175170","collectionBlock":"med:med-clinica-medica-med-clm-03","collectionLabel":"MED · MED CLM 03","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 03","subtopic":"","stem":"Quando analisamos os aspectos relacionados aos cuidados de Hipertensão\nrelacionados na população idosa, apenas\npodemos considerar como correta a seguinte alternativa:","options":{"A":"Aspectos especiais na medição da PA na população idosa decorrem de alterações próprias do\nenvelhecimento, como a maior frequência do hiato auscultatório, que consiste no desaparecimento\ndos sons durante a deflação do manguito, resultando em valores falsamente baixos para a PAS ou\nfalsamente altos para a PAD.","B":"A grande variação da PA nos idosos ao longo das 24 horas torna a MAPA uma ferramenta\npoucas vezes útil.","C":"A pseudo-hipertensão, que está associada ao processo aterosclerótico, sendo que a manobra\nde Osler não tem capacidade de\ndiagnosticá-la, pois a artéria radial permanece ainda palpável\napós a insuflação do manguito pelo menos 30 mmHg acima do desaparecimento do pulso radial.","D":"Maior ocorrência de hipertensão pós-prandial e, finalmente, a presença de arritmias, como\nfibrilação atrial, podem impossibilitar a medição da PA."},"answer":"A","source":"Clinica médica/MED CLM 03/MED CLM 03.txt","sourceLabel":"MED · MED CLM 03","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-03-183923","number":"183923","sourceNumber":"183923","collectionBlock":"med:med-clinica-medica-med-clm-03","collectionLabel":"MED · MED CLM 03","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 03","subtopic":"","stem":"A respeito da hipertensão arterial sistêmica (HAS), considerada o principal fator de\nrisco\npara ocorrência de acidente vascular cerebral (AVC) e de infarto agudo do miocardio (IAM), julgue o\nitem a seguir. A avaliação do paciente hipertenso deverá incluir a realização de exame físico e de\nexames laboratoriais, entre eles o exame de urina para avaliação de proteinúria.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Clinica médica/MED CLM 03/MED CLM 03.txt","sourceLabel":"MED · MED CLM 03","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-03-183936","number":"183936","sourceNumber":"183936","collectionBlock":"med:med-clinica-medica-med-clm-03","collectionLabel":"MED · MED CLM 03","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 03","subtopic":"","stem":"A respeito da hipertensão arterial sistêmica (HAS), considerada o principal fator de\nrisco\npara ocorrência de acidente vascular cerebral (AVC) e de infarto agudo do miocárdio (IAM), julgue o\nitem a seguir. Apesar de o tabagismo ser uma prática social mundialmente relacionada a doenças\npulmonares, não existe relação comprovada entre o uso do cigarro e a ocorrência de infarto agudo\ndo miocárdio entre fumantes, independentemente da faixa etária.","options":{"A":"CERTO","B":"ERRADO"},"answer":"B","source":"Clinica médica/MED CLM 03/MED CLM 03.txt","sourceLabel":"MED · MED CLM 03","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-03-183946","number":"183946","sourceNumber":"183946","collectionBlock":"med:med-clinica-medica-med-clm-03","collectionLabel":"MED · MED CLM 03","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 03","subtopic":"","stem":"A respeito da hipertensão arterial sistêmica (HAS), considerada o principal fator de\nrisco\npara ocorrência de acidente vascular cerebral (AVC) e de infarto agudo do miocardio (IAM), julgue o\nitem a seguir. A obesidade e o sobrepeso constituem condições de risco para várias enfermidades\ncardiovasculares, como hipertensão, dislipdemias e diabetes tipo 2. No Brasil, a prevalência de\nsobrepeso, que era predominante entre mulheres, sofreu inversão, sendo o sobrepeso mais\nfrequente atualmente entre os homens.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Clinica médica/MED CLM 03/MED CLM 03.txt","sourceLabel":"MED · MED CLM 03","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-03-183954","number":"183954","sourceNumber":"183954","collectionBlock":"med:med-clinica-medica-med-clm-03","collectionLabel":"MED · MED CLM 03","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 03","subtopic":"","stem":"A respeito da hipertensão arterial sistêmica (HAS), considerada o principal fator de\nrisco\npara ocorrência de acidente vascular cerebrla (AVC) e de infarto agudo do miocardio (IAM), julgue o\nitem a seguir. As medidas para o tratamento da HAS demandam elevado custo financeiro,\nconsistindo grande desafio em todo mundo.","options":{"A":"CERTO","B":"ERRADO"},"answer":"B","source":"Clinica médica/MED CLM 03/MED CLM 03.txt","sourceLabel":"MED · MED CLM 03","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-03-154507","number":"154507","sourceNumber":"154507","collectionBlock":"med:med-clinica-medica-med-clm-03","collectionLabel":"MED · MED CLM 03","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 03","subtopic":"","stem":"A aferição correta da pressão arterial (PA) em lactentes e crianças, capaz de indicar o\ndiagnóstico de HAS deve ser realizada com técnica adequada. A alternativa que contempla a\ntécnica correta e a interpretação correta dos valores é:","options":{"A":"Idealmente a criança deverá estar sentada, com as costas bem apoiadas e com o braço direito\nao nível do coração. Valores de PA abaixo do\npercentil 90 para sexo, peso e altura são\nconsideradas normais.","B":"A relação largura/comprimento do manguito deverá ser maior ou igual a 1:2. Valores de PA entre\nos percentis 90 e 95 são considerados pré-\nhipertensão.","C":"A relação largura/comprimento do manguito deverá ser maior ou igual a 1:2. Valores de PA entre\nos percentis 95 e 99 são considerados\nhipertensão grau I.","D":"Idealmente a criança deverá estar sentada, com as costas bem apoiadas e com o braço direito\nao nível do coração. Nos adolescentes,\nvalores de PA iguais ou acima de 120x80mmHg, porém\nabaixo do percentil 90 , são considerados normais.","E":"A relação largura/comprimento do manguito deverá ser menor ou igual a 1:2. Valores de PA\nentre os percentis 90 e 95 são considerados hipertensão leve."},"answer":"B","source":"Clinica médica/MED CLM 03/MED CLM 03.txt","sourceLabel":"MED · MED CLM 03","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-03-158066","number":"158066","sourceNumber":"158066","collectionBlock":"med:med-clinica-medica-med-clm-03","collectionLabel":"MED · MED CLM 03","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 03","subtopic":"","stem":"Paciente de 13 anos de idade, obeso, mas sem outras comorbidades conhecidas,\napresenta-se à consulta acompanhado da mãe a\nfim de solicitar atestado para liberação para\natividade física, exigido para participação das aulas de educação física na respectiva escola. Ao\nexame físico, apresenta: PA MSD = 200 mmHg x 120 mmHg; PA MSE = 120 mmHg x 80 mmHg;\nAC = BNF; RR; 2T, presença de sopro sistólico 2+/6+ em todo o precórdio; AP = normal; ABD =\nnormal; Ext = pulsos pediosos presentes, mas de baixa amplitude. O ECG foi realizado com\npresteza pela equipe de ambulatório, revelando sinais de sobrecarga de ventrículo esquerdo. Em\nrelação ao caso apresentado, quanto ao provável diagnóstico do paciente e considerando as\nDiretrizes de Hipertensão da Sociedade Brasileira de Cardiologia, assinale a alternativa CORRETA.","options":{"A":"As formas mais severas dessa patologia costumam causar insuficiência cardíaca entre o final da\nadolescência e o início da idade adulta.","B":"Caso haja condições clínicas de postergação do tratamento cirúrgico, realizá-lo após os 14 anos\nde idade diminui a recorrência.","C":"O quadro clínico é compatível com coarctação de aorta na topografia de aorta torácica\ndescendente.","D":"O tratamento é sempre intervencionista.","E":"Essa patologia representa a segunda maior causa de hipertensão secundária na população\nbrasileira."},"answer":"E","source":"Clinica médica/MED CLM 03/MED CLM 03.txt","sourceLabel":"MED · MED CLM 03","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-03-133927","number":"133927","sourceNumber":"133927","collectionBlock":"med:med-clinica-medica-med-clm-03","collectionLabel":"MED · MED CLM 03","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 03","subtopic":"","stem":"De acordo com o documento VI Diretrizes Brasileiras de Hipertensão, a aferição da\npressão arterial dever ser feita a partir de","options":{"A":"Dois minutos de repouso em ambiente calmo.","B":"Doze horas de abstinência sexual.","C":"Deflação do manguito na velocidade de 10 mmHg por segundo.","D":"Sessenta minutos sem atividade física.","E":"Duas horas sem uso de tabaco."},"answer":"D","source":"Clinica médica/MED CLM 03/MED CLM 03.txt","sourceLabel":"MED · MED CLM 03","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-03-133935","number":"133935","sourceNumber":"133935","collectionBlock":"med:med-clinica-medica-med-clm-03","collectionLabel":"MED · MED CLM 03","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 03","subtopic":"","stem":"Paciente feminina de 36 anos de idade, sedentária e obesa, agenda uma consulta por\nestar preocupada com a pressão arterial em razão\nde recente óbito familiar. Mostra-se ansiosa para\nfazer \"todos os exames de pressão\", mas se queixa de dificuldade financeira e pede somente os\nexames com maior nível de evidência. Considerando essa situação hipotética, é CORRETO afirmar\nque a paciente foi adequadamente orientada, caso tenha sido informada de que, entre os exames\niniciais, os que têm nível de evidência B, de acordo com VI Diretrizes Brasileiras de Hipertensão,\nsão os seguintes:","options":{"A":"De ureia e de potássio.","B":"Ecocardiograma e de glicemia de jejum.","C":"De glicemia pós-prandial e de creatinina.","D":"De curva glicêmica e de colesterol total.","E":"De creatinina e de eletrocardiograma."},"answer":"E","source":"Clinica médica/MED CLM 03/MED CLM 03.txt","sourceLabel":"MED · MED CLM 03","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-03-104742","number":"104742","sourceNumber":"104742","collectionBlock":"med:med-clinica-medica-med-clm-03","collectionLabel":"MED · MED CLM 03","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 03","subtopic":"","stem":"Para a avaliação da pressão arterial em consulta ambulatorial ser adequada, deve ser\nfeita em:","options":{"A":"duas medidas espaçadas em cinco minutos.","B":"duas medidas seguidas.","C":"uma medida, em decúbito dorsal, seguida de outra em posição ortostática.","D":"uma medida no braço direito e, cinco minutos após, na perna direita,","E":"três medidas seguidas."},"answer":"A","source":"Clinica médica/MED CLM 03/MED CLM 03.txt","sourceLabel":"MED · MED CLM 03","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-03-104755","number":"104755","sourceNumber":"104755","collectionBlock":"med:med-clinica-medica-med-clm-03","collectionLabel":"MED · MED CLM 03","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 03","subtopic":"","stem":"Além dos benefícios de natureza mais ampla para a saúde e a melhoria da qualidade\nde vida, vários estudos têm demonstrado que a\natividade física é um fator importante na prevenção\ne no controle de alguns problemas de saúde, quando analisada a partir da perspectiva\npopulacional. A orientação para a prática de atividades físicas moderadas está relacionada ao\ncontrole da frequência cardíaca como parâmetro de segurança. Um indivíduo de sessenta anos de\nidade deve atingir frequência cardíaca (bat/min) máxima e ideal, respectivamente, de","options":{"A":"140 e entre 110 e 118.","B":"150 e entre 124 e 138.","C":"160 e entre 104 e 128.","D":"170 e entre 114 e 138.","E":"180 e entre 108 e 128."},"answer":"C","source":"Clinica médica/MED CLM 03/MED CLM 03.txt","sourceLabel":"MED · MED CLM 03","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-03-97839","number":"97839","sourceNumber":"97839","collectionBlock":"med:med-clinica-medica-med-clm-03","collectionLabel":"MED · MED CLM 03","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 03","subtopic":"","stem":"Um homem, com 45 anos de idade, professor do ensino médio, é atendido em\nambulatório para tratamento de hipertensão\narterial diagnosticada há três anos como de natureza\nessencial (primária). Refere que nos últimos meses, mesmo fazendo uso regular de inibidores da\nenzima conversora de angiotensina, de bloqueador de canal de cálcio e de diurético, os seus níveis\npressóricos mantêm-se elevados. Tem história familiar de hipertensão arterial. Não refere\nantecedentes patológicos. Não é submetido a acompanhamento dietético ou à prática de exercícios\nfísicos regulares. Não utiliza outros medicamentos. Ao exame físico, apresenta-se em bom estado\ngeral, com índice de massa corporal = 30,6 kg/m², frequência respiratória = 22 irpm, frequência\ncardíaca = 112 bpm e pressão arterial = 160 x 110 mmHg; ausculta pulmonar normal; ritmo\ncardíaco regular em 2T, bulhas normofonéticas, sem sopros ou arritmias; exame abdominal e de\nmembros sem alterações. Exame de fundo de olho: tortuosidade e espessamento de arteríolas,\npresença de alguns cruzamentos patológicos. Eletrocardiograma com sinais de sobrecarga\nventricular esquerda e alterações difusas de repolarização. Radiografia de tórax com aumento da\nárea cardíaca por aumento do ventrículo esquerdo. Bioquímica sérica: glisose = 116 mg/dl (Valor\nde referência = 75-99 mg/dl), ureia = 70 mg/dl (Valor de referência = 20-35 mg/dl), creatinina = 1,8\nmg/dl (Valor de referência = 0,7-1,2 mg/dl). O quadro apresentado é demonstrativo de:","options":{"A":"hipertensão maligna instalada.","B":"insuficiência renal decorrente do uso de agentes hipertensivos.","C":"evolução natural da hipertensão essencial ligada à história familiar.","D":"comprometimento dos órgãos-alvos na hipertensão arterial sistêmica."},"answer":"D","source":"Clinica médica/MED CLM 03/MED CLM 03.txt","sourceLabel":"MED · MED CLM 03","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-03-75542","number":"75542","sourceNumber":"75542","collectionBlock":"med:med-clinica-medica-med-clm-03","collectionLabel":"MED · MED CLM 03","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 03","subtopic":"","stem":"Homem com 48 anos de idade procura o ambulatório de Clínica Médica para avaliação.\nNão apresenta história de comorbidades\nconhecidas prévias, mas é tabagista (20 maços-ano) e\ntem histórico familiar de Hipertensão Arterial Sistêmica (HAS) importante. Nega diabetes,\ndislipidemia, etilismo, drogadição, acidente vascular cerebral, doença renal prévia, doenças da\ntireoide, doença arterial coronariana e uso crônico de medicações. No momento, encontra-se\nassintomático, com Pressão Arterial (PA) = 145 x 95 mmHg (medida duas vezes na consulta) e\níndice de massa corporal de 26,8 kg/m². A fundoscopia revelou arteríolas estreitadas, tortuosas e\nbrilhantes (em fio de prata), além de cruzamento arterial patológico. A ausculta cardíaca revelou\nbulhas normofonéticas, ritmo cardíaco regular em três tempos, com presença de B4 e frequência\ncardíaca = 88 bpm. Não havia turgência jugular. A ausculta pulmonar era normal. Não havia edema\nde membros inferiores. O eletrocardiograma revelaram sinais de hipertrofia ventricular esquerda. A\ndosagem de creatinina e o sumário de urina (Urina I) eram normais. Diante do quadro desse\npaciente, a meta de PA e a recomendação do tratamento neste momento são, respectivamente:","options":{"A":"PA < 140 x 90; modificação do estilo de vida isolado.","B":"PA < 130 x 80; modificação do estilo de vida isolado.","C":"PA < 140 x 90; modificação do estilo de vida e tratamento medicamentoso.","D":"PA < 120 x 80; modificação do estilo de vida e tratamento medicamentoso.","E":"PA < 130 x 80; modificação do estilo de vida e tratamento medicamentoso."},"answer":"E","source":"Clinica médica/MED CLM 03/MED CLM 03.txt","sourceLabel":"MED · MED CLM 03","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-03-368167","number":"368167","sourceNumber":"368167","collectionBlock":"med:med-clinica-medica-med-clm-03","collectionLabel":"MED · MED CLM 03","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 03","subtopic":"","stem":"Um pediatra atende há dois anos uma paciente feminina de 12 anos de idade com\nestatura no percentil 50, e ela tem excesso\nde peso (IMC: percentil 90). A aferição da PA nas\núltimas três ocasiões mostrou os seguintes valores: 1) 126x84 mmHg; 2) 130x84 mmHg; 3) 128x80\nmmHg. Ela é assintomática e tem antecedentes familiares de hipertensão arterial (pai e avós\nmaternos). Sabe-se que os valores normais da tabela de PA são: P50: 108x62 mmHg, P90: 121x75\nmmHg, P95: 125x78 mmHg e P99: 137x90 mmHg. Nesse contexto, é correto afirmar:","options":{"A":"Essa paciente não precisa ser acompanhada quanto à sua pressão arterial porque não será\nnecessário o uso de medicamentos.","B":"Deve-se pesquisar a etiologia da hipertensão arterial com dosagens de renina sérica e ultrassom\nde artérias renais com Doppler.","C":"A adolescente tem diagnóstico de pré-hipertensão arterial, e o tratamento medicamentoso deve\nser instituído o mais breve possível.","D":"A adolescente deve ser investigada com relação a possível acometimento de órgãos-alvo\n(exame de fundo de olho, ecocardiograma,\nalbuminúria)."},"answer":"D","source":"Clinica médica/MED CLM 03/MED CLM 03.txt","sourceLabel":"MED · MED CLM 03","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-03-345715","number":"345715","sourceNumber":"345715","collectionBlock":"med:med-clinica-medica-med-clm-03","collectionLabel":"MED · MED CLM 03","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 03","subtopic":"","stem":"Com relação à medida da pressão arterial (PA), assinale a alternativa correta.","options":{"A":"A medida da PA por dispositivo oscilométrico é padrão ouro.","B":"A medida da PA por dispositivo oscilométrico deve ser preferencialmente realizada em membros\ninferiores.","C":"O valor da razão da largura do manguito pela circunferência do braço deve ser próximo de 0,5.","D":"A medida da PA por meio de cateter intra-arterial é uma técnica simples, sem complicações."},"answer":"C","source":"Clinica médica/MED CLM 03/MED CLM 03.txt","sourceLabel":"MED · MED CLM 03","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-03-335098","number":"335098","sourceNumber":"335098","collectionBlock":"med:med-clinica-medica-med-clm-03","collectionLabel":"MED · MED CLM 03","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 03","subtopic":"","stem":"Mulher de 53 anos de idade, sedentária, tabagista, hipertensa, em uso de anlodipino 10\nmg por dia de forma regular, sem história\nde eventos isquêmicos prévios, foi abordada quanto à\ncessação do tabagismo, mas se recusou: vê no cigarro a única estratégia de controle da ansiedade\ne não deseja parar de fumar. Tem IMC = 29, FC = 82 bpm, PA = 160 x 100 mmHg (duas medidas\nna mesma consulta) e circunferência abdominal = 88 cm. Traz os seguintes resultados de exames:\nglicemia de jejum = 155 mg/dL, glicemia pós sobrecarga de dextrosol = 249 mg/dL, colesterol total\n\n= 263 mg/dL, HDL = 35 mg/dL, triglicerídeos = 290 mg/dL. A abordagem que nesse momento seria\na mais coerente com os dados clínicos dessa\npaciente é reforçar a importância da busca por um\nestilo de vida saudável e","options":{"A":"associar um segundo anti-hipertensivo à sua prescrição, bem como reavaliar sua glicemia em\ntrês meses, apenas.","B":"associar um segundo anti-hipertensivo e metformina à sua prescrição nessa consulta.","C":"aumentar a dose da anlodipina e prescrever associação de metformina + glibenclamida nessa\nconsulta.","D":"suspender a anlodipina e prescrever inibidor da enzima conversora de angiotensina e insulina\nNPH nessa consulta."},"answer":"B","source":"Clinica médica/MED CLM 03/MED CLM 03.txt","sourceLabel":"MED · MED CLM 03","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-03-335107","number":"335107","sourceNumber":"335107","collectionBlock":"med:med-clinica-medica-med-clm-03","collectionLabel":"MED · MED CLM 03","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 03","subtopic":"","stem":"Aaferição da pressão arterial na criança e no adolescente ainda não é um hábito na\nconsulta pediátrica e, portanto, muitos desses\npacientes hipertensos ficam por longo tempo sem\ndiagnóstico. Ademais, alguns pediatras desconhecem os métodos dessa aferição e / ou não\npossuem o instrumental adequado. Acerca da hipertensão arterial na infância, assinale a alternativa\ncorreta.","options":{"A":"A principal causa de hipertensão arterial em crianças pré-escolares e escolares é a hipertensão\nessencial.","B":"A definição de emergência hipertensiva contempla uma elevação da pressão arterial sistólica e\ndiastólica sem lesão de órgãos-alvo.","C":"A obesidade na criança e no adolescente só é considerada fator de risco para hipertensão\narterial se o paciente for obeso desde o\nnascimento.","D":"A hipertensão arterial em recém-nascidos e lactentes habitualmente está relacionada à doença\nrenal ou vascular."},"answer":"B","source":"Clinica médica/MED CLM 03/MED CLM 03.txt","sourceLabel":"MED · MED CLM 03","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-03-336302","number":"336302","sourceNumber":"336302","collectionBlock":"med:med-clinica-medica-med-clm-03","collectionLabel":"MED · MED CLM 03","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 03","subtopic":"","stem":"Homem, 65 anos, portador de hipertensão arterial sistêmica e diabetes melitus,\nassintomático, em uso regular de losartan\n100mg/dia, atenolol 50mg/dia e metformina 85 mg 3x ao\ndia, vem para consulta de rotina no ambulatorio de nefrologia por doenca renal cronica, onde faz\nacompanahmento. Traz exames de controle que apresentam elevação da creatinina (creatinina 3,2\nmg/dl ? TFGe CKD-EPI 50 ml/min) em relação aos exames anteriores (creatinina 1,7 mg/dl ? TFGe\nCKD-EPI 26 ml/min). Ao exame: anicterico, aciantico, afebril, corado e hidratado. PA: 150/90 mmHg\nFC:64 bpm FR: 12 ipm. Sem outras alterações no exame fisico. Outros exames laboratoriais: sodio\n140 mEq/l | ureia 40 mg/dl | potassio 4,9 mEq/l, | glicemia em jejum 127 mg/dl hemoglobina glicada\n6g%. Qual o melhor conduta para o caso?","options":{"A":"Associar insulinoterapia a noite para controle glicemico","B":"Iniciar vasodilatador arterial para controle da pressao arterial","C":"Supender betabloqueador e associar enalapril","D":"Suspender losartan e iniciar bloqueador de canal de calcio"},"answer":"D","source":"Clinica médica/MED CLM 03/MED CLM 03.txt","sourceLabel":"MED · MED CLM 03","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-03-291919","number":"291919","sourceNumber":"291919","collectionBlock":"med:med-clinica-medica-med-clm-03","collectionLabel":"MED · MED CLM 03","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 03","subtopic":"","stem":"Um paciente do sexo masculino, com 59 anos e história de insuficiência coronariana,\nchega à Emergência com quadro de dor precordial,\nem repouso, há cerca de quinze minutos.\n\nApresenta sudorese e PA: 190X120mmHg. Nesse caso, é CORRETO afirmar que o diagnóstico\nmais provável e a conduta mais adequada, são,\nrespectivamente:","options":{"A":"Emergência hipertensiva associada à síndrome coronariana aguda; tratar com MONA e\nmetoprolol.","B":"Urgência hipertensiva associada à síndrome coronariana aguda; tratar com captopril, ácido\nacetilsalicílico e isordil®.","C":"Emergência hipertensiva associada à síndrome coronariana aguda; tratar com captopril, ácido\nacetilsalicílico e isordil®.","D":"Urgência hipertensiva associada à síndrome coronariana aguda; tratar com morfina e oxigênio,\nnitroglicerina, ácido acetilsalicílico (MONA) e captopril."},"answer":"A","source":"Clinica médica/MED CLM 03/MED CLM 03.txt","sourceLabel":"MED · MED CLM 03","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-03-314031","number":"314031","sourceNumber":"314031","collectionBlock":"med:med-clinica-medica-med-clm-03","collectionLabel":"MED · MED CLM 03","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 03","subtopic":"","stem":"As modificações do estilo de vida, para o paciente com Hipertensão Arterial Sistêmica\n(HAS), devem fazer parte de qualquer regime\nanti-hipertensivo. No entanto, as intervenções na\ndieta e no exercício são difíceis de sustentar em longo prazo. Dessa maneira, quase todos os\npacientes vão necessitar de medicação para otimizar os resultados. Em relação aos medicamentos\nutilizados para o tratamento da HAS, assinalar a alternativa CORRETA.","options":{"A":"Os inibidores do sistema renina-angiotensina (IECA) e os bloqueadores do receptor de\nangiotensina (BRA) têm efeitos comparáveis na função renal nos pacientes com doença renal\ncrônica, mas os IECA produzem maior regressão da hipertrofia ventricular esquerda do que os\noutros anti-hipertensivos.","B":"Todos os inibidores do sistema renina-angiotensina são contraindicados nas grávidas, porque\neles causam agenesia renal materna e outros\nefeitos maternos.","C":"Uma dieta rica em sal ou terapias concomitantes com medicamentos anti-inflamatórios não\nesteroides comprometem a eficácia dos bloqueadores de canais de cálcio (BCC) di-hidropiridinas.","D":"Os IECA e os BRA podem provocar hipercalemia no quadro de doença renal crônica ou diabetes\ncom acidose tubular renal tipo 4; dessa\nmaneira, em todos os pacientes, os níveis de potássio e\ncreatinina séricos devem ser monitorados.","E":"Os BCC di-hidropiridinicos de longa ação não devem ser usados para tratar hipertensão, pois, ao\ndesencadear uma queda abrupta na pressão arterial com ativação simpática reflexa, podem\nprecipitar síncope."},"answer":"D","source":"Clinica médica/MED CLM 03/MED CLM 03.txt","sourceLabel":"MED · MED CLM 03","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-03-305023","number":"305023","sourceNumber":"305023","collectionBlock":"med:med-clinica-medica-med-clm-03","collectionLabel":"MED · MED CLM 03","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 03","subtopic":"","stem":"Considere um homem de 65 anos de idade, diabético, hipertenso, em uso de\nmetformina 2500 mg/dia, atorvastatina 20\nmg/dia, enalapril 20 mg/dia e hidroclorotiazida 25 mg/dia.\nCom boa adesão e tolerância às medicações, mantém PA = 160 x 90 mmHg. Seu médico optou,\nentão, por aumentar a dose do enalapril para 40 mg/dia, mantendo as demais medicações nas\nmesmas dosagens. Duas semanas após o ajuste da medicação, o paciente estava assintomático e\napresentou os seguintes dados: PA = 155 x 90 mmHg, FC = 80 bpm, potássio: 4,8 mEq/L (VR = 3-5\nmEq/L), creatinina = 1,1mg/dL (VR<1,5 mg/dL), ureia = 37 mg/dL (VR = 16-40 mg/dL), ácido úrico =\n8,5mg/dL (VR = 3,5-7 mg/dL). Há dois meses sua creatinina era 0,8 mg/dL. A respeito do\ntratamento deste paciente, assinale a alternativa correta.","options":{"A":"A anlodipina tem vantagens para esse paciente em relação à hidroclorotiazida, por não interferir\nnegativamente no seu perfil glicêmico.","B":"Ahidroclorotiazida está contraindicada para esse paciente em virtude dos seus níveis elevados\nde ácido úrico.","C":"A persistência dos níveis pressóricos acima do desejável nessa consulta indica a necessidade\nde associação de uma terceira droga ao seu esquema\nanti-hipertensivo.","D":"Apesar dos potenciais benefícios da medicação, não é seguro manter o enalapril para esse\npaciente e a medicação deve ser suspensa."},"answer":"A","source":"Clinica médica/MED CLM 03/MED CLM 03.txt","sourceLabel":"MED · MED CLM 03","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-03-305024","number":"305024","sourceNumber":"305024","collectionBlock":"med:med-clinica-medica-med-clm-03","collectionLabel":"MED · MED CLM 03","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 03","subtopic":"","stem":"Considere que uma mulher de 36 anos de idade, assintomática, sedentária,\n\nnão-tabagista, apresenta IMC = 28, PA= 145 x 85 mmHg em MSD e 140 x 85 mmHg MSE em duas\nconsultas com intervalo de 21 dias, sem outras alterações ao exame físico. Relata dieta pobre em\nfrutas e legumes, rica em alimentos ultraprocessados e que sempre acrescenta sal no prato. Traz\nresultados de exames: glicemia jejum = 88 mg/dL; colesterol total = 181 mg/dL; HDL = 59 mg/dL;\ntriglicerídeos = 110 mg/dL. Não há relato de doença arterial coronariana ou de acidente vascular\nencefálico na sua família. Com base nesses dados clínicos disponíveis, a recomendação da\nSociedade Brasileira de Cardiologia para essa paciente é considerar tratamento farmacológico:","options":{"A":"Após seis meses de modificações no seu estilo de vida.","B":"Após um ano de modificações no seu estilo de vida.","C":"Imediatamente, com uma medicação apenas.","D":"Imediatamente, com associação de medicações."},"answer":"A","source":"Clinica médica/MED CLM 03/MED CLM 03.txt","sourceLabel":"MED · MED CLM 03","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-03-291643","number":"291643","sourceNumber":"291643","collectionBlock":"med:med-clinica-medica-med-clm-03","collectionLabel":"MED · MED CLM 03","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 03","subtopic":"","stem":"Mulher negra de 24 anos, casada há um ano, procurou pela primeira vez a unidade de\nsaúde ambulatorial para uma consulta clínica,\npor apresentar atraso menstrual de três semanas. O\nmédico avaliou a paciente e, ao exame físico, verificou PA = 140 x 88 mmHg, utilizando-se\nmanguito convencional, e MC = 33 kg/m2. Foi diagnosticada hipertensão arterial e, por isso, o\nmédico prescreveu captopril 25 mg, três vezes ao dia. Considerando o diagnóstico, pode-se afirmar\nque ele está:","options":{"A":"Correto e a conduta deveria ser orientar sobre medidas de modificação de estilo de vida.","B":"Correto e deveria ser recomendada como droga de escolha o enalapril pela facilidade\nposológica.","C":"Incorreto e deveria ser recomendada como droga de escolha a hidroclorotiazida pelo fato de a\npaciente ser negra.","D":"Incorreto e a conduta deveria ser orientar sobre medidas de modificação de estilo de vida.","E":"Correto e a conduta adequada seria trocar o captopril por metildopa."},"answer":"A","source":"Clinica médica/MED CLM 03/MED CLM 03.txt","sourceLabel":"MED · MED CLM 03","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 03","MED"],"answerSource":"inferred","commentDeferred":true},{"id":"med-clinica-medica-med-clm-03-305040","number":"305040","sourceNumber":"305040","collectionBlock":"med:med-clinica-medica-med-clm-03","collectionLabel":"MED · MED CLM 03","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 03","subtopic":"","stem":"Considere um paciente, sexo masculino, 13 anos de idade, estatura no percentil 50 e\npeso em excesso (IMC percentil 90)\nacompanhado há dois anos.Aaferição da PA, nas últimas três\nocasiões, mostrou os valores a seguir. 1. 126 x 84 mmHg; 2. 130 x 84 mmHg; 3. 128 x 80 mmHg. O\nadolescente é assintomático e tem antecedentes familiares de hipertensão arterial (pai e avós\npaternos). Sabe-se que os valores normais da tabela de PA são: P50 = 108 x 62 mmHg; P90 = 121\nx 75 mmHg; P95 = 125 x 78 mmHg. Nesse contexto, é correto afirmar:","options":{"A":"O adolescente tem diagnóstico de pré-hipertensão arterial e o tratamento medicamentoso deve\nser instituído o mais breve possível.","B":"O adolescente deve ser investigado com relação a possível acometimento de órgãos-alvo\n(exame de fundo de olho, ecocardiograma,\nalbuminúria).","C":"A etiologia da hipertensão arterial deve ser pesquisada com dosagens de renina sérica e\nultrassom de artérias renais com Doppler.","D":"O paciente não precisa ser acompanhado quanto à sua pressão arterial porque não será\nnecessário o uso de medicamentos."},"answer":"B","source":"Clinica médica/MED CLM 03/MED CLM 03.txt","sourceLabel":"MED · MED CLM 03","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-03-257339","number":"257339","sourceNumber":"257339","collectionBlock":"med:med-clinica-medica-med-clm-03","collectionLabel":"MED · MED CLM 03","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 03","subtopic":"","stem":"Homem de 57 anos realiza exame periódico de saúde com seu clínico. É portador de\nHipertensão Arterial Sistêmica (HAS) há 22 anos e diabetes mellitus tipo 2 há 2 anos. Faz uso\nregular de anlodipino 10 mg, 1 vez ao dia, e metformina 1.000 mg, 1 vez ao dia. Não possui\nqueixas ou outras comorbidades. O exame físico não apresenta anormalidades. Traz resultado de\npesquisa de sangue oculto nas fezes, que resultou positivo em 1 de 3 amostras. Assinale a\nalternativa que apresenta o exame que NÃO está indicado para o rastreio das lesões de órgão-alvo\nda HAS nesse paciente.","options":{"A":"Ecocardiograma.","B":"Eletrocardiograma.","C":"Exame do fundo de olho.","D":"Relação albumina-creatinina na amostra de urina."},"answer":"A","source":"Clinica médica/MED CLM 03/MED CLM 03.txt","sourceLabel":"MED · MED CLM 03","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-03-283893","number":"283893","sourceNumber":"283893","collectionBlock":"med:med-clinica-medica-med-clm-03","collectionLabel":"MED · MED CLM 03","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 03","subtopic":"","stem":"Em relação ao uso de estatinas, assinale a alternativa INCORRETA.","options":{"A":"Indicado para pacientes com doença clínica aterosclerótica.","B":"Indicado para indivíduos assintomáticos com LDL-colesterol ? 190 mg/dL.","C":"Indicado para indivíduos assintomáticos com risco calculado de mortalidade por doença\ncardiovascular ? 3% em 10 anos.","D":"Indicado para pacientes diabéticos entre 40-75 anos.","E":"Indicado como profilaxia secundária da cardiopatia isquêmica."},"answer":"C","source":"Clinica médica/MED CLM 03/MED CLM 03.txt","sourceLabel":"MED · MED CLM 03","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-03-287863","number":"287863","sourceNumber":"287863","collectionBlock":"med:med-clinica-medica-med-clm-03","collectionLabel":"MED · MED CLM 03","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 03","subtopic":"","stem":"A estratificação do risco cardiovascular, por parte do Médico, faz parte da avaliação de\ntodo paciente hipertenso que se apresente em consulta médica. Assinalar a alternativa que\napresenta um fator que influencia o risco cardiovascular global em pacientes com hipertensão:","options":{"A":"Sexo feminino.","B":"Taxa de filtração glomerular > 60mL/min/1,73m².","C":"Índice tornozelo-braquial igual a 1,0.","D":"Diabetes mellitus.","E":"Sexo masculino, idade 45 anos."},"answer":"D","source":"Clinica médica/MED CLM 03/MED CLM 03.txt","sourceLabel":"MED · MED CLM 03","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-03-287352","number":"287352","sourceNumber":"287352","collectionBlock":"med:med-clinica-medica-med-clm-03","collectionLabel":"MED · MED CLM 03","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 03","subtopic":"","stem":"Pré-adolescente, 10 anos, apresenta pressão arterial alterada (aferida 03 vezes, em\nintervalos de 02 a 03 semanas cada) e IMC (Índice de Massa Corpórea) acima do P95.\n\nCorrelacionado com sua altura e peso, evidenciou-se que todas as aferições da pressão arterial\nestavam superiores ao P95. Pai e mãe apresentam obesidade. Qual o provável diagnóstico e\norientações?","options":{"A":"Hipertensão arterial essencial. Deve ser orientado perda de peso, atividade física e tratamento\nmedicamentoso até nova avaliação.","B":"Hipertensão arterial secundária a lesão reno-vascular. Deve ser solicitado Ultrassonografia de\nartérias renais.","C":"Hipertensão arterial secundária a alterações endocrinológicas. Encaminhar ao Endocrinologista.","D":"Não há necessidade de se preocupar. Aguardar o estirão puberal que haverá normalização da\npressão arterial."},"answer":"A","source":"Clinica médica/MED CLM 03/MED CLM 03.txt","sourceLabel":"MED · MED CLM 03","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-03-246348","number":"246348","sourceNumber":"246348","collectionBlock":"med:med-clinica-medica-med-clm-03","collectionLabel":"MED · MED CLM 03","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 03","subtopic":"","stem":"Homem, negro, 60 anos, chega para reavaliação após consulta médica realizada há 2\nmeses, em que apresentou pressão arterial = 166/98mmHg. Ao examinar o paciente você identifica\npressão arterial = 160/100mmHg. Qual seria o tratamento mais adequado para este paciente, neste\nmomento?","options":{"A":"Iniciar hidroclorotiazida 25mg/dia associada a anlodipino 5mg/dia","B":"Iniciar Losartan 50mg/dia associada a hidralazina 50mg de 12 em 12 horas","C":"Iniciar hidroclorotiazida 25mg/dia","D":"Iniciar atenolol 50mg/dia"},"answer":"A","source":"Clinica médica/MED CLM 03/MED CLM 03.txt","sourceLabel":"MED · MED CLM 03","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-03-246718","number":"246718","sourceNumber":"246718","collectionBlock":"med:med-clinica-medica-med-clm-03","collectionLabel":"MED · MED CLM 03","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 03","subtopic":"","stem":"Em pacientes que já sofreram um infarto do miocárdio previamente, o nível de LDL que\ndevemos perseguir, segundo as mais recentes\ndiretrizes de prevenção secundária, para reduzirmos\na chance de novo evento adverso em coronárias, é:","options":{"A":"LDL menor que 30 mg/dl","B":"LDL menor que 50 mg/dl","C":"LDL menor que 70 mg/dl","D":"LDL menor que 90 mg/dl","E":"LDL menor que 100 mg/dl"},"answer":"B","source":"Clinica médica/MED CLM 03/MED CLM 03.txt","sourceLabel":"MED · MED CLM 03","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-03-227247","number":"227247","sourceNumber":"227247","collectionBlock":"med:med-clinica-medica-med-clm-03","collectionLabel":"MED · MED CLM 03","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 03","subtopic":"","stem":"Mulher de 65 anos, hipertensa, obesa, deu entrada no Pronto Atendimento com cefaleia\nintensa, parestesias em membro superior direito e disartria. Ao exame apresentava pressão arterial\nde 232/145mmHg, ritmo cardíaco regular, discreto papiledema bilateral, glicemia capilar de 144\nmg/dL. O tratamento inicial desta paciente deve ser:","options":{"A":"Hidralazina em infusão venosa.","B":"Nitruprussiado em infusão venosa.","C":"Inibidor da enzima conversora da angiotensina por via sublingual.","D":"Diurético de alça por via endovenosa."},"answer":"B","source":"Clinica médica/MED CLM 03/MED CLM 03.txt","sourceLabel":"MED · MED CLM 03","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-03-232134","number":"232134","sourceNumber":"232134","collectionBlock":"med:med-clinica-medica-med-clm-03","collectionLabel":"MED · MED CLM 03","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 03","subtopic":"","stem":"Paciente masculino de 32 anos de idade, negro, com diagnóstico de hipertensão aos 22\nanos. Em uso de enalapril 20 mg duas vezes por dia, hidroclorotiazida 25 mg uma vez por dia e\nanlodipino 10 mg uma vez por dia. Retorna para consulta ambulatorial com exames\ncomplementares. Creatinina = 1,0 mg/dl; ureia = 38 mg/dl; sódio = 138 mEq/L; potássio = 3,2\nmEq/L; bicarbonato = 32 mEq/L. Ultrassonografia de vias urinárias normal. O diagnóstico mais\nprovável é:","options":{"A":"Feocromocitoma.","B":"Coarctação da aorta.","C":"Estenose de artéria renal bilateral.","D":"Hiperaldosteronismo primário.","E":"Hipertensão arterial primaria."},"answer":"D","source":"Clinica médica/MED CLM 03/MED CLM 03.txt","sourceLabel":"MED · MED CLM 03","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-03-232142","number":"232142","sourceNumber":"232142","collectionBlock":"med:med-clinica-medica-med-clm-03","collectionLabel":"MED · MED CLM 03","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 03","subtopic":"","stem":"Adolescente de 18 anos procura serviço médico por quadro de cansaço aos esforços,\nsem outras queixas. Nega emagrecimento, febre,\ntosse ou edema. Ao exame físico, observado\nsopro contínuo suave em região infraclavicular esquerda, irradiando para região infraescapular do\nmesmo lado. Ictus discretamente desviado para esquerda, ausência de turgência jugular. Pressão\narterial no braço esquerdo de 144 x 88 mmHg e no braço direito de 142 x 86 mmHg. Pulsos radiais\namplos e simétricos. Pulsos femorais presentes, embora com amplitude diminuída. Qual o principal\ndiagnóstico diferencial para o caso?","options":{"A":"Estenose mitral.","B":"Transposição de grandes artérias.","C":"Coarctação de aorta pós-ductal.","D":"Membrana subaórtica.","E":"Comunicação interatrial."},"answer":"C","source":"Clinica médica/MED CLM 03/MED CLM 03.txt","sourceLabel":"MED · MED CLM 03","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-03-255660","number":"255660","sourceNumber":"255660","collectionBlock":"med:med-clinica-medica-med-clm-03","collectionLabel":"MED · MED CLM 03","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 03","subtopic":"","stem":"Principal causa de morte nos pacientes adultos hipertensos? MARQUE A CORRETA:","options":{"A":"Doença cardíaca.","B":"Doença renal primária.","C":"Acidente Vascular Encefálico (AVE).","D":"Doença arterial periférica."},"answer":"A","source":"Clinica médica/MED CLM 03/MED CLM 03.txt","sourceLabel":"MED · MED CLM 03","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-03-243037","number":"243037","sourceNumber":"243037","collectionBlock":"med:med-clinica-medica-med-clm-03","collectionLabel":"MED · MED CLM 03","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 03","subtopic":"","stem":"Paciente branca, de 25 anos apresenta hipertensão arterial severa de início recente.\nExames revelam uréia e creatinina normais,\npotássio sérico baixo (3,0mEq/L) e EAS normal. Ao\nexame presença de sopro abdominal. Ultra-sonografia mostra rins de aspecto normal, porém com\nassimetria, medindo o direito 11,8cm e o esquerdo 9,8cm. A etiologia mais provável da hipertensão\narterial é:","options":{"A":"feocromocitoma.","B":"estenose da arteria renal.","C":"glomerulonefrite crônica.","D":"hiperaldosteronismo primário.","E":"hipertensão arterial essencial ou primária."},"answer":"B","source":"Clinica médica/MED CLM 03/MED CLM 03.txt","sourceLabel":"MED · MED CLM 03","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-03-243068","number":"243068","sourceNumber":"243068","collectionBlock":"med:med-clinica-medica-med-clm-03","collectionLabel":"MED · MED CLM 03","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 03","subtopic":"","stem":"Paciente do sexo feminino, 67 anos, portadora de angina aos grandes esforços há 2\nanos. Apresenta hipertensão arterial (diagnosticada há 15 anos) e diabetes melito tipo 2 (há 10\nanos). Ao exame físico, apresenta pressão arterial (PA) = 150 x 90 mmHg; frequência cardíaca\n(FC) = 78 bpm. Dentre os exames laboratoriais, apresenta LDL colesterol de 100 mg/dL. Relata\nestar em uso de metformina XR 1.500 mg/dia e clortalidona12,5 mg/dia. Qual a melhor associação\nmedicamentosa na continuidade do tratamento desta paciente?","options":{"A":"ácido acetilsalicílico (AAS), ivabradina, estatina potente em dose alta e inibidor da enzima\nconversora da angiotensina.","B":"ácido acetilsalicílico (AAS), betabloqueador, estatina potente em dose alta e inibidor da enzima\nconversora da angiotensina.","C":"ácido acetilsalicílico (AAS), trimetazidina, estatina em dose baixa e bloqueador do receptor AT1\nda angiotensina II.","D":"clopidogrel, antagonista dos canais de cálcio, estatina potente em dose moderada e bloqueador\ndo receptor AT1 da angiotensina II.","E":"ticagrelor, ivabradina, estatina potente em dose alta e inibidor da enzima conversora da\nangiotensina."},"answer":"B","source":"Clinica médica/MED CLM 03/MED CLM 03.txt","sourceLabel":"MED · MED CLM 03","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-03-243073","number":"243073","sourceNumber":"243073","collectionBlock":"med:med-clinica-medica-med-clm-03","collectionLabel":"MED · MED CLM 03","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 03","subtopic":"","stem":"Dentre as opções abaixo, a que contém recomendações corretas para o tratamento da\nhipertensão arterial resistente de acordo com a 7a Diretriz Brasileira de Hipertensão Arterial é:","options":{"A":"modificações do estilo de vida, uso de diurético de alça e betabloqueador como 4º fármaco.","B":"modificações do estilo de vida, prescrição de uma das medicações à noite e avaliação da\nadesão ao tratamento.","C":"uso da combinação de três medicações, sendo um diurético, um bloqueador dos canais de\ncálcio e espironolactona.","D":"simpatolíticos de ação central, vasodilatadores diretos ou espironolactona são igualmente\nrecomendados como 4ª opção medicamentosa.","E":"avaliação de adesão ao tratamento, uso combinado de inibidores da enzima conversora de\nangiotensina, clortalidona e bloqueador do receptor da angiotensina."},"answer":"B","source":"Clinica médica/MED CLM 03/MED CLM 03.txt","sourceLabel":"MED · MED CLM 03","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-03-220284","number":"220284","sourceNumber":"220284","collectionBlock":"med:med-clinica-medica-med-clm-03","collectionLabel":"MED · MED CLM 03","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 03","subtopic":"","stem":"Homem de 56 anos comparece à consulta periódica de saúde. É portador de\nhipertensão arterial sistêmica e gota. Faz uso\nde anlodipino 5 mg e alopurinol 100 mg ao dia há 2\nmeses. Após a introdução desses medicamentos, relata que teve 2 crises de gota e o surgimento\nde edema nos membros inferiores. Ao exame físico, PA = 145 x 86 mmHg, FC = 50 bpm, FR = 25\nirpm, SpO? = 98%. Exames respiratório, cardiovascular e abdominal sem anormalidades. Há\nedema maleolar, depressível e simétrico. Em relação ao caso descrito, assinale a alternativa que\napresenta a prescrição MAIS adequada para o tratamento da HAS:","options":{"A":"Hidroclorotiazida.","B":"Losartana.","C":"Atenolol.","D":"Anlodipino e enalapril."},"answer":"B","source":"Clinica médica/MED CLM 03/MED CLM 03.txt","sourceLabel":"MED · MED CLM 03","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-03-199553","number":"199553","sourceNumber":"199553","collectionBlock":"med:med-clinica-medica-med-clm-03","collectionLabel":"MED · MED CLM 03","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 03","subtopic":"","stem":"São fatores relacionados à hiperuricemia:","options":{"A":"Uso de diuréticos tiazídicos, doenças cardiovasculares, tabagismo.","B":"Obesidade, hipertensão arterial, dieta rica em frutos do mar.","C":"Doença renal crônica, diabetes, uso de probenecida.","D":"Abuso de álcool, sedentarismo, consumo de açúcares."},"answer":"B","source":"Clinica médica/MED CLM 03/MED CLM 03.txt","sourceLabel":"MED · MED CLM 03","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-03-199578","number":"199578","sourceNumber":"199578","collectionBlock":"med:med-clinica-medica-med-clm-03","collectionLabel":"MED · MED CLM 03","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 03","subtopic":"","stem":"L.M.L., feminina, 53 anos, apresentou há cerca de 3 horas quadro de cefaleia\nholocraniana intensa, mal-estar, com confusão\nmental e distúrbios visuais. No pronto atendimento\nfez uma crise convulsiva tônico-clônica generalizada. A pressão arterial encontrava-se em 220 x\n140 mmHg; frequência cardíaca = 90 bpm; frequência respiratória = 20 irpm, murmúrio vesicular\nfisiológico, sem ruídos adventícios. O exame neurológico foi normal e no fundo de olho tem\npapiledema; a glicemia capilar foi de 125 mg/dl e não havia história de uso de drogas ilícitas ou\nuso\nde medicamentos anteriores. Qual a conduta apropriada?","options":{"A":"Iniciar nitroprussiato de sódio endovenoso.","B":"Iniciar betabloqueador oral.","C":"Prescrever furosemida por via endovenosa.","D":"Prescrever captopril sublingual."},"answer":"A","source":"Clinica médica/MED CLM 03/MED CLM 03.txt","sourceLabel":"MED · MED CLM 03","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-03-202768","number":"202768","sourceNumber":"202768","collectionBlock":"med:med-clinica-medica-med-clm-03","collectionLabel":"MED · MED CLM 03","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 03","subtopic":"","stem":"Homem, 70 anos, vem ao consultório para um retorno de check-up. É diabético,\nassintomático do ponto de vista\ncardiovascular, e não possui alterações ao exame físico. Traz entre\nos exames solicitados na primeira consulta, os seguintes: HDL 45 mg/ dL; LDL 108 mg/ dL;\ntriglicerídeos 330 mg/ dL; colesterol total 209 mg/ dL; hemoglobina glicada 6,6%; glicemia de jejum\n120 mg/ dL. Com relação ao tratamento da dislipidemia, é CORRETO afirmar:","options":{"A":"Faz-se necessária a adição de estatina para o controle da dislipidemia neste momento, além de\nmodificação no estilo de vida.","B":"A associação de genfibrozila e sinvastatina está indicada em razão dos níveis altos de\ntriglicerídeos e LDL.","C":"O tratamento da dislipidemia em idosos deve ter metas menos estritas, uma vez que essa\npopulação tem menor benefício no controle lipídico para a prevenção de doença cardiovascular.\nAssim, pode-se orientar apenas modificações do estilo de vida, além de ajustar o esquema\nhipoglicemiante.","D":"O tratamento desse paciente deve incluir estatina e niacina, visando à melhora dos níveis de\nLDL e HDL.","E":"A ezetimiba pode ser empregada nesse paciente em vez da estatina, visto que este grupo de\nfármacos provoca mais efeitos adversos nessa faixa etária."},"answer":"A","source":"Clinica médica/MED CLM 03/MED CLM 03.txt","sourceLabel":"MED · MED CLM 03","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-03-196746","number":"196746","sourceNumber":"196746","collectionBlock":"med:med-clinica-medica-med-clm-03","collectionLabel":"MED · MED CLM 03","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 03","subtopic":"","stem":"Paciente de 8 anos de idade foi levado à sua terceira consulta pediátrica para avaliação\nde possíveis consequências do excesso de peso.\nAvaliou-se a terceira aferição de pressão arterial\ndo menino com valor semelhante aos anteriores e classificou-se conforme o último guideline de\nmanejo de hipertensão arterial da Academia Americana de Pediatria, conforme dados a seguir e\ntabela abaixo. Marque o diagnóstico para o caso: E/I: percentil 75; pressão arterial: 114/70 mmHg.","options":{"A":"Hipertensão arterial estádio I.","B":"Hipertensão arterial estádio II.","C":"Pressão arterial elevada.","D":"Pré-hipertensão."},"answer":"C","source":"Clinica médica/MED CLM 03/MED CLM 03.txt","sourceLabel":"MED · MED CLM 03","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-03-196803","number":"196803","sourceNumber":"196803","collectionBlock":"med:med-clinica-medica-med-clm-03","collectionLabel":"MED · MED CLM 03","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 03","subtopic":"","stem":"A Hipertensão arterial sistêmica (HAS) por ser um fator de risco a longo prazo para\ndoenças cardiovasculares. O profissional que atua\nem medicina ambulatorial pode falha em iniciar\nou intensificar uma terapia para HAS quando necessária. Como se chama este fenômeno? Marque\na CORRETA:","options":{"A":"Indefinição terapêutica","B":"Inércia clínica","C":"Procrastinação referencial","D":"Intervenção retardada"},"answer":"B","source":"Clinica médica/MED CLM 03/MED CLM 03.txt","sourceLabel":"MED · MED CLM 03","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-03-196810","number":"196810","sourceNumber":"196810","collectionBlock":"med:med-clinica-medica-med-clm-03","collectionLabel":"MED · MED CLM 03","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 03","subtopic":"","stem":"Homem negro, de 45 anos, com diagnóstico recente de hipertensão arterial, com\ndiversas medidas de PA, em geral em torno de 160/100 mmHg a 170/110 mmHg. Sem\ncomorbidades. Assinale o tratametno farmacológico recomendado","options":{"A":"Losartan + Hidroclorotiazida.","B":"Anlodipina + Enalapril.","C":"Captopril + Hidroclorotiazida","D":"Anlodipina + Clortalidona."},"answer":"D","source":"Clinica médica/MED CLM 03/MED CLM 03.txt","sourceLabel":"MED · MED CLM 03","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-03-172818","number":"172818","sourceNumber":"172818","collectionBlock":"med:med-clinica-medica-med-clm-03","collectionLabel":"MED · MED CLM 03","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 03","subtopic":"","stem":"A principal causa da hipertensão renovascular é:","options":{"A":"Aterosclerose de artéria renal.","B":"Displasia fibromuscular.","C":"Arterite de Takayasu.","D":"Dissecção da aorta."},"answer":"A","source":"Clinica médica/MED CLM 03/MED CLM 03.txt","sourceLabel":"MED · MED CLM 03","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-03-174375","number":"174375","sourceNumber":"174375","collectionBlock":"med:med-clinica-medica-med-clm-03","collectionLabel":"MED · MED CLM 03","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 03","subtopic":"","stem":"No manejo medicamentoso dos pacientes de alto risco cardiovascular, segundo a\nDiretriz de Dislipidemia da Sociedade Brasileira de Cardiologia de 2017, as metas de LDL-c a\nserem atingidas e a estatina/dose diária a ser utilizada são, respectivamente:","options":{"A":"LDL-c < 70 mg/ dL, utilizar Sinvastatina/40 mg por dia.","B":"LDL-c < 50 mg/ dL, utilizar Rosuvastatina/40 mg por dia.","C":"LDL-c < 50 mg/ dL, utilizar Rosuvastatina/20 mg por dia.","D":"LDL-c < 70 mg/ dL, utilizar Rosuvastatina/20 mg por dia.","E":"LDL-c < 70 mg/ dL, utilizar Sinvastatina 20 mg + Ezetimiba 10 mg/dia."},"answer":"D","source":"Clinica médica/MED CLM 03/MED CLM 03.txt","sourceLabel":"MED · MED CLM 03","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-03-148546","number":"148546","sourceNumber":"148546","collectionBlock":"med:med-clinica-medica-med-clm-03","collectionLabel":"MED · MED CLM 03","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 03","subtopic":"","stem":"Paciente masculino, 35 anos, pardo, procura a unidade de saúde queixando-se de\nepistaxe frequente, cefaleia occipital e\nmal-estar. Encontra-se com vários problemas de\nrelacionamento na família e no emprego. Na história familiar, relata mãe hipertensa, diabética e\ndislipidêmica; pai com doença coronariana e hipotireoidismo. A pressão arterial aferida com o\npaciente deitado foi de 150 x 110 mmHg. No prontuário da unidade de saúde, já havia outros três\natendimentos com a pressão arterial sistólica acima de 140 e a pressão arterial diastólica acima de\n100 mmHg. Foi definido por tratamento medicamentoso para hipertensão arterial. Assinale a\nafirmativa INCORRETA quanto ao tratamento medicamentoso de hipertensão arterial:","options":{"A":"A ação dos diuréticos em reduzir a resistência vascular periférica no tratamento da hipertensão\narterial ocorre cerca de 4 a 6 semanas após o\ninício de uso.","B":"O mecanismo de ação dos betabloqueadores no tratamento da hipertensão arterial envolve a\ndiminuição do débito cardíaco, redução da secreção de renina, readaptação de barorreceptores e\ndiminuição das catecolaminas nas sinapses nervosas.","C":"Os betabloqueadores são eficazes na redução da pressão arterial, mas a redução de morbidade\ne mortalidade por eventos cardiovasculares somente\nsão encontrados em menores de 60 anos.","D":"Hidralazina e minoxidil não devem ser usados com diuréticos, pois a diminuição da resistência\nperiférica ocorre somente quando utilizados isoladamente.","E":"Os inibidores de enzima conversora da angiotensina, quando administrados em longo prazo,\nretardam o declínio da função renal em pacientes com nefropatia diabética."},"answer":"D","source":"Clinica médica/MED CLM 03/MED CLM 03.txt","sourceLabel":"MED · MED CLM 03","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-03-148612","number":"148612","sourceNumber":"148612","collectionBlock":"med:med-clinica-medica-med-clm-03","collectionLabel":"MED · MED CLM 03","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 03","subtopic":"","stem":"Paciente de 18 anos, em consulta com seu médico de família e comunidade, apresenta\nPA = 132 x 86 mmHg e IMC = 29 kg/m². Qual o\nintervalo de rastreamento ambulatorial de\nhipertensão arterial sistêmica para este paciente?","options":{"A":"Trimestral.","B":"Semestral.","C":"Anual.","D":"Bianual.","E":"Quinquenal."},"answer":"E","source":"Clinica médica/MED CLM 03/MED CLM 03.txt","sourceLabel":"MED · MED CLM 03","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 03","MED"],"answerSource":"inferred","commentDeferred":true},{"id":"med-clinica-medica-med-clm-03-162547","number":"162547","sourceNumber":"162547","collectionBlock":"med:med-clinica-medica-med-clm-03","collectionLabel":"MED · MED CLM 03","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 03","subtopic":"","stem":"Sobre a hipertensão arterial na infância, é CORRETO afirmar que:","options":{"A":"Não há relação entre obesidade e hipertensão arterial em crianças.","B":"No lactente e pré-escolar, a hipertensão arterial essencial primária é a etiologia mais\nfrequente.","C":"Crianças com 3 anos de idade ou mais devem ter sua pressão arterial aferida durante cada\nepisódio de cuidado de saúde.","D":"Coarctação de aorta não é uma causa de hipertensão arterial na infância.","E":"É indicado tratamento farmacológico em todos os casos de hipertensão arterial na infância."},"answer":"E","source":"Clinica médica/MED CLM 03/MED CLM 03.txt","sourceLabel":"MED · MED CLM 03","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-03-126897","number":"126897","sourceNumber":"126897","collectionBlock":"med:med-clinica-medica-med-clm-03","collectionLabel":"MED · MED CLM 03","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 03","subtopic":"","stem":"MCR, 48 anos, procura atendimento em consultório para realização de exames de\nrotina. Apresenta exames recentes com glicemia\nde jejum, função renal e perfil lipídico sem\nalterações. O exame físico era normal com exceção dos níveis pressóricos elevados (PA:\n160/102mmHg). Considerando o caso descrito, assinale a alternativa que apresenta a droga que\nNÃO deve ser usada de rotina, como primeira escolha no início da terapia medicamentosa desse\npaciente.","options":{"A":"Valsartana.","B":"Lisinopril.","C":"Clortalidona.","D":"Clonidina."},"answer":"D","source":"Clinica médica/MED CLM 03/MED CLM 03.txt","sourceLabel":"MED · MED CLM 03","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-03-100949","number":"100949","sourceNumber":"100949","collectionBlock":"med:med-clinica-medica-med-clm-03","collectionLabel":"MED · MED CLM 03","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 03","subtopic":"","stem":"Uma criança de 9 anos foi atendida em consulta de rotina. Após três mensurações da\npressão arterial e após consultar as tabelas\nreferenciais para a pressão arterial em crianças e\nadolescentes, o pediatra informa que a criança está hipertensa. Sobre esta situação, qual afirmativa\nestá CORRETA?","options":{"A":"As tabelas referenciais são baseadas nas variáveis sexo, idade e percentis de peso.","B":"O ponto de corte para considerar hipertensão em escolares é 120 x 80 mmHg.","C":"A hipertensão arterial em pediatria pode ser primária ou secundária.","D":"A hipertensão primária em adolescentes é geralmente sintomática.","E":"A terapêutica farmacológica está sempre indicada."},"answer":"C","source":"Clinica médica/MED CLM 03/MED CLM 03.txt","sourceLabel":"MED · MED CLM 03","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-03-77360","number":"77360","sourceNumber":"77360","collectionBlock":"med:med-clinica-medica-med-clm-03","collectionLabel":"MED · MED CLM 03","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 03","subtopic":"","stem":"A cirurgia bariátrica para o tratamento da obesidade:","options":{"A":"É considerada um procedimento médico experimental não validado para o tratamento de\nportadores de obesidade mórbida.","B":"A gastrectomia vertical é a técnica mais antiga e a mais usada no Brasil e no Mundo.","C":"Obteve melhor resultado no controle glicêmico de pacientes severamente obesos com diabetes\ntipo 2 do que a terapia médica convencional,\nconforme estudo publicado recentemente pela New\nEngland Journal of Medicine.","D":"Todas as técnicas e tipos de cirurgia levam ao emagrecimento apenas por um mecanismo\nrestritivo, ou seja, por diminuição da\ncapacidade de alimentos que o estômago é capaz de suportar.","E":"Os pacientes que mais se beneficiam da cirurgia são os portadores de distúrbios psiquiátricos,\npois estes não conseguem compreender e realizar\nas dietas e exercícios convencionais\nnecessários à perda de peso natural."},"answer":"C","source":"Clinica médica/MED CLM 03/MED CLM 03.txt","sourceLabel":"MED · MED CLM 03","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-03-59012","number":"59012","sourceNumber":"59012","collectionBlock":"med:med-clinica-medica-med-clm-03","collectionLabel":"MED · MED CLM 03","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 03","subtopic":"","stem":"Em relação ao tratamento farmacológico no idoso hipertenso, está correto afirmar,\nEXCETO:","options":{"A":"O tratamento farmacológico é menos efetivo no idoso que em pacientes mais jovens, gerando\nmenor redução de eventos cérebro e\ncardiovasculares.","B":"O controle da pressão arterial diastólica não deve ser feito abaixo de 70 mmHg, especialmente\nem pacientes com hipertensão arterial sistólica\nacima de 80 anos e portadores de doença arterial\ncoronariana.","C":"Existe evidência científica suficiente para indicar o tratamento farmacológico do idoso\nhipertenso\ncom faixa etária igual ou superior a 80\nanos.","D":"A maioria dos idosos com hipertensão estágio 3 não alcança suas metas de pressão arterial com\nmonoterapia e requer dois ou mais medicamentos de classes diferentes.","E":"Em relação ao uso de tiazídicos, são efetivos e reduzem eventos cérebro e cardiovasculares,\nporém devem ser utilizados com cautela devido às\ncomorbidades (prostatismo, insuficiência renal,\ndislipidemia e hiperuricemia)."},"answer":"A","source":"Clinica médica/MED CLM 03/MED CLM 03.txt","sourceLabel":"MED · MED CLM 03","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-03-59464","number":"59464","sourceNumber":"59464","collectionBlock":"med:med-clinica-medica-med-clm-03","collectionLabel":"MED · MED CLM 03","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 03","subtopic":"","stem":"Paciente 39 anos, obesa, tabagista (20 cigarros/dia há 4 anos), sem outras\ncomorbidades prévias, dá entrada em um\npronto-socorro em Niterói-RJ, com quadro de dispneia e\ndesconforto precordial que descreve como \"angústia\", iniciados há cerca de 20 minutos da\nadmissão ao hospital, após problema familiar grave (prisão de seu irmão). Apresentava ainda\nhistória de hipermenorreia. É atendida por seu colega de plantão, que assim descreve o exame\nfísico em prontuário: \"Paciente agitada, com dificuldade de manter-se deitada no leito, sendo\ncontida por terceiros, acianótica, anictérica, sem edemas, corada, hidratada. RCR 2t FC 140 bpm,\nPA 200 x 100 mmHg. Taquipneica, com FR 40, sem tiragem intercostal e sem batimento de aleta\nnasal. Sons pulmonares normais. Abdome livre e peristáltico\". Seu colega de plantão solicita\nimediatamente na chegada ao hospital os exames abaixo: Hemograma: Hb 7,8 VCM 60 Leucócitos\n7000 Plaquetas 200000; Gasometria arterial: pH 7,52 PCO2 20 PO2 110 Gradiente alveoloarterial\nde O2 10, restante normal; CK total de 500 (Normal < 200); CKMB 15 (N < 25); restante da\nbioquímica sem alterações; RX de tórax sem alterações; ECG (VER IMAGEM). Diante do exposto\nvocê o ajuda a elaborar o seguinte diagnóstico inicial:","options":{"A":"Provável Crise Hipertensiva do tipo emergência hipertensiva; Hipertensão arterial + Infarto\nAgudo do Miocárdio (IAM) com supra ST em\nparede inferior. Internação em CTI, controle de HAS\ncom Nitroprussiato e medidas para IAM.","B":"Provável Crise Hipertensiva do tipo emergência hipertensiva: Hipertensão arterial + Angina\nInstável (AI). Internação em Unidade de Dor\ntorácica, controle de HAS com Nitroglicerina, dosagem\nimediata de troponina e medidas para AI.","C":"Provável Crise Hipertensiva do tipo emergência hipertensiva: Hipertensão arterial + Infarto\nagudo do Miocárdio (IAM) sem supra de ST.\nInternação em CTI, controle de HAS com Nitroglicerina\ne medidas para IAM sem supra.","D":"Provável Crise Hipertensiva do tipo urgência hipertensiva: Hipertensão arterial + Desconforto\nprecordial a esclarecer. Internação em Unidade\nde dor torácica, controle de HAS com Captopril via\nsublingual, dosagem imediata de troponina.","E":"Provável pseudocrise hipertensiva: Hipertensão arterial em paciente com crise de ansiedade tipo\nSíndrome do Pânico. Medicações para controle de ansiedade, reavaliar paciente e pressão arterial\nperiodicamente."},"answer":"E","source":"Clinica médica/MED CLM 03/MED CLM 03.txt","sourceLabel":"MED · MED CLM 03","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-03-44009","number":"44009","sourceNumber":"44009","collectionBlock":"med:med-clinica-medica-med-clm-03","collectionLabel":"MED · MED CLM 03","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 03","subtopic":"","stem":"Lucas, 09 anos, tem IMC acima do escores +3 e apresenta 4 medidas consecutivas de\npressão arterial (intervalos de 2 a 3 semanas cada) alteradas. Nada mais foi evidenciado em seu\nexame clínico. Correlacionando com sua altura, evidenciou-se que todas as aferições da pressão\narterial estavam superiores ao P95. História familiar de obesidade em ambos os pais. Qual a\nconduta preferencial a ser adotada?","options":{"A":"Orientar perda de peso, realizar investigação diagnóstica para esclarecimento e avaliar\ntratamento farmacológico.","B":"Aguardar estirão puberal, realizar investigação diagnóstica para esclarecimento e avaliar\ntratamento farmacológico.","C":"Realizar investigação diagnóstica para esclarecimento e avaliar tratamento farmacológico, já que\na história familiar não auxiliaria a\ntentativa de perda ponderal.","D":"Orientar a perda de peso, realizar investigação diagnóstica para esclarecimento, mas só pode\nser iniciado o tratamento farmacológico após os\n12 anos.","E":"Realizar investigação diagnóstica para esclarecimento e avaliar tratamento psicológico para toda\na família."},"answer":"E","source":"Clinica médica/MED CLM 03/MED CLM 03.txt","sourceLabel":"MED · MED CLM 03","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-03-32475","number":"32475","sourceNumber":"32475","collectionBlock":"med:med-clinica-medica-med-clm-03","collectionLabel":"MED · MED CLM 03","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 03","subtopic":"","stem":"A Síndrome de Apneia-Hipopneia Obstrutiva do Sono é considerada fator de risco\nindependente para:","options":{"A":"DPOC.","B":"Sinusopatia.","C":"Hipertensão Arterial Sistêmica.","D":"Asma Brônquica.","E":"Pneumonia."},"answer":"C","source":"Clinica médica/MED CLM 03/MED CLM 03.txt","sourceLabel":"MED · MED CLM 03","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-03-27397","number":"27397","sourceNumber":"27397","collectionBlock":"med:med-clinica-medica-med-clm-03","collectionLabel":"MED · MED CLM 03","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 03","subtopic":"","stem":"Paciente 67 anos de idade, deu entrada no PS com pressão arterial 165/100 mmHg\nqueixando-se de cefaleia, tosse seca noturna e agitação . Relata que na noite anterior fez uso\nabusivo do sal e tomou um captopril a mais. Hipertenso de longa data, faz uso regular da\nmedicação anti-hipertensiva (captopril 25 mg 3 x dia + hidroclorotiazida 25 mg cedo). Nega dibetes,\nnega dislipidemia, Peso 74kg e 173cm. De acordo com estes dados qual a sua conduta?","options":{"A":"Orientar uma dieta saudável, diminuir quantidade de sal, estimular atividade física e aumentar a\ndosagem do captopril para 50 mg 3 x dia.","B":"Orientar a dieta DASCH, diminuir quantidade de sal estimular atividade física, manter o inibidor\nde ECA e trocar o diurético por um\nbeta-bloqueador.","C":"Orientar a dieta DASCH, estimular atividade física e aumentar a dosagem do diurético com o\nintuito de reduzir o excesso de liquido mediado pela maior absorção de água devido ao excesso de\nsal.","D":"Orientar uma dieta saudável, diminuir quantidade de sal, estimular atividade física e trocar o\nInibidor de ECA por um Bloqueador do receptor AT1.","E":"Oriento apenas a diminuição do Sal e manutenção da pressão arterial."},"answer":"D","source":"Clinica médica/MED CLM 03/MED CLM 03.txt","sourceLabel":"MED · MED CLM 03","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-03-23161","number":"23161","sourceNumber":"23161","collectionBlock":"med:med-clinica-medica-med-clm-03","collectionLabel":"MED · MED CLM 03","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 03","subtopic":"","stem":"Adolescente de 11 anos, sexo masculino, é atendido em consulta de rotina com os\nseguintes parâmetros: peso = 60 Kg (acima do\npercentil 97), estatura de 145cm (percentil 50),\npressão arterial de 130x90 mmHg (acima do percentil 95, na tabela de níveis pressóricos por idade,\nsexo e percentil de estatura) e índice de massa corpórea (IMC) de 28,5 (acima do percentil97),\nestágio puberal G2P2 pelos critérios de Tanner. No exame da pele apresenta manchas escuras e\nespessadas em região cervical, axilas e na região medial de coxas. Quais os problemas você\nlistraria nesta história clínica?","options":{"A":"Sobrepeso, hipertensão arterial, puberdade precoce.","B":"Sobrepeso, estágio de pré-hipertensão, dermatite de contato.","C":"Obesidade, dermatite de contato, puberdade precoce, pré-hipertensão.","D":"Obesidade, hipertensão arterial, acanthosis nigricans.","E":"Obesidade, hipertensão arterial, acanthosis nigricans, puberdade precoce."},"answer":"D","source":"Clinica médica/MED CLM 03/MED CLM 03.txt","sourceLabel":"MED · MED CLM 03","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-03-9388","number":"9388","sourceNumber":"9388","collectionBlock":"med:med-clinica-medica-med-clm-03","collectionLabel":"MED · MED CLM 03","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 03","subtopic":"","stem":"Paciente de 67 anos, portador de hipertensão arterial, tem colesterol total de 280\nmg/dL, HDL 32 mg/dL, triglicerídeos 190 mg/dL e cintura 104 cm. Fez uma CT Slice-64 para\ndiagnóstico de doença coronariana. Que parecer clínico é dado ao paciente?","options":{"A":"O teste negativo para estenose coronariana nos permite excluir a possibilidade de doença\naterosclerótica coronariana.","B":"A presença de estenose não necessita confirmação por cateterismo coronariano.","C":"Trata-se de um exame com baixa especificidade e sensibilidade, sem aplicabilidade clínica.","D":"O valor preditivo negativo para estenose dos segmentos iniciais, médio e distal das artérias\ncoronárias é baixo, aproximadamente 20%.","E":"Esse teste apresenta pequena exposição à radiação, sem risco para o paciente."},"answer":"A","source":"Clinica médica/MED CLM 03/MED CLM 03.txt","sourceLabel":"MED · MED CLM 03","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-03-9392","number":"9392","sourceNumber":"9392","collectionBlock":"med:med-clinica-medica-med-clm-03","collectionLabel":"MED · MED CLM 03","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 03","subtopic":"","stem":"Em um paciente idoso com hipotensão arterial postural sintomática idiopática, qual\nmedicamento poderá ser empregado?","options":{"A":"Amiodarone.","B":"Aminofilina.","C":"Codeína.","D":"Midodrine.","E":"Cloridrato dietilefedrina."},"answer":"D","source":"Clinica médica/MED CLM 03/MED CLM 03.txt","sourceLabel":"MED · MED CLM 03","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-03-8097","number":"8097","sourceNumber":"8097","collectionBlock":"med:med-clinica-medica-med-clm-03","collectionLabel":"MED · MED CLM 03","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 03","subtopic":"","stem":"Nos estudos da hipertensão arterial essencial em crianças e adolescentes podemos\nencontrar:","options":{"A":"Níveis baixos de cálcio, obesidade e baixo peso ao nascer.","B":"Contraceptivos orais na adolescência e dieta rica em potássio.","C":"Antecedência familiar de hipertensão arterial e dieta hipossódica ou assódica.","D":"Falta de atividade física e sonambulismo.","E":"Uso abusivo de internet e cobrança excessiva na escola."},"answer":"A","source":"Clinica médica/MED CLM 03/MED CLM 03.txt","sourceLabel":"MED · MED CLM 03","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-03-362661","number":"362661","sourceNumber":"362661","collectionBlock":"med:med-clinica-medica-med-clm-03","collectionLabel":"MED · MED CLM 03","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 03","subtopic":"","stem":"Qual é a primeira linha de tratamento para hipertensão em pacientes afro-americanos\nsem diabetes?","options":{"A":"Betabloqueadores","B":"Inibidores da ECA","C":"Bloqueadores dos canais de cálcio","D":"Tiazídicos."},"answer":"D","source":"Clinica médica/MED CLM 03/MED CLM 03.txt","sourceLabel":"MED · MED CLM 03","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-03-362659","number":"362659","sourceNumber":"362659","collectionBlock":"med:med-clinica-medica-med-clm-03","collectionLabel":"MED · MED CLM 03","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 03","subtopic":"","stem":"Um paciente de 67 anos com história de asma brônquica e bloqueio AV de segundo\ngrau não tratado chega à clínica se queixando\nde palpitações frequentes. Ele foi recentemente\ndiagnosticado com hipertensão. Qual das seguintes opções Não é uma contraindicação para a\nprescrição de betabloqueadores para esse paciente?","options":{"A":"Asma brônquica.","B":"Diabetes mellitus tipo 2 bem controlado.","C":"Bloqueio AV de segundo grau.","D":"Hipercalemia."},"answer":"B","source":"Clinica médica/MED CLM 03/MED CLM 03.txt","sourceLabel":"MED · MED CLM 03","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-03-353874","number":"353874","sourceNumber":"353874","collectionBlock":"med:med-clinica-medica-med-clm-03","collectionLabel":"MED · MED CLM 03","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 03","subtopic":"","stem":"A medição adequada da pressão arterial em crianças deve seguir critérios específicos e\npode ser classificada com base em\npercentis, de acordo com a Sociedade Brasileira de Pediatria.\n\nDessa forma, é CORRETO afirmar:","options":{"A":"A medida da PA é melhor realizada com o paciente de pé para garantir uma leitura mais precisa\ne é classificada em três estágios: normal,\npré-hipertensão e hipertensão.","B":"A medida da PA é feita preferencialmente com a criança em repouso de pelo menos 5 minutos,\nsentada, com o braço direito estendido na altura do coração. A classificação da PA segue\npercentis, com hipertensão estágio 2 sendo PAS e/ou PAD ? 12 mmHg acima do p95 ou ? 140x90\nmmHg.","C":"A classificação de PA elevada corresponde a PAS e/ou PAD ? p95 e < 12 mmHg acima do p95,\nenquanto a criança está em atividade física moderada.","D":"O manguito deve possuir uma câmara interna com largura correspondente a 30% da\ncircunferência do braço e o comprimento equivalente a 90% a 110% da mesma."},"answer":"B","source":"Clinica médica/MED CLM 03/MED CLM 03.txt","sourceLabel":"MED · MED CLM 03","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-03-354839","number":"354839","sourceNumber":"354839","collectionBlock":"med:med-clinica-medica-med-clm-03","collectionLabel":"MED · MED CLM 03","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 03","subtopic":"","stem":"Durante uma consulta, o médico de familia afere a pressão arterial (PA) do seu paciente\nconforme recomendado pela Diretriz Brasileira de Hipertensão (2020). A suspeita é de que o\npaciente esteja com hipertensão, visto que o resultado da primeira medida foi de 146 x 92 mmHg\nem membro superior esquerdo (MSE). De posse dessa informação, após a primeira aferição, e para\ndefinir o diagnóstico do paciente em questão, a conduta adotada pelo médico deverá ser:","options":{"A":"aguardar pelo menos 5 minutos a partir do esvaziamento do manguito e repetir a aferição no\noutro membro, se for registrada uma diferença\nentre os braços < 10 mmHg, aferir mais uma vez no\nmembro de PA mais elevada e a PA do paciente será a média das duas últimas leituras. Se a\nmédia for qualquer valor maior ou igual a 140/90 mmHg, o paciente será considerado\n\nhipertenso nesta consulta.","B":"aguardar pelo menos 5 minutos a partir do esvaziamento do manguito, repetir a aferição no outro\nmembro, se for registrada uma diferença entre os braços < 10 mmHg, aferir mais uma vez no\nmembro de PA mais elevada e a PA do paciente será a média das duas últimas leituras. Se a\nmédia for qualquer valor maior ou igual a 140/90 mmHg, o paciente deverá ser reavaliado em nova\nconsulta para estabelecer diagnóstico.","C":"aguardar pelo menos 1 minuto a partir do esvaziamento do manguito, repetir a aferição no\nmesmo membro e a PA do paciente será a média\ndas duas leituras. Se a média for qualquer valor\nmaior ou igual a 140/90 mmHg, o paciente deverá ser reavaliado em nova consulta para\nestabelecer diagnóstico.","D":"aguardar pelo menos 1 minuto a partir do esvaziamento do manguito, repetir a aferição no outro\nmembro, se for registrada uma diferença entre os braços < 10 mmHg da PA, aferir mais uma vez no\nmembro de PA mais elevada e a PA do paciente será a média das duas últimas leituras. Se a\nmédia for qualquer valor maior ou igual 180/110 mmHg o paciente será considerado hipertenso\nnesta consulta."},"answer":"D","source":"Clinica médica/MED CLM 03/MED CLM 03.txt","sourceLabel":"MED · MED CLM 03","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-03-339764","number":"339764","sourceNumber":"339764","collectionBlock":"med:med-clinica-medica-med-clm-03","collectionLabel":"MED · MED CLM 03","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 03","subtopic":"","stem":"Um paciente diabético e hipertenso está em fase de recuperação de infarto do\nmiocárdio e apresenta um bloqueio\nátrio-ventricular do segundo grau. De outras comorbidades, ele\nrefere um passado de angioedema e gota. Qual das drogas anti- hipertensivas a seguir seria a ideal\npara esse paciente?","options":{"A":"Losartan.","B":"Enalapril.","C":"Metoprolol.","D":"Verapamil.","E":"Hidroclorotiazida."},"answer":"A","source":"Clinica médica/MED CLM 03/MED CLM 03.txt","sourceLabel":"MED · MED CLM 03","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-03-342616","number":"342616","sourceNumber":"342616","collectionBlock":"med:med-clinica-medica-med-clm-03","collectionLabel":"MED · MED CLM 03","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 03","subtopic":"","stem":"No tratamento da hipertensão arterial, a associação de inibidor da enzima conversora\nde angiotensina a bloqueador do receptor de\nangiotensina II:","options":{"A":"pode ser indicada caso o uso de um desses fármacos não tenha promovido o controle adequado\nda pressão arterial","B":"está indicada a pacientes com insuficiência cardíaca pós-infarto agudo do miocárdio","C":"está indicada a pacientes diabéticos que estejam evoluindo com perda da função renal","D":"não é recomendada, pois, além de não mostrar benefícios em desfechos cardiovasculares,\nacrescenta riscos de efeitos adversos"},"answer":"D","source":"Clinica médica/MED CLM 03/MED CLM 03.txt","sourceLabel":"MED · MED CLM 03","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-03-342617","number":"342617","sourceNumber":"342617","collectionBlock":"med:med-clinica-medica-med-clm-03","collectionLabel":"MED · MED CLM 03","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 03","subtopic":"","stem":"Homem de 49 anos procura atendimento de emergência por cefaleia. Refere história de\nrevascularização miocárdica há 1 ano e nega dor precordial. Ao exame físico apresenta PA =\n200x125mmHg sem 3' ou 4' bulha. O exame neurológico é normal. Qual é o diagnóstico mais\nprovável e qual é a melhor conduta terapêutica para o caso?","options":{"A":"emergência hipertensiva; nitroglicerina intravenosa","B":"urgência hipertensiva; hidralazina intravenosa","C":"urgência hipertensiva; nitroprussiato de sódio intravenoso e administração de analgésico","D":"urgência hipertensiva; captopril oral e administração de analgésico"},"answer":"D","source":"Clinica médica/MED CLM 03/MED CLM 03.txt","sourceLabel":"MED · MED CLM 03","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-03-337463","number":"337463","sourceNumber":"337463","collectionBlock":"med:med-clinica-medica-med-clm-03","collectionLabel":"MED · MED CLM 03","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 03","subtopic":"","stem":"Vários estudos comprovam os benefícios das terapias para a redução do colesterol em\npacientes em prevenção secundária. Sendo correto que:","options":{"A":"Nos pacientes de alto risco, o benefício não é independente dos níveis basais do LDL-C.","B":"Nos pacientes de alto risco, o benefício é dependente dos níveis basais do LDL-C.","C":"Nos pacientes de alto risco, o benefício é independente dos níveis basais do LDL-C.","D":"Nos pacientes de baixo risco, o benefício é independente dos níveis basais do LDL-C."},"answer":"C","source":"Clinica médica/MED CLM 03/MED CLM 03.txt","sourceLabel":"MED · MED CLM 03","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-03-334174","number":"334174","sourceNumber":"334174","collectionBlock":"med:med-clinica-medica-med-clm-03","collectionLabel":"MED · MED CLM 03","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 03","subtopic":"","stem":"Os ácidos graxos exercem ações distintas sobre a trigliceridemia:","options":{"A":"Por não modularem os fatores de transcrição envolvidos na síntese de enzimas lipogênicas\nenvolvidas na produção de ácidos graxos.","B":"Por modularem os fatores de transcrição nunca envolvidos na síntese de enzimas lipogênicas\nenvolvidas na produção de ácidos graxos.","C":"Por modularem os fatores de transcrição envolvidos na síntese de enzimas lipogênicas\nenvolvidas na produção de ácidos graxos.","D":"Por modularem os fatores de transcrição envolvidos na síntese de enzimas lipogênicas não\nenvolvidas na produção de ácidos graxos."},"answer":"C","source":"Clinica médica/MED CLM 03/MED CLM 03.txt","sourceLabel":"MED · MED CLM 03","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-03-315763","number":"315763","sourceNumber":"315763","collectionBlock":"med:med-clinica-medica-med-clm-03","collectionLabel":"MED · MED CLM 03","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 03","subtopic":"","stem":"Alfabloqueadores promovem maior redução pressórica quando:","options":{"A":"Na posição ortostática e nunca taquicardia reflexa. Por isso, é comum a hipotensão postural,\ncomumente descrita na primeira dose.","B":"Na posição ortostática e na taquicardia reflexa. Por isso, é comum a hipotensão postural,\ncomumente descrita na primeira dose.","C":"Na posição ortostática e na taquicardia reflexa. Por isso, é comum a hipotensão postural, nunca\ndescrita na primeira dose.","D":"Na posição ortostática e na taquicardia reflexa. Por isso, é raro a hipotensão postural."},"answer":"B","source":"Clinica médica/MED CLM 03/MED CLM 03.txt","sourceLabel":"MED · MED CLM 03","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-03-315766","number":"315766","sourceNumber":"315766","collectionBlock":"med:med-clinica-medica-med-clm-03","collectionLabel":"MED · MED CLM 03","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 03","subtopic":"","stem":"O risco de doença arterial coronariana DAC é maior em portadores de mutações\npatogênicas, se comparado àqueles sem\nmutações para qualquer valor de LDL-c., sendo correto\nque:","options":{"A":"Acima de 100 mg/dl, o risco de DAC chega a ser mais de 3 vezes maior para um mesmo nível\nde LDL-c nos portadores de mutações causais, comparado aos não portadores de mutações.","B":"Acima de 190 mg/dl, o risco de DAC chega a ser mais de 3 vezes maior para um mesmo nível\nde LDL-c nos portadores de mutações causais, comparado aos não portadores de mutações.","C":"Acima de 190 mg/dl, o risco de DAC chega a ser mais de 10 vezes maior para um mesmo nível\nde LDL-c nos portadores de mutações causais, comparado aos não portadores de mutações.","D":"Acima de 190 mg/dl, o risco de DAC chega a ser mais de 15 vezes maior para um mesmo nível\nde LDL-c nos portadores de mutações causais, comparado aos portadores de mutações."},"answer":"B","source":"Clinica médica/MED CLM 03/MED CLM 03.txt","sourceLabel":"MED · MED CLM 03","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-03-314102","number":"314102","sourceNumber":"314102","collectionBlock":"med:med-clinica-medica-med-clm-03","collectionLabel":"MED · MED CLM 03","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 03","subtopic":"","stem":"O alvo terapêutico da hipertensão arterial para um paciente com DRC, de 50 anos, sem\noutras comorbidades, deve ser inferior a","options":{"A":"120/70 mmHg.","B":"130/80 mmHg.","C":"140/90 mmHg.","D":"160/90 mmHg."},"answer":"B","source":"Clinica médica/MED CLM 03/MED CLM 03.txt","sourceLabel":"MED · MED CLM 03","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-03-313196","number":"313196","sourceNumber":"313196","collectionBlock":"med:med-clinica-medica-med-clm-03","collectionLabel":"MED · MED CLM 03","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 03","subtopic":"","stem":"Um homem de 40 anos, assintomático, procura atendimento médico devido a\nhipertensão arterial sistêmica. Encontra-se em\nuso de enalapril 10mg a cada 12 horas. Ao exame\nfísico, observam-se FC = 80bpm e PA aferida no consultório = 148x90mmHg. Foi submetido a\nmonitorização ambulatorial da pressão arterial nas 24 horas = 134x82mmHg e na vigília =\n136x86mmHg. Qual é o diagnóstico?","options":{"A":"hipertensão mascarada","B":"hipertensão controlada","C":"hipertensão ?do avental branco\"\"","D":"hipertensão não controlada"},"answer":"D","source":"Clinica médica/MED CLM 03/MED CLM 03.txt","sourceLabel":"MED · MED CLM 03","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-03-317941","number":"317941","sourceNumber":"317941","collectionBlock":"med:med-clinica-medica-med-clm-03","collectionLabel":"MED · MED CLM 03","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 03","subtopic":"","stem":"Homem de 54 anos, administrador de empresa, procura endocrinologista com queixa\nde ganho progressivo de peso nos últimos\nquatro anos. Nega tabagismo e refere etilismo social.\nHipertenso em uso de losartan 50 mg/d. Sedentário. Alimentação hipercalórica e hiperlipídica. Ao\nexame: ausculta cardiopulmonar normal. Peso 104 kg, estatura 1,70 m. IMC: 35,9 kg/m², PA\n130x80 mmHg, FC 80 BPM, circunferência abdominal (CA) 104 cm. Exames laboratoriais: HDL 38\nmg/dL, LDL 156 mg/dL, triglicerídeos 144 mg/dL, glicemia de jejum 95 mg/dL, creatinina 0,7 mg/dL.\nSegundo critérios de Síndrome Metabólica (SM) da International Diabetes Association (IDF), o\npaciente","options":{"A":"tem o diagnóstico de SM por ter obesidade central (CA> 90 cm), LDL elevado (? 150 mg/dL) e\ndiagnóstico de hipertensão arterial.","B":"tem o diagnóstico de SM por ter obesidade central (CA> 90 cm), HDL baixo (?40 mg/dL) e\ndiagnóstico de hipertensão arterial.","C":"não tem o diagnóstico de SM, pois não tem glicemia ou TOTG alterados.","D":"não tem o diagnóstico de SM, pois encontra-se normotenso."},"answer":"B","source":"Clinica médica/MED CLM 03/MED CLM 03.txt","sourceLabel":"MED · MED CLM 03","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-03-295356","number":"295356","sourceNumber":"295356","collectionBlock":"med:med-clinica-medica-med-clm-03","collectionLabel":"MED · MED CLM 03","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 03","subtopic":"","stem":"Paciente masculino, de 54 anos, com antecedente de DM2 há cinco anos, hipertenso e\ncom obesidade visceral (CA= 106 cm). Comparece em consulta médica, após seis meses da última\navaliação, na qual foi evidenciada nefropatia diabética no estágio G2A2. Está em uso de:\nMetformina 2g/d, Dapaglifozina 10mg/d e Losartana 100mg/d. Traz o resultado do seguinte perfil\nlipídico: CT: 242 mg/dL, HDL: 51 mg/dL, LDL: 158 mg/dL, VLDL: 33 mg/dL, TG: 180 mg/dL. De\nacordo com o consenso da Sociedade Brasileira de Diabetes, qual a opção terapêutica mais\nindicada para esse paciente no presente momento?","options":{"A":"Rosuvastatina 20 mg.","B":"Sinvastatina 20 mg.","C":"Fenofibrato 160 mg.","D":"Ezetimiba 10 mg."},"answer":"A","source":"Clinica médica/MED CLM 03/MED CLM 03.txt","sourceLabel":"MED · MED CLM 03","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-03-317166","number":"317166","sourceNumber":"317166","collectionBlock":"med:med-clinica-medica-med-clm-03","collectionLabel":"MED · MED CLM 03","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 03","subtopic":"","stem":"Um homem de 60 anos está em pré-operatório de artroplastia de quadril por\nosteoartrite. Ele é hipertenso e diabético,\nem uso de metformina, glibenclamida, losartana e\nhidroclorotiazida. Seu exame físico não revela alterações relevantes e PA = 138x82mmHg. Exames\nlaboratoriais mostram hemograma e coagulograma normais; glicemia=105mg/dL; Hemoglobina\nglicada = 6.3%; creatinina = 2,1mg/dL; colesterol total = 200mg/dL; Triglicérides=200mg/dL;\nHDL=20mg/dL. O eletrocardiograma em repouso é normal. Sobre o planejamento terapêutico de\nlongo prazo, assinale a afirmativa correta","options":{"A":"Deve manter seu colesterol LDL, pela fórmula de Friedwald, abaixo de 100mg/dL","B":"Deve-se iniciar um fibrato","C":"Deve-se associar um anti-hipertensivo com alvo de pressão arterial abaixo de 130x80mmHg","D":"Há indicação para prescrição de rosuvastatina"},"answer":"B","source":"Clinica médica/MED CLM 03/MED CLM 03.txt","sourceLabel":"MED · MED CLM 03","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-03-308250","number":"308250","sourceNumber":"308250","collectionBlock":"med:med-clinica-medica-med-clm-03","collectionLabel":"MED · MED CLM 03","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 03","subtopic":"","stem":"Um dos grandes problemas que são frequentemente abordados nas unidades de saúde\nda família é o da síndrome metabólica.\nAdentra consultório médico, paciente, sexo feminino, 42\nanos, IMC=30 kg/m2, PA=140x90mmHg e história de diabetes em uso de metformina e gliclazida,\nnão sabe informar doses. Com base nos dados acima, marque a resposta correta:","options":{"A":"Já é possível fazer o diagnóstico de síndrome metabólica na paciente acima.","B":"A síndrome metabólica só pode ser diagnosticada se houver valores de triglicerídeos e HDL,\nportanto, no caso acima, a paciente ainda não tem síndrome metabólica.","C":"Com base nos dados, a paciente ainda não tem critérios para inclusão em síndrome metabólica.","D":"Só a obesidade e o fato de ser diabética, já são suficientes para a caracterização da síndrome\nmetabólica na paciente."},"answer":"D","source":"Clinica médica/MED CLM 03/MED CLM 03.txt","sourceLabel":"MED · MED CLM 03","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-03-311953","number":"311953","sourceNumber":"311953","collectionBlock":"med:med-clinica-medica-med-clm-03","collectionLabel":"MED · MED CLM 03","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 03","subtopic":"","stem":"Em relação às formas de medida da pressão arterial, além da medida em consultório,\ntem-se a Medida Residencial da Pressão\nArterial (MRPA) e a Medida Ambulatorial da Pressão\nArterial (MAPA) que auxiliam o médico nas tomadas de decisão diagnósticas e terapêuticas no que\nse refere a patologias hipertensivas. Tomando como base as VI Diretrizes para Medida\nAmbulatorial da Pressão Arterial e as VI Diretrizes Medida Residencial da Pressão Arterial é correto\nafirmar que:","options":{"A":"na MRPA devemos excluir medidas discrepantes, tais como medidas de Pressão Arterial\nSistólica (PAS) >210mmHg ou <70mmHg.","B":"na MAPA em 24h, consideramos valores normais a média da pressão arterial <135mmHg para a\nPAS e <80mmHg para a Pressão Arterial Diastólica (PAD).","C":"na MRPA devemos excluir medidas discrepantes, tais como medidas de PAD >1200mmHg ou\n\n<40mmHg.","D":"na MRPA, consideramos valores anormais a média da pressão arterial >135mmHg para PAS e\n\n>85mmHg para a PAD."},"answer":"D","source":"Clinica médica/MED CLM 03/MED CLM 03.txt","sourceLabel":"MED · MED CLM 03","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-03-311955","number":"311955","sourceNumber":"311955","collectionBlock":"med:med-clinica-medica-med-clm-03","collectionLabel":"MED · MED CLM 03","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 03","subtopic":"","stem":"Em relação à Hipertensão Arterial, assinale a alternativa que não configura indícios de\nhipertensão secundária.","options":{"A":"Hipocalemia na ausência de diuréticos.","B":"Fraca resposta ao tratamento anti-hipertensivo.","C":"Início da hipertensão antes dos 30 anos.","D":"Obesidade central."},"answer":"D","source":"Clinica médica/MED CLM 03/MED CLM 03.txt","sourceLabel":"MED · MED CLM 03","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-03-317212","number":"317212","sourceNumber":"317212","collectionBlock":"med:med-clinica-medica-med-clm-03","collectionLabel":"MED · MED CLM 03","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 03","subtopic":"","stem":"Homem, 51 anos, retorna à Unidade Básica de Saúde assintomático, para apresentar\nresultados de exames. Ao exame físico: PA: 138x88 mmHg, IMC: 26kg/m², Glicemia: 90 mg/dL,\nTriglicérides: 182 mg/dL e colesterol total: 195 mg/dL. A conduta mais adequada para esse\npaciente é:","options":{"A":"Terapia não farmacológica","B":"Diurético tiazídico","C":"Inibidor da enzima conversora de angiotensina","D":"Betabloqueador"},"answer":"A","source":"Clinica médica/MED CLM 03/MED CLM 03.txt","sourceLabel":"MED · MED CLM 03","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-03-316367","number":"316367","sourceNumber":"316367","collectionBlock":"med:med-clinica-medica-med-clm-03","collectionLabel":"MED · MED CLM 03","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 03","subtopic":"","stem":"Dona Filomena, 50 anos, em tratamento para hipertensão arterial primária com enalapril\n20mg/dia, chega na consulta com a sua médica de família Dra. Juliana, que após avaliação do\nMAPA pressórico, identifica a necessidade de incluir um segundo medicamento anti-hipertensivo.\n\nEntre as opções a seguir, qual a melhor opção de escolha para a segunda droga?","options":{"A":"Clortalidona.","B":"Propranolol.","C":"Losartana.","D":"Doxazosina."},"answer":"A","source":"Clinica médica/MED CLM 03/MED CLM 03.txt","sourceLabel":"MED · MED CLM 03","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-03-317214","number":"317214","sourceNumber":"317214","collectionBlock":"med:med-clinica-medica-med-clm-03","collectionLabel":"MED · MED CLM 03","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 03","subtopic":"","stem":"Em relação as medicações em uso do paciente hipertenso, diabético e IAM prévio, qual\né mais provável de causar edema como efeito\nadverso?","options":{"A":"Glibenclamida","B":"AAS","C":"Losartana.","D":"Anlodipino"},"answer":"D","source":"Clinica médica/MED CLM 03/MED CLM 03.txt","sourceLabel":"MED · MED CLM 03","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-03-317215","number":"317215","sourceNumber":"317215","collectionBlock":"med:med-clinica-medica-med-clm-03","collectionLabel":"MED · MED CLM 03","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 03","subtopic":"","stem":"Paciente masculino de 62 anos, hipertenso, diabético e portador de insuficiência\ncardíaca vem à consulta da UBS referindo\ndificuldade de controlar a pressão em casa. Qual das\ncondições a seguir relacionadas a história clínica NÃO podem ter contribuído para o quadro clínico\natual:","options":{"A":"Tabagismo 20 anos-maço","B":"Faringotonsilites de repetição na infância","C":"Hiperplasia prostática benigna","D":"Pai falecido por IAM fulminante"},"answer":"C","source":"Clinica médica/MED CLM 03/MED CLM 03.txt","sourceLabel":"MED · MED CLM 03","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-03-311964","number":"311964","sourceNumber":"311964","collectionBlock":"med:med-clinica-medica-med-clm-03","collectionLabel":"MED · MED CLM 03","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 03","subtopic":"","stem":"Uma pequena parcela dos pacientes hipertensos são portadores de hipertensão arterial\nsecundária. Estes pacientes são potencialmente curáveis, desde que corretamente identificados e\ntratados. É um achado sugestivo de hipertensão arterial secundária:","options":{"A":"glicemia de jejum alterada.","B":"hipocalemia na ausência do uso de diuréticos.","C":"hipercalemia.","D":"obesidade central."},"answer":"B","source":"Clinica médica/MED CLM 03/MED CLM 03.txt","sourceLabel":"MED · MED CLM 03","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-03-313256","number":"313256","sourceNumber":"313256","collectionBlock":"med:med-clinica-medica-med-clm-03","collectionLabel":"MED · MED CLM 03","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 03","subtopic":"","stem":"Dentro das Doenças Crônicas Não Transmissíveis (DCNTs), a obesidade surge como\numa epidemia crescente e acompanhada de várias\ncomorbidades. Dessa forma, deve ser tratada e\nprevenida. Assim, é correto afirmar que:","options":{"A":"a promoção de saúde está restrita aos profissionais de saúde, que têm o dever de prevenir,\nidentificar e tratar a obesidade","B":"epidemiologicamente, o Brasil, por ser considerado um país em desenvolvimento, tem\napresentado elevados índices de obesidade,\nprincipalmente nas faixas de renda mais baixa, no\nNorte e Nordeste do país","C":"existem algumas situações e fases de curso da vida em que as pessoas ficam mais expostas ao\nganho de peso excessivo, como idade da\nmenarca, ganho de peso gestacional, número de filhos,\nintervalo entre os partos, duração da amamentação, menopausa, casamento, estresse, ansiedade,\nmedicamentos, álcool, suspensão do tabagismo, consumo de álcool e redução da atividade física","D":"a orientação alimentar, com vistas a promoção de peso saudável, deve ser debatida em\nconsultas individualizadas e regrada ao objetivo de IMC a ser alcançado"},"answer":"C","source":"Clinica médica/MED CLM 03/MED CLM 03.txt","sourceLabel":"MED · MED CLM 03","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-03-281249","number":"281249","sourceNumber":"281249","collectionBlock":"med:med-clinica-medica-med-clm-03","collectionLabel":"MED · MED CLM 03","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 03","subtopic":"","stem":"Encefalopatia Hipertensiva é uma disfunção neurológica definida corretamente pelo\nitem:","options":{"A":"Sinais e/ou sintomas de edema cerebral primário à elevação súbita e/ou mantida da PA.","B":"Sinais e/ou sintomas de sangramento cerebral secundário à elevação súbita e/ou mantida da\nPA.","C":"Sinais e/ou sintomas de edema cerebral secundário à elevação súbita e não mantida da PA.","D":"Sinais e/ou sintomas de edema cerebral secundário à elevação súbita e/ou mantida da PA."},"answer":"D","source":"Clinica médica/MED CLM 03/MED CLM 03.txt","sourceLabel":"MED · MED CLM 03","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-03-281255","number":"281255","sourceNumber":"281255","collectionBlock":"med:med-clinica-medica-med-clm-03","collectionLabel":"MED · MED CLM 03","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 03","subtopic":"","stem":"Posicionamento Luso-Brasileiro de Emergências Hipertensivas ? 2020. Encefalopatia\nhipertensiva representa um diagnóstico de exclusão, sendo correto o item:","options":{"A":"Confirmado retrospectivamente quando o quadro neurológico melhora após o controle da PA.","B":"Nunca confirmado retrospectivamente quando o quadro neurológico melhora após o controle da\nPA.","C":"Confirmado retrospectivamente quando o quadro neurológico não melhora após o controle da\nPA.","D":"Confirmado retrospectivamente quando o quadro neurológico piora após o controle da PA."},"answer":"A","source":"Clinica médica/MED CLM 03/MED CLM 03.txt","sourceLabel":"MED · MED CLM 03","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-03-285064","number":"285064","sourceNumber":"285064","collectionBlock":"med:med-clinica-medica-med-clm-03","collectionLabel":"MED · MED CLM 03","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 03","subtopic":"","stem":"Homem, 37 anos, IMC, 43kg/m2 sai de consulta com cirurgião bariátrico que indica uma\ngastrectomia em manga (sleeve). O médico explica que a grelina é um fator importante e\nmodificado com esse procedimento. Em relação a esse hormônio, assinale a alternativa Correta.","options":{"A":"Produzido, preferencialmente, pelo antro-piloro gástrico.","B":"Tem efeito sinérgico à leptina, apesar de as duas agirem em receptores diferentes.","C":"Tem secreção aumentada após distensão gástrica.","D":"Promove diminuição da mortalidade estomacal.","E":"Age no sistema límbico, nos mecanismos de satisfação e compulsão"},"answer":"E","source":"Clinica médica/MED CLM 03/MED CLM 03.txt","sourceLabel":"MED · MED CLM 03","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-03-281259","number":"281259","sourceNumber":"281259","collectionBlock":"med:med-clinica-medica-med-clm-03","collectionLabel":"MED · MED CLM 03","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 03","subtopic":"","stem":"A Encefalopatia Hipertensiva pode se apresentar com o quadro clínico descrito,\ncorretamente, no item:","options":{"A":"Nunca com início insidioso, evoluindo com cefaleia holocraniana, náuseas ou vômitos.","B":"Com início insidioso, jamais evoluindo com cefaleia holocraniana, náuseas ou vômitos.","C":"Com início insidioso, evoluindo com cefaleia holocraniana, náuseas ou vômitos.","D":"Com início insidioso, evoluindo com cefaleia holocraniana e náuseas, porém nunca com vômitos."},"answer":"C","source":"Clinica médica/MED CLM 03/MED CLM 03.txt","sourceLabel":"MED · MED CLM 03","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-03-277409","number":"277409","sourceNumber":"277409","collectionBlock":"med:med-clinica-medica-med-clm-03","collectionLabel":"MED · MED CLM 03","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 03","subtopic":"","stem":"Homem de 75 anos, hipertenso há mais de 15 anos, tabagista, com história de\nhipertensão arterial descontrolada há 90 dias.\nAo exame físico se apresenta corado, com\nfrequência cardíaca de 75 batimentos por minuto e pressão arterial de 165x110mmHg, à ausculta\nna topografia de carótida direita percebe-se sopro, à ausculta cardíaca não se percebe qualquer\nalteração. percebe-se pulsos pedioso e radial esquerdo diminuídos. No referido caso qual exame\ndiagnóstico é mais adequado para auxiliar no diagnóstico:","options":{"A":"Monitorização Ambulatorial de Pressão Arterial (MAPA)","B":"Ecocardiograma","C":"Doppler de membro inferior esquerdo","D":"Angiotomografia de Aorta"},"answer":"D","source":"Clinica médica/MED CLM 03/MED CLM 03.txt","sourceLabel":"MED · MED CLM 03","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-03-257721","number":"257721","sourceNumber":"257721","collectionBlock":"med:med-clinica-medica-med-clm-03","collectionLabel":"MED · MED CLM 03","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 03","subtopic":"","stem":"O uso de fibratos, associado a medidas não farmacológicas, para hipertrigliceridemia\nmaior que 500 mg/dl, tem recomendação e nível de\nevidência:","options":{"A":"IA.","B":"IIaB.","C":"IIaC.","D":"IIbC."},"answer":"A","source":"Clinica médica/MED CLM 03/MED CLM 03.txt","sourceLabel":"MED · MED CLM 03","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-03-265852","number":"265852","sourceNumber":"265852","collectionBlock":"med:med-clinica-medica-med-clm-03","collectionLabel":"MED · MED CLM 03","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 03","subtopic":"","stem":"Emergência Hipertensiva (EH) está integrada em um quadro nosológico mais geral\ndenominado Crise Hipertensiva (CH). Podemos indicar como CORRETO que:","options":{"A":"A CH representa situações clínicas que cursam com elevação aguda da Pressão Arterial (PA),\ngeralmente níveis de PA sistólica (PAS) ? 180 mmHg e diastólica (PAD) ? 120 mmHg, que podem\nresultar ou não em Lesões de Órgãos-Alvo (LOA) (coração, cérebro, rins e artérias).","B":"A CH representa situações clínicas que cursam com elevação aguda da Pressão Arterial (PA),\ngeralmente níveis de PA sistólica (PAS) ? 180 mmHg e diastólica (PAD) ? 120 mmHg, que podem\nresultar ou não em Lesões de Órgãos-Alvo (LOA) (coração, cérebro, rins e artérias).","C":"A CH representa situações clínicas que cursam com elevação crônica da Pressão Arterial (PA),\ngeralmente níveis de PA sistólica (PAS) ? 180 mmHg e diastólica (PAD) ? 120 mmHg, que podem\nresultar ou não em Lesões de Órgãos-Alvo (LOA) (coração, cérebro, rins e artérias).","D":"A CH representa situações clínicas que cursam com elevação aguda da Pressão Arterial (PA),\ngeralmente níveis de PA sistólica (PAS) ? 180 mmHg e diastólica (PAD) ? 120 mmHg, que podem\nresultar ou não em Lesões de Órgãos-Alvo (LOA) (coração, cérebro, rins e não artérias)."},"answer":"B","source":"Clinica médica/MED CLM 03/MED CLM 03.txt","sourceLabel":"MED · MED CLM 03","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-03-257927","number":"257927","sourceNumber":"257927","collectionBlock":"med:med-clinica-medica-med-clm-03","collectionLabel":"MED · MED CLM 03","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 03","subtopic":"","stem":"Homem negro de 52 anos, com história familiar rica em hipertensão severa, apresenta\npressão arterial média após três medidas de\n164/106 mmHg. Nesse caso, qual opção mais\nindicada para tratar sua hipertensão?","options":{"A":"Começar com hidroclorotiazida 12,5 mg, uma vez ao dia.","B":"Começar com uma combinação de duas drogas.","C":"Insistir apenas em modificação no estilo de vida e checar a pressão em duas semanas.","D":"Começar com uma combinação de duas drogas, apenas se a primeira droga tiver falhado."},"answer":"B","source":"Clinica médica/MED CLM 03/MED CLM 03.txt","sourceLabel":"MED · MED CLM 03","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-03-265862","number":"265862","sourceNumber":"265862","collectionBlock":"med:med-clinica-medica-med-clm-03","collectionLabel":"MED · MED CLM 03","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 03","subtopic":"","stem":"As apresentações da Crise Hipertensiva é a descrita com valores acima dos 180/120\nmmHg, atualmente o maior consenso se estabelece\nno conceito de que mais do que os valores é o\ndano ou o risco iminente de acometimento de órgãos-alvo. Podemos nesse contexto determinar\ncomo CORRETO que:","options":{"A":"A maior importância diagnóstica é a observação dos sinais/sintomas e da disfunção aguda dos\nórgãos-alvo, mais do que no valor da PA.","B":"A menor importância diagnóstica é a observação dos sinais/sintomas e da disfunção aguda dos\nórgãos-alvo, mais do que no valor da PA.","C":"A maior importância diagnóstica é a observação dos sinais/sintomas e da disfunção crônica dos\nórgãos-alvo, mais do que no valor da PA.","D":"A maior importância diagnóstica é a observação dos sinais/sintomas e da disfunção aguda dos\nórgãos-alvo, menos do que no valor da PA."},"answer":"A","source":"Clinica médica/MED CLM 03/MED CLM 03.txt","sourceLabel":"MED · MED CLM 03","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-03-281993","number":"281993","sourceNumber":"281993","collectionBlock":"med:med-clinica-medica-med-clm-03","collectionLabel":"MED · MED CLM 03","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 03","subtopic":"","stem":"Paciente do sexo feminino, 72 anos, hipertensa, PA 168x92, FC 88 bpm. Queixa-se de\ndispnéia aos grandes esforços. ECG com ritmo sinusal e alterações inespecíficas. Ecocardiograma\ncom hipertrofia ventricular, FE 71%. A estratégia terapêutica anti-hipertensiva preferencial para\neste\ncaso deve ser:","options":{"A":"Losartana + enalapril.","B":"Losartana + clortalidona.","C":"Hidroclortiazida + metoprolol.","D":"Bisoprolol + anlodipino."},"answer":"B","source":"Clinica médica/MED CLM 03/MED CLM 03.txt","sourceLabel":"MED · MED CLM 03","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-03-273217","number":"273217","sourceNumber":"273217","collectionBlock":"med:med-clinica-medica-med-clm-03","collectionLabel":"MED · MED CLM 03","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 03","subtopic":"","stem":"Pesquisas demonstram que a complexidade da obesidade aponta para um problema\nmultifatorial. Nesse contexto, analise as\nproposições abaixo e, em seguida, assinale a alternativa\nque as classificam em V (verdadeira) ou F (falsa) de forma respectivamente CORRETA: I. A\nobesidade é um dos maiores desafios da saúde pública na atualidade. II. A obesidade não pode ser\nconsiderada como atributo físico, percebido, interpretado e influenciado pelo sistema social. III.\nFatores estruturais, como mobilidade, incluindo migração e trabalho sazonal e instabilidade\npolítica,\nnão influenciam na obesidade.","options":{"A":"V, V, V.","B":"F, V, V.","C":"V, F, V.","D":"V, V, F."},"answer":"C","source":"Clinica médica/MED CLM 03/MED CLM 03.txt","sourceLabel":"MED · MED CLM 03","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-03-246519","number":"246519","sourceNumber":"246519","collectionBlock":"med:med-clinica-medica-med-clm-03","collectionLabel":"MED · MED CLM 03","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 03","subtopic":"","stem":"Considerando a técnica de aferição da pressão arterial, assinale a alternativa\nincorreta.","options":{"A":"A medida da pressão deve ser realizada, pelo menos anualmente, nos indivíduos cuja pressão\nseja <140x80 mmHg e > 120x80 mmHg.","B":"O paciente deve estar de pernas descruzadas, com os pés apoiados no chão, o dorso recostado\nna cadeira e relaxado.","C":"Para medida da pressão arterial o paciente pode ter fumado até 15 minutos antes de aferir a\npressão.","D":"Deve-se selecionar o manguito adequado à circunferência braquial, medida no ponto médio\nentre acrômio e olecrano.","E":"É preciso estimar o nível da pressão sistólica pela palpação da artéria radial."},"answer":"C","source":"Clinica médica/MED CLM 03/MED CLM 03.txt","sourceLabel":"MED · MED CLM 03","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-03-249460","number":"249460","sourceNumber":"249460","collectionBlock":"med:med-clinica-medica-med-clm-03","collectionLabel":"MED · MED CLM 03","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 03","subtopic":"","stem":"Considerando as aplicações da monitorização residencial da pressão arterial, não\npodemos apenas indicar como inadequado que:","options":{"A":"As variações dia a dia da PA podem ser avaliadas.","B":"Variações permitem estabelecer separadamente as medidas do período matinal e do\nentardecer/anoitecer.","C":"A PA matinal não pode estar associada a dano em órgão-alvo como AVE.","D":"A associação de dano em órgão-alvo com a PA durante o entardecer/anoitecer da MRPA pode\nser equivalente à PA durante o sono da MAPA."},"answer":"C","source":"Clinica médica/MED CLM 03/MED CLM 03.txt","sourceLabel":"MED · MED CLM 03","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-03-248913","number":"248913","sourceNumber":"248913","collectionBlock":"med:med-clinica-medica-med-clm-03","collectionLabel":"MED · MED CLM 03","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 03","subtopic":"","stem":"De acordo com as novas diretrizes americanas de hipertensão arterial, publicadas em\n2017, assinale a alternativa incorreta:","options":{"A":"a hipertensão arterial passa a ser definida pelos valores de PA >130x80mmHg","B":"o uso da calculadora para estimar o risco cardiovascular em 10 anos (ASCVD risk calculator)\nauxilia na tomada de decisão ao selecionar os\npacientes, em prevenção primária e estágio I, que\ndevem receber drogas anti-hipertensivas","C":"para a maioria dos pacientes, a meta a ser atingida é PA <130x80mmHg","D":"a urgência hipertensiva continua a ser definida como elevação significativa da PA associada à\ndisfunção de órgãos-alvo"},"answer":"D","source":"Clinica médica/MED CLM 03/MED CLM 03.txt","sourceLabel":"MED · MED CLM 03","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-03-248914","number":"248914","sourceNumber":"248914","collectionBlock":"med:med-clinica-medica-med-clm-03","collectionLabel":"MED · MED CLM 03","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 03","subtopic":"","stem":"No tratamento da hipertensão arterial, a associação de inibidor da enzima conversora\nde angiotensina a bloqueador do receptor de\nangiotensina II:","options":{"A":"pode ser indicada caso o uso de um desses fármacos não tenha promovido o controle adequado\nda pressão arterial","B":"está indicada a pacientes com insuficiência cardíaca pós-infarto agudo do miocárdio","C":"está indicada a pacientes diabéticos que estejam evoluindo com perda da função renal","D":"não é recomendada, pois, além de não mostrar benefícios em desfechos cardiovasculares,\nacrescenta riscos de efeitos adversos"},"answer":"D","source":"Clinica médica/MED CLM 03/MED CLM 03.txt","sourceLabel":"MED · MED CLM 03","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-03-234324","number":"234324","sourceNumber":"234324","collectionBlock":"med:med-clinica-medica-med-clm-03","collectionLabel":"MED · MED CLM 03","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 03","subtopic":"","stem":"Qual é a meta terapêutica de LDL colesterol para pacientes de baixo risco\ncardiovascular?","options":{"A":"< 130 mg/dl.","B":"< 100 mg/dl.","C":"< 70 mg/dl.","D":"< 50 mg/dl."},"answer":"A","source":"Clinica médica/MED CLM 03/MED CLM 03.txt","sourceLabel":"MED · MED CLM 03","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-03-247410","number":"247410","sourceNumber":"247410","collectionBlock":"med:med-clinica-medica-med-clm-03","collectionLabel":"MED · MED CLM 03","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 03","subtopic":"","stem":"Paciente de 45 anos, sexo feminino, comparece ao pronto-socorro com queixa de\ncefaleia occipital e náuseas, de início há\nquatro horas, associadas a borramento visual, sem outras\nqueixas. A paciente é tabagista e tem história prévia de hipertensão arterial, em uso regular de\nanlodipino. O exame físico é normal, exceto pela Pressão Arterial (PA) = 216/128 mmHg em ambos\nos membros superiores. Esta condição trata-se de uma:","options":{"A":"urgência hipertensiva. A paciente deve receber furosemida por via endovenosa e captopril via\noral.","B":"urgência hipertensiva. A paciente deve receber nitroprussiato de sódio por via endovenosa.","C":"emergência hipertensiva. A paciente deve receber furosemida por via endovenosa e captopril\nsublingual.","D":"emergência hipertensiva. A paciente deve receber nitroprussiato de sódio por via endovenosa."},"answer":"D","source":"Clinica médica/MED CLM 03/MED CLM 03.txt","sourceLabel":"MED · MED CLM 03","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-03-234335","number":"234335","sourceNumber":"234335","collectionBlock":"med:med-clinica-medica-med-clm-03","collectionLabel":"MED · MED CLM 03","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 03","subtopic":"","stem":"Paciente de 70 anos, do sexo masculino, é levado ao pronto-socorro com perda da\nmovimentação e fala. Era hipertenso em uso regular de losartana 50 mg, duas vezes ao dia. Ao\nexame, apresentava BNF 2T, sem sopros, MVF sem RA, abdome normal, sonolência, PA = 190 x\n105 mmHg, FC = 95 BPM, FR = 17 IRPM, saturação de O? = 96%, glicemia capilar de 112 mg/dl.\nEscala de coma de Glasgow = 10. Hemiplegia direita completa e afasia motora, força preservada a\nesquerda, sem sinais de perda sensitiva. Aumento dos reflexos profundos à direita e Babinski.\n\nPupilas iso e fotorreativas, nuca livre, demais pares cranianos normais. Considerando a principal\nhipótese diagnóstica para o caso, a conduta recomendada quanto à pressão arterial é:","options":{"A":"Iniciar metoprolol 50 mg via oral de 12 em 12 horas e associar a clonidina 0,1 mg a critério\nmédico de quatro em quatro horas, com meta de PAS ? 120 mmHg.","B":"Iniciar nitroprussiato 0,5 a 8 mg/kg/min, medir PA a cada 15 minutos por duas horas e, após, a\ncada 30 minutos, com meta de PAS entre 130 e\n150 mmHg.","C":"Fazer nifedipina 20 mg sublingual, de quatro em quatro horas, com meta de PAS menor que 180\nmmHg.","D":"Fazer captopril 25 mg sublingual, de duas em duas horas, até normalização da PAS entre 100 e\n120 mmHg."},"answer":"B","source":"Clinica médica/MED CLM 03/MED CLM 03.txt","sourceLabel":"MED · MED CLM 03","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-03-247471","number":"247471","sourceNumber":"247471","collectionBlock":"med:med-clinica-medica-med-clm-03","collectionLabel":"MED · MED CLM 03","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 03","subtopic":"","stem":"\"O interesse no estudo da Hipertensão Arterial Sistêmica (HAS) nas crianças e\nadolescentes é antigo, porém, ainda hoje,\no diagnóstico tem sido feito de forma tardia por causa da\nfalta de inclusão da aferição de pressão arterial como rotina no exame físico da criança\"\n(Departamento científico de Nefrologia da SBP, manual de orientação, 2019). Em relação à HAS na\ninfância e adolescência, qual é a alternativa mais correta?","options":{"A":"A gravidade da elevação da pressão arterial é o que difere HAS primária e secundária. Além\ndisso, a pressão arterial diastólica é mais elevada na Hipertensão Arterial Sistêmica primária.","B":"As principais causas de Hipertensão Arterial em lactentes são: doenças do parênquima renal,\ncoarctação da artéria aorta e estenose de artéria renal. Fazendo, portanto, parte da investigação\ndiagnóstica, a solicitação de ultrassonografia renal.","C":"Considera-se Hipertensão Arterial na Infância e Adolescência, valores de pressão arterial\nsistólica e diastólica maiores ou iguais a\n130/90 mmHg, em três ou mais aferições em ocasiões\ndiferentes.","D":"O ecocardiograma com doppler não tem sido indicado como consenso para investigação de\nórgãos-alvo, pois na infância não há alterações na musculatura ventricular associada a hipertensão\narterial."},"answer":"B","source":"Clinica médica/MED CLM 03/MED CLM 03.txt","sourceLabel":"MED · MED CLM 03","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-03-210528","number":"210528","sourceNumber":"210528","collectionBlock":"med:med-clinica-medica-med-clm-03","collectionLabel":"MED · MED CLM 03","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 03","subtopic":"","stem":"Com relação aos exames complementares nos casos de emergência hipertensiva,\nassinale a alternativa correta.","options":{"A":"Ecocardiograma transtorácico é sensível para confirmar dissecção aguda de aorta.","B":"BNP é indicado na dúvida entre edema agudo de pulmão e dispneia não cardiogênica.","C":"Tomografia de crânio é necessária mesmo na ausência de sintomas neurológicos.","D":"Punção liquórica é útil na suspeita de hemorragia subaracnoidea e TC compatível.","E":"Gasometria arterial é importante somente na presença de insuficiência respiratória."},"answer":"B","source":"Clinica médica/MED CLM 03/MED CLM 03.txt","sourceLabel":"MED · MED CLM 03","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-03-215418","number":"215418","sourceNumber":"215418","collectionBlock":"med:med-clinica-medica-med-clm-03","collectionLabel":"MED · MED CLM 03","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 03","subtopic":"","stem":"As áreas sob as curvas, como um modelo de interpretação do comportamento da PA\npela MAPA, foram avaliadas em comparação com\noutros parâmetros obtidos ? por exemplo, cargas\nde pressão e médias de PA ? mostrando excelente correlação. Assinale a opção CORRETA.","options":{"A":"Porém, a falta de estudos correlacionando esses valores de áreas sob as curvas obtidas com\nmorbidade e mortalidade faz com que seu uso na prática clínica e na interpretação do exame ainda\nnão seja autorizado.","B":"Porém, a falta de estudos correlacionando esses valores de áreas sob as curvas obtidas com\nmorbidade e mortalidade faz com que seu uso na prática clínica e na interpretação do exame seja\nautorizado.","C":"Porém, a falta de estudos correlacionando esses valores de áreas sob as curvas obtidas com\nmorbidade e mortalidade faz com que seu uso na prática clínica e na interpretação do exame seja\nrotineiro.","D":"Porém, a falta de estudos correlacionando esses valores de áreas sob as curvas obtidas com\nmorbidade e mortalidade faz com que seu uso na prática clínica e na interpretação do exame seja o\npadrão."},"answer":"A","source":"Clinica médica/MED CLM 03/MED CLM 03.txt","sourceLabel":"MED · MED CLM 03","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-03-202718","number":"202718","sourceNumber":"202718","collectionBlock":"med:med-clinica-medica-med-clm-03","collectionLabel":"MED · MED CLM 03","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 03","subtopic":"","stem":"Qual é o único hipolipemiante liberado para mulheres no período gestacional?","options":{"A":"Colestiramina.","B":"Ezetimibe.","C":"Fibratos.","D":"Fitosteróis."},"answer":"A","source":"Clinica médica/MED CLM 03/MED CLM 03.txt","sourceLabel":"MED · MED CLM 03","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-03-215417","number":"215417","sourceNumber":"215417","collectionBlock":"med:med-clinica-medica-med-clm-03","collectionLabel":"MED · MED CLM 03","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 03","subtopic":"","stem":"Após estudos surgiram debates sobre a possibilidade da redução de riscos\ncardiovasculares dos idosos por meio de\ntratamento ?agressivo?, com a redução da PA a valores\nde 120/80 mmHg ou menos. Indique a afirmação CORRETA.","options":{"A":"Observou-se, porém, que idosos com baixos valores da PA não apresentaram aumento de\neventos adversos como síncope.","B":"Admitindo-se que o tratamento ?agressivo? realmente reduza riscos, ele seria recomendado\nmesmo que não tolerado.","C":"MAPA não poderia acrescentar informações à avaliação clínica para otimizar o tratamento dos\nidosos.","D":"Observou-se, porém, que idosos com baixos valores da PA apresentaram aumento de eventos\nadversos como hipotensão e bradicardia."},"answer":"D","source":"Clinica médica/MED CLM 03/MED CLM 03.txt","sourceLabel":"MED · MED CLM 03","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-03-201717","number":"201717","sourceNumber":"201717","collectionBlock":"med:med-clinica-medica-med-clm-03","collectionLabel":"MED · MED CLM 03","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 03","subtopic":"","stem":"Leia o caso clínco a seguir. Homem de 53 anos, hipertenso e diabético, com\nantecedente de angioplastia há dois anos em\nduas coronárias. Mesmo em uso de AAS 100 mg/dia,\natorvastatina 40 mg/dia e atenolol 25 mg duas vezes ao dia, apresenta os seguintes exames\nlaboratoriais: colesterol total 200 mg/dl; HDL 50 mg/dl; triglicerídeos 180 mg/dl; LDL 114 mg/dl;\nglicemia de jejum 150 mg/dl; HbA1c 7,4%. Considerando a Atualização da Diretriz Brasileira de\nDislipidemias e Prevenção da Aterosclerose - 2017, realizada pelo Departamento de Aterosclerose\nda Sociedade Brasileira de Cardiologia (SBC-DA) em conjunto com Sociedade Brasileira de\nDiabetes (SBD) e Sociedade Brasileira de Endocrinologia e Metabologia (SBEM), a meta de LDL\ncolesterol para este paciente prevê a seguinte terapêutica:","options":{"A":"O uso do ezetimiba é uma alternativa em acréscimo à dose máxima tolerada de estatina, caso\nas metas de LDL não sejam alcançadas.","B":"O dobro da dose de atorvastatina será o suficiente para alcançar a meta de LDL.","C":"O uso de fenofibrato deve ser iniciado, caso as metas de LDL colesterol não sejam alcançadas,\njá que o paciente apresenta níveis de\ntriglicerídeos acima do alvo de 150 mg/dl.","D":"O uso de estatinas poderia ser dispensado, caso o paciente apresentasse o nível de LDL\ncolesterol < 50 mg/dl."},"answer":"A","source":"Clinica médica/MED CLM 03/MED CLM 03.txt","sourceLabel":"MED · MED CLM 03","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-03-214976","number":"214976","sourceNumber":"214976","collectionBlock":"med:med-clinica-medica-med-clm-03","collectionLabel":"MED · MED CLM 03","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 03","subtopic":"","stem":"Homem de 49 anos procura atendimento de emergência por cefaleia. Refere história de\nrevascularização miocárdica há 1 ano e nega dor precordial. Ao exame físico apresenta PA =\n200x125mmHg sem 3' ou 4' bulha. O exame neurológico é normal. Qual é o diagnóstico mais\nprovável e qual é a melhor conduta terapêutica para o caso?","options":{"A":"emergência hipertensiva; nitroglicerina intravenosa","B":"urgência hipertensiva; hidralazina intravenosa","C":"urgência hipertensiva; nitroprussiato de sódio intravenoso e administração de analgésico","D":"urgência hipertensiva; captopril oral e administração de analgésico"},"answer":"D","source":"Clinica médica/MED CLM 03/MED CLM 03.txt","sourceLabel":"MED · MED CLM 03","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-03-216657","number":"216657","sourceNumber":"216657","collectionBlock":"med:med-clinica-medica-med-clm-03","collectionLabel":"MED · MED CLM 03","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 03","subtopic":"","stem":"L.S.A., é um paciente de 54 anos de idade, que vai ao ambulatório de clínica médica\npara acompanhamento após sofrer um acidente vascular\nencefálico. Ele faz uso de medicamentos\npara o controle pressórico e é sabidamente portador de dislipidemia mista. Segundo o consenso\nbrasileiro de dislipidemia, o alvo terapêutico a ser atingido é um LDL colesterol abaixo de:","options":{"A":"70 mg/dl.","B":"50 mg/dl.","C":"100 mg/dl.","D":"130 mg/dl."},"answer":"B","source":"Clinica médica/MED CLM 03/MED CLM 03.txt","sourceLabel":"MED · MED CLM 03","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-03-201689","number":"201689","sourceNumber":"201689","collectionBlock":"med:med-clinica-medica-med-clm-03","collectionLabel":"MED · MED CLM 03","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 03","subtopic":"","stem":"Leia o caso a seguir. Uma mulher de 65 anos, com hipertensão arterial, insuficiência\nventricular esquerda e nefropatia diabética,\ndesenvolveu tosse seca, persistente e intolerável na\nvigência do tratamento com lisinopril. Qual das seguintes alternativas tem a menor probabilidade de\nmelhorar a tosse?","options":{"A":"Substituir o lisinopril por um antagonista dos receptores de angiotensina II.","B":"Substituir o lisinopril pelo enalapril.","C":"Acrescentar a nifedipina.","D":"Acrescentar a indometacina."},"answer":"B","source":"Clinica médica/MED CLM 03/MED CLM 03.txt","sourceLabel":"MED · MED CLM 03","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-03-214983","number":"214983","sourceNumber":"214983","collectionBlock":"med:med-clinica-medica-med-clm-03","collectionLabel":"MED · MED CLM 03","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 03","subtopic":"","stem":"Um homem de 70 anos diabético e assintomático do ponto de vista cardiovascular e\nnão possui alterações ao exame físico vem com\nos seguintes resultados de exames: HDL =\n47mg/dL, LDL = 110mg/dL, triglicérides = 335mg/dL, colesterol total = 222mg/dL, hemoglobina\nglicada = 6,8% e glicemia de jejum = 123mg/dL. Com relação ao tratamento da dislipidemia, é\ncorreto afirmar que:","options":{"A":"a associação de genfibrozila e sinvastatina está indicada em razão dos níveis altos de\ntriglicérides e LDL","B":"o tratamento da dislipidemia em idosos deve ter metas menos estritas, uma vez que essa\npopulação tem menor benefício no controle lipídico para a prevenção de doença cardiovascular.\nAssim, podem-se orientar apenas modificações do estilo de vida, além de ajustar o esquema\nhipoglicemiante","C":"é necessária a adição de estatina para o controle da dislipidemia nesse momento, além de\nmodificação no estilo de vida","D":"a ezetimiba pode ser empregada nesse paciente em vez da estatina, visto que esse grupo de\nfármacos provoca mais efeitos adversos nessa faixa etária"},"answer":"C","source":"Clinica médica/MED CLM 03/MED CLM 03.txt","sourceLabel":"MED · MED CLM 03","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-03-205572","number":"205572","sourceNumber":"205572","collectionBlock":"med:med-clinica-medica-med-clm-03","collectionLabel":"MED · MED CLM 03","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 03","subtopic":"","stem":"Recomenda-se, preferencialmente, que os pacientes idosos sejam acompanhados por\nequipe multidisciplinar e que seus familiares sejam envolvidos em todo o processo, o que aumenta\nas taxas de adesão e as chances de sucesso com o tratamento. Sendo INADEQUADO que:","options":{"A":"A maior ocorrência da hipotensão ortostática e pós-prandial e, finalmente, a presença de\narritmias, como fibrilação atrial, pode dificultar a medição da PA nos idosos.","B":"A medição da PA em idosos deve ser revestida de cuidados especiais do ponto de vista técnico.","C":"Ocorre sempre a necessidade da avaliação de hipotensão postural, definida como redução igual\nou superior a 20 mmHg na PAS, ou diminuição de qualquer valor seguida de sintomas clínicos e/ou\nredução de 10 mmHg ou mais na PAD, quando comparados, após 3 minutos, os valores obtidos na\nposição ortostática com aqueles medidos nas posições de decúbito ou sentada.","D":"O tratamento da HA nesse grupo de pacientes traz benefícios duvidosos na redução de eventos\nCV maiores (IAM, AVE e IC)."},"answer":"D","source":"Clinica médica/MED CLM 03/MED CLM 03.txt","sourceLabel":"MED · MED CLM 03","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-03-205597","number":"205597","sourceNumber":"205597","collectionBlock":"med:med-clinica-medica-med-clm-03","collectionLabel":"MED · MED CLM 03","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 03","subtopic":"","stem":"Não existem estudos suficientes para embasar com grau de evidência satisfatório o\ndiagnóstico de HA nos pacientes em terapia dialítica, podemos apenas aceitar que:","options":{"A":"A associação entre PA e mortalidade em pacientes com DRC em terapia dialítica não tem\ndistribuição em ?U? para a PAS e a PAD.","B":"A associação entre PA e mortalidade em pacientes com DRC em terapia dialítica tem\ndistribuição em ?U? para a PAS e a PAD, de tal\nforma que tanto os níveis elevados, quanto os\nreduzidos, relacionam-se com mau prognóstico.","C":"A associação entre PA e mortalidade em pacientes com DRC em terapia dialítica tem\ndistribuição em ?U? para a PAS apenas, de tal forma que tanto os níveis elevados, quanto os\nreduzidos, relacionam-se com mau prognóstico.","D":"A associação entre PA e mortalidade em pacientes com DRC em terapia dialítica tem\ndistribuição em ?U? para a PAS e a PAD, de tal\nforma que tanto os níveis elevados, quanto os\nreduzidos, relacionam-se com melhor prognóstico."},"answer":"B","source":"Clinica médica/MED CLM 03/MED CLM 03.txt","sourceLabel":"MED · MED CLM 03","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-03-183301","number":"183301","sourceNumber":"183301","collectionBlock":"med:med-clinica-medica-med-clm-03","collectionLabel":"MED · MED CLM 03","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 03","subtopic":"","stem":"Existe considerável heterogeneidade no tamanho das partículas de LDL, porém não\npodemos concordar com a seguinte afirmação:","options":{"A":"Existe considerável heterogeneidade no tamanho das partículas de LDL, cuja densidade pode\nvariar entre 1,019 a 1,063 g/L,55 particularmente em pacientes com hiperlipidemia mista, quando\ncomparados a portadores de HF isolada.","B":"As partículas de LDL pequenas e densas coexistem com níveis elevados de TG, sendo\nconsideradas mais aterogênicas do que LDL maiores e boiantes, que predominam em\nconcentrações mais baixas de TG.","C":"Apesar da possível maior aterogenicidade das partículas LDL pequenas, alguns estudos têm\nmostrado que o tamanho da partícula de LDL por si só, pode não se associar com o risco futuro de\neventos cardiovasculares, quando se leva em conta o aumento da concentração do total de\npartículas de LDL presente nestas situações.","D":"Apesar da possível maior aterogenicidade das partículas LDL densas, alguns estudos têm\nmostrado que o tamanho da partícula de LDL\npor si só, pode não se associar com o risco futuro de\neventos cardiovasculares, quando se leva em conta o aumento da concentração do total de\npartículas de LDL ausente nestas situações."},"answer":"D","source":"Clinica médica/MED CLM 03/MED CLM 03.txt","sourceLabel":"MED · MED CLM 03","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-03-187702","number":"187702","sourceNumber":"187702","collectionBlock":"med:med-clinica-medica-med-clm-03","collectionLabel":"MED · MED CLM 03","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 03","subtopic":"","stem":"A respeito do tratamento de Hipertensão Arterial, assinale a alternativa correta:","options":{"A":"São responsáveis por aumento da incidência de disfunção erétil: diuréticos tiazídicos, alfa e\nbetabloqueadores.","B":"Os betabloqueadores, em múltiplos estudos de grande porte, mais freqüentemente o Atenolol,\nforam responsáveis por incidência aumentada de\nAcidente Vascular Cerebral. Entretanto, eles\nforam os anti-hipertensivos que mais reduziram mortalidade por eventos cardiovasculares em todos\nos estudos, por isso são considerados de primeira linha para tratamento da hipertensão arterial.","C":"Indivíduos com níveis inicialmente baixos de Renina ou Aldosterona, como os jovens e brancos,\ntendem a apresentar um efeito\nanti-hipertensivo maior com os diuréticos.","D":"Com a interrupção abrupta dos bloqueadores de canais de cálcio, a inibição da liberação de\ncatecolaminas desaparece em 12 a 18 horas, os níveis de catecolaminas no sangue aumentam\nsignificativamente."},"answer":"A","source":"Clinica médica/MED CLM 03/MED CLM 03.txt","sourceLabel":"MED · MED CLM 03","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-03-178780","number":"178780","sourceNumber":"178780","collectionBlock":"med:med-clinica-medica-med-clm-03","collectionLabel":"MED · MED CLM 03","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 03","subtopic":"","stem":"Qual é a apresentação mais comum das emergências hipertensivas?","options":{"A":"Encefalopatia Hipertensiva.","B":"AVE hemorrágico.","C":"AVE isquêmico.","D":"Síndrome Coronariana Aguda.","E":"Edema Agudo de Pulmão."},"answer":"E","source":"Clinica médica/MED CLM 03/MED CLM 03.txt","sourceLabel":"MED · MED CLM 03","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-03-174466","number":"174466","sourceNumber":"174466","collectionBlock":"med:med-clinica-medica-med-clm-03","collectionLabel":"MED · MED CLM 03","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 03","subtopic":"","stem":"Quando avaliamos a abordagem da Dislipidemia de um paciente diabético, devemos\nconsiderar diversos fatores, aponte a alternativa INCORRETA:","options":{"A":"Assim, convencionou-se chamar de ?moderado? o tratamento capaz de reduzir o LDL-c de 30%\na 50% e de ?intensivo? o tratamento em que\nse pretende redução de LDL-c acima de 50%.","B":"Não há um tipo específico de estatina que configure tratamento moderado ou intensivo. Desde\nque sejam atingidos os critérios de\n\nredução acima descritos, qualquer estatina poderia ser usada. Na prática, entretanto, pelo\nobservado nos estudos disponíveis, a média de\nredução de LDL-c dependerá muito do tipo e da\ndose de estatina utilizada.","C":"Em geral, as estatinas menos potentes, como a atorvastatina e a rosuvastatina, em doses altas,\ntêm menor probabilidade de obter sucesso no tratamento intensivo.","D":"É importante fazer a ressalva de que a resposta biológica varia muito de indivíduo para\nindivíduo, e não se pode esquecer que as medidas de estilo de vida exercem papel muito\nimportante na otimização do tratamento."},"answer":"C","source":"Clinica médica/MED CLM 03/MED CLM 03.txt","sourceLabel":"MED · MED CLM 03","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-03-183323","number":"183323","sourceNumber":"183323","collectionBlock":"med:med-clinica-medica-med-clm-03","collectionLabel":"MED · MED CLM 03","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 03","subtopic":"","stem":"A Hipercolesterolemia Familiar ou HF, uma das doenças monogênicas mais comuns, foi\ndescrita como doença de herança autossômica dominante, sendo caracterizada pela elevação do\nCT e do LDL-c. Sobre isso, assinale a alternativa INCORRETA:","options":{"A":"Variantes genéticas, que levem a uma menor produção de uma destas proteínas ou mesmo a\nproteínas com menor atividade biológica, têm como consequência um clearance maior das\npartículas de LDL e resultam em hipercolesterolemia.","B":"O defeito mais frequente na HF é uma mutação no gene específico do receptor para LDL\nplasmático.","C":"Localizado na superfície das células hepáticas e de outros órgãos, o receptor para LDL\nplasmático liga-se à LDL via ApoB e facilita sua captação, realizada por um mecanismo de\ninternalização e endocitose do complexo LDL.","D":"Quando ocorre alguma mutação que altere sua estrutura ou função, o nível de remoção de LDL\ndo plasma diminui, e o nível plasmático de LDL\naumenta em proporção inversa ao número de\nreceptores funcionais presentes."},"answer":"A","source":"Clinica médica/MED CLM 03/MED CLM 03.txt","sourceLabel":"MED · MED CLM 03","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-03-174491","number":"174491","sourceNumber":"174491","collectionBlock":"med:med-clinica-medica-med-clm-03","collectionLabel":"MED · MED CLM 03","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 03","subtopic":"","stem":"Durante ambulatório de hipertensão foi discutido em grupo as metas pressóricas\naceitas como adequadas atualmente, sendo que foi\nimportante entender que situações clínicas\ndiversas também indicam metas diferentes. Sobre isso, assinale a alternativa INCORRETA:","options":{"A":"Hipertensos com PA no estágio 3, embora de alto risco CV, deverão ter como meta pressórica a\nPA < 140/90 mmHg,7 pois não há evidências\ncientíficas que suportem reduções mais intensas da\nPA.","B":"Para hipertensos sem controle adequado da PA, recomendam-se avaliações médicas\nsemestrais, com o objetivo de alcançar a meta\npressórica recomendada o mais breve possível\nmediante ajustes terapêuticos sequenciais.","C":"Para hipertensos idosos \"maior ou igual a\" 80 anos, não há evidência de benefícios\nproporcionados por cifras < 140 mmHg, além de\naumentar a possibilidade de efeitos adversos.","D":"A presença de HSI impõe cuidado com a redução exagerada da PAD, que deverá ser\nprudentemente mantida acima de 60 mmHg ou mesmo 65 mmHg na presença de DAC."},"answer":"B","source":"Clinica médica/MED CLM 03/MED CLM 03.txt","sourceLabel":"MED · MED CLM 03","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-03-174419","number":"174419","sourceNumber":"174419","collectionBlock":"med:med-clinica-medica-med-clm-03","collectionLabel":"MED · MED CLM 03","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 03","subtopic":"","stem":"Durante uma consulta em seu ambulatório, você foi questionado rudemente por um\npaciente sobre sua prescrição, o mesmo alegava que não via motivo para a prescrição de\nmedicação para o ?Colesterol?, uma vez que o mesmo não sentia absolutamente nenhum sintoma.\nTodas as justificativas abaixo são adequadas, EXCETO:","options":{"A":"A Doença Arterial Coronariana (DAC) é a principal causa de mortalidade no mundo ocidental.","B":"Nos últimos 30 anos, o tratamento dos fatores de risco cardiovascular resultou na redução de\n90% das mortes por DAC, em grande parte\ndevido ao advento das estatinas.","C":"A eficácia comprovada das estatinas, além do bom perfil de segurança, aliados ao baixo custo,\ntêm sido os principais determinantes do\naumento do uso.","D":"O grande debate atual sobre a prevenção de doenças cardiovasculares refere-se, cada vez\nmais, à questão de como e quando usar\nestatinas no controle efetivo do risco cardiovascular sem\nincorrer em banalização e super tratamento com potencial aumento de efeitos adversos."},"answer":"B","source":"Clinica médica/MED CLM 03/MED CLM 03.txt","sourceLabel":"MED · MED CLM 03","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-03-182493","number":"182493","sourceNumber":"182493","collectionBlock":"med:med-clinica-medica-med-clm-03","collectionLabel":"MED · MED CLM 03","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 03","subtopic":"","stem":"Um paciente de 50 anos procura a Emergência por cefaleia. Refere história de\nrevascularização miocárdica há 1 ano e nega dor precordial. Ao exame físico, é detectada PA =\n200x120mnnHg sem 3a ou 4a bulha. O exame neurológico é normal. Qual é o diagnóstico mais\nprovável e qual é a melhor conduta terapêutica para o caso?","options":{"A":"emergência hipertensiva; nitroglicerina intravenosa","B":"urgência hipertensiva; captopril oral e administração de analgésico","C":"urgência hipertensiva; nitroprussiato de sódio intravenoso e administração de analgésico","D":"emergência hipertensiva; metoprolol intravenoso"},"answer":"A","source":"Clinica médica/MED CLM 03/MED CLM 03.txt","sourceLabel":"MED · MED CLM 03","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-03-174401","number":"174401","sourceNumber":"174401","collectionBlock":"med:med-clinica-medica-med-clm-03","collectionLabel":"MED · MED CLM 03","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 03","subtopic":"","stem":"Eduarda, 2 anos, apresenta diarreia (10 episódios, líquido, fétido, amarelado) e vômitos\n(3 episódios com restos alimentares) há um dia,\nnega febre, chegou no PSI em REG, acianótica,\nanictérica, afebril, eupneica, Glasgow 15. Coração e Pulmão normais; abdome normotenso,\nlevemente doloroso à palpação profunda, S/ VCM, RHA aumentados; DB negativo; pulsos cheios e\nperfusão periférica de 4 segundos; sem sinais meníngeos. Realizado expansão 40 ml/Kg quando a\ncriança apresentou edema generalizado. Foi aferida PA e a mesma encontra-se acima do percentil\n99 para o sexo, idade, peso e estatura. A melhor maneira para tratar esse paciente é administrar:","options":{"A":"Hipontensor para reduzir a PA em 1/3 nas primeiras 24 h.","B":"Hipotensor para reduzir a PA em 1/3 nas primeiras 6 h.","C":"Nitroprussiato de sódio para reduzir a PA em 10% nos primeiros minutos.","D":"Espironolactona (hipotensor de escolha) para reduzir a PA em 2/3 nas primeiras 6 h."},"answer":"B","source":"Clinica médica/MED CLM 03/MED CLM 03.txt","sourceLabel":"MED · MED CLM 03","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-03-186441","number":"186441","sourceNumber":"186441","collectionBlock":"med:med-clinica-medica-med-clm-03","collectionLabel":"MED · MED CLM 03","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 03","subtopic":"","stem":"Adolescente afrodescendente, sexo masculino, 12 anos, apresenta curva de estatura\nno percentil 50, e IMC no percentil 90. Ao\nlongo dos últimos 3 meses apresentou as seguintes\naferições de PA: 1) 126 x 84mmHg; 2) 130 x 84mmHg; 3) 128 x 80mmHg. Assintomático com\nantecedentes familiares de hipertensão. Considerando-se que os limites de PA normal são: P50:\n111 x 63mmHg, P90: 125 x 78mmHg, P95: 128 x 82mmHg e P99: 136 x 90mmHg, pode-se afirmar\nque:","options":{"A":"O adolescente apresenta pré-hipertensão e a conduta é seguimento clínico.","B":"O adolescente tem hipertensão arterial estágio I, devendo-se instituir tratamento\nmedicamentoso.","C":"Deve-se investigar acometimento de órgãos alvo com exame de fundo de olho e\necocardiograma antes de definir o tratamento.","D":"Devido à idade precoce de apresentação do quadro, primeiramente deve-se investigar\ncomorbidades associadas a HAS como lúpus eritematoso sistêmico."},"answer":"C","source":"Clinica médica/MED CLM 03/MED CLM 03.txt","sourceLabel":"MED · MED CLM 03","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-03-156986","number":"156986","sourceNumber":"156986","collectionBlock":"med:med-clinica-medica-med-clm-03","collectionLabel":"MED · MED CLM 03","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 03","subtopic":"","stem":"Sobre o tratamento farmacológico no idoso hipertenso, marque a INCORRETA.","options":{"A":"A pressão diastólica não deve ser superior a 70 mmHg, principalmente nos pacientes com\nhipertensão arterial sistólica acima dos 80 anos e portadores de doença arterial coronariana.","B":"É menos efetivo em pacientes mais jovens, com menor redução de eventos cardiovasculares.","C":"A maioria desses pacientes com hipertensão estágio 3 requerem 2 ou mais medicamentos de\nclasse diferentes para o controle pressórico","D":"Os tiazídicos reduzem eventos cerebrais e cardiovasculares, mas relacionam-se com\ncomorbidades como prostatismo, insuficiência renal e dislipidemia."},"answer":"B","source":"Clinica médica/MED CLM 03/MED CLM 03.txt","sourceLabel":"MED · MED CLM 03","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-03-158454","number":"158454","sourceNumber":"158454","collectionBlock":"med:med-clinica-medica-med-clm-03","collectionLabel":"MED · MED CLM 03","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 03","subtopic":"","stem":"No Brasil a HA atinge por volta de 32,5% da população adulta e suas complicações tem\num impacto elevado na perda de produtividade do trabalho e da renda familiar (US$ 4,18 bilhões\nentre 2006 e 2015). O tratamento não medicamentoso com mudança do estilo de vida tem grande\nimportância no controle dos níveis pressóricos dessa população. Qual das medidas não\nfarmacológicas a seguir tem maior impacto na redução os níveis pressóricos?","options":{"A":"Realização de atividade física regular.","B":"Restrição do consumo de sal.","C":"Redução do peso corporal.","D":"Moderação no consumo de álcool."},"answer":"C","source":"Clinica médica/MED CLM 03/MED CLM 03.txt","sourceLabel":"MED · MED CLM 03","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-03-157300","number":"157300","sourceNumber":"157300","collectionBlock":"med:med-clinica-medica-med-clm-03","collectionLabel":"MED · MED CLM 03","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 03","subtopic":"","stem":"Paciente homem, 58 anos, diagnosticado na emergência com Infarto Agudo do\nMiocárdio, apresenta-se com PA = 210 x 120 mmHg, Killip II. Assinale a alternativa com o\nanti-hipertensivo venoso mais apropriado para esse caso.","options":{"A":"Nitroprussiato de Sódio.","B":"Nitroglicerina.","C":"Metoprolol.","D":"Hidralazina.","E":"Furosemida."},"answer":"B","source":"Clinica médica/MED CLM 03/MED CLM 03.txt","sourceLabel":"MED · MED CLM 03","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-03-160524","number":"160524","sourceNumber":"160524","collectionBlock":"med:med-clinica-medica-med-clm-03","collectionLabel":"MED · MED CLM 03","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 03","subtopic":"","stem":"Homem de 48 anos vai ao ambulatório com história de hipertensão arterial\ndiagnosticada há 2 meses, em uso regular de\nenalapril 20 mg/dia, queixando cansaço e fadiga\ncrônicos, sonolência excessiva, chegando a dormir ao assistir TV, ao ler um livro, ou até mesmo em\numa fila enquanto aguarda para ser atendido. Esses sintomas iniciaram há 6 meses, de caráter\nprogressivo. É tabagista e sedentário. Ao exame físico: PA = 152/102 mmHg, FC = 96 bpm, IMC =\n33,2 kg/m2. A hipótese mais provável e o método de escolha para investigação são,\nrespectivamente:","options":{"A":"DPOC; espirometria e radiografia de tórax.","B":"Síndrome da apneia do sono; polissonografia.","C":"Insuficiência cardíaca; eletrocardiograma e ecocardiograma.","D":"Descondicionamento físico; teste ergométrico."},"answer":"B","source":"Clinica médica/MED CLM 03/MED CLM 03.txt","sourceLabel":"MED · MED CLM 03","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-03-150245","number":"150245","sourceNumber":"150245","collectionBlock":"med:med-clinica-medica-med-clm-03","collectionLabel":"MED · MED CLM 03","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 03","subtopic":"","stem":"Mulher de 75 anos dá entrada no pronto-socorro referindo intensa cefaleia associada a\nconfusão mental, vômitos e sudorese. Ao exame, apresentava desvio da rima labial para a\nesquerda e PA = 240x140 mmHg em ambos os membros superiores. Qual é o diagnóstico mais\nprovável?","options":{"A":"Emergência hipertensiva.","B":"Edema agudo de pulmão.\n\n.","C":"Urgência hipertensiva","D":"Dissecção de aorta."},"answer":"A","source":"Clinica médica/MED CLM 03/MED CLM 03.txt","sourceLabel":"MED · MED CLM 03","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-03-149226","number":"149226","sourceNumber":"149226","collectionBlock":"med:med-clinica-medica-med-clm-03","collectionLabel":"MED · MED CLM 03","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 03","subtopic":"","stem":"Em toda consulta, Nestor da Silva apresenta, na sua avaliação médica, uma\nelevação de 20 mmHg em sua medida da pressão sistólica. Refere que isso se deve à\nansiedade causada pela consulta profissional, mas em casa, ao utilizar aparelho devidamente\ncertificado e calibrado, sua pressão sistólica se encontra em 125 mmHg. Assim, ele pode ser\nclassificado como ?vítima? do efeito de avental branco. Sobre isso, conclui-se que:","options":{"A":"Seu diagnóstico irá mudar.","B":"Será agora classificado como hipertenso.","C":"Pode ocorrer falsa impressão de necessidade de adequação medicamentosa.","D":"Agora é classificado como hipertenso sistólico isolado."},"answer":"C","source":"Clinica médica/MED CLM 03/MED CLM 03.txt","sourceLabel":"MED · MED CLM 03","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-03-149233","number":"149233","sourceNumber":"149233","collectionBlock":"med:med-clinica-medica-med-clm-03","collectionLabel":"MED · MED CLM 03","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 03","subtopic":"","stem":"Paciente masculino de 46 anos de idade apresentou quadro de mal-estar geral e\ndesorientação com agitação associada. Foi realizada tomografia de crânio que demonstrou edema\ncerebral difuso, e sua pressão foi aferida inicialmente com valor de 230 x 130 mmHg. Assim, foi\ninicialmente firmado diagnóstico de encefalopatia hipertensiva. Acerca desse quadro clínico, indique\na opção CORRETA:","options":{"A":"Assim que se obter controle da emergência hipertensiva com medicação via venosa, devemos\niniciar medicação menos tóxica por via oral.","B":"Disfunções orgânicas não interagem nessa situação clínica.","C":"Fica contraindicado o uso de medicações tóxicas nessa situação clínica.","D":"Reduzir a pressão pode deteriorar função neurológica, sendo, portanto, contraindicado redução\nda pressão."},"answer":"A","source":"Clinica médica/MED CLM 03/MED CLM 03.txt","sourceLabel":"MED · MED CLM 03","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-03-156509","number":"156509","sourceNumber":"156509","collectionBlock":"med:med-clinica-medica-med-clm-03","collectionLabel":"MED · MED CLM 03","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 03","subtopic":"","stem":"Marque a afirmativa correta sobre as drogas utilizadas no tratamento da hipertensão\narterial:","options":{"A":"A losartana é um vasodilatador","B":"A hidralazina é um bloqueador dos receptores de angiotensina II","C":"O propranolol é um inibidor adrenérgico de ação central","D":"O Enalapril é um inibidor da enzima de conversão de angiotensina II"},"answer":"D","source":"Clinica médica/MED CLM 03/MED CLM 03.txt","sourceLabel":"MED · MED CLM 03","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-03-149258","number":"149258","sourceNumber":"149258","collectionBlock":"med:med-clinica-medica-med-clm-03","collectionLabel":"MED · MED CLM 03","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 03","subtopic":"","stem":"A pseudo-hipertensão pode ser detectada pela manobra de Osler, ou seja, a\nartéria radial permanece ainda palpável após a insuflação do manguito pelo menos 30 mmHg\nacima do desaparecimento do pulso radial. Isso está relacionado:","options":{"A":"Ao processo arteriosclerótico no idoso.","B":"A arritmias cardíacas.","C":"Ao aneurisma arterial.","D":"Ao manguito sem tamanho adequado."},"answer":"A","source":"Clinica médica/MED CLM 03/MED CLM 03.txt","sourceLabel":"MED · MED CLM 03","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-03-149262","number":"149262","sourceNumber":"149262","collectionBlock":"med:med-clinica-medica-med-clm-03","collectionLabel":"MED · MED CLM 03","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 03","subtopic":"","stem":"A respeito da Hipertensão Mascarada, marque a opção CORRETA.","options":{"A":"Não se relaciona com maior risco na população diabética.","B":"É caracterizada por valores normais da PA no consultório, porém com PA elevada pela MAPA ou\nmedidas residenciais.","C":"Não ocorre relação com dados pessoais, como sexo masculino, tabagismo, consumo de álcool,\natividade física e hipertensão induzida pelo exercício.","D":"Sua prevalência é menor quando a PA do consultório está no nível limítrofe."},"answer":"B","source":"Clinica médica/MED CLM 03/MED CLM 03.txt","sourceLabel":"MED · MED CLM 03","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-03-149255","number":"149255","sourceNumber":"149255","collectionBlock":"med:med-clinica-medica-med-clm-03","collectionLabel":"MED · MED CLM 03","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 03","subtopic":"","stem":"A compreensão do quadro clínico chamado de crise hipertensiva necessita da análise\nde diversos fatores relacionados, NÃO podendo\nser associado a eles:","options":{"A":"O tempo para medicação e controle.","B":"O risco de lesão em órgão-alvo.","C":"A lesão em órgão-alvo.","D":"A presença de cefaleia."},"answer":"D","source":"Clinica médica/MED CLM 03/MED CLM 03.txt","sourceLabel":"MED · MED CLM 03","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-03-157362","number":"157362","sourceNumber":"157362","collectionBlock":"med:med-clinica-medica-med-clm-03","collectionLabel":"MED · MED CLM 03","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 03","subtopic":"","stem":"Hipertensão arterial é a condição clínica multifatorial caracterizada por elevação\nsustentada dos níveis pressóricos, comumente\nassociada a distúrbios metabólicos, alterações\nfuncionais e estruturais de órgãos-alvo. Mantém associação independente com eventos, como\nmorte súbita, acidente vascular encefálico, infarto agudo do miocárdio, entre outros. A esse\nrespeito, indique a alternativa CORRETA:","options":{"A":"No Brasil, acomete mais de 60% dos idosos.","B":"A hipertensão contribui direta ou indiretamente para 80% das mortes por Doença Cardiovascular\n(DCV).","C":"Junto com DM, suas complicações (cardíacas, renais e AVE) têm impacto sutil na perda da\nprodutividade do trabalho e da renda familiar.","D":"Doença Cardiovascular é a quinta causa de morte no Brasil."},"answer":"A","source":"Clinica médica/MED CLM 03/MED CLM 03.txt","sourceLabel":"MED · MED CLM 03","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-03-157369","number":"157369","sourceNumber":"157369","collectionBlock":"med:med-clinica-medica-med-clm-03","collectionLabel":"MED · MED CLM 03","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 03","subtopic":"","stem":"Hipertensão arterial é a condição comumente associada a distúrbios hidroeletrolíticos e\na alterações funcionais e estruturais de\nórgãos-alvo. A ingestão de sal a influencia diretamente.\n\nSegundo os dados da última diretriz, indique a alternativa considerada INADEQUADA:","options":{"A":"O consumo excessivo de sódio, um dos principais FR para HA, associa-se a eventos CV e\nrenais.","B":"No Brasil, dados indicam que, em muitos domicílios, mostraram disponibilidade domiciliar de 4,7\ng de sódio/pessoa/dia (ajustado para\nconsumo de 2.000 kcal), excedendo em mais de duas vezes o\nconsumo máximo recomendado.","C":"Apenas a minoria das pessoas entrevistadas reconhece o conteúdo alto ou muito alto de sal nos\nalimentos.","D":"O consumo de sódio é maior na área urbana da região Sudeste, e menor nos domicílios rurais\nda região Norte."},"answer":"D","source":"Clinica médica/MED CLM 03/MED CLM 03.txt","sourceLabel":"MED · MED CLM 03","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-03-157383","number":"157383","sourceNumber":"157383","collectionBlock":"med:med-clinica-medica-med-clm-03","collectionLabel":"MED · MED CLM 03","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 03","subtopic":"","stem":"Dentre os achados que relacionam a hipertensão a fatores socioeconômicos, de acordo\ncom a diretriz em vigor, assinale a\nalternativa INCORRETA:","options":{"A":"Adultos com menor nível de escolaridade apresentaram a maior prevalência de HA autorreferida\n(31,1%).","B":"Adultos com menor nível de escolaridade apresentaram a menor prevalência de HA autorreferida\nem relação a que concluiu o Ensino Fundamental.","C":"A proporção de hipertensos diminuiu naqueles que completam o Ensino Fundamental.","D":"Dados de estudos brasileiros, realizados com funcionários de seis universidades e hospitais\nuniversitários do Brasil com maior nível de\nescolaridade, apresentaram uma prevalência de HA de\n35,8%, sendo maior entre homens."},"answer":"B","source":"Clinica médica/MED CLM 03/MED CLM 03.txt","sourceLabel":"MED · MED CLM 03","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-03-157390","number":"157390","sourceNumber":"157390","collectionBlock":"med:med-clinica-medica-med-clm-03","collectionLabel":"MED · MED CLM 03","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 03","subtopic":"","stem":"A Hipertensão Arterial (HA) é a condição clínica multifatorial que leva à elevação\nsustentada dos níveis pressóricos ? 140 e/ou 90\nmmHg. Frequentemente, está associada a\ndistúrbios metabólicos, alterações funcionais e/ou estruturais de órgãos-alvo, sendo agravada pela\npresença de outros fatores de risco, como a genética, que influencia a sua ocorrência. Acerca da\nHipertensão Arterial, marque a opção considerada INCORRETA:","options":{"A":"Estudos brasileiros que avaliaram o impacto de polimorfismos genéticos na população de\nquilombolas não conseguiram identificar um padrão mais prevalente.","B":"Mostraram forte impacto da miscigenação, dificultando ainda mais a identificação de um padrão\ngenético para a elevação dos níveis pressóricos.","C":"Mostraram pequeno impacto da miscigenação, no padrão genético para a elevação dos níveis\npressóricos.","D":"A miscigenação dificulta mais a identificação de um padrão genético para a elevação dos níveis\npressóricos."},"answer":"C","source":"Clinica médica/MED CLM 03/MED CLM 03.txt","sourceLabel":"MED · MED CLM 03","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-03-157397","number":"157397","sourceNumber":"157397","collectionBlock":"med:med-clinica-medica-med-clm-03","collectionLabel":"MED · MED CLM 03","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 03","subtopic":"","stem":"A ingestão de bebidas alcoólicas interfere de maneira diversa nos achados de\nhipertensão da população. Desse modo, aponte a alternativa INCORRETA:","options":{"A":"Ingestão de álcool crônico e elevado aumenta a PA de forma consistente.","B":"Em mulheres, houve efeito protetor com dose inferior a 10 g de álcool/dia.","C":"Em mulheres, houve risco de hipertensão com consumo de 100 g de álcool/dia.","D":"Em ambos os sexos, o consumo abusivo de bebidas alcoólicas foi mais frequente entre os mais\njovens e aumentou com o nível de escolaridade."},"answer":"C","source":"Clinica médica/MED CLM 03/MED CLM 03.txt","sourceLabel":"MED · MED CLM 03","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-03-157404","number":"157404","sourceNumber":"157404","collectionBlock":"med:med-clinica-medica-med-clm-03","collectionLabel":"MED · MED CLM 03","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 03","subtopic":"","stem":"Em relação ao sedentarismo e à hipertensão, ocorrem diversos dados relevantes, com\nEXCEÇÃO do seguinte. Aponte-o.","options":{"A":"Observou-se associação significativa entre HA e idade, sexo masculino, sobrepeso, adiposidade\ncentral, sedentarismo nos momentos de folga e\ndurante o trabalho, escolaridade inferior a 8 anos e\nrenda per capita < 3 salários mínimos.","B":"Dados apontam que indivíduos insuficientemente ativos (adultos que não atingiram pelo menos\n150 minutos semanais de atividade física\nconsiderando o lazer, o trabalho e o deslocamento)\nrepresentaram grande parte dos adultos, sendo o percentual significantemente menor entre as\nmulheres.","C":"Houve diferença nas frequências de insuficientemente ativos entre as faixas etárias, com\ndestaque para idosos (62,7%).","D":"Houve diferença nas frequências de insuficientemente ativos para adultos sem instrução e com\nnível de escolaridade fundamental incompleto."},"answer":"B","source":"Clinica médica/MED CLM 03/MED CLM 03.txt","sourceLabel":"MED · MED CLM 03","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-03-160486","number":"160486","sourceNumber":"160486","collectionBlock":"med:med-clinica-medica-med-clm-03","collectionLabel":"MED · MED CLM 03","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 03","subtopic":"","stem":"Dr. João assume uma estratégia de saúde da familía. Dentro da equipe, descobre que\no nível de violência familiar na comunidade\né alto. Em seu primeiro dia de trabalho recebe a família\nde Maria e José para atendimento. Esta utiliza com frequência a unidade. Maria e José têm 3 filhos:\nAna (6 anos), Ester (18 anos) e Pedro (9 anos); além deles, mora com a família, Carlos, pai de\nMaria, um senhor de 79 anos, que possui hipertensão arterial e diabetes. Possui uma capsulite\nadesiva intensa e dificuldade visual. Sobre a hipertensão do Sr. Carlos, sabe-se que","options":{"A":"é importante associar a dietary approaches to stop hipertension (DASH) para o paciente.","B":"os betabloqueadores são a melhor opção terapêutica para o paciente.","C":"os níveis pressóricos de 140-159 e 90-99 mmhg são aceitáveis para pacientes com 79 anos.","D":"deve-se avaliar o paciente todos os meses devido à sua pressão e idade."},"answer":"A","source":"Clinica médica/MED CLM 03/MED CLM 03.txt","sourceLabel":"MED · MED CLM 03","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-03-150276","number":"150276","sourceNumber":"150276","collectionBlock":"med:med-clinica-medica-med-clm-03","collectionLabel":"MED · MED CLM 03","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 03","subtopic":"","stem":"Pré-escolar do sexo masculino, de quatro anos, foi encaminhado ao pediatra pela\nsuspeita de hipertensão arterial. Peso = 16 kg (percentil 50) e estatura = 103 cm (percentil 50).\nAferida a pressão arterial por três vezes, em momentos diferentes e em condições ideais, as\nmedidas foram: 107/65, 108/68, 108/69 mmHg. (Conforme a imagem do caderno de questões).\nCom base nos resultados, o pré-escolar é classificado como:","options":{"A":"Hipertenso.","B":"Pré-hipertenso.","C":"Hipotenso.","D":"Normotenso."},"answer":"B","source":"Clinica médica/MED CLM 03/MED CLM 03.txt","sourceLabel":"MED · MED CLM 03","images":["question_bank/media/medcurso/med-clinica-medica-med-clm-03/150276.png"],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-03-129820","number":"129820","sourceNumber":"129820","collectionBlock":"med:med-clinica-medica-med-clm-03","collectionLabel":"MED · MED CLM 03","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 03","subtopic":"","stem":"Paciente do sexo masculino, de 51 anos, chega ao consultório com medidas\ndomiciliares persistentemente acima de 140/90 mmHg,\nmesmo com modificação de estilo de vida\nem duas consultas médicas anteriores. Assintomático do ponto de vista cardiovascular, tem como\ncomorbidades dislipidemia e hiperuricemia com sintomas de gota. Qual das medicações deve ser\nevitada, neste paciente?","options":{"A":"Enalapril.","B":"Losartana.","C":"Amlodipina.","D":"Hidroclorotiazida."},"answer":"D","source":"Clinica médica/MED CLM 03/MED CLM 03.txt","sourceLabel":"MED · MED CLM 03","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-03-127344","number":"127344","sourceNumber":"127344","collectionBlock":"med:med-clinica-medica-med-clm-03","collectionLabel":"MED · MED CLM 03","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 03","subtopic":"","stem":"Durante a escolha de medicações para tratamento de hipertensão, ocorre a\nnecessidade da individualização, de acordo com o quadro clínico. Qual das mediações abaixo\napresenta correlação INADEQUADA?","options":{"A":"Diabéticos utilizam IECA.","B":"Diabéticos utilizam nifedipina.","C":"Migrâneas podem indicar betabloqueadores.","D":"Pacientes com insuficiência coronariana podem utilizar antagonistas do canal de cálcio não\ndiidropirimidínicos."},"answer":"B","source":"Clinica médica/MED CLM 03/MED CLM 03.txt","sourceLabel":"MED · MED CLM 03","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-03-136602","number":"136602","sourceNumber":"136602","collectionBlock":"med:med-clinica-medica-med-clm-03","collectionLabel":"MED · MED CLM 03","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 03","subtopic":"","stem":"Paciente deu entrada no hospital com intensa dor torácica que irradiava para dorso.\nSeu Eletrocardiograma demonstrava alteração de\nrepolarização, estando o paciente hipertenso\ncom PA de 200x120 mm Hg. Foi iniciado Nitroglicerina, Atenolol VO e Captopril SL, mas como a\ndor não melhorava e a Radiografia Torácica demonstrava uma imagem mediastinal que não era\nfisiológica, foi solicitada tomografia torácica que diagnosticou uma dissecção aórtica. Então, é\niniciado Nitroprussiato EV além de Metoprolol EV. Qual das medicações abaixo utilizadas apresenta\ninteração tóxica com o metabolismo oxidativo?","options":{"A":"Captopril.","B":"Metoprolol.","C":"Nitroprussiato de Sódio.","D":"Nitroglicerina."},"answer":"C","source":"Clinica médica/MED CLM 03/MED CLM 03.txt","sourceLabel":"MED · MED CLM 03","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-03-136999","number":"136999","sourceNumber":"136999","collectionBlock":"med:med-clinica-medica-med-clm-03","collectionLabel":"MED · MED CLM 03","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 03","subtopic":"","stem":"José, 52 anos, hipertenso controlado, comparece à unidade básica de saúde. Relata\nque mostrou exames há seis meses, que\nevidenciaram \"colesterol alto\" e que \"o doutor orientou a\nmelhorar a alimentação e a retornar com novos exames após o período de seis meses\". Durante a\nconsulta, negou outras comorbidades ou história de evento cardiovascular prévio. Paciente entrega\nexames que mostram: colesterol total: 242 mg/dl; triglicerídeos: 390; LDL: 123. Risco cardiovascular\nglobal calculado de 6,5%. A MELHOR conduta, nesta situação, é:","options":{"A":"Sinvastatina 40 mg/dia e ciprofibrato 100 mg/dia.","B":"Somente sinvastatina 40 mg/dia.","C":"Somente ciprofibrato 100 mg/dia.","D":"Somente orientações alimentares."},"answer":"D","source":"Clinica médica/MED CLM 03/MED CLM 03.txt","sourceLabel":"MED · MED CLM 03","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-03-127660","number":"127660","sourceNumber":"127660","collectionBlock":"med:med-clinica-medica-med-clm-03","collectionLabel":"MED · MED CLM 03","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 03","subtopic":"","stem":"Escolar de três anos, no percentil 10 para peso e estatura, é atendido em consulta de\nrotina. Sua pressão arterial foi aferida com manguito cobrindo 2/3 do comprimento e circundando\n80% do diâmetro de seu braço. Foram constatados valores tensionais sistólicos e diastólicos entre\nos percentis 90 a 95 para idade e sexo. A conduta no presente caso é:","options":{"A":"Adequar o manguito do aparelho de pressão.","B":"Iniciar a investigação etiológica da hipertensão arterial.","C":"Aferir a pressão em mais duas consultas sucessivas.","D":"Tratar a criança, pois está hipertensa."},"answer":"C","source":"Clinica médica/MED CLM 03/MED CLM 03.txt","sourceLabel":"MED · MED CLM 03","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-03-109337","number":"109337","sourceNumber":"109337","collectionBlock":"med:med-clinica-medica-med-clm-03","collectionLabel":"MED · MED CLM 03","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 03","subtopic":"","stem":"A aterosclerose é uma doença sistêmica, na qual ocorre acúmulo de lipídio e de\nmaterial fibroso na camada","options":{"A":"endotelial.","B":"intimal.","C":"média.","D":"muscular."},"answer":"B","source":"Clinica médica/MED CLM 03/MED CLM 03.txt","sourceLabel":"MED · MED CLM 03","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-03-106732","number":"106732","sourceNumber":"106732","collectionBlock":"med:med-clinica-medica-med-clm-03","collectionLabel":"MED · MED CLM 03","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 03","subtopic":"","stem":"Mulher de 62 anos de idade procura o seu consultório para consulta de rotina. Refere\nestar sentindo-se bem, sem queixas. Apresenta\nantecedentes de hipertensão arterial, diabetes\nmellitus e colocação de stent para artéria coronária direita há dois anos. Exame clínico: PA = 150 x\n90 mmHg, FC = 72 bpm, IMC = 32 kg/m². Coração: bulhas rítmicas, sem sopros. Pulmões:\nmurmúrios vesiculares simétricos sem ruídos adventícios. Medicações em uso: losartana = 50 mg\nduas vezes ao dia; metformina = 850 mg duas vezes ao dia; AAS = 100 mg ao dia. Quais as metas\na serem atingidas para esta paciente em relação à pressão arterial e nível de LDL-colesterol?","options":{"A":"PA = 130 x 80 mmHg; LDL < 70 mg/dl.","B":"PA < 140 x 90 mmHg; LDL < 70 mg/dl.","C":"PA = 120 x 80 mmHg; LDL < 100 mg/dl.","D":"PA = 120 x 70 mmHg; LDL < 100 mg/dl."},"answer":"A","source":"Clinica médica/MED CLM 03/MED CLM 03.txt","sourceLabel":"MED · MED CLM 03","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-03-78151","number":"78151","sourceNumber":"78151","collectionBlock":"med:med-clinica-medica-med-clm-03","collectionLabel":"MED · MED CLM 03","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 03","subtopic":"","stem":"Homem, 52 anos, refere ganho progressivo de peso após seu casamento, há 13 anos.\nHipertensão arterial diagnosticada há 8 anos. Pai e mãe obesos e diabéticos. IMC = 34 kg/m²;\ncircunferência abdominal = 108 cm; PA = 130 X 90 mmHg; colesterol total = 224 mg/dL; colesterol\nHDL = 29 mg/dL; triglicerídios = 448 mg/dL; ácido úrico = 8,3 mg/dL; glicemia de jejum = 112\nmg/dL; insulina = 27 µU/ml. De acordo com o quadro clínico deste paciente:","options":{"A":"a dislipidemia favorece o desenvolvimento de aterosclerose, pois as concentrações séricas\nelevadas de triglicérides resultam em alterações nas partículas de LDL que se tornam cada vez\nmaiores.","B":"a resistência insulínica pode resultar em hiperglicemia, levando assim à redução da produção\nhepática de glicose.","C":"os dados clínicos e laboratoriais permitem classificá-lo como tendo síndrome metabólica de\nacordo com os critérios da IDF (International Diabetes Federation).","D":"a hiperuricemia deve-se provavelmente a uma doença reumatológica."},"answer":"C","source":"Clinica médica/MED CLM 03/MED CLM 03.txt","sourceLabel":"MED · MED CLM 03","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-03-85378","number":"85378","sourceNumber":"85378","collectionBlock":"med:med-clinica-medica-med-clm-03","collectionLabel":"MED · MED CLM 03","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 03","subtopic":"","stem":"Paciente de 38 anos, sexo masculino, chega ao ambulatório preocupado com as\ndoenças do coração. Pergunta sobre os\nprováveis riscos de sofrer um infarto agudo do miocárdio\nou um acidente vascular encefálico e gostaria de saber se há como prever e prevenir tais eventos.\nSegundo a Diretriz de Prevenção Cardiovascular de 2013, como você poderia estratificar seu\npaciente?","options":{"A":"O Risco por Tempo de Vida (RTV) avalia a probabilidade de um indivíduo, a partir de 45 anos,\napresentar um evento isquêmico.","B":"Escore de Risco Framingham (ERF) é usado para avaliar risco de infarto agudo do miocárdio ou\nmorte por doença coronária no período de 10 anos em indivíduos com diagnóstico prévio de\naterosclerose clínica.","C":"Portadores de doença renal crônica já se enquadram no risco intermediário, mesmo sem avaliar\noutros critérios.","D":"A síndrome metabólica é fator agravante de risco e seu diagnóstico pode ser feito utilizando o\nHAS e o DM como fatores essencias, associado à hipercolesterolemia."},"answer":"A","source":"Clinica médica/MED CLM 03/MED CLM 03.txt","sourceLabel":"MED · MED CLM 03","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-03-61265","number":"61265","sourceNumber":"61265","collectionBlock":"med:med-clinica-medica-med-clm-03","collectionLabel":"MED · MED CLM 03","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 03","subtopic":"","stem":"A causa mais comum de hipertensão renovascular no jovem é:","options":{"A":"Arterite renal.","B":"Coarctação da aorta.","C":"Displasia fibromuscular.","D":"Aterosclerose.","E":"Nefroangiite."},"answer":"C","source":"Clinica médica/MED CLM 03/MED CLM 03.txt","sourceLabel":"MED · MED CLM 03","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-03-62717","number":"62717","sourceNumber":"62717","collectionBlock":"med:med-clinica-medica-med-clm-03","collectionLabel":"MED · MED CLM 03","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 03","subtopic":"","stem":"A dislipidemia na síndrome metabólica favorece o desenvolvimento da aterosclerose,\numa vez que:","options":{"A":"os valores do colesterol LDL são em geral muito elevados.","B":"os valores baixos do colesterol HDL provocam elevação dos níveis de triglicérides.","C":"os valores elevados de triglicérides resultam em alterações nas partículas de LDL que se tornam\nmenores e mais aterogênicas.","D":"os valores elevados de triglicérides resultam em aumentos do tamanho das partículas de HDL."},"answer":"C","source":"Clinica médica/MED CLM 03/MED CLM 03.txt","sourceLabel":"MED · MED CLM 03","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-03-61818","number":"61818","sourceNumber":"61818","collectionBlock":"med:med-clinica-medica-med-clm-03","collectionLabel":"MED · MED CLM 03","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 03","subtopic":"","stem":"A Síndrome da Apneia-Hipopneia Obstrutiva do Sono (SAHOS) é uma doença de\ngrande impacto na qualidade de vida dos\npacientes. Dentre as comorbidades a seguir, qual NÃO\ntem relação com esta doença?","options":{"A":"Hipertensão arterial.","B":"DPOC.","C":"Dislipidemia.","D":"Alterações no metabolismo da glicose.","E":"NDA."},"answer":"B","source":"Clinica médica/MED CLM 03/MED CLM 03.txt","sourceLabel":"MED · MED CLM 03","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-03-53554","number":"53554","sourceNumber":"53554","collectionBlock":"med:med-clinica-medica-med-clm-03","collectionLabel":"MED · MED CLM 03","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 03","subtopic":"","stem":"Homem, 26 anos, com HAS refratária, hipopotassemia e excesso de potássio na urina\nde 24 horas mais provavelmente apresenta:","options":{"A":"estenose de artéria renal.","B":"feocromocitoma.","C":"hiperplasia unilateral da adrenal.","D":"hipertensão arterial sistêmica primária.","E":"adenoma unilateral da adrenal."},"answer":"E","source":"Clinica médica/MED CLM 03/MED CLM 03.txt","sourceLabel":"MED · MED CLM 03","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-03-51034","number":"51034","sourceNumber":"51034","collectionBlock":"med:med-clinica-medica-med-clm-03","collectionLabel":"MED · MED CLM 03","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 03","subtopic":"","stem":"A tosse é um efeito colateral comum no uso de inibidores da enzima conversora de\nangiotensina devido ao acúmulo de qual substância?","options":{"A":"Renina.","B":"Angiotensinogênio.","C":"Bradicinina.","D":"Angiotensina I.","E":"Angiotensina II."},"answer":"C","source":"Clinica médica/MED CLM 03/MED CLM 03.txt","sourceLabel":"MED · MED CLM 03","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-03-53537","number":"53537","sourceNumber":"53537","collectionBlock":"med:med-clinica-medica-med-clm-03","collectionLabel":"MED · MED CLM 03","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 03","subtopic":"","stem":"São critérios diagnósticos para a síndrome metabólica, EXCETO:","options":{"A":"Hipertrigliceridemia e hipercolesterolemia com elevação do HDL-c e do LDL-c.","B":"Intolerância à glicose ou glicemia de jejum elevada.","C":"Resistência insulínica.","D":"Hipertensão arterial sistêmica.","E":"Nenhuma das alternativas acima."},"answer":"A","source":"Clinica médica/MED CLM 03/MED CLM 03.txt","sourceLabel":"MED · MED CLM 03","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-03-49013","number":"49013","sourceNumber":"49013","collectionBlock":"med:med-clinica-medica-med-clm-03","collectionLabel":"MED · MED CLM 03","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 03","subtopic":"","stem":"Paciente jovem, de 95 kg e 1,60 m de altura, etilista de fim de semana, sedentário e\ncom sintomas dispéticos foi ao gastroenterologista para \"check up\". Nos exames de rotina\napresentou hipercolesterolemia, leve alteração da TGO e TGP, glicemia normal e ao ultrassom\nesteatose hepática grau leve. Marque a alternativa correta referente ao caso clínico.","options":{"A":"O índice de massa corpórea do paciente é de 36, portanto segundo as definições da\nOrganização Mundial de Saúde o paciente possui obesidade moderada.","B":"O paciente tem um risco de saúde para Diabetes Mellitus e doença cardíaca isquêmica igual a\npacientes com um IMC menor que 28.","C":"O método \"padrão-ouro\" para o diagnóstico da esteatose hepática não alcoólica é a ressonância\nmagnética já que a maioria dos ultrassons vem com o laudo de esteatose hepática leve.","D":"A distribuição de Gordura no corpo é importante com relação à mortalidade; a gordura de\ndistribuição central tem risco mais elevado que a gordura de distribuição periférica.","E":"A causa mais frequente atualmente de paciente de pancreatite aguda é a hipertrigliceridemia da\nsíndrome metabólica."},"answer":"D","source":"Clinica médica/MED CLM 03/MED CLM 03.txt","sourceLabel":"MED · MED CLM 03","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-03-34040","number":"34040","sourceNumber":"34040","collectionBlock":"med:med-clinica-medica-med-clm-03","collectionLabel":"MED · MED CLM 03","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 03","subtopic":"","stem":"Um homem de 54 anos de idade procurou atendimento médico por causa de\npalpitações ocasionais, dispneia, fadiga aos\nesforços e sonolência. A esposa referiu que ele\nroncava muito, havia ganhado peso nos últimos quatro anos e batido o carro por duas vezes nos\núltimos três meses. Ao exame físico, a PA era de 180/110 e a FC = 100 bpm, presença de B4+. O\nhemograma mostrava Ht = 58%. O achado cardíaco mais provável ao exame deste paciente é:","options":{"A":"Estenose da valva mitral ao ecocardiograma.","B":"Episódios repetitivos de taquicardia ventricular ao\nHolter.","C":"Hipertrofia ventricular direita ao ecocardiograma.","D":"Comunicação interatrial ao ecocardiograma."},"answer":"C","source":"Clinica médica/MED CLM 03/MED CLM 03.txt","sourceLabel":"MED · MED CLM 03","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-03-35807","number":"35807","sourceNumber":"35807","collectionBlock":"med:med-clinica-medica-med-clm-03","collectionLabel":"MED · MED CLM 03","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 03","subtopic":"","stem":"Todas as manifestações abaixo são típicas da crise hipertensiva, exceto:","options":{"A":"Hemorragias retinianas.","B":"Pressão arterial diastólica superior a 140mmhg.","C":"Proteinúria.","D":"Estado mental normal.","E":"Confusão mental."},"answer":"D","source":"Clinica médica/MED CLM 03/MED CLM 03.txt","sourceLabel":"MED · MED CLM 03","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-03-35672","number":"35672","sourceNumber":"35672","collectionBlock":"med:med-clinica-medica-med-clm-03","collectionLabel":"MED · MED CLM 03","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 03","subtopic":"","stem":"A medida da pressão arterial deve ser parte do exame de puericultura em todas as\ncrianças a partir de 3 anos de idade. A largura ideal do manguito do esfigmomanômetro é\nimportante para a acuidade da medida. Pode-se afirmar que a largura do manguito deve cobrir:","options":{"A":"1/2 da medida do braço e os manguitos mais largos superestimam os valores reais da pressão.","B":"1/2 da medida do braço e os manguitos mais largos subestimam os valores reais da pressão.","C":"1/3 da medida do braço e os manguitos mais largos superestimam os valores reais da pressão.","D":"1/3 da medida do braço e os manguitos mais largos subestimam os valores reais da pressão.","E":"2/3 da medida do braço e os manguitos mais largos subestimam os valores reais da pressão."},"answer":"E","source":"Clinica médica/MED CLM 03/MED CLM 03.txt","sourceLabel":"MED · MED CLM 03","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-03-22968","number":"22968","sourceNumber":"22968","collectionBlock":"med:med-clinica-medica-med-clm-03","collectionLabel":"MED · MED CLM 03","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 03","subtopic":"","stem":"Das doenças enumeradas abaixo, a que NÃO está relacionada a fenômenos\ntromboembólicos para as extremidades é:","options":{"A":"o infarto agudo do miocárdio.","B":"a cardiopatia chagásica.","C":"a arritmia cardíaca.","D":"a hipertensão renovascular."},"answer":"D","source":"Clinica médica/MED CLM 03/MED CLM 03.txt","sourceLabel":"MED · MED CLM 03","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-03-26943","number":"26943","sourceNumber":"26943","collectionBlock":"med:med-clinica-medica-med-clm-03","collectionLabel":"MED · MED CLM 03","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 03","subtopic":"","stem":"Qual dos pacientes abaixo está apresentando uma emergência hipertensiva?","options":{"A":"Adalgisa, 65 anos, obesa, hipertensa e diabética há 20 anos, vai visitar sua mãe na UTI e fica\nmuito emocionada. Levada ao OS, refere sentir\nmuita tontura e sua PA=210/120mmHg. Demais do\nexame físico é normal.","B":"Max, 12 anos, acordou ontem com as pálpebras edemaciadas. Hoje, não conseguiu fazer\neducação física por dispnéia. Há 15 dias teve impetigo. Agora, ao exame físico tem\nPA=160/100mmHg e pulmões limpos.","C":"Miguel, 72 anos, revascularizado do miocárdio há 2 anos, refere dor retroesternal há 3 horas. Ao\nexame físico, revela PA=210/130mmHg e os\npulsos diminuídos nos membros superiores e não\npalpáveis nos membros inferiores.","D":"Clara, 22 anos, sabidamente lúpica, fez exames para avaliação do controle da doença\nreumatológica há 1 semana e estavam todos\nnormais. Hoje, refere cefaleia e PA=180/100mmHg.","E":"Eda, 48 anos, portadora de estenose aórtica devido cardite reumática, refere tontura rotatória e\nvômitos desde hoje cedo. PA=180/105mmHg."},"answer":"C","source":"Clinica médica/MED CLM 03/MED CLM 03.txt","sourceLabel":"MED · MED CLM 03","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-03-22981","number":"22981","sourceNumber":"22981","collectionBlock":"med:med-clinica-medica-med-clm-03","collectionLabel":"MED · MED CLM 03","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 03","subtopic":"","stem":"Em indivíduos de alto risco cardiovascular com dislipidemias, o tipo de tratamento e as\nmetas a serem atingidas para os valores dos lipídeos são:","options":{"A":"tratamento não famacológico inicial (três meses) e metas de LDL-Colesterol < 100 mg/dL;\nHDL-Colesterol maior ou igual a 40 mg/dL para homens e mulheres e triglicerídeos < 150 mg/dL.","B":"tratamento não farmacológico + tratamento farmacológico e metas de LDL-Colesterol < 100\nmg/dL; HDL-Colesterol maior ou igual a 40 mg/dL para homens; HDL-Colesterol maior ou igual a\n50 mg/dL para mulheres e Triglicerídeos < 150 mg/dL.","C":"tratamento não farmacológico inicial (três meses) e metas de LDL-Colesterol < 130 mg/dL;\nHDL-Colesterol maior ou igual a 40 mg/dL para homens e mulheres e triglicerídeos < 150 mg/dL.","D":"tratamento não famacológico + tratamento farmacológico e metas de LDL-Colesterol < 130\nmg/dL; HDL-Colesterol maior ou igual a 40 mg/dL para\nhomens; HDL-Colesterol maior ou igual a 50\nmg/dL para mulheres e Triglicerídeos < 150 mg/dL."},"answer":"B","source":"Clinica médica/MED CLM 03/MED CLM 03.txt","sourceLabel":"MED · MED CLM 03","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-03-9321","number":"9321","sourceNumber":"9321","collectionBlock":"med:med-clinica-medica-med-clm-03","collectionLabel":"MED · MED CLM 03","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 03","subtopic":"","stem":"Paciente com diabetes tipo 2, portador de hipertensão arterial estágio I, deverá iniciar\ntratamento para a pressão preferencialmente com:","options":{"A":"tratamento não farmacológico isolado nos primeiros três meses","B":"tratamento não farmacológico + tratamento farmacológico com betabloqueador e diurético\ntiazídico.","C":"tratamento não farmacológico + tratamento farmacológico com inibidor da enzima conversora da\nangiotensina ou bloqueador do receptor de angiotensina II + diuréticos tiazídicos, se necessário.","D":"tratamento farmacológico com bloqueador dos canais de cálcio + diurético tiazídico."},"answer":"C","source":"Clinica médica/MED CLM 03/MED CLM 03.txt","sourceLabel":"MED · MED CLM 03","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-03-9322","number":"9322","sourceNumber":"9322","collectionBlock":"med:med-clinica-medica-med-clm-03","collectionLabel":"MED · MED CLM 03","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 03","subtopic":"","stem":"Paciente com 40 anos de idade, com diagnóstico de hipertensão há três anos, que\nevoluiu com dificuldade de controle\npressórico e hipocalemia persistente sem causa aparente. Na\ninvestigação para hiperaldosteronismo primário, os seguintes resultados foram obtidos: aldosterona\nplasmática em repouso: 36 ng/ml (VR: 1-16): atividade plasmática de renina: 0,08 ng/ml/hora (VR:\n0,4- 0,7): aldosterona plasmática ao teste da postura: 36 ng/dl. Na tomografia computadorizada de\nabdome, nenhuma massa adrenal foi visualizada. Qual seria o diagnóstico mais provável para essa\npaciente?","options":{"A":"Adenoma produtor de aldosterona (APA)","B":"Hiperaldosteronismo idiopático (HAI)","C":"Hiperaldosteronismo supressível com glicocorticoide","D":"Hiperplasia adrenal primária"},"answer":"A","source":"Clinica médica/MED CLM 03/MED CLM 03.txt","sourceLabel":"MED · MED CLM 03","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-03-10643","number":"10643","sourceNumber":"10643","collectionBlock":"med:med-clinica-medica-med-clm-03","collectionLabel":"MED · MED CLM 03","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 03","subtopic":"","stem":"Ao decidir pela introdução de um programa de atenção ao hipertenso, em uma unidade\nprimária de saúde, é fundamental garantir o acesso imediato dos pacientes aos exames:","options":{"A":"ECG, EAS, colesterol, glicemia.","B":"ergometria, hematócrito, glicemia uricemia.","C":"hematócrito, ultrassonografia, glicemia, creatinina.","D":"ultrassonografia, ECG, radiografia de tórax, glicemia.","E":"radiografia de tórax, glicemia, colesterol, ecocardiografia."},"answer":"A","source":"Clinica médica/MED CLM 03/MED CLM 03.txt","sourceLabel":"MED · MED CLM 03","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-03-250235","number":"250235","sourceNumber":"250235","collectionBlock":"med:med-clinica-medica-med-clm-03","collectionLabel":"MED · MED CLM 03","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 03","subtopic":"","stem":"Paciente de 66 anos, portador de insuficiência cardíaca de etiologia isquêmica,\nhipertensão arterial sistêmica, realizou\ncirurgia de revascularização miocárdica há 3 meses no\nHospital Universitário Presidente Dutra. Vem ao ambulatório de clínica médica para seguimento.\nTem diabetes mellitus tipo 2 há +/- 10 anos, sempre em uso de droga oral. Relata que há alguns\ndias, passou a apresentar suores frios ao fim da manhã. Para o diabetes, em uso atual de\nmetformina 500 mg 2x dia + Glibenclamida (GBC) 10 mg/dia. IMC = 31,1 kg/m² e obesidade\ncentrípeta. Exames com glicemia de jejum = 130 mg/dl; Hb1ac = 7,0%; glicemia pós-prandial = 190\nmg/dl; creatinina = 0,8 mg/dl. Relação albumina/creatinina = 68 mg/g em 1ª amostra e 76 mg/g na\n2ª amostra. O paciente retornou ao ambulatório com o resultado do lipidograma. CT = 180 mg/dl;\nHDL = 35 mg/dl; LDL = 115 mg/dl; TG = 150 mg/dl. Está em uso regular de sinvastatina 40 mg\ndesde a cirurgia. Qual é sua meta para o LDL, baseado no seu risco cardiovascular e conduta?","options":{"A":"LDL < 70 mg/dl. Reforçar as modificações no estilo de vida.","B":"LDL < 50 mg/dl. Modificar a sinvastatina 40 mg por estatina de alta potência (rosuvastatina 20\nmg ou atorvastatina 40 mg).","C":"LDL < 70 mg/dl. Modificar a sinvastatina 40 mg por estatina de alta potência (rosuvastatina 20\nmg ou atorvastatina 40 mg).","D":"LDL < 50 mg/dl. Reforçar as modificações no estilo de vida."},"answer":"B","source":"Clinica médica/MED CLM 03/MED CLM 03.txt","sourceLabel":"MED · MED CLM 03","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-03-216400","number":"216400","sourceNumber":"216400","collectionBlock":"med:med-clinica-medica-med-clm-03","collectionLabel":"MED · MED CLM 03","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 03","subtopic":"","stem":"Em relação à hipertensão arterial na infância, assinale a alternativa CORRETA.","options":{"A":"Para crianças de 1 a 13 anos, PA normal é abaixo do percentil 95.","B":"Para crianças com mais de 13 anos, PA normal é abaixo de 129 x 80 mmHg.","C":"Para crianças com mais de 13 anos, considera-se hipertensão arterial estágio I, PA de 140 x 80\nmmHg.","D":"Para crianças de 1 a 13 anos, PA normal é abaixo do percentil 90."},"answer":"D","source":"Clinica médica/MED CLM 03/MED CLM 03.txt","sourceLabel":"MED · MED CLM 03","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-03-216310","number":"216310","sourceNumber":"216310","collectionBlock":"med:med-clinica-medica-med-clm-03","collectionLabel":"MED · MED CLM 03","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 03","subtopic":"","stem":"As crises hipertensivas na infância têm alta morbimortalidade e necessitam de\nabordagem terapêutica imediata. Sobre esse assunto, assinale a alternativa INCORRETA.","options":{"A":"A hipertensão arterial em crianças é geralmente secundária a uma condição clínica adjacente,\nprincipalmente a nefropatia, que representa 60 a 90% dos casos.","B":"A urgência e a emergência hipertensivas são equivalentes em sua definição, tendo como\ndiferença apenas a conduta farmacológica a ser seguida.","C":"A emergência hipertensiva se caracteriza por lesão de órgão alvo com risco iminente de vida. O\npaciente pode apresentar falência cardíaca, edema agudo de pulmão, encefalopatia hipertensiva,\nretinopatia e hemorragia cerebral.","D":"A encefalopatia hipertensiva é uma condição rara em crianças, encontrada principalmente em\npacientes com elevação aguda da pressão arterial."},"answer":"B","source":"Clinica médica/MED CLM 03/MED CLM 03.txt","sourceLabel":"MED · MED CLM 03","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-03-176143","number":"176143","sourceNumber":"176143","collectionBlock":"med:med-clinica-medica-med-clm-03","collectionLabel":"MED · MED CLM 03","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 03","subtopic":"","stem":"Paciente sem qualquer histórico clínico pregresso e sem relato de qualquer medicação\nem uso, é submetido a exame de monitorização\nambulatorial da pressão arterial, após aferição\npressórica isolada de 140 x 80 mmHg em consultório. Laudo do exame mostra comportamento\nnormal da pressão arterial durante a vigília e atenuação do descenso noturno. Dentre as opções\nabaixo, esse achado pode estar relacionado mais PROVAVELMENTE a:","options":{"A":"Hiperaldosteronismo primário.","B":"Hipertensão mascarada.","C":"Uso de benzodiazepínicos para indução de sono.","D":"Apneia obstrutiva do sono.","E":"Dislipidemia."},"answer":"D","source":"Clinica médica/MED CLM 03/MED CLM 03.txt","sourceLabel":"MED · MED CLM 03","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-03-105661","number":"105661","sourceNumber":"105661","collectionBlock":"med:med-clinica-medica-med-clm-03","collectionLabel":"MED · MED CLM 03","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 03","subtopic":"","stem":"De acordo com o VIII Joint Committee, que redigiu o Guidelines Americano 2014, para\nhipertensão arterial:","options":{"A":"O duplo bloqueio do sistema renina-angiotensina-aldosterona com IECA + BRA está\nrecomendado em pacientes que não obtenham\ncontrole da proteinúria com apenas uma das\nclasses de droga.","B":"Em renais crônicos, as drogas de primeira escolha são os inibidores da enzima conversora da\nangiotensina ou bloqueadores de receptor de angiotensina.","C":"Betabloqueadores estão entre as drogas de primeira escolha para início do tratamento\nanti-hipertensivo.","D":"É contraindicado iniciar uma segunda droga no tratamento HAS sem que a primeira esteja em\ndose máxima.","E":"O alvo pressórico a ser perseguido em pacientes com menos de 60 anos é 130 x 85 mmHg."},"answer":"B","source":"Clinica médica/MED CLM 03/MED CLM 03.txt","sourceLabel":"MED · MED CLM 03","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-03-84881","number":"84881","sourceNumber":"84881","collectionBlock":"med:med-clinica-medica-med-clm-03","collectionLabel":"MED · MED CLM 03","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 03","subtopic":"","stem":"Sobre a Hipertensão Arterial Sistêmica e o seu tratamento: I - A decisão terapêutica\ndeve ser baseada no risco cardiovascular\nconsiderando-se a presença de fatores de risco, lesão\nem órgão-alvo e/ou doença cardiovascular estabelecida, e não apenas no nível da PA. II - Os\nalfabloqueadores atuam sobre a musculatura da parede vascular, promovendo relaxamento\nmuscular com consequente vasodilatação e redução da resistência vascular periférica. São\nutilizados em associação com diuréticos e/ou betabloqueadores. Hidralazina e metildopa são dois\ndos principais representantes desse grupo. III - Os Inibidores da Enzima Conversora da\nAngiotensina (IECA) quando usados em indivíduos com DRC, podem eventualmente agravar a\nhiperpotassemia. Em pacientes com hipertensão renovascular bilateral ou unilateral associada a rim\núnico podem promover redução da filtração glomerular com aumento dos níveis séricos de ureia e\ncreatinina. IV - O uso dos IECA em pacientes com função renal reduzida pode causar diminuição de\naté 30% da creatinina, mas a longo prazo preponderá seu efeito nefroprotetor. Marque a alternativa\nCORRETA:","options":{"A":"As alternativas I, III e IV estão corretas.","B":"Todas as alternativas estão corretas.","C":"As alternativas I, II e III estão corretas.","D":"As alternativas I, II e IV estão corretas.","E":"As alternativas I e III estão corretas."},"answer":"E","source":"Clinica médica/MED CLM 03/MED CLM 03.txt","sourceLabel":"MED · MED CLM 03","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-03-80838","number":"80838","sourceNumber":"80838","collectionBlock":"med:med-clinica-medica-med-clm-03","collectionLabel":"MED · MED CLM 03","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 03","subtopic":"","stem":"Quanto à hipertensão arterial em crianças e adolescentes, assinale a alternativa\nCORRETA.","options":{"A":"Havendo disparidade entre a pressão sistólica e diastólica, o valor mais baixo determinará o\nestágio ou gravidade da hipertensão arterial.","B":"O diagnóstico de hipertensão arterial deve ser dado a toda criança ou adolescente que\napresente valor de pressão sistólica e/ou\ndiastólica maior ou igual ao percentil 95 pelo menos uma\nvez, durante consultas médicas.","C":"Idade, sexo e estatutura são fatores de importância a serem considerados no diagnóstico.","D":"A hipertensão arterial não deve ser abordada na infância.","E":"O ambiente em que se encontra o paciente não interfere nos valores da pressão arterial."},"answer":"C","source":"Clinica médica/MED CLM 03/MED CLM 03.txt","sourceLabel":"MED · MED CLM 03","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-03-35704","number":"35704","sourceNumber":"35704","collectionBlock":"med:med-clinica-medica-med-clm-03","collectionLabel":"MED · MED CLM 03","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 03","subtopic":"","stem":"Qual a estratégia anti-hipertensiva preferencial no paciente hipertenso, diabético e com\nproteinúria?","options":{"A":"Diurético como droga inicial e alcançar meta < 130/80.","B":"IECA ou BRA como droga inicial e alcançar meta < 135/85.","C":"Terapia combinada onde uma das drogas é IECA ou BRA e alcançar a meta < 130/80.","D":"Terapia combinada com diurético e betabloqueadores e meta < 120/75 se proteinúria é\nsignificativa.","E":"Antagonistas de cálcio são excelentes hipotensores e promovem alcance significativo da meta <\n135/80 em monoterapia."},"answer":"C","source":"Clinica médica/MED CLM 03/MED CLM 03.txt","sourceLabel":"MED · MED CLM 03","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-03-35757","number":"35757","sourceNumber":"35757","collectionBlock":"med:med-clinica-medica-med-clm-03","collectionLabel":"MED · MED CLM 03","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 03","subtopic":"","stem":"Dos abaixo qual não representa quadro de emergência hipertensiva?","options":{"A":"Dissecção aguda de aorta e eclâmpsia.","B":"Feocromocitoma e encefalopatia hipertensiva.","C":"Glomerulonefrite aguda e síndrome coronariana aguda.","D":"Pressão arterial de 180 X 120 associado à cefaleia com tomografia de crânio normal em uma\npaciente que trata irregularmente sua hipertensão.","E":"Paciente de 38 anos com pressão arterial de 170 X 130 mmHg com cefaleia intensa e torpor."},"answer":"D","source":"Clinica médica/MED CLM 03/MED CLM 03.txt","sourceLabel":"MED · MED CLM 03","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-03-35773","number":"35773","sourceNumber":"35773","collectionBlock":"med:med-clinica-medica-med-clm-03","collectionLabel":"MED · MED CLM 03","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 03","subtopic":"","stem":"A ginecomastia é um evento comum, presente em 30-50 % no adolescente masculino,\nem maior ou menor grau. São comuns alterações\nemocionais de vergonha, de culpa, evitando o\nadolescente tirar a camisa, frequentar piscina, muitas vezes levando-o a uma baixa autoestima ou a\numa depressão. Dentre as opções abaixo, quais as drogas causam ginecomastia:","options":{"A":"Espironolactona, diclofenaco, dipirona.","B":"Captopril, A.A.S, paracetamol.","C":"Espironolactona, captopril, benzodiazepínicos.","D":"Digoxina, benzodiazepínicos, ácido fólico.","E":"Ácido fólico, dipirona, digoxina."},"answer":"C","source":"Clinica médica/MED CLM 03/MED CLM 03.txt","sourceLabel":"MED · MED CLM 03","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-03-28284","number":"28284","sourceNumber":"28284","collectionBlock":"med:med-clinica-medica-med-clm-03","collectionLabel":"MED · MED CLM 03","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 03","subtopic":"","stem":"Analise as afirmações abaixo sobre hipertensão arterial sistêmica: I - A pressão arterial\nsistêmica tem relação direta com os índices de mortalidade cárdio e cerebrovasculares já a partir de\nvalores de pressão arterial sistólica de 115 mmHg com duplicação da ocorrência de eventos a cada\n20 mmHg de aumento nos valores da pressão arterial sistólica, independentemente da idade do\nindivíduo; II - Em pacientes hipertensos, o álcool é benéfico, porque, além de aumentar os níveis de\nHDL, diminui a resistência periférica e, consequentemente, diminui a pressão arterial; III - No\ntratamento dos pacientes hipertensos portadores de diabetes mellitus e também nos pacientes com\ninsuficiência cardíaca estão indicados os IECA (inibidores da enzima conversora da angiotensina);\nEstão corretos os itens:","options":{"A":"I, II, III","B":"I e II apenas;","C":"I e III apenas","D":"II e III, apenas","E":"III, apenas"},"answer":"C","source":"Clinica médica/MED CLM 03/MED CLM 03.txt","sourceLabel":"MED · MED CLM 03","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-03-342379","number":"342379","sourceNumber":"342379","collectionBlock":"med:med-clinica-medica-med-clm-03","collectionLabel":"MED · MED CLM 03","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 03","subtopic":"","stem":"O cuidado da pessoa com hipertensão arterial sistêmica (HAS) deve ser\nmultiprofissional. O objetivo do\ntratamento é a manutenção de níveis pressóricos controlados\nconforme as características do paciente e tem por finalidade reduzir o risco de doenças\ncardiovasculares, diminuir a morbimortalidade e melhorar a qualidade de vida dos indivíduos\n(BRASIL, 2010). Considere a Hipertensão Arterial em diferentes ciclos de vida, e classifique as\nalternativas em Verdadeira (V) ou Falsa (F). I-Não há clara evidência que associe a pressão arterial\nem crianças e adolescentes a eventos cardiovasculares futuros. Valores mais elevados são\nencontrados em crianças obesas, mas que tendem a se reduzir com a diminuição de peso,\nespecialmente na adolescência. II-A dose de anti-hipertensivos a ser iniciada em idosos deve ser a\nmetade da dose utilizada em jovens. Especial atenção deve ser dada a idosos frágeis e com risco\naumentado de eventos decorrentes da redução excessiva da pressão arterial como quedas,\nhipotensão postural e sonolência excessiva. III-O tratamento da Hipertensão Arterial na grávida\ndeve ser focado em medidas farmacológicas, nas formas leve, moderada e grave optando-se pelo\ntratamento usual recomendado para cada condição clínica específica. IV- Recomenda-se\npreferentemente intervenções medicamentosas, para crianças. A opção que contém a sequência\nCORRETA é:","options":{"A":"V, F, V, V","B":"F, V, V, V","C":"F, F, F, V","D":"V, V, F, F","E":"V, F, V, F"},"answer":"A","source":"Clinica médica/MED CLM 03/MED CLM 03.txt","sourceLabel":"MED · MED CLM 03","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 03","MED"],"answerSource":"inferred","commentDeferred":true}]};
